        std::vector<std::thread> workers;

        auto start = std::chrono::high_resolution_clock::now();

        for (size_t tid = 0; tid < NUM_THREADS; ++tid) {
            workers.emplace_back([&engine, tid, OPS_PER_THREAD]() {
                size_t registered_tid = EpochManager::instance().register_thread();

                for (size_t i = 0; i < OPS_PER_THREAD; ++i) {
                    uint64_t key = (i % 200); // High-skew Zipfian collision simulation
                    std::string val_str = "value_payload_" + std::to_string(key) + "_" + std::to_string(i);
                    std::span<const uint8_t> val_span(reinterpret_cast<const uint8_t*>(val_str.data()), val_str.size());

                    // Transaction Write
                    auto txn = engine.begin_transaction(registered_tid);
                    if (txn.put(key, val_span)) {
                        txn.commit();
                    } else {
                        txn.abort();
                    }

                    // Transaction Snapshot Read
                    auto ro_txn = engine.begin_transaction(registered_tid);
                    auto res = ro_txn.get(key);
                    (void)res;
                    ro_txn.commit();
                }

                EpochManager::instance().unregister_thread(registered_tid);
            });
        }

        for (auto& th : workers) {
            th.join();
        }

        auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::high_resolution_clock::now() - start).count();

        std::cout << ">>> Completed " << (NUM_THREADS * OPS_PER_THREAD * 2)
                  << " transactions in " << elapsed << " ms ("
                  << (NUM_THREADS * OPS_PER_THREAD * 2 * 1000) / (elapsed ? elapsed : 1)
                  << " tx/sec)" << std::endl;
    }

    std::cout << ">>> Verifying Cold Crash Recovery Protocol..." << std::endl;
    LockFreeMVCCIndex recovered_index;
    uint64_t max_txid = 0;
    RecoveryManager::recover_from_wal(wal_file, recovered_index, max_txid);

