            uint64_t min_key = rand() % 500;
            uint64_t max_key = min_key + 50;

            auto results = engine.scan(min_key, max_key, snapshot_ts, 20, tid);

            // Verify monotonic ordering in range scan result
            for (size_t k = 1; k < results.size(); ++k) {
                assert(results[k].first >= results[k - 1].first);
            }
            total_scans.fetch_add(1, std::memory_order_relaxed);
        }

        EpochManager::instance().deregister_thread(tid);
    };

    std::vector<std::thread> threads;
    for (size_t i = 0; i < NUM_WRITERS; ++i) threads.emplace_back(writer_worker, i);
    for (size_t i = 0; i < NUM_READERS; ++i) threads.emplace_back(reader_worker, i);
    for (size_t i = 0; i < NUM_SCANNERS; ++i) threads.emplace_back(scanner_worker, i);

    auto start_time = std::chrono::high_resolution_clock::now();
    start_flag.store(true, std::memory_order_release);

    for (auto& th : threads) {
        th.join();
    }
    auto end_time = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed = end_time - start_time;

