    LockFreeMVCCIndex index;
    constexpr TxnTimestamp T1 = 100;
    constexpr TxnTimestamp T2 = 200;
    constexpr TxnId TX_A = 10;
    constexpr TxnId TX_B = 11;
    constexpr TxnId TX_C = 12;

    // 1. Transaction A commits an insert
    auto& tx_a = TxnManager::instance().get_desc(TX_A);
