    tx_a.commit_ts.store(T1, std::memory_order_relaxed);
    index.append_update(index.get_root(), 42, 1001, TX_A, T1);

    // 2. Transaction B performs an update and aborts
    index.append_update(index.get_root(), 42, 9999, TX_B, T2);
    index.abort_transaction(index.get_root(), 42, TX_B);

    // 3. Reader validates that aborted value is skipped and committed value 1001 is retrieved
    ReadResult res1 = index.read_record(index.get_root(), 42, T2);
    assert(res1.status == ReadStatus::FOUND && res1.value == 1001);

    // 4. Fill node to trigger split consolidation
    for (uint64_t k = 1; k <= 20; ++k) {
        TxnId tid = 100 + k;
        auto& txd = TxnManager::instance().get_desc(tid);
        txd.state.store(TxnState::COMMITTED, std::memory_order_relaxed);
        txd.commit_ts.store(T1 + k, std::memory_order_relaxed);
        index.append_update(index.get_root(), k, k * 10, tid, T1 + k);
    }

    // Consolidate and split delta chain
    Node* head = index.get_root().load(std::memory_order_acquire);
    bool consolidated = index.consolidate_and_split(index.get_root(), head);
    assert(consolidated);

    // 5. Verify reads across split boundary
    ReadResult r_low = index.read_record(index.get_root(), 5, 500);
    assert(r_low.status == ReadStatus::FOUND && r_low.value == 50);

    ReadResult r_high = index.read_record(index.get_root(), 18, 500);
    assert(r_high.status == ReadStatus::FOUND && r_high.value == 180);

    std::cout << "[SUCCESS] NUMA-Aware Latch-Free MVCC EBR Index Tests Passed." << std::endl;
    return 0;
}
