### Part 2: Complete C++20 Implementation

```cpp
#pragma once

#include <atomic>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <new>
#include <optional>
#include <thread>
#include <type_traits>
#include <utility>
#include <vector>

#if defined(__x86_64__) || defined(_M_X64)
#include <immintrin.h>
#endif

// ============================================================================
// Architecture-Specific Pause / Yield Optimization
// ============================================================================
namespace detail {
    inline void cpu_relax() noexcept {
#if defined(__aarch64__) || defined(_M_ARM64)
        asm volatile("yield" ::: "memory");
#elif defined(__x86_64__) || defined(_M_X64)
        #if defined(_MSC_VER)
        _mm_pause();
        #else
        asm volatile("pause" ::: "memory");
        #endif
#else
        std::this_thread::yield();
#endif
    }

#ifdef __cpp_lib_hardware_interference_size
    using std::hardware_destructive_interference_size;
#else
    // 64 bytes is the standard cacheline size for x86_64 and ARM Neoverse N1/N2/V2.
    constexpr size_t hardware_destructive_interference_size = 64;
#endif
} // namespace detail

// ============================================================================
// Epoch-Based Reclamation (EBR) Subsystem
// ============================================================================
class EpochManager {
public:
    static constexpr uint64_t INACTIVE_EPOCH = UINT64_MAX;
    static constexpr size_t RETIRE_THRESHOLD = 64;

    struct RetiredNode {
        void* ptr;
        void (*deleter)(void*);
        RetiredNode* next;
    };

    struct alignas(detail::hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{INACTIVE_EPOCH};
        std::atomic<bool> is_registered{true};
        std::atomic<ThreadControlBlock*> next{nullptr};

        // Thread-local limbo bags for epochs: e % 3
        std::vector<std::pair<void*, void (*)(void*)>> limbo_bags[3];
        size_t local_retired_count{0};
        uint32_t nesting_depth{0};
    };

private:
    alignas(detail::hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_{0};
    alignas(detail::hardware_destructive_interference_size) std::atomic<ThreadControlBlock*> thread_list_head_{nullptr};
    alignas(detail::hardware_destructive_interference_size) std::atomic<RetiredNode*> orphan_list_head_{nullptr};

public:
    EpochManager() = default;

    ~EpochManager() {
        // Drain all orphan nodes unconditionally on shutdown
        drain_orphans_force();

        // Deallocate all thread control blocks
        ThreadControlBlock* curr = thread_list_head_.load(std::memory_order_relaxed);
        while (curr != nullptr) {
            ThreadControlBlock* next = curr->next.load(std::memory_order_relaxed);
            // Free any remaining objects in thread limbo bags
            for (int i = 0; i < 3; ++i) {
                for (auto& item : curr->limbo_bags[i]) {
                    item.second(item.first);
                }
                curr->limbo_bags[i].clear();
            }
            delete curr;
            curr = next;
        }
    }

    EpochManager(const EpochManager&) = delete;
    EpochManager& operator=(const EpochManager&) = delete;

    ThreadControlBlock& get_or_register_thread() {
        static thread_local ThreadControlBlock* tls_tcb = nullptr;
        if (__builtin_expect(tls_tcb != nullptr, 1)) {
            return *tls_tcb;
        }

        tls_tcb = new ThreadControlBlock();

        // Push into lock-free global thread list
        ThreadControlBlock* old_head = thread_list_head_.load(std::memory_order_relaxed);
        do {
            tls_tcb->next.store(old_head, std::memory_order_relaxed);
        } while (!thread_list_head_.compare_exchange_weak(
            old_head, tls_tcb, std::memory_order_release, std::memory_order_relaxed));

        return *tls_tcb;
    }

    void enter() noexcept {
        ThreadControlBlock& tcb = get_or_register_thread();
        if (tcb.nesting_depth++ == 0) {
            uint64_t g_epoch = global_epoch_.load(std::memory_order_relaxed);
            tcb.local_epoch.store(g_epoch, std::memory_order_relaxed);

            // Crucial ARM64 barrier: Prevents StoreLoad reordering between local_epoch
            // publication and subsequent queue pointer dereferencing.
            std::atomic_thread_fence(std::memory_order_seq_cst);
        }
    }

    void exit() noexcept {
        ThreadControlBlock& tcb = get_or_register_thread();
        assert(tcb.nesting_depth > 0);
        if (--tcb.nesting_depth == 0) {
            // Ensure all reads inside critical section finish before going inactive
            std::atomic_thread_fence(std::memory_order_seq_cst);
            tcb.local_epoch.store(INACTIVE_EPOCH, std::memory_order_release);

            if (tcb.local_retired_count >= RETIRE_THRESHOLD) {
                try_advance_and_reclaim(tcb);
            }
        }
    }

    template <typename U>
    void retire(U* ptr) {
        retire_raw(ptr, [](void* p) { delete static_cast<U*>(p); });
    }

    void retire_raw(void* ptr, void (*deleter)(void*)) {
        if (!ptr) return;
        ThreadControlBlock& tcb = get_or_register_thread();
        uint64_t g_epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t bag_idx = g_epoch % 3;

        tcb.limbo_bags[bag_idx].emplace_back(ptr, deleter);
        tcb.local_retired_count++;

        if (tcb.local_retired_count >= RETIRE_THRESHOLD && tcb.nesting_depth == 0) {
            try_advance_and_reclaim(tcb);
        }
    }

    void try_advance_and_reclaim(ThreadControlBlock& tcb) {
        uint64_t curr_epoch = global_epoch_.load(std::memory_order_acquire);

        // Check if all active threads have reached curr_epoch
        bool can_advance = true;
        ThreadControlBlock* curr = thread_list_head_.load(std::memory_order_acquire);
        while (curr != nullptr) {
            if (curr->is_registered.load(std::memory_order_relaxed)) {
                uint64_t t_epoch = curr->local_epoch.load(std::memory_order_acquire);
                if (t_epoch != INACTIVE_EPOCH && t_epoch < curr_epoch) {
                    can_advance = false;
                    break;
                }
            }
            curr = curr->next.load(std::memory_order_relaxed);
        }

        if (can_advance) {
            if (global_epoch_.compare_exchange_strong(curr_epoch, curr_epoch + 1,
                                                      std::memory_order_acq_rel,
                                                      std::memory_order_acquire)) {
                curr_epoch++;
            }
        }

        // In 3-epoch scheme, nodes retired at <= (curr_epoch - 2) are in bag (curr_epoch + 1) % 3
        size_t reclaim_bag_idx = (curr_epoch + 1) % 3;
        auto& bag = tcb.limbo_bags[reclaim_bag_idx];
        if (!bag.empty()) {
            for (auto& item : bag) {
                item.second(item.first);
            }
            tcb.local_retired_count -= bag.size();
            bag.clear();
        }

        // Drain global orphan list if present
        drain_orphans(curr_epoch);
    }

    void offload_to_orphan_list(ThreadControlBlock& tcb) {
        for (int i = 0; i < 3; ++i) {
            for (auto& item : tcb.limbo_bags[i]) {
                auto* node = new RetiredNode{item.first, item.second, nullptr};
                RetiredNode* old_head = orphan_list_head_.load(std::memory_order_relaxed);
                do {
                    node->next = old_head;
                } while (!orphan_list_head_.compare_exchange_weak(
                    old_head, node, std::memory_order_release, std::memory_order_relaxed));
            }
            tcb.limbo_bags[i].clear();
        }
        tcb.local_retired_count = 0;
    }

private:
    void drain_orphans(uint64_t curr_epoch) {
        RetiredNode* head = orphan_list_head_.exchange(nullptr, std::memory_order_acq_rel);
        if (!head) return;

        RetiredNode* curr = head;
        while (curr != nullptr) {
            RetiredNode* next = curr->next;
            curr->deleter(curr->ptr);
            delete curr;
            curr = next;
        }
    }

    void drain_orphans_force() {
        RetiredNode* head = orphan_list_head_.exchange(nullptr, std::memory_order_relaxed);
        while (head != nullptr) {
            RetiredNode* next = head->next;
            head->deleter(head->ptr);
            delete head;
            head = next;
        }
    }
};

// RAII Epoch Guard
class EpochGuard {
public:
    explicit EpochGuard(EpochManager& em) noexcept : em_(em) {
        em_.enter();
    }
    ~EpochGuard() noexcept {
        em_.exit();
    }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;

private:
    EpochManager& em_;
};

// ============================================================================
// Lock-Free Segmented MPMC Queue Implementation
// ============================================================================
template <typename T, size_t SegmentSize = 1024>
class LockFreeMPMCQueue {
    static_assert((SegmentSize & (SegmentSize - 1)) == 0, "SegmentSize must be a power of 2");
    static_assert(std::is_nothrow_destructible_v<T>, "T must have a noexcept destructor");

public:
    enum class SlotState : uint8_t {
        EMPTY = 0,
        WRITING = 1,
        READY = 2,
        READING = 3,
        CONSUMED = 4,
        ABORTED = 5
    };

    struct Slot {
        alignas(alignof(T)) std::byte storage[sizeof(T)];
        std::atomic<SlotState> state{SlotState::EMPTY};
    };

    struct alignas(detail::hardware_destructive_interference_size) Segment {
        alignas(detail::hardware_destructive_interference_size) std::atomic<size_t> tail_idx{0};
        alignas(detail::hardware_destructive_interference_size) std::atomic<size_t> head_idx{0};
        alignas(detail::hardware_destructive_interference_size) std::atomic<Segment*> next{nullptr};
        uint64_t segment_id{0};

        Slot slots[SegmentSize];

        explicit Segment(uint64_t id) noexcept : segment_id(id) {}

        ~Segment() {
            // Destruct any items that were published (READY) but never consumed
            for (size_t i = 0; i < SegmentSize; ++i) {
                SlotState s = slots[i].state.load(std::memory_order_relaxed);
                if (s == SlotState::READY) {
                    T* obj = reinterpret_cast<T*>(slots[i].storage);
                    obj->~T();
                }
            }
        }
    };

private:
    alignas(detail::hardware_destructive_interference_size) std::atomic<Segment*> head_segment_;
    alignas(detail::hardware_destructive_interference_size) std::atomic<Segment*> tail_segment_;
    EpochManager epoch_manager_;

public:
    LockFreeMPMCQueue() {
        Segment* init_seg = new Segment(0);
        head_segment_.store(init_seg, std::memory_order_relaxed);
        tail_segment_.store(init_seg, std::memory_order_relaxed);
    }

    ~LockFreeMPMCQueue() {
        // Collect all remaining segments starting from head
        Segment* curr = head_segment_.load(std::memory_order_relaxed);
        while (curr != nullptr) {
            Segment* next = curr->next.load(std::memory_order_relaxed);
            delete curr;
            curr = next;
        }
    }

    LockFreeMPMCQueue(const LockFreeMPMCQueue&) = delete;
    LockFreeMPMCQueue& operator=(const LockFreeMPMCQueue&) = delete;

    template <typename... Args>
    void emplace(Args&&... args) {
        EpochGuard guard(epoch_manager_);

        while (true) {
            Segment* tail_seg = tail_segment_.load(std::memory_order_acquire);
            size_t idx = tail_seg->tail_idx.fetch_add(1, std::memory_order_relaxed);

            if (idx < SegmentSize) {
                // Reserved slot idx in tail_seg
                tail_seg->slots[idx].state.store(SlotState::WRITING, std::memory_order_relaxed);

                try {
                    new (tail_seg->slots[idx].storage) T(std::forward<Args>(args)...);
                    tail_seg->slots[idx].state.store(SlotState::READY, std::memory_order_release);
                } catch (...) {
                    tail_seg->slots[idx].state.store(SlotState::ABORTED, std::memory_order_release);
                    throw;
                }
                return;
            }

            // Segment is full. Ensure next segment is allocated and linked.
            Segment* next_seg = tail_seg->next.load(std::memory_order_acquire);
            if (next_seg == nullptr) {
                Segment* new_seg = new Segment(tail_seg->segment_id + 1);
                if (!tail_seg->next.compare_exchange_strong(
                        next_seg, new_seg, std::memory_order_release, std::memory_order_acquire)) {
                    delete new_seg; // Another producer linked its segment first
                } else {
                    next_seg = new_seg;
                }
            }

            // Advance global tail_segment pointer
            tail_segment_.compare_exchange_strong(
                tail_seg, next_seg, std::memory_order_release, std::memory_order_acquire);
        }
    }

    void enqueue(T value) {
        emplace(std::move(value));
    }

    bool try_dequeue(T& out) {
        EpochGuard guard(epoch_manager_);

        while (true) {
            Segment* head_seg = head_segment_.load(std::memory_order_acquire);
            size_t h_idx = head_seg->head_idx.load(std::memory_order_relaxed);
            size_t t_idx = head_seg->tail_idx.load(std::memory_order_acquire);

            if (h_idx >= SegmentSize) {
                // Segment exhausted. Advance head_segment to next segment.
                Segment* next_seg = head_seg->next.load(std::memory_order_acquire);
                if (next_seg == nullptr) {
                    return false; // Queue empty
                }

                if (head_segment_.compare_exchange_strong(
                        head_seg, next_seg, std::memory_order_release, std::memory_order_acquire)) {
                    epoch_manager_.retire(head_seg);
                }
                continue;
            }

            if (h_idx >= t_idx) {
                // No unconsumed slots in this segment currently
                Segment* next_seg = head_seg->next.load(std::memory_order_acquire);
                if (next_seg != nullptr && head_seg->head_idx.load(std::memory_order_relaxed) >= SegmentSize) {
                    continue;
                }
                return false;
            }

            // Claim slot h_idx via CAS
            if (head_seg->head_idx.compare_exchange_weak(
                    h_idx, h_idx + 1, std::memory_order_acquire, std::memory_order_relaxed)) {

                // Spin-wait until producer finishes writing
                while (true) {
                    SlotState state = head_seg->slots[h_idx].state.load(std::memory_order_acquire);
                    if (__builtin_expect(state == SlotState::READY, 1)) {
                        break;
                    }
                    if (state == SlotState::ABORTED) {
                        // Slot aborted due to producer exception, skip to next iteration
                        goto continue_outer;
                    }
                    detail::cpu_relax();
                }

                // Slot is READY: Move value out and call destructor
                {
                    T* val_ptr = reinterpret_cast<T*>(head_seg->slots[h_idx].storage);
                    out = std::move(*val_ptr);
                    val_ptr->~T();
                }

                head_seg->slots[h_idx].state.store(SlotState::CONSUMED, std::memory_order_release);
                return true;
            }

        continue_outer:;
            detail::cpu_relax();
        }
    }

    std::optional<T> try_dequeue() {
        T val;
        if (try_dequeue(val)) {
            return val;
        }
        return std::nullopt;
    }
};
```

