        }

        for (size_t i = 0; i < OPS_PER_THREAD; ++i) {
            uint64_t raw_key = static_cast<uint64_t>(zipf(rng) * 100.0) % KEY_SPACE;
            uint32_t op = rng() % 100;
            Timestamp ts = global_ts.fetch_add(1, std::memory_order_relaxed);

            if (op < 50) { // 50% Insert/Update
                if (tree.Insert(raw_key, raw_key * 10, ts)) {
