### Complete Production-Grade Implementation (`LockFreeMPMCQueue.hpp`)

```cpp
#pragma once

#include <atomic>
#include <cstddef>
#include <cstdint>
#include <memory>
#include <new>
#include <span>
#include <type_traits>
#include <utility>
#include <stdexcept>
#include <system_error>

// Linux kernel eventfd / unistd
#include <sys/eventfd.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

// Architecture-specific pause intrinsics
#if defined(__x86_64__) || defined(_M_X64) || defined(__i386__) || defined(_M_IX86)
#include <immintrin.h>
#define CPU_PAUSE() _mm_pause()
#elif defined(__aarch64__) || defined(__arm__)
#define CPU_PAUSE() asm volatile("yield" ::: "memory")
#else
#define CPU_PAUSE() do {} while (0)
#endif

namespace pipeline {

#if defined(__cpp_lib_hardware_interference_size)
using std::hardware_destructive_interference_size;
#else
constexpr size_t hardware_destructive_interference_size = 64;
#endif

/**
 * @brief Adaptive backoff state machine for spin loops.
 * Transitions through: Exponential PAUSE -> Sched Yield -> Eventfd Sleep.
 */
class AdaptiveBackoff {
public:
    static constexpr uint32_t SPIN_THRESHOLD  = 64;
    static constexpr uint32_t YIELD_THRESHOLD = 256;

    inline void pause() noexcept {
        if (step_ < SPIN_THRESHOLD) {
            for (uint32_t i = 0; i < (1U << (step_ >> 2)); ++i) {
                CPU_PAUSE();
            }
        } else if (step_ < YIELD_THRESHOLD) {
            sched_yield();
        }
        ++step_;
    }

    [[nodiscard]] inline bool should_sleep() const noexcept {
        return step_ >= YIELD_THRESHOLD;
    }

    inline void reset() noexcept {
        step_ = 0;
    }

private:
    uint32_t step_{0};
};

template <typename T, size_t Capacity>
class LockFreeMPMCQueue {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of 2");
    static_assert(Capacity >= 2, "Capacity must be at least 2");

    static constexpr size_t BufferMask = Capacity - 1;

    // Slot layout with independent sequence counter and uninitialized storage
    struct alignas(hardware_destructive_interference_size) Slot {
        std::atomic<uint64_t> sequence;
        alignas(alignof(T)) std::byte storage[sizeof(T)];

        inline T* ptr() noexcept {
            return reinterpret_cast<T*>(storage);
        }

        inline const T* ptr() const noexcept {
            return reinterpret_cast<const T*>(storage);
        }
    };

public:
    LockFreeMPMCQueue()
        : read_eventfd_(-1), write_eventfd_(-1) {
        // Initialize slot sequences to initial cycle values [0 ... Capacity-1]
        for (size_t i = 0; i < Capacity; ++i) {
            slots_[i].sequence.store(i, std::memory_order_relaxed);
        }

        // Initialize non-blocking eventfds for epoll handoff
        read_eventfd_ = ::eventfd(0, EFD_NONBLOCK | EFD_CLOEXEC | EFD_SEMAPHORE);
        if (read_eventfd_ < 0) {
            throw std::system_error(errno, std::generic_category(), "Failed to create read eventfd");
        }

        write_eventfd_ = ::eventfd(0, EFD_NONBLOCK | EFD_CLOEXEC | EFD_SEMAPHORE);
        if (write_eventfd_ < 0) {
            ::close(read_eventfd_);
            throw std::system_error(errno, std::generic_category(), "Failed to create write eventfd");
        }
    }

    ~LockFreeMPMCQueue() {
        // Drain and destroy any remaining constructed objects
        uint64_t deq = dequeue_pos_.load(std::memory_order_relaxed);
        uint64_t enq = enqueue_pos_.load(std::memory_order_relaxed);

        while (deq < enq) {
            Slot& slot = slots_[deq & BufferMask];
            uint64_t seq = slot.sequence.load(std::memory_order_relaxed);
            if (seq == deq + 1) {
                std::destroy_at(slot.ptr());
            }
            ++deq;
        }

        if (read_eventfd_ >= 0) ::close(read_eventfd_);
        if (write_eventfd_ >= 0) ::close(write_eventfd_);
    }

    LockFreeMPMCQueue(const LockFreeMPMCQueue&) = delete;
    LockFreeMPMCQueue& operator=(const LockFreeMPMCQueue&) = delete;
    LockFreeMPMCQueue(LockFreeMPMCQueue&&) = delete;
    LockFreeMPMCQueue& operator=(LockFreeMPMCQueue&&) = delete;

    // =========================================================================
    // Single-Item Operations
    // =========================================================================

    template <typename... Args>
    bool emplace(Args&&... args) {
        uint64_t pos = enqueue_pos_.load(std::memory_order_relaxed);
        for (;;) {
            Slot& slot = slots_[pos & BufferMask];
            const uint64_t seq = slot.sequence.load(std::memory_order_acquire);
            const int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(pos);

            if (diff == 0) {
                // Slot is empty and at the correct cycle: attempt to claim pos
                if (enqueue_pos_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed)) {
                    std::construct_at(slot.ptr(), std::forward<Args>(args)...);
                    slot.sequence.store(pos + 1, std::memory_order_release);
                    notify_read_waiter();
                    return true;
                }
            } else if (diff < 0) {
                // Buffer is full (slot belongs to a previous unread cycle)
                return false;
            } else {
                // Another producer claimed pos; re-read enqueue_pos_
                pos = enqueue_pos_.load(std::memory_order_relaxed);
            }
        }
    }

    bool push(const T& item) {
        return emplace(item);
    }

    bool push(T&& item) {
        return emplace(std::move(item));
    }

    bool pop(T& destination) {
        uint64_t pos = dequeue_pos_.load(std::memory_order_relaxed);
        for (;;) {
            Slot& slot = slots_[pos & BufferMask];
            const uint64_t seq = slot.sequence.load(std::memory_order_acquire);
            const int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(pos + 1);

            if (diff == 0) {
                // Slot is ready to be consumed: attempt to claim pos
                if (dequeue_pos_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed)) {
                    destination = std::move(*slot.ptr());
                    std::destroy_at(slot.ptr());
                    slot.sequence.store(pos + Capacity, std::memory_order_release);
                    notify_write_waiter();
                    return true;
                }
            } else if (diff < 0) {
                // Buffer is empty (producer has not yet published this index)
                return false;
            } else {
                // Another consumer claimed pos; re-read dequeue_pos_
                pos = dequeue_pos_.load(std::memory_order_relaxed);
            }
        }
    }

    // =========================================================================
    // Batched Operations
    // =========================================================================

    /**
     * @brief Pushes up to items.size() elements into the queue.
     * @return Number of elements successfully written.
     */
    size_t push_batch(std::span<T> items) {
        if (items.empty()) return 0;

        uint64_t pos = enqueue_pos_.load(std::memory_order_relaxed);
        size_t claimed = 0;

        while (claimed < items.size()) {
            Slot& slot = slots_[pos & BufferMask];
            const uint64_t seq = slot.sequence.load(std::memory_order_acquire);
            const int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(pos);

            if (diff == 0) {
                if (enqueue_pos_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed)) {
                    std::construct_at(slot.ptr(), std::move(items[claimed]));
                    slot.sequence.store(pos + 1, std::memory_order_release);
                    ++claimed;
                    ++pos;
                }
            } else if (diff < 0) {
                // Queue full
                break;
            } else {
                pos = enqueue_pos_.load(std::memory_order_relaxed);
            }
        }

        if (claimed > 0) {
            notify_read_waiter();
        }
        return claimed;
    }

    /**
     * @brief Atomically claims a contiguous range of up to max_batch_size slots.
     * Yields/waits internally for uncommitted producer slots within its reservation
     * using adaptive backoff, avoiding deadlock across consumer threads.
     * @return Number of elements successfully popped.
     */
    size_t pop_batch(std::span<T> output_buffer, size_t max_batch_size) {
        const size_t request_size = std::min({output_buffer.size(), max_batch_size, Capacity});
        if (request_size == 0) return 0;

        uint64_t deq = dequeue_pos_.load(std::memory_order_relaxed);
        size_t num_claimed = 0;
        uint64_t claim_start = 0;

        for (;;) {
            // Check available elements up to request_size
            const uint64_t enq = enqueue_pos_.load(std::memory_order_relaxed);
            if (deq >= enq) {
                return 0; // Queue empty
            }

            const size_t available = static_cast<size_t>(enq - deq);
            num_claimed = std::min(request_size, available);

            if (dequeue_pos_.compare_exchange_weak(deq, deq + num_claimed, std::memory_order_acq_rel)) {
                claim_start = deq;
                break;
            }
            // deq reloaded by compare_exchange_weak
        }

        // We exclusively own indices [claim_start, claim_start + num_claimed - 1].
        // Drain each slot, resolving non-monotonic publishing via adaptive backoff.
        AdaptiveBackoff backoff;
        for (size_t i = 0; i < num_claimed; ++i) {
            const uint64_t current_pos = claim_start + i;
            Slot& slot = slots_[current_pos & BufferMask];

            backoff.reset();
            while (slot.sequence.load(std::memory_order_acquire) != (current_pos + 1)) {
                backoff.pause();
            }

            output_buffer[i] = std::move(*slot.ptr());
            std::destroy_at(slot.ptr());
            slot.sequence.store(current_pos + Capacity, std::memory_order_release);
        }

        if (num_claimed > 0) {
            notify_write_waiter();
        }
        return num_claimed;
    }

    // =========================================================================
    // Epoll Reactor & Notification Interface
    // =========================================================================

    [[nodiscard]] int get_read_eventfd() const noexcept {
        return read_eventfd_;
    }

    [[nodiscard]] int get_write_eventfd() const noexcept {
        return write_eventfd_;
    }

    /**
     * @brief Registration handshakes with seq_cst store-load fences
     * to eliminate lost-wakeup races before epoll_wait.
     */
    void register_read_waiter() noexcept {
        read_waiters_.fetch_add(1, std::memory_order_seq_cst);
    }

    void unregister_read_waiter() noexcept {
        read_waiters_.fetch_sub(1, std::memory_order_seq_cst);
    }

    void register_write_waiter() noexcept {
        write_waiters_.fetch_add(1, std::memory_order_seq_cst);
    }

    void unregister_write_waiter() noexcept {
        write_waiters_.fetch_sub(1, std::memory_order_seq_cst);
    }

    /**
     * @brief Clears the eventfd semaphore counter after epoll wake-up.
     */
    void drain_read_eventfd() const noexcept {
        uint64_t val = 0;
        [[maybe_unused]] auto res = ::read(read_eventfd_, &val, sizeof(val));
    }

    void drain_write_eventfd() const noexcept {
        uint64_t val = 0;
        [[maybe_unused]] auto res = ::read(write_eventfd_, &val, sizeof(val));
    }

private:
    inline void notify_read_waiter() noexcept {
        // Enforce sequential consistency barrier: slot publish -> read waiters check
        std::atomic_thread_fence(std::memory_order_seq_cst);
        if (read_waiters_.load(std::memory_order_seq_cst) > 0) {
            static constexpr uint64_t increment = 1;
            [[maybe_unused]] auto res = ::write(read_eventfd_, &increment, sizeof(increment));
        }
    }

    inline void notify_write_waiter() noexcept {
        std::atomic_thread_fence(std::memory_order_seq_cst);
        if (write_waiters_.load(std::memory_order_seq_cst) > 0) {
            static constexpr uint64_t increment = 1;
            [[maybe_unused]] auto res = ::write(write_eventfd_, &increment, sizeof(increment));
        }
    }

private:
    // =========================================================================
    // Cacheline-Isolated Memory Layout
    // =========================================================================

    // Producer cursor on its own dedicated cacheline
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> enqueue_pos_{0};

    // Consumer cursor on its own dedicated cacheline
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> dequeue_pos_{0};

    // Notification states isolated from cursor hot paths
    alignas(hardware_destructive_interference_size) std::atomic<int32_t>  read_waiters_{0};
    alignas(hardware_destructive_interference_size) std::atomic<int32_t>  write_waiters_{0};

    int read_eventfd_{-1};
    int write_eventfd_{-1};

    // Array of isolated ring slots
    alignas(hardware_destructive_interference_size) Slot slots_[Capacity];
};

} // namespace pipeline
```

---

### Memory Layout & Cacheline Isolation

Under heavy NUMA and multi-core contention, cacheline false sharing between producers and consumers degrades throughput exponentially due to Read-For-Ownership (RFO) invalidation traffic across the interconnect.

```
+-------------------------------------------------------------------------+
| CACHELINE 0 (Offset 0x000):  std::atomic<uint64_t> enqueue_pos_         |
|                              [Padding: (CacheLineSize - 8) bytes]       |
+-------------------------------------------------------------------------+
| CACHELINE 1 (Offset 0x040):  std::atomic<uint64_t> dequeue_pos_         |
|                              [Padding: (CacheLineSize - 8) bytes]       |
+-------------------------------------------------------------------------+
| CACHELINE 2 (Offset 0x080):  std::atomic<int32_t>  read_waiters_        |
|                              [Padding: (CacheLineSize - 4) bytes]       |
+-------------------------------------------------------------------------+
| CACHELINE 3 (Offset 0x0C0):  std::atomic<int32_t>  write_waiters_       |
|                              int read_eventfd_, write_eventfd_          |
|                              [Padding to CacheLineSize]                 |
+-------------------------------------------------------------------------+
| CACHELINE 4..N (Offset 0x100+): Array of Slot[Capacity]                 |
|   Each Slot is aligned to hardware_destructive_interference_size:       |
|     - std::atomic<uint64_t> sequence (8B)                               |
|     - alignas(alignof(T)) std::byte storage[sizeof(T)]                  |
|     - Remaining bytes padded out to 64/128 bytes                        |
+-------------------------------------------------------------------------+
```

1. **Producer-Consumer Independence**: `enqueue_pos_` and `dequeue_pos_` reside on separate cachelines (`alignas(hardware_destructive_interference_size)`). Pushes only invalidate `enqueue_pos_`, while pops only invalidate `dequeue_pos_`.
2. **Slot Cacheline Isolation**: Each `Slot` is aligned to a cacheline boundary. When a producer populates slot $k$, it modifies only the cacheline for `slots_[k]`, preventing ping-ponging with adjacent slots $k-1$ and $k+1$.

---

### Memory Ordering & Synchronization Proofs

```
      Producer Thread (Slot I)                     Consumer Thread (Slot I)
   ==============================               ==============================
1. CAS enqueue_pos_ (Relaxed)
2. std::construct_at(slot.ptr())
3. slot.sequence.store(I + 1, Release) --------> 4. slot.sequence.load(Acquire) == I + 1
                                                5. Read/Move from slot.ptr()
                                                6. std::destroy_at(slot.ptr())
8. slot.sequence.load(Acquire) == I + C <------- 7. slot.sequence.store(I + C, Release)
```

#### 1. Preventing Speculative Loads of Uninitialized Memory
* **Producer side**: Construction happens in uninitialized storage. Step 3 issues `slot.sequence.store(pos + 1, std::memory_order_release)`. The *Release* barrier guarantees that all prior stores (in-place object construction) are committed to the memory subsystem and visible to all cores before the updated sequence value becomes visible.
* **Consumer side**: Step 4 issues `slot.sequence.load(std::memory_order_acquire)`. The *Acquire* barrier establishes a synchronizes-with relationship with Step 3. It creates a one-way memory barrier prohibiting compiler and CPU speculative loads of `slot.storage` from being executed prior to confirming `seq == pos + 1`.

#### 2. Slot Recirculation & Safe Destruction
* In Step 6, the consumer destroys the object. In Step 7, it updates `slot.sequence.store(pos + Capacity, std::memory_order_release)`.
* When producer cycle $cycle + 1$ arrives at the same slot in Step 8, it performs `slot.sequence.load(std::memory_order_acquire)`. Because of the acquire-release pair, the producer will not begin constructing the next generation object until the previous object's destructor has fully completed.

---

### Batched Claiming & Live-Lock Elimination

#### Batch Claim Mechanics
When a consumer calls `pop_batch(output_buffer, K)`:
1. It calculates $B = \min(K, \text{enq} - \text{deq})$.
2. It executes a single `dequeue_pos_.compare_exchange_weak(deq, deq + B, std::memory_order_acq_rel)`.
3. Consumer $C_1$ now strictly and exclusively owns the index interval $[I, I + B - 1]$.

#### Handling Non-Monotonic Producer Publication
Producers on different cores may experience preemption or thread migration while holding reserved index slots, causing slots to become ready out-of-order (e.g., slot $I+1$ is published before slot $I$).

1. **No Consumer Interference**: Other consumers ($C_2$) will advance `dequeue_pos_` to $[I + B, I + 2B - 1]$ and process their own disjoint ranges simultaneously without blocking on $C_1$'s range.
2. **Adaptive Spin Isolation**: $C_1$ drains slots $[I, I + B - 1]$ sequentially. If slot $I + k$ is not yet published, $C_1$ executes the `AdaptiveBackoff` state machine (`_mm_pause()` $\to$ `sched_yield()`).
3. **No Deadlock Guarantee**: Because the producer has already advanced `enqueue_pos_` beyond $I + k$ when $C_1$ sampled the queue, the producer for slot $I + k$ is already running or runnable. There is no circular dependency.

---

### Epoll Integration & Lost-Wakeup Proof

#### The Lost-Wakeup Race Condition
In a standard uncoordinated check-and-sleep pattern, the following interleaved schedule causes an indefinite sleep:
1. Consumer checks queue $\to$ empty.
2. Producer writes item $\to$ checks waiters $\to$ $0 \to$ does not notify.
3. Consumer increments `read_waiters_` $\to$ enters `epoll_wait()` blocking indefinitely.

#### Sequence Proof of the Dual-Stage Handshake
To prevent this, we enforce a **Store-Load barrier** (`memory_order_seq_cst`) on both sides:

```
          Producer                                       Consumer
--------------------------------------         --------------------------------------
[P1] Publish Slot (Seq Release)                [C1] register_read_waiter() (SeqCst fetch_add)
[P2] atomic_thread_fence(seq_cst)              [C2] Queue Check / pop()
[P3] Read read_waiters_ (SeqCst load)          [C3] If empty: epoll_wait(read_eventfd)
                                               [C4] unregister_read_waiter() (SeqCst fetch_sub)
                                               [C5] drain_read_eventfd()
```

According to the ISO C++ memory model (§31.4 / Sequential Consistency):
* The total global order $S$ of all `seq_cst` operations guarantees that either:
  1. **Case A**: $[C1] \prec [P3]$. The producer loads `read_waiters_ > 0` and issues `eventfd_write`. Even if the consumer reaches $[C3]$ (`epoll_wait`), the eventfd descriptor is already ready for reading (readable counter incremented), causing `epoll_wait` to return immediately.
  2. **Case B**: $[P1] \prec [C2]$. The consumer's re-check at $[C2]$ observes the published slot (`seq == pos + 1`), successfully pops the item without calling `epoll_wait`, and unregisters itself at $[C4]$.

Thus, lost wakeups are mathematically impossible.

