### Production-Grade C++20 Implementation

```cpp
#pragma once

#include <atomic>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <memory>
#include <new>
#include <span>
#include <type_traits>
#include <utility>
#include <thread>
#include <chrono>

#include <sys/eventfd.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#if defined(__x86_64__) || defined(_M_X64)
#include <immintrin.h>
#define CPU_PAUSE() _mm_pause()
#elif defined(__aarch64__)
#define CPU_PAUSE() asm volatile("yield" ::: "memory")
#else
#define CPU_PAUSE() std::this_thread::yield()
#endif

// Dual-cacheline isolation constant across modern microarchitectures (Intel/AMD/ARM Neoverse)
inline constexpr size_t CACHELINE_SIZE = 64;
inline constexpr size_t DUAL_CACHELINE_SIZE = 128;

template <typename T, size_t Capacity>
class LockFreeMPMCQueue {
    static_assert((Capacity >= 2) && ((Capacity & (Capacity - 1)) == 0),
                  "Capacity must be a power of 2 and at least 2.");

private:
    static constexpr size_t INDEX_MASK = Capacity - 1;

    // Slot structure with explicit storage alignment and sequence tag
    struct alignas(CACHELINE_SIZE) Slot {
        std::atomic<uint64_t> sequence;
        alignas(alignof(T)) std::byte storage[sizeof(T)];

        template <typename... Args>
        void construct(Args&&... args) {
            ::new (static_cast<void*>(storage)) T(std::forward<Args>(args)...);
        }

        void destroy() noexcept {
            reinterpret_cast<T*>(storage)->~T();
        }

        T& value() noexcept {
            return *reinterpret_cast<T*>(storage);
        }

        T move_value() noexcept {
            return std::move(*reinterpret_cast<T*>(storage));
        }
    };

    // -------------------------------------------------------------------------
    // Cacheline-isolated Producer Cursor
    // -------------------------------------------------------------------------
    alignas(DUAL_CACHELINE_SIZE) std::atomic<uint64_t> head_{0};
    alignas(CACHELINE_SIZE)      std::atomic<uint64_t> cached_tail_for_producers_{0};

    // -------------------------------------------------------------------------
    // Cacheline-isolated Consumer Cursor
    // -------------------------------------------------------------------------
    alignas(DUAL_CACHELINE_SIZE) std::atomic<uint64_t> tail_{0};
    alignas(CACHELINE_SIZE)      std::atomic<uint64_t> cached_head_for_consumers_{0};

    // -------------------------------------------------------------------------
    // Notification & Waiter Coordination
    // -------------------------------------------------------------------------
    alignas(CACHELINE_SIZE) std::atomic<uint32_t> read_waiters_{0};
    alignas(CACHELINE_SIZE) std::atomic<uint32_t> write_waiters_{0};

    int read_eventfd_{-1};
    int write_eventfd_{-1};

    // -------------------------------------------------------------------------
    // Slot Storage Array
    // -------------------------------------------------------------------------
    alignas(DUAL_CACHELINE_SIZE) Slot buffer_[Capacity];

public:
    LockFreeMPMCQueue() {
        for (size_t i = 0; i < Capacity; ++i) {
            buffer_[i].sequence.store(i, std::memory_order_relaxed);
        }

        read_eventfd_ = ::eventfd(0, EFD_NONBLOCK | EFD_CLOEXEC);
        write_eventfd_ = ::eventfd(0, EFD_NONBLOCK | EFD_CLOEXEC);

        if (read_eventfd_ < 0 || write_eventfd_ < 0) {
            if (read_eventfd_ >= 0) ::close(read_eventfd_);
            if (write_eventfd_ >= 0) ::close(write_eventfd_);
            throw std::system_error(errno, std::generic_category(), "Failed to create eventfd handles");
        }
    }

    ~LockFreeMPMCQueue() {
        // Drain and destroy remaining live objects
        uint64_t t = tail_.load(std::memory_order_relaxed);
        uint64_t h = head_.load(std::memory_order_relaxed);
        while (t < h) {
            Slot& slot = buffer_[t & INDEX_MASK];
            uint64_t seq = slot.sequence.load(std::memory_order_acquire);
            if (seq == t + 1) {
                slot.destroy();
                slot.sequence.store(t + Capacity, std::memory_order_relaxed);
            }
            ++t;
        }

        if (read_eventfd_ >= 0) ::close(read_eventfd_);
        if (write_eventfd_ >= 0) ::close(write_eventfd_);
    }

    LockFreeMPMCQueue(const LockFreeMPMCQueue&) = delete;
    LockFreeMPMCQueue& operator=(const LockFreeMPMCQueue&) = delete;
    LockFreeMPMCQueue(LockFreeMPMCQueue&&) = delete;
    LockFreeMPMCQueue& operator=(LockFreeMPMCQueue&&) = delete;

    [[nodiscard]] int get_read_eventfd() const noexcept { return read_eventfd_; }
    [[nodiscard]] int get_write_eventfd() const noexcept { return write_eventfd_; }

    void register_read_waiter() noexcept {
        read_waiters_.fetch_add(1, std::memory_order_seq_cst);
    }

    void unregister_read_waiter() noexcept {
        read_waiters_.fetch_sub(1, std::memory_order_seq_cst);
    }

    void register_write_waiter() noexcept {
        write_waiters_.fetch_add(1, std::memory_order_seq_cst);
    }

    void unregister_write_waiter() noexcept {
        write_waiters_.fetch_sub(1, std::memory_order_seq_cst);
    }

private:
    void notify_read_waiters() noexcept {
        // Full barrier to synchronize with consumer entering epoll_wait
        std::atomic_thread_fence(std::memory_order_seq_cst);
        if (read_waiters_.load(std::memory_order_relaxed) > 0) {
            uint64_t counter = 1;
            ssize_t res = ::write(read_eventfd_, &counter, sizeof(counter));
            (void)res; // EAGAIN or success is acceptable
        }
    }

    void notify_write_waiters() noexcept {
        std::atomic_thread_fence(std::memory_order_seq_cst);
        if (write_waiters_.load(std::memory_order_relaxed) > 0) {
            uint64_t counter = 1;
            ssize_t res = ::write(write_eventfd_, &counter, sizeof(counter));
            (void)res;
        }
    }

    static void adaptive_backoff(size_t step) noexcept {
        if (step < 16) {
            CPU_PAUSE();
        } else if (step < 32) {
            for (int i = 0; i < 4; ++i) CPU_PAUSE();
        } else {
            std::this_thread::yield();
        }
    }

public:
    // -------------------------------------------------------------------------
    // Single-Item Emplace
    // -------------------------------------------------------------------------
    template <typename... Args>
    bool emplace(Args&&... args) {
        uint64_t head = head_.load(std::memory_order_relaxed);

        for (;;) {
            Slot& slot = buffer_[head & INDEX_MASK];
            uint64_t seq = slot.sequence.load(std::memory_order_acquire);
            int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(head);

            if (diff == 0) {
                // Slot is ready for publication at 'head'
                if (head_.compare_exchange_weak(head, head + 1, std::memory_order_relaxed)) {
                    slot.construct(std::forward<Args>(args)...);
                    slot.sequence.store(head + 1, std::memory_order_release);
                    notify_read_waiters();
                    return true;
                }
            } else if (diff < 0) {
                // Queue is full or slot is wrapped behind
                uint64_t tail = tail_.load(std::memory_order_relaxed);
                if (head - tail >= Capacity) {
                    return false;
                }
                head = head_.load(std::memory_order_relaxed);
            } else {
                // Slot sequence advanced past head; re-sample cursor
                head = head_.load(std::memory_order_relaxed);
            }
        }
    }

    // -------------------------------------------------------------------------
    // Single-Item Pop
    // -------------------------------------------------------------------------
    bool pop(T& destination) {
        uint64_t tail = tail_.load(std::memory_order_relaxed);

        for (;;) {
            Slot& slot = buffer_[tail & INDEX_MASK];
            uint64_t seq = slot.sequence.load(std::memory_order_acquire);
            int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(tail + 1);

            if (diff == 0) {
                // Slot is ready for consumption at 'tail'
                if (tail_.compare_exchange_weak(tail, tail + 1, std::memory_order_relaxed)) {
                    destination = slot.move_value();
                    slot.destroy();
                    slot.sequence.store(tail + Capacity, std::memory_order_release);
                    notify_write_waiters();
                    return true;
                }
            } else if (diff < 0) {
                // Queue is empty
                uint64_t head = head_.load(std::memory_order_relaxed);
                if (tail >= head) {
                    return false;
                }
                tail = tail_.load(std::memory_order_relaxed);
            } else {
                // Slot sequence advanced; re-sample tail
                tail = tail_.load(std::memory_order_relaxed);
            }
        }
    }

    // -------------------------------------------------------------------------
    // Batched Push Operation
    // -------------------------------------------------------------------------
    size_t push_batch(std::span<T> items) {
        if (items.empty()) return 0;

        uint64_t head = head_.load(std::memory_order_relaxed);
        uint64_t cached_tail = cached_tail_for_producers_.load(std::memory_order_relaxed);
        size_t batch_size = 0;
        uint64_t claim_start = 0;

        for (;;) {
            int64_t available = static_cast<int64_t>(Capacity) - static_cast<int64_t>(head - cached_tail);
            if (available <= 0) {
                cached_tail = tail_.load(std::memory_order_acquire);
                cached_tail_for_producers_.store(cached_tail, std::memory_order_relaxed);
                available = static_cast<int64_t>(Capacity) - static_cast<int64_t>(head - cached_tail);
                if (available <= 0) {
                    return 0; // Completely full
                }
            }

            batch_size = std::min(items.size(), static_cast<size_t>(available));
            if (head_.compare_exchange_weak(head, head + batch_size,
                                            std::memory_order_acquire,
                                            std::memory_order_relaxed)) {
                claim_start = head;
                break;
            }
            // 'head' is re-read on CAS failure
        }

        // Populate claimed slots
        for (size_t i = 0; i < batch_size; ++i) {
            uint64_t idx = claim_start + i;
            Slot& slot = buffer_[idx & INDEX_MASK];

            // Wait for slot to be recycled by consumer: sequence must reach 'idx'
            size_t backoff_step = 0;
            while (slot.sequence.load(std::memory_order_acquire) != idx) {
                adaptive_backoff(backoff_step++);
            }

            slot.construct(std::move(items[i]));
            slot.sequence.store(idx + 1, std::memory_order_release);
        }

        notify_read_waiters();
        return batch_size;
    }

    // -------------------------------------------------------------------------
    // Batched Pop (Drain) Operation
    // -------------------------------------------------------------------------
    size_t pop_batch(std::span<T> output_buffer, size_t max_batch_size) {
        if (output_buffer.empty() || max_batch_size == 0) return 0;

        const size_t requested = std::min(output_buffer.size(), max_batch_size);
        uint64_t tail = tail_.load(std::memory_order_relaxed);
        uint64_t cached_head = cached_head_for_consumers_.load(std::memory_order_relaxed);
        size_t batch_size = 0;
        uint64_t claim_start = 0;

        for (;;) {
            int64_t available = static_cast<int64_t>(cached_head - tail);
            if (available <= 0) {
                cached_head = head_.load(std::memory_order_acquire);
                cached_head_for_consumers_.store(cached_head, std::memory_order_relaxed);
                available = static_cast<int64_t>(cached_head - tail);
                if (available <= 0) {
                    return 0; // Empty
                }
            }

            batch_size = std::min(requested, static_cast<size_t>(available));
            if (tail_.compare_exchange_weak(tail, tail + batch_size,
                                            std::memory_order_acquire,
                                            std::memory_order_relaxed)) {
                claim_start = tail;
                break;
            }
        }

        // Drain claimed slots
        for (size_t i = 0; i < batch_size; ++i) {
            uint64_t idx = claim_start + i;
            Slot& slot = buffer_[idx & INDEX_MASK];

            // Wait for producer to publish: sequence must reach 'idx + 1'
            size_t backoff_step = 0;
            while (slot.sequence.load(std::memory_order_acquire) != (idx + 1)) {
                adaptive_backoff(backoff_step++);
            }

            output_buffer[i] = slot.move_value();
            slot.destroy();
            slot.sequence.store(idx + Capacity, std::memory_order_release);
        }

        notify_write_waiters();
        return batch_size;
    }
};
```

---

### Cache-Conscious Memory Architecture

1. **Dual-Cacheline Isolation (`DUAL_CACHELINE_SIZE = 128`)**:
   - Intel and AMD spatial prefetchers prefetch adjacent 64-byte blocks (pairs of lines). Aligning `head_` and `tail_` on 128-byte boundaries prevents false sharing across producer and consumer cores.
2. **Local Caching of Counters**:
   - `cached_tail_for_producers_` and `cached_head_for_consumers_` prevent producers from repeatedly invalidating the true consumer `tail_` (and vice versa) during capacity checks.
3. **Per-Slot Cacheline Alignment**:
   - Each `Slot` is `alignas(64)`, ensuring that a producer publishing payload data into slot $k$ does not invalidate slot $k-1$ or $k+1$ currently being drained by parallel consumer cores.

---

### Memory Model & Correctness Verification

#### 1. Slot Publication Synchronization
- **Producer ($\text{Thread } P$)**:
  1. Writes payload to `slot.storage`.
  2. Executes `slot.sequence.store(idx + 1, memory_order_release)`.
- **Consumer ($\text{Thread } C$)**:
  1. Reads `slot.sequence.load(memory_order_acquire)` verifying it equals `idx + 1`.
  2. Performs move extraction from `slot.storage`.

*Proof of Non-Speculative Visibility*:
The release store on the sequence counter establishes a *synchronizes-with* edge with the acquire load on the consumer. Under the ISO C++ memory model and ARMv8 weak memory architectures:
$$\text{Write}(\text{Payload}) \xrightarrow{\text{sequenced-before}} \text{Store}_{\text{rel}}(\text{Seq}) \xrightarrow{\text{synchronizes-with}} \text{Load}_{\text{acq}}(\text{Seq}) \xrightarrow{\text{sequenced-before}} \text{Read}(\text{Payload})$$
This ensures the compiler and CPU cannot hoist reads of `slot.storage` before `slot.sequence` equals `idx + 1`.

#### 2. Progress Guarantee & Non-Interference in Batched Claims
- When $C_1$ claims $[J, J+B_1-1]$ and $C_2$ claims $[J+B_1, J+B_1+B_2-1]$:
  - $C_2$'s slot sequence dependencies ($idx_{C_2} + 1$) depend strictly on **producers** publishing to those slots, not on $C_1$'s read throughput.
  - $C_2$ does not block on $C_1$; both consumers proceed concurrently in parallel slot index ranges.

#### 3. Epoll/Eventfd Lost-Wakeup Race Mitigation Proof
The race condition is eliminated by establishing a sequential consistency total order:
- **Consumer Sleep Sequence**:
  1. `register_read_waiter()`: `read_waiters_.fetch_add(1, memory_order_seq_cst)`.
  2. Queue emptiness re-check (via non-blocking drain attempt).
  3. If empty $\implies$ `epoll_wait(epfd, ...)` on `read_eventfd_`.
  4. On return $\implies$ `unregister_read_waiter()`: `read_waiters_.fetch_sub(1, memory_order_seq_cst)`.

- **Producer Push Sequence**:
  1. Complete slot write and advance sequence with `release`.
  2. `std::atomic_thread_fence(memory_order_seq_cst)`.
  3. Load `read_waiters_.load(memory_order_relaxed)`. If $> 0$, invoke `eventfd_write`.

*Sequencing Invariant*:
If the consumer re-checks the queue and finds it empty, the write of the item was not yet visible. Therefore, the producer's execution of step 3 **must** observe `read_waiters_ > 0` due to the `seq_cst` store/load barrier duality ($S_{\text{consumer}} \prec L_{\text{producer}}$), guaranteeing `eventfd_write` is dispatched.

