#pragma once

#include <atomic>
#include <cstddef>
#include <cstdint>
#include <memory>
#include <new>
#include <span>
#include <thread>
#include <type_traits>
#include <utility>

#include <fcntl.h>
#include <sys/eventfd.h>
#include <unistd.h>

#if defined(__x86_64__) || defined(_M_X64)
#include <immintrin.h>
#endif

namespace lowlatency {

// Fallback for hardware interference sizes if not defined or conservative
#if defined(__cpp_lib_hardware_interference_size)
using std::hardware_constructive_interference_size;
using std::hardware_destructive_interference_size;
#else
constexpr size_t hardware_destructive_interference_size = 64;
constexpr size_t hardware_constructive_interference_size = 64;
#endif

/**
 * @brief CPU pause primitive for adaptive spin-wait loops.
 */
inline void cpu_relax() noexcept {
#if defined(__x86_64__) || defined(_M_X64)
    _mm_pause();
#elif defined(__aarch64__)
    asm volatile("yield" ::: "memory");
#else
    std::this_thread::yield();
#endif
}

/**
 * @brief Multi-stage adaptive backoff policy.
 */
class Backoff {
    static constexpr uint32_t kSpinYieldThreshold = 16;
    static constexpr uint32_t kThreadYieldThreshold = 32;
    uint32_t step_{0};

public:
    void spin() noexcept {
        if (step_ < kSpinYieldThreshold) {
            cpu_relax();
        } else if (step_ < kThreadYieldThreshold) {
            std::this_thread::yield();
        } else {
            // Adaptive sleep for extreme preemption latency
            std::this_thread::yield();
        }
        ++step_;
    }

    void reset() noexcept {
        step_ = 0;
    }
};

template <typename T, size_t Capacity>
class LockFreeMPMCQueue {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of 2");
    static_assert(Capacity >= 2, "Capacity must be at least 2");

    static constexpr size_t kIndexMask = Capacity - 1;
    static constexpr size_t kCacheLineSize = hardware_destructive_interference_size;

    // Slot layout: Isolated to a full cache line to eliminate false sharing.
    struct alignas(kCacheLineSize) Slot {
        std::atomic<uint64_t> sequence{0};
        alignas(alignof(T)) std::byte storage[sizeof(T)];

        template <typename... Args>
        void construct(Args&&... args) {
            ::new (static_cast<void*>(storage)) T(std::forward<Args>(args)...);
        }

        void destroy() noexcept {
            std::destroy_at(reinterpret_cast<T*>(storage));
        }

        T& value() noexcept {
            return *reinterpret_cast<T*>(storage);
        }

        const T& value() const noexcept {
            return *reinterpret_cast<const T*>(storage);
        }
    };

public:
    LockFreeMPMCQueue()
        : read_fd_(::eventfd(0, EFD_NONBLOCK | EFD_CLOEXEC)),
          write_fd_(::eventfd(0, EFD_NONBLOCK | EFD_CLOEXEC)) {
        if (read_fd_ < 0 || write_fd_ < 0) {
            if (read_fd_ >= 0) ::close(read_fd_);
            if (write_fd_ >= 0) ::close(write_fd_);
            throw std::system_error(errno, std::generic_category(), "Failed to create eventfd");
        }

        // Initialize sequences: slot i has initial sequence i
        for (size_t i = 0; i < Capacity; ++i) {
            buffer_[i].sequence.store(i, std::memory_order_relaxed);
        }
        enqueue_pos_.store(0, std::memory_order_relaxed);
        dequeue_pos_.store(0, std::memory_order_relaxed);
        read_waiters_.store(0, std::memory_order_relaxed);
        write_waiters_.store(0, std::memory_order_relaxed);
    }

    ~LockFreeMPMCQueue() {
        // Drain any remaining live elements
        T temp;
        while (pop(temp)) {}

        if (read_fd_ >= 0) ::close(read_fd_);
        if (write_fd_ >= 0) ::close(write_fd_);
    }

    LockFreeMPMCQueue(const LockFreeMPMCQueue&) = delete;
    LockFreeMPMCQueue& operator=(const LockFreeMPMCQueue&) = delete;
    LockFreeMPMCQueue(LockFreeMPMCQueue&&) = delete;
    LockFreeMPMCQueue& operator=(LockFreeMPMCQueue&&) = delete;

    // =========================================================================
    // Single-item non-blocking operations
    // =========================================================================

    template <typename... Args>
    bool emplace(Args&&... args) {
        uint64_t pos = enqueue_pos_.load(std::memory_order_relaxed);
        for (;;) {
            Slot& slot = buffer_[pos & kIndexMask];
            const uint64_t seq = slot.sequence.load(std::memory_order_acquire);
            const int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(pos);

            if (diff == 0) {
                // Slot is ready for this turn; attempt to claim ticket
                if (enqueue_pos_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed)) {
                    slot.construct(std::forward<Args>(args)...);
                    slot.sequence.store(pos + 1, std::memory_order_release);
                    notify_read_waiters();
                    return true;
                }
            } else if (diff < 0) {
                // Buffer is full (slot is still occupied by consumer in previous lap)
                return false;
            } else {
                // Another producer beat us; reload position
                pos = enqueue_pos_.load(std::memory_order_relaxed);
            }
        }
    }

    bool push(const T& item) { return emplace(item); }
    bool push(T&& item) { return emplace(std::move(item)); }

    bool pop(T& destination) {
        uint64_t pos = dequeue_pos_.load(std::memory_order_relaxed);
        for (;;) {
            Slot& slot = buffer_[pos & kIndexMask];
            const uint64_t seq = slot.sequence.load(std::memory_order_acquire);
            const int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(pos + 1);

            if (diff == 0) {
                // Slot contains valid payload for this consumer generation
                if (dequeue_pos_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed)) {
                    destination = std::move(slot.value());
                    slot.destroy();
                    slot.sequence.store(pos + Capacity, std::memory_order_release);
                    notify_write_waiters();
                    return true;
                }
            } else if (diff < 0) {
                // Queue is empty (producer hasn't committed payload yet)
                return false;
            } else {
                // Another consumer advanced dequeue_pos_; retry
                pos = dequeue_pos_.load(std::memory_order_relaxed);
            }
        }
    }

    // =========================================================================
    // Batched Operations
    // =========================================================================

    /**
     * @brief Pushes up to items.size() elements in a batch.
     * @return Number of elements successfully written.
     */
    size_t push_batch(std::span<T> items) {
        if (items.empty()) return 0;

        uint64_t head = enqueue_pos_.load(std::memory_order_relaxed);
        size_t claim_count = 0;

        while (claim_count == 0) {
            const uint64_t tail = dequeue_pos_.load(std::memory_order_relaxed);
            const size_t occupied = static_cast<size_t>(head - tail);
            if (occupied >= Capacity) {
                return 0; // Completely full
            }

            const size_t available = Capacity - occupied;
            claim_count = std::min(items.size(), available);

            if (!enqueue_pos_.compare_exchange_weak(head, head + claim_count, std::memory_order_relaxed)) {
                claim_count = 0; // CAS failed; re-evaluate
            }
        }

        // Thread exclusively owns slots [head, head + claim_count - 1]
        Backoff backoff;
        for (size_t i = 0; i < claim_count; ++i) {
            const uint64_t slot_idx = head + i;
            Slot& slot = buffer_[slot_idx & kIndexMask];

            // Wait until previous consumer has completed lap-around reset
            while (slot.sequence.load(std::memory_order_acquire) != slot_idx) {
                backoff.spin();
            }
            backoff.reset();

            slot.construct(std::move(items[i]));
            slot.sequence.store(slot_idx + 1, std::memory_order_release);
        }

        notify_read_waiters();
        return claim_count;
    }

    /**
     * @brief Atomically claims and drains up to max_batch_size elements.
     * @return Number of elements successfully extracted.
     */
    size_t pop_batch(std::span<T> output_buffer, size_t max_batch_size) {
        const size_t max_items = std::min(output_buffer.size(), max_batch_size);
        if (max_items == 0) return 0;

        uint64_t tail = dequeue_pos_.load(std::memory_order_relaxed);
        size_t claim_count = 0;

        while (claim_count == 0) {
            const uint64_t head = enqueue_pos_.load(std::memory_order_relaxed);
            if (tail >= head) {
                return 0; // Queue empty
            }

            const size_t available = static_cast<size_t>(head - tail);
            claim_count = std::min(max_items, available);

            if (!dequeue_pos_.compare_exchange_weak(tail, tail + claim_count, std::memory_order_relaxed)) {
                claim_count = 0; // CAS failed; retry
            }
        }

        // Thread exclusively owns slots [tail, tail + claim_count - 1]
        Backoff backoff;
        for (size_t i = 0; i < claim_count; ++i) {
            const uint64_t slot_idx = tail + i;
            Slot& slot = buffer_[slot_idx & kIndexMask];

            // Safely wait for uncommitted slot without stalling subsequent claim ranges
            while (slot.sequence.load(std::memory_order_acquire) != (slot_idx + 1)) {
                backoff.spin();
            }
            backoff.reset();

            output_buffer[i] = std::move(slot.value());
            slot.destroy();
            slot.sequence.store(slot_idx + Capacity, std::memory_order_release);
        }

        notify_write_waiters();
        return claim_count;
    }

    // =========================================================================
    // Epoll / Eventfd Reactor Integration
    // =========================================================================

    [[nodiscard]] int get_read_eventfd() const noexcept { return read_fd_; }
    [[nodiscard]] int get_write_eventfd() const noexcept { return write_fd_; }

    void register_read_waiter() noexcept {
        read_waiters_.fetch_add(1, std::memory_order_seq_cst);
    }

    void unregister_read_waiter() noexcept {
        read_waiters_.fetch_sub(1, std::memory_order_seq_cst);
    }

    void register_write_waiter() noexcept {
        write_waiters_.fetch_add(1, std::memory_order_seq_cst);
    }

    void unregister_write_waiter() noexcept {
        write_waiters_.fetch_sub(1, std::memory_order_seq_cst);
    }

    /**
     * @brief Drains the internal eventfd counter (required after epoll_wait wakeups).
     */
    static void drain_eventfd(int fd) noexcept {
        uint64_t val = 0;
        [[maybe_unused]] auto res = ::read(fd, &val, sizeof(val));
    }

private:
    void notify_read_waiters() noexcept {
        // Sequential consistency fence to ensure memory visibility before checking waiter count
        std::atomic_thread_fence(std::memory_order_seq_cst);
        if (read_waiters_.load(std::memory_order_relaxed) > 0) {
            const uint64_t val = 1;
            [[maybe_unused]] auto res = ::write(read_fd_, &val, sizeof(val));
        }
    }

    void notify_write_waiters() noexcept {
        std::atomic_thread_fence(std::memory_order_seq_cst);
        if (write_waiters_.load(std::memory_order_relaxed) > 0) {
            const uint64_t val = 1;
            [[maybe_unused]] auto res = ::write(write_fd_, &val, sizeof(val));
        }
    }

private:
    // =========================================================================
    // Cacheline Layout & Padding
    // =========================================================================

    // Producer cursor cacheline
    alignas(kCacheLineSize) std::atomic<uint64_t> enqueue_pos_{0};

    // Consumer cursor cacheline
    alignas(kCacheLineSize) std::atomic<uint64_t> dequeue_pos_{0};

    // Waiter counters & file descriptors
    alignas(kCacheLineSize) std::atomic<uint32_t> read_waiters_{0};
    std::atomic<uint32_t> write_waiters_{0};
    int read_fd_{-1};
    int write_fd_{-1};

    // Data buffer: each slot is cacheline-aligned
    alignas(kCacheLineSize) Slot buffer_[Capacity];
};

} // namespace lowlatency
