// 4. Lock-Free MVCC Version Chain Data Structures
// ============================================================================

/// In-memory MVCC node holding a specific version of a record.
/// Padded to 64 bytes to eliminate false sharing between cache lines.
#[repr(C, align(64))]
pub struct VersionRecord {
    /// Monotonic timestamp of the transaction that created this version.
    pub tx_id_created: TxId,
    /// Transaction that deleted/superseded this version. Set to SENTINEL_TX_ACTIVE if live.
    pub tx_id_deleted: AtomicU64,
    /// Length of the payload in bytes.
    pub value_len: u32,
    /// Node flags (Tombstone, Inlined, etc.).
    pub flags: u16,
    /// Unused padding for struct alignment.
    pub _reserved: u16,
    /// Lock-free atomic link to the preceding historical version.
    pub next: AtomicPtr<VersionRecord>,
    /// Inline payload pointer or dynamic buffer offset.
    pub payload: [u8; 0],
}

impl VersionRecord {
    pub fn allocate(
        tx_id_created: TxId,
        flags: u16,
        value: &[u8],
        next: *mut VersionRecord,
    ) -> *mut Self {
        let base_size = std::mem::size_of::<VersionRecord>();
        let total_size = base_size + value.len();
        let layout = Layout::from_size_align(total_size, CACHE_LINE_SIZE)
            .expect("Valid VersionRecord layout");

        unsafe {
            let raw = alloc_zeroed(layout) as *mut VersionRecord;
            if raw.is_null() {
                std::alloc::handle_alloc_error(layout);
            }

            ptr::write(&mut (*raw).tx_id_created, tx_id_created);
            // Invariant: Initial state is SENTINEL_TX_ACTIVE using Relaxed ordering
            // because publication is synchronized through pointer publication via CAS/Release.
            (*raw).tx_id_deleted.store(SENTINEL_TX_ACTIVE, Ordering::Relaxed);
            (*raw).value_len = value.len() as u32;
            (*raw).flags = flags;
            (*raw)._reserved = 0;
            (*raw).next.store(next, Ordering::Relaxed);

            let payload_ptr = (raw as *mut u8).add(base_size);
            ptr::copy_nonoverlapping(value.as_ptr(), payload_ptr, value.len());

            raw
        }
    }

    #[inline(always)]
    pub unsafe fn value_bytes<'a>(ptr: *const VersionRecord) -> &'a [u8] {
        let base_size = std::mem::size_of::<VersionRecord>();
        let val_len = (*ptr).value_len as usize;
        let payload_ptr = (ptr as *const u8).add(base_size);
        std::slice::from_raw_parts(payload_ptr, val_len)
    }

    pub unsafe fn deallocate(ptr: *mut Self) {
        if ptr.is_null() {
            return;
        }
        let total_size = std::mem::size_of::<VersionRecord>() + (*ptr).value_len as usize;
        let layout = Layout::from_size_align(total_size, CACHE_LINE_SIZE).unwrap();
        dealloc(ptr as *mut u8, layout);
    }
}

