// 6. Lock-Free MVCC Index Map
// ============================================================================

/// Lock-free fixed-bucket hash map indexing key -> atomic VersionRecord chain.
pub struct MvccIndex {
    buckets: Box<[AtomicPtr<VersionRecord>]>,
    mask: usize,
}

impl MvccIndex {
    pub fn new(capacity: usize) -> Self {
        let power_of_two = capacity.next_power_of_two();
        let mut buckets = Vec::with_capacity(power_of_two);
        for _ in 0..power_of_two {
            buckets.push(AtomicPtr::new(ptr::null_mut()));
        }

        Self {
            buckets: buckets.into_boxed_slice(),
            mask: power_of_two - 1,
        }
    }

    #[inline(always)]
    fn hash_key(&self, key: Key) -> usize {
        let mut x = key;
        x ^= x >> 30;
        x = x.wrapping_mul(0xbf58476d1ce4e5b9);
        x ^= x >> 27;
        x = x.wrapping_mul(0x94d049bb133111eb);
        x ^= x >> 31;
        (x as usize) & self.mask
    }

    #[inline(always)]
    pub fn get_head(&self, key: Key) -> *mut VersionRecord {
        let bucket = self.hash_key(key);
        // Memory Ordering Invariant:
        // Acquire order ensures visibility of VersionRecord fields published by CAS Release.
        self.buckets[bucket].load(Ordering::Acquire)
    }

    #[inline(always)]
    pub fn cas_head(&self, key: Key, old: *mut VersionRecord, new: *mut VersionRecord) -> bool {
        let bucket = self.hash_key(key);
        // Memory Ordering Invariant:
        // AcqRel ensures synchronization on update: Acquire loads current head, Release publishes new node.
        self.buckets[bucket]
            .compare_exchange_weak(old, new, Ordering::AcqRel, Ordering::Acquire)
            .is_ok()
    }
}

