#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IsolationLevel {
    SnapshotIsolation,
    ReadCommitted,
}

#[derive(Debug)]
pub enum TxError {
    WriteConflict,
    WalError(String),
    Aborted,
}

pub struct TxContext {
    pub tx_id: TxId,
    pub read_snapshot_ts: TxId,
    pub isolation: IsolationLevel,
    pub writes: Vec<(Key, Option<Vec<u8>>)>, // None signifies deletion
}

pub struct StorageEngine {
    index: Arc<MvccIndex>,
    epoch_mgr: Arc<EpochManager>,
    wal: Arc<WalAppender>,
    next_tx_id: AtomicU64,
}

impl StorageEngine {
    pub fn new<P: AsRef<Path>>(wal_path: P, index_capacity: usize) -> std::io::Result<Self> {
        let wal = WalAppender::open(wal_path)?;
        Ok(Self {
            index: Arc::new(MvccIndex::new(index_capacity)),
            epoch_mgr: Arc::new(EpochManager::new()),
            wal,
            next_tx_id: AtomicU64::new(100),
        })
    }

    pub fn register_thread(&self) -> ThreadRegistration {
        self.epoch_mgr.register()
    }

    pub fn begin_transaction(&self, isolation: IsolationLevel) -> TxContext {
        let snapshot_ts = self.next_tx_id.load(Ordering::Acquire);
        TxContext {
            tx_id: snapshot_ts,
            read_snapshot_ts: snapshot_ts,
            isolation,
            writes: Vec::with_capacity(16),
        }
    }

    /// Read path: Wait-free snapshot version chain traversal.
    pub fn read(
        &self,
        _guard: &EpochGuard,
        tx: &TxContext,
        key: Key,
    ) -> Option<Vec<u8>> {
        // 1. Check thread-local uncommitted write buffer (Read-Your-Own-Writes)
        for (w_key, w_val) in tx.writes.iter().rev() {
            if *w_key == key {
                return w_val.clone();
            }
        }

        // 2. Lock-free traversal over the MVCC version chain
        let mut curr_ptr = self.index.get_head(key);

        while !curr_ptr.is_null() {
            let record = unsafe { &*curr_ptr };

            let created = record.tx_id_created;
            let deleted = record.tx_id_deleted.load(Ordering::Acquire);

            // Snapshot visibility rules:
            // Visible iff created <= read_snapshot_ts and (deleted > read_snapshot_ts)
            if created <= tx.read_snapshot_ts && (deleted == SENTINEL_TX_ACTIVE || deleted > tx.read_snapshot_ts) {
                if (record.flags & FLAG_TOMBSTONE) != 0 {
                    return None; // Deleted record
                }
                let bytes = unsafe { VersionRecord::value_bytes(curr_ptr) };
                return Some(bytes.to_vec());
            }

            // Memory Ordering Invariant:
            // Acquire traversal ensures preceding versions linked in the chain are visibly populated.
            curr_ptr = record.next.load(Ordering::Acquire);
        }

        None
    }

    pub fn write(&self, tx: &mut TxContext, key: Key, value: Vec<u8>) -> Result<(), TxError> {
        tx.writes.push((key, Some(value)));
        Ok(())
    }

    pub fn delete(&self, tx: &mut TxContext, key: Key) -> Result<(), TxError> {
        tx.writes.push((key, None));
        Ok(())
    }

    /// Group-commit transaction and install version chain records via CAS.
    pub fn commit(&self, mut tx: TxContext) -> Result<Lsn, TxError> {
        if tx.writes.is_empty() {
            return Ok(0);
        }

        let commit_tx_id = self.next_tx_id.fetch_add(1, Ordering::SeqCst);
        tx.tx_id = commit_tx_id;

        // Step 1: Write BEGIN & Payloads to WAL
        self.wal
            .append_record(commit_tx_id, WAL_RECORD_TX_BEGIN, 0, &[])
            .map_err(TxError::WalError)?;

        for (key, val_opt) in &tx.writes {
            let (rec_type, payload) = match val_opt {
                Some(v) => (WAL_RECORD_PUT, v.as_slice()),
                None => (WAL_RECORD_DELETE, [].as_slice()),
            };
            self.wal
                .append_record(commit_tx_id, rec_type, *key, payload)
                .map_err(TxError::WalError)?;
        }

        let commit_lsn = self
            .wal
            .append_record(commit_tx_id, WAL_RECORD_TX_COMMIT, 0, &[])
            .map_err(TxError::WalError)?;

        // Step 2: In-Memory MVCC CAS Installation
        for (key, val_opt) in &tx.writes {
            let (flags, payload_slice) = match val_opt {
                Some(v) => (0u16, v.as_slice()),
                None => (FLAG_TOMBSTONE, [].as_slice()),
            };

            loop {
                let head = self.index.get_head(*key);

                // First-committer-wins write-conflict detection
                if !head.is_null() {
                    let head_ref = unsafe { &*head };
                    let head_del = head_ref.tx_id_deleted.load(Ordering::Acquire);
                    if head_ref.tx_id_created > tx.read_snapshot_ts
                        || (head_del != SENTINEL_TX_ACTIVE && head_del > tx.read_snapshot_ts)
                    {
                        return Err(TxError::WriteConflict);
                    }
                }

                let new_node = VersionRecord::allocate(commit_tx_id, flags, payload_slice, head);

                // Publish new version pointer via CAS
                if self.index.cas_head(*key, head, new_node) {
                    if !head.is_null() {
                        // Mark old head as superseded by this commit timestamp
                        unsafe {
                            (*head)
                                .tx_id_deleted
                                .store(commit_tx_id, Ordering::Release);
                        }
                    }
                    break;
                } else {
                    // CAS failed; deallocate unused allocated node and retry
                    unsafe {
                        VersionRecord::deallocate(new_node);
                    }
                }
            }
        }

        // Step 3: Wait for group-commit WAL persistence
        self.wal.wait_for_commit(commit_lsn);

        Ok(commit_lsn)
    }

    /// Prune unlinked historical versions older than the oldest active reader snapshot.
    pub fn gc_sweep(&self) {
        self.epoch_mgr.try_advance_and_reclaim();
    }
}

