        let ops_per_thread = 2000;
        let barrier = Arc::new(Barrier::new(num_writers + num_readers + 1));
        let mut handles = Vec::new();

        // 1. Spawn Concurrent Writers
        for t_id in 0..num_writers {
            let eng = Arc::clone(&engine);
            let bar = Arc::clone(&barrier);
            handles.push(thread::spawn(move || {
                let reg = eng.register_thread();
                bar.wait();

                for i in 0..ops_per_thread {
                    let key = (i % 50) as u64; // Key collision domain
                    let mut tx = eng.begin_transaction(IsolationLevel::SnapshotIsolation);
                    let val = format!("val_w{}_{}", t_id, i).into_bytes();
                    eng.write(&mut tx, key, val).unwrap();
                    let _ = eng.commit(tx);
                }
            }));
        }

        // 2. Spawn Concurrent Readers (Assert Snapshot Repeatable Reads)
        let read_violations = Arc::new(AtomicUsize::new(0));
        for _ in 0..num_readers {
            let eng = Arc::clone(&engine);
            let bar = Arc::clone(&barrier);
            let violations = Arc::clone(&read_violations);
            handles.push(thread::spawn(move || {
                let reg = eng.register_thread();
                bar.wait();

                for _ in 0..ops_per_thread {
                    let guard = reg.enter();
                    let tx = eng.begin_transaction(IsolationLevel::SnapshotIsolation);
                    let key = 10u64;

                    let first_read = eng.read(&guard, &tx, key);
                    // Read again inside the same snapshot context; repeatable read invariant
                    let second_read = eng.read(&guard, &tx, key);

                    if first_read != second_read {
                        violations.fetch_add(1, Ordering::SeqCst);
                    }
                    drop(guard);
                }
            }));
        }

        // 3. Background GC Sweeper
        let eng_gc = Arc::clone(&engine);
        let bar_gc = Arc::clone(&barrier);
        let gc_handle = thread::spawn(move || {
            bar_gc.wait();
            for _ in 0..50 {
                thread::sleep(Duration::from_millis(2));
                eng_gc.gc_sweep();
            }
        });

        for h in handles {
            h.join().unwrap();
        }
        gc_handle.join().unwrap();

        assert_eq!(
            read_violations.load(Ordering::SeqCst),
            0,
            "Repeatable read isolation violations detected!"
        );

        // 4. Teardown Engine & Test Post-Crash Recovery
        engine.wal.shutdown();

        let (recovered_index, max_lsn) =
            RecoveryManager::recover(&temp.path, 65536).expect("Recovery failed");

        assert!(max_lsn > 0, "LSN counter did not advance");

        // Verify that the recovered head points to valid reconstructed data
        let sample_head = recovered_index.get_head(10);
        assert!(!sample_head.is_null(), "Key 10 must exist post-recovery");
        let sample_val = unsafe { VersionRecord::value_bytes(sample_head) };
        assert!(!sample_val.is_empty(), "Payload must be reconstructed");
    }
}

