// ============================================================================
// Section 1: Low-Level Primitives, HLC, and Alignments
// ============================================================================

constexpr size_t CACHELINE_SIZE = 64;
constexpr size_t SECTOR_SIZE = 4096;

inline void FutexWake(volatile uint32_t* addr, int count = 1) {
    syscall(SYS_futex, addr, FUTEX_WAKE_PRIVATE, count, nullptr, nullptr, 0);
}

inline void FutexWait(volatile uint32_t* addr, uint32_t val) {
