}

// 64-bit CRC32C software implementation for WAL record checksumming
uint32_t CalculateCRC32C(const uint8_t* data, size_t length) {
    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            crc = (crc >> 1) ^ (0x82F63B78 & (-(crc & 1)));
        }
    }
    return ~crc;
}

// Hybrid Logical Clock (HLC)
struct alignas(16) HLC {
    uint64_t physical_time{0}; // Milliseconds or nanoseconds since epoch
    uint64_t logical_counter{0};

    static constexpr uint64_t InfinityLogical = UINT64_MAX;
    static constexpr uint64_t InfinityPhysical = UINT64_MAX;

    static HLC Infinity() noexcept {
        return HLC{InfinityPhysical, InfinityLogical};
    }

    static HLC Zero() noexcept {
        return HLC{0, 0};
    }

    bool operator==(const HLC& o) const noexcept {
        return physical_time == o.physical_time && logical_counter == o.logical_counter;
    }

    bool operator<(const HLC& o) const noexcept {
        if (physical_time != o.physical_time) {
            return physical_time < o.physical_time;
        }
        return logical_counter < o.logical_counter;
    }

    bool operator<=(const HLC& o) const noexcept {
        return (*this < o) || (*this == o);
    }

    bool operator>(const HLC& o) const noexcept {
        return !(*this <= o);
    }

    bool operator>=(const HLC& o) const noexcept {
        return !(*this < o);
    }
};

class HLCGenerator {
private:
    alignas(CACHELINE_SIZE) std::atomic<uint64_t> last_physical_{0};
    alignas(CACHELINE_SIZE) std::atomic<uint64_t> last_logical_{0};

    static uint64_t GetSystemPhysicalTime() noexcept {
        return static_cast<uint64_t>(
            std::chrono::duration_cast<std::chrono::microseconds>(
                std::chrono::system_clock::now().time_since_epoch()
            ).count()
        );
    }

public:
    HLC Now() noexcept {
        uint64_t phys = GetSystemPhysicalTime();
        while (true) {
            uint64_t old_phys = last_physical_.load(std::memory_order_relaxed);
            uint64_t old_log = last_logical_.load(std::memory_order_relaxed);

            uint64_t new_phys = std::max(old_phys, phys);
            uint64_t new_log = (new_phys == old_phys) ? (old_log + 1) : 0;

            if (last_physical_.compare_exchange_weak(old_phys, new_phys,
                                                    std::memory_order_acq_rel,
                                                    std::memory_order_relaxed)) {
                last_logical_.store(new_log, std::memory_order_release);
                return HLC{new_phys, new_log};
            }
        }
    }

    void Update(HLC msg_hlc) noexcept {
        uint64_t phys = GetSystemPhysicalTime();
        while (true) {
            uint64_t old_phys = last_physical_.load(std::memory_order_relaxed);
            uint64_t old_log = last_logical_.load(std::memory_order_relaxed);

            uint64_t new_phys = std::max({old_phys, msg_hlc.physical_time, phys});
            uint64_t new_log = 0;
            if (new_phys == old_phys && new_phys == msg_hlc.physical_time) {
                new_log = std::max(old_log, msg_hlc.logical_counter) + 1;
            } else if (new_phys == old_phys) {
                new_log = old_log + 1;
            } else if (new_phys == msg_hlc.physical_time) {
                new_log = msg_hlc.logical_counter + 1;
            }

            if (last_physical_.compare_exchange_weak(old_phys, new_phys,
                                                    std::memory_order_acq_rel,
                                                    std::memory_order_relaxed)) {
                last_logical_.store(new_log, std::memory_order_release);
                break;
            }
        }
    }
};

// ============================================================================
// Section 2: Epoch-Based Memory Reclamation Subsystem (EBR)
// ============================================================================

struct RetiredNode {
    void* ptr{nullptr};
    void (*deleter)(void*){nullptr};
    RetiredNode* next{nullptr};
};

struct alignas(CACHELINE_SIZE) ThreadControlBlock {
    std::atomic<uint64_t> local_epoch{UINT64_MAX}; // UINT64_MAX indicates quiescent/unpinned
    std::atomic<bool> active{false};
    std::atomic<ThreadControlBlock*> next{nullptr};

    // 3 Retirement limbo lists (epoch % 3)
    RetiredNode* limbo[3]{nullptr, nullptr, nullptr};
    size_t limbo_count[3]{0, 0, 0};
};

class EpochManager {
private:
    alignas(CACHELINE_SIZE) std::atomic<uint64_t> global_epoch_{0};
    alignas(CACHELINE_SIZE) std::atomic<ThreadControlBlock*> global_tcb_head_{nullptr};

public:
    static EpochManager& Instance() {
        static EpochManager instance;
        return instance;
    }

    ThreadControlBlock* RegisterThread() {
        auto* tcb = new ThreadControlBlock();
        tcb->active.store(true, std::memory_order_relaxed);

        ThreadControlBlock* head = global_tcb_head_.load(std::memory_order_relaxed);
        do {
            tcb->next.store(head, std::memory_order_relaxed);
        } while (!global_tcb_head_.compare_exchange_weak(head, tcb,
                                                        std::memory_order_acq_rel,
                                                        std::memory_order_acquire));
        return tcb;
    }

    void DeregisterThread(ThreadControlBlock* tcb) {
        if (!tcb) return;
        Unpin(tcb);

        // Purge all remaining limbo items to prevent leaks on dynamic thread exit
        for (size_t i = 0; i < 3; ++i) {
            PurgeLimboList(tcb->limbo[i]);
            tcb->limbo[i] = nullptr;
            tcb->limbo_count[i] = 0;
        }

        tcb->active.store(false, std::memory_order_release);
    }

    inline void Pin(ThreadControlBlock* tcb) noexcept {
        // Enforce acquire semantics so subsequent pointer loads see valid memory
        uint64_t g_epoch = global_epoch_.load(std::memory_order_acquire);
        tcb->local_epoch.store(g_epoch, std::memory_order_release);
        // Memory barrier to ensure local_epoch write is visible globally before any reads
        std::atomic_thread_fence(std::memory_order_seq_cst);
    }

    inline void Unpin(ThreadControlBlock* tcb) noexcept {
        tcb->local_epoch.store(UINT64_MAX, std::memory_order_release);
    }

    void RetireNode(ThreadControlBlock* tcb, void* ptr, void (*deleter)(void*)) {
        if (!ptr) return;
        uint64_t epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t slot = epoch % 3;

        auto* node = new RetiredNode{ptr, deleter, tcb->limbo[slot]};
        tcb->limbo[slot] = node;
        tcb->limbo_count[slot]++;

        // Threshold-triggered epoch advancement check
        if (tcb->limbo_count[slot] >= 64) {
            TryAdvanceEpoch(tcb);
        }
    }

    void TryAdvanceEpoch(ThreadControlBlock* tcb) {
        uint64_t curr_epoch = global_epoch_.load(std::memory_order_acquire);

        // Check if any thread is lagging behind curr_epoch
        ThreadControlBlock* curr = global_tcb_head_.load(std::memory_order_acquire);
        while (curr) {
            if (curr->active.load(std::memory_order_acquire)) {
                uint64_t thread_epoch = curr->local_epoch.load(std::memory_order_acquire);
                if (thread_epoch != UINT64_MAX && thread_epoch < curr_epoch) {
                    // At least one active thread is reading in an older epoch
                    return;
                }
            }
            curr = curr->next.load(std::memory_order_acquire);
        }

        // Advance global epoch
        if (global_epoch_.compare_exchange_strong(curr_epoch, curr_epoch + 1,
                                                  std::memory_order_acq_rel,
                                                  std::memory_order_relaxed)) {
            // It is now safe to collect slot (curr_epoch + 1) % 3 for this thread
            size_t safe_slot = (curr_epoch + 1) % 3;
            PurgeLimboList(tcb->limbo[safe_slot]);
            tcb->limbo[safe_slot] = nullptr;
            tcb->limbo_count[safe_slot] = 0;
        }
    }

private:
    static void PurgeLimboList(RetiredNode* head) {
        while (head) {
            RetiredNode* tmp = head;
            head = head->next;
            if (tmp->deleter && tmp->ptr) {
                tmp->deleter(tmp->ptr);
            }
            delete tmp;
        }
    }
};

thread_local ThreadControlBlock* tls_tcb = nullptr;

struct EpochGuard {
    ThreadControlBlock* tcb;

    EpochGuard() {
        if (!tls_tcb) {
            tls_tcb = EpochManager::Instance().RegisterThread();
        }
        tcb = tls_tcb;
        EpochManager::Instance().Pin(tcb);
    }

    ~EpochGuard() {
        EpochManager::Instance().Unpin(tcb);
    }

    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
};

// ============================================================================
// Section 3: Lock-Free Multi-Version Record & Index Engine
// ============================================================================

struct alignas(CACHELINE_SIZE) VersionNode {
    HLC create_hlc;
    std::atomic<HLC> expire_hlc;
    std::atomic<VersionNode*> next;
    uint64_t key;
    bool is_tombstone;
    uint32_t val_size;
    char payload[24]; // Inline payload or pointer indirection

    VersionNode(uint64_t k, std::string_view val, HLC create_t, bool tombstone = false)
        : create_hlc(create_t),
          expire_hlc(HLC::Infinity()),
          next(nullptr),
          key(k),
          is_tombstone(tombstone),
          val_size(static_cast<uint32_t>(val.size())) {
        std::memset(payload, 0, sizeof(payload));
        std::memcpy(payload, val.data(), std::min(val.size(), sizeof(payload) - 1));
    }
};

class LockFreeMVCCIndex {
private:
    static constexpr size_t NUM_BUCKETS = 65536;

    struct alignas(CACHELINE_SIZE) IndexBucket {
        std::atomic<VersionNode*> head{nullptr};
    };

    std::array<IndexBucket, NUM_BUCKETS> buckets_;

    static size_t HashKey(uint64_t key) noexcept {
        // Murmur3 64-bit mixer
        key ^= key >> 33;
        key *= 0xff51afd7ed558ccdULL;
        key ^= key >> 33;
        key *= 0xc4ceb9fe1a85ec53ULL;
        key ^= key >> 33;
        return key % NUM_BUCKETS;
    }

public:
    LockFreeMVCCIndex() = default;

    ~LockFreeMVCCIndex() {
        for (size_t i = 0; i < NUM_BUCKETS; ++i) {
            VersionNode* curr = buckets_[i].head.load(std::memory_order_relaxed);
            while (curr) {
                VersionNode* tmp = curr;
                curr = curr->next.load(std::memory_order_relaxed);
                delete tmp;
            }
        }
    }

    // Lock-Free MVCC Read Path
    bool Get(uint64_t key, HLC read_hlc, std::string& out_val) {
        EpochGuard guard; // Pins thread to prevent memory reclamation while traversing
        size_t b_idx = HashKey(key);

        VersionNode* curr = buckets_[b_idx].head.load(std::memory_order_acquire);
        while (curr != nullptr) {
            if (curr->key == key) {
                HLC c_hlc = curr->create_hlc;
                HLC exp_hlc = curr->expire_hlc.load(std::memory_order_acquire);

                // Visibility condition: create_hlc <= read_hlc < expire_hlc
                if (c_hlc <= read_hlc && read_hlc < exp_hlc) {
                    if (curr->is_tombstone) {
                        return false; // Key was deleted as of this snapshot
                    }
                    out_val = std::string(curr->payload, curr->val_size);
                    return true;
                }
            }
            curr = curr->next.load(std::memory_order_acquire);
        }
        return false;
    }

    // Lock-Free MVCC Write Path
    bool Put(uint64_t key, std::string_view val, HLC write_hlc, bool is_tombstone = false) {
        EpochGuard guard;
        size_t b_idx = HashKey(key);

        auto* new_node = new VersionNode(key, val, write_hlc, is_tombstone);
        VersionNode* old_head = buckets_[b_idx].head.load(std::memory_order_acquire);

        while (true) {
            new_node->next.store(old_head, std::memory_order_relaxed);

            // Atomically prepends new version as the head of the chain
            if (buckets_[b_idx].head.compare_exchange_weak(
                    old_head, new_node,
                    std::memory_order_acq_rel,
                    std::memory_order_acquire)) {

                // Chain update: invalidate predecessor if it matches the same key
                VersionNode* pred = new_node->next.load(std::memory_order_acquire);
                while (pred != nullptr) {
                    if (pred->key == key) {
                        HLC exp = pred->expire_hlc.load(std::memory_order_acquire);
                        if (exp == HLC::Infinity()) {
                            pred->expire_hlc.store(write_hlc, std::memory_order_release);
                        }
                        break;
                    }
                    pred = pred->next.load(std::memory_order_acquire);
                }
                return true;
            }
        }
    }

    // Lock-Free MVCC Garbage Collector: unlinks versions obscured past watermark
    void PruneOldVersions(uint64_t key, HLC min_active_hlc) {
        EpochGuard guard;
        size_t b_idx = HashKey(key);

        VersionNode* prev = nullptr;
        VersionNode* curr = buckets_[b_idx].head.load(std::memory_order_acquire);
        bool seen_visible_version = false;

        while (curr != nullptr) {
            VersionNode* next_node = curr->next.load(std::memory_order_acquire);

            if (curr->key == key) {
                HLC exp_hlc = curr->expire_hlc.load(std::memory_order_acquire);

                if (exp_hlc <= min_active_hlc) {
                    if (!seen_visible_version) {
                        // Keep this version: it covers the watermark interval
                        seen_visible_version = true;
                        prev = curr;
                    } else {
                        // Node is entirely unreachable by any active snapshot; unlink
                        if (prev != nullptr) {
                            if (prev->next.compare_exchange_strong(
                                    curr, next_node,
                                    std::memory_order_acq_rel,
                                    std::memory_order_acquire)) {

                                EpochManager::Instance().RetireNode(
                                    guard.tcb, curr, [](void* p) {
                                        delete static_cast<VersionNode*>(p);
                                    });
                                curr = next_node;
                                continue;
                            }
                        }
                    }
                } else {
                    prev = curr;
                }
            } else {
                prev = curr;
            }
            curr = next_node;
        }
    }
};

// ============================================================================
// Section 4: Direct-I/O Asynchronous io_uring Write-Ahead Logger
// ============================================================================

enum class LogRecordType : uint8_t {
    INSERT = 1,
    DELETE = 2,
    CHECKPOINT = 3
};

#pragma pack(push, 1)
struct LogRecordHeader {
    uint32_t magic{0x57414C47}; // "WALG"
    uint32_t crc32{0};
    uint64_t lsn{0};
    HLC timestamp;
    uint64_t key{0};
    uint32_t val_size{0};
    uint8_t record_type{0};
};
#pragma pack(pop)

struct PendingLogWrite {
    LogRecordHeader header;
    std::string payload;
    std::atomic<bool> is_committed{false};
    alignas(CACHELINE_SIZE) uint32_t futex_word{0};
    PendingLogWrite* next{nullptr};
};

class AsyncIOUringWAL {
private:
    int fd_{-1};
    std::atomic<uint64_t> sequence_lsn_{0};
    std::atomic<uint64_t> durable_lsn_{0};
    std::atomic<bool> running_{false};
    std::thread flush_worker_;

    // Lock-Free MPSC Append Queue
    alignas(CACHELINE_SIZE) std::atomic<PendingLogWrite*> mpsc_head_{nullptr};

    // Direct-I/O Sector-Aligned Write Buffers
    uint8_t* write_buffer_{nullptr};
    size_t write_buffer_offset_{0};
    uint64_t file_offset_{0};

#if HAS_LIBURING
    struct io_uring ring_;
#endif

public:
    explicit AsyncIOUringWAL(const std::string& log_path) {
        // Direct I/O requires O_DIRECT and sector-aligned buffers
        fd_ = open(log_path.c_str(), O_DIRECT | O_DSYNC | O_CREAT | O_RDWR, 0644);
        if (fd_ < 0) {
            // Fallback for filesystems without O_DIRECT support in test environments
            fd_ = open(log_path.c_str(), O_DSYNC | O_CREAT | O_RDWR, 0644);
        }
        assert(fd_ >= 0 && "Failed to open WAL file");

        // Allocate 4KB-aligned memory for Direct I/O
        int ret = posix_memalign(reinterpret_cast<void**>(&write_buffer_), SECTOR_SIZE, SECTOR_SIZE * 16);
        assert(ret == 0 && "posix_memalign failed");
        std::memset(write_buffer_, 0, SECTOR_SIZE * 16);

#if HAS_LIBURING
        io_uring_queue_init(64, &ring_, 0);
#endif
        running_.store(true, std::memory_order_relaxed);
        flush_worker_ = std::thread(&AsyncIOUringWAL::WorkerLoop, this);
    }

    ~AsyncIOUringWAL() {
        running_.store(false, std::memory_order_release);
        if (flush_worker_.joinable()) {
            flush_worker_.join();
        }

#if HAS_LIBURING
        io_uring_queue_exit(&ring_);
#endif
        if (write_buffer_) {
            free(write_buffer_);
        }
        if (fd_ >= 0) {
            close(fd_);
        }
    }

    uint64_t AppendRecord(uint64_t key, std::string_view val, HLC hlc, LogRecordType type) {
        uint64_t lsn = sequence_lsn_.fetch_add(1, std::memory_order_relaxed) + 1;

        auto* req = new PendingLogWrite();
        req->header.lsn = lsn;
        req->header.timestamp = hlc;
        req->header.key = key;
        req->header.val_size = static_cast<uint32_t>(val.size());
        req->header.record_type = static_cast<uint8_t>(type);
        req->payload = std::string(val);

        // Compute checksum across header and payload
        std::vector<uint8_t> bytes(sizeof(LogRecordHeader) + val.size());
        std::memcpy(bytes.data(), &req->header, sizeof(LogRecordHeader));
        if (!val.empty()) {
            std::memcpy(bytes.data() + sizeof(LogRecordHeader), val.data(), val.size());
        }
        req->header.crc32 = CalculateCRC32C(bytes.data() + sizeof(uint32_t) * 2, bytes.size() - sizeof(uint32_t) * 2);

        // Lock-Free enqueue to MPSC batch list
        PendingLogWrite* head = mpsc_head_.load(std::memory_order_relaxed);
        do {
            req->next = head;
        } while (!mpsc_head_.compare_exchange_weak(head, req,
                                                   std::memory_order_acq_rel,
                                                   std::memory_order_acquire));

        return lsn;
    }

    void WaitDurable(uint64_t lsn) {
        while (durable_lsn_.load(std::memory_order_acquire) < lsn) {
            // Futex pause until group commit notifies durability
            std::this_thread::yield();
        }
    }

private:
    void WorkerLoop() {
        while (running_.load(std::memory_order_acquire) || mpsc_head_.load(std::memory_order_relaxed) != nullptr) {
            // Harvest all pending batch writes atomically
            PendingLogWrite* batch = mpsc_head_.exchange(nullptr, std::memory_order_acq_rel);

            if (!batch) {
                std::this_thread::sleep_for(std::chrono::microseconds(50));
                continue;
            }

            // Reverse batch singly-linked list to process in FIFO order
            PendingLogWrite* curr = batch;
            PendingLogWrite* prev = nullptr;
            while (curr) {
                PendingLogWrite* nxt = curr->next;
                curr->next = prev;
                prev = curr;
                curr = nxt;
            }
            PendingLogWrite* fifo_batch = prev;

            // Serialize into aligned direct-I/O sectors
            uint64_t max_batch_lsn = 0;
            std::vector<PendingLogWrite*> processed_nodes;

            curr = fifo_batch;
            while (curr) {
                size_t total_sz = sizeof(LogRecordHeader) + curr->header.val_size;

                if (write_buffer_offset_ + total_sz > SECTOR_SIZE * 16) {
                    FlushBuffer();
                }

                std::memcpy(write_buffer_ + write_buffer_offset_, &curr->header, sizeof(LogRecordHeader));
                write_buffer_offset_ += sizeof(LogRecordHeader);

                if (curr->header.val_size > 0) {
                    std::memcpy(write_buffer_ + write_buffer_offset_, curr->payload.data(), curr->header.val_size);
                    write_buffer_offset_ += curr->header.val_size;
                }

                max_batch_lsn = std::max(max_batch_lsn, curr->header.lsn);
                processed_nodes.push_back(curr);
                curr = curr->next;
            }

            FlushBuffer();

            // Notify waiting client threads of group commit durability
            durable_lsn_.store(max_batch_lsn, std::memory_order_release);

            for (auto* node : processed_nodes) {
                node->is_committed.store(true, std::memory_order_release);
                node->futex_word = 1;
                FutexWake(&node->futex_word, 1);
                delete node;
            }
        }
    }

    void FlushBuffer() {
        if (write_buffer_offset_ == 0) return;

        // Direct-I/O requires transfers in exact sector multiples (4096 bytes)
        size_t sectors = (write_buffer_offset_ + SECTOR_SIZE - 1) / SECTOR_SIZE;
        size_t bytes_to_write = sectors * SECTOR_SIZE;

#if HAS_LIBURING
        struct io_uring_sqe* sqe = io_uring_get_sqe(&ring_);
        io_uring_prep_write(sqe, fd_, write_buffer_, bytes_to_write, file_offset_);
        io_uring_submit_and_wait(&ring_, 1);

        struct io_uring_cqe* cqe;
        io_uring_wait_cqe(&ring_, &cqe);
        io_uring_cqe_seen(&ring_, cqe);
#else
        pwrite(fd_, write_buffer_, bytes_to_write, file_offset_);
        fdatasync(fd_);
#endif
        file_offset_ += bytes_to_write;
        write_buffer_offset_ = 0;
        std::memset(write_buffer_, 0, SECTOR_SIZE * 16);
    }
};

// ============================================================================
// Section 5: Crash Recovery and Invariant Verification Subsystem
// ============================================================================

class CrashRecoveryEngine {
public:
    static bool RecoverAndVerify(const std::string& log_path, LockFreeMVCCIndex& index, HLCGenerator& hlc_gen) {
        int fd = open(log_path.c_str(), O_RDONLY);
        if (fd < 0) return false;

        struct stat st;
        fstat(fd, &st);
        size_t fsize = st.st_size;
        if (fsize == 0) {
            close(fd);
            return true;
        }

        std::vector<uint8_t> buffer(fsize);
        ssize_t bytes_read = pread(fd, buffer.data(), fsize, 0);
        close(fd);

        if (bytes_read <= 0) return false;

        size_t offset = 0;
        uint64_t last_lsn = 0;

        while (offset + sizeof(LogRecordHeader) <= static_cast<size_t>(bytes_read)) {
            LogRecordHeader header;
            std::memcpy(&header, buffer.data() + offset, sizeof(LogRecordHeader));

            // Validate WAL segment magic invariant
            if (header.magic != 0x57414C47) {
                // End of valid log stream (reached zero-padded sector tail)
                break;
            }

            if (offset + sizeof(LogRecordHeader) + header.val_size > static_cast<size_t>(bytes_read)) {
                // Torn write detected at log tail
                std::cerr << "[Recovery] Warning: Torn log record detected at LSN " << header.lsn << "\n";
                break;
            }

            // CRC Validation
            size_t total_rec_size = sizeof(LogRecordHeader) + header.val_size;
            uint32_t computed_crc = CalculateCRC32C(
                buffer.data() + offset + sizeof(uint32_t) * 2,
                total_rec_size - sizeof(uint32_t) * 2
            );

            if (computed_crc != header.crc32) {
                std::cerr << "[Recovery] Corrupted CRC at LSN " << header.lsn << ". Halting recovery.\n";
                break;
            }

            // Monotonic LSN invariant verification
            assert(header.lsn > last_lsn && "LSN invariant violated!");
            last_lsn = header.lsn;

            // Reconstruct state into MVCC Index
            std::string_view val(
                reinterpret_cast<const char*>(buffer.data() + offset + sizeof(LogRecordHeader)),
                header.val_size
            );

            bool is_tombstone = (header.record_type == static_cast<uint8_t>(LogRecordType::DELETE));
            index.Put(header.key, val, header.timestamp, is_tombstone);
            hlc_gen.Update(header.timestamp);

            offset += total_rec_size;
        }

        std::cout << "[Recovery] Successfully verified & replayed WAL through durable LSN " << last_lsn << "\n";
        return true;
    }
};

// ============================================================================
// Section 6: Unified Storage Engine & Verification Entry Point
// ============================================================================

class TransactionalKVEngine {
private:
    LockFreeMVCCIndex index_;
    HLCGenerator hlc_;
    std::unique_ptr<AsyncIOUringWAL> wal_;
    const std::string wal_path_;

public:
    explicit TransactionalKVEngine(std::string wal_path)
        : wal_path_(std::move(wal_path)) {
        wal_ = std::make_unique<AsyncIOUringWAL>(wal_path_);
    }

    bool Put(uint64_t key, std::string_view value) {
        HLC write_hlc = hlc_.Now();
        uint64_t lsn = wal_->AppendRecord(key, value, write_hlc, LogRecordType::INSERT);
        wal_->WaitDurable(lsn); // Ensure group commit persistence
        return index_.Put(key, value, write_hlc, false);
    }

    bool Delete(uint64_t key) {
        HLC write_hlc = hlc_.Now();
        uint64_t lsn = wal_->AppendRecord(key, "", write_hlc, LogRecordType::DELETE);
        wal_->WaitDurable(lsn);
        return index_.Put(key, "", write_hlc, true);
    }

    bool Get(uint64_t key, std::string& out_val) {
        HLC read_hlc = hlc_.Now();
        return index_.Get(key, read_hlc, out_val);
    }

    bool GetSnapshot(uint64_t key, HLC snapshot_hlc, std::string& out_val) {
        return index_.Get(key, snapshot_hlc, out_val);
    }

    void GarbageCollect(uint64_t key, HLC min_active_watermark) {
        index_.PruneOldVersions(key, min_active_watermark);
    }

    HLC GetCurrentHLC() noexcept {
