struct alignas(16) HLC {
    uint64_t physical; // Physical milliseconds / nanoseconds
    uint64_t logical;  // Logical tie-breaker counter

    constexpr HLC() : physical(0), logical(0) {}
    constexpr HLC(uint64_t p, uint64_t l) : physical(p), logical(l) {}

    bool operator<(const HLC& o) const noexcept {
        if (physical != o.physical) return physical < o.physical;
        return logical < o.logical;
    }

    bool operator<=(const HLC& o) const noexcept {
        if (physical != o.physical) return physical <= o.physical;
        return logical <= o.logical;
    }

    bool operator==(const HLC& o) const noexcept {
        return physical == o.physical && logical == o.logical;
    }

    bool operator>(const HLC& o) const noexcept { return !(*this <= o); }
    bool operator>=(const HLC& o) const noexcept { return !(*this < o); }
};

class HLCGenerator {
private:
    alignas(HARDWARE_CACHELINE_SIZE) std::atomic<uint64_t> last_physical_{0};
    alignas(HARDWARE_CACHELINE_SIZE) std::atomic<uint64_t> last_logical_{0};

    static uint64_t GetPhysicalTime() noexcept {
        return static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now().time_since_epoch()).count());
    }

public:
    HLC Now() noexcept {
        uint64_t phys = GetPhysicalTime();
        while (true) {
            uint64_t cur_p = last_physical_.load(std::memory_order_relaxed);
            uint64_t cur_l = last_logical_.load(std::memory_order_relaxed);

            uint64_t next_p = std::max(cur_p, phys);
            uint64_t next_l = (next_p == cur_p) ? (cur_l + 1) : 0;

            // Atomic 2-word update using CAS loop
            if (cur_p == next_p) {
                if (last_logical_.compare_exchange_weak(cur_l, next_l,
                        std::memory_order_relaxed, std::memory_order_relaxed)) {
                    return HLC{next_p, next_l};
                }
            } else {
                if (last_physical_.compare_exchange_weak(cur_p, next_p,
                        std::memory_order_relaxed, std::memory_order_relaxed)) {
                    last_logical_.store(0, std::memory_order_relaxed);
                    return HLC{next_p, 0};
                }
            }
        }
    }

    void Update(HLC remote) noexcept {
        uint64_t phys = GetPhysicalTime();
        while (true) {
            uint64_t cur_p = last_physical_.load(std::memory_order_relaxed);
            uint64_t cur_l = last_logical_.load(std::memory_order_relaxed);

            uint64_t next_p = std::max({cur_p, phys, remote.physical});
            uint64_t next_l = 0;
            if (next_p == cur_p && next_p == remote.physical) {
                next_l = std::max(cur_l, remote.logical) + 1;
            } else if (next_p == cur_p) {
                next_l = cur_l + 1;
            } else if (next_p == remote.physical) {
                next_l = remote.logical + 1;
            }

            if (last_physical_.compare_exchange_weak(cur_p, next_p,
                    std::memory_order_relaxed, std::memory_order_relaxed)) {
                last_logical_.store(next_l, std::memory_order_relaxed);
                return;
            }
        }
    }
};

// ============================================================================
// 3. EPOCH-BASED RECLAMATION (EBR) SUBSYSTEM
// ============================================================================

struct RetiredNode {
    void* ptr;
    void (*deleter)(void*);
    RetiredNode* next;
};

struct alignas(HARDWARE_CACHELINE_SIZE) ThreadControlBlock {
    std::atomic<uint64_t> local_epoch{UINT64_MAX}; // UINT64_MAX means inactive/quiescent
    std::atomic<bool> active{false};
    std::atomic<ThreadControlBlock*> next{nullptr};

    // 3 Epoch retirement limbo lists
    std::array<RetiredNode*, 3> limbo_lists{nullptr, nullptr, nullptr};
    std::array<size_t, 3> limbo_counts{0, 0, 0};

    char pad[HARDWARE_CACHELINE_SIZE - sizeof(std::atomic<uint64_t>) - sizeof(std::atomic<bool>) - 
             sizeof(std::atomic<ThreadControlBlock*>) - sizeof(std::array<RetiredNode*, 3>) - 
             sizeof(std::array<size_t, 3>)];
};

class EpochManager {
private:
    alignas(HARDWARE_CACHELINE_SIZE) std::atomic<uint64_t> global_epoch_{0};
    alignas(HARDWARE_CACHELINE_SIZE) std::atomic<ThreadControlBlock*> global_threads_head_{nullptr};

public:
    static EpochManager& Instance() {
        static EpochManager instance;
        return instance;
    }

    void RegisterThread(ThreadControlBlock* tcb) {
        ThreadControlBlock* old_head = global_threads_head_.load(std::memory_order_relaxed);
        do {
            tcb->next.store(old_head, std::memory_order_relaxed);
        } while (!global_threads_head_.compare_exchange_weak(
            old_head, tcb, std::memory_order_release, std::memory_order_relaxed));
    }

    void DeregisterThread(ThreadControlBlock* tcb) {
        // Mark inactive first
        tcb->active.store(false, std::memory_order_release);
        tcb->local_epoch.store(UINT64_MAX, std::memory_order_release);

        // Force drain all local limbo lists on thread exit
        for (size_t i = 0; i < 3; ++i) {
            RetiredNode* curr = tcb->limbo_lists[i];
            while (curr) {
                RetiredNode* next = curr->next;
                curr->deleter(curr->ptr);
                delete curr;
                curr = next;
            }
            tcb->limbo_lists[i] = nullptr;
            tcb->limbo_counts[i] = 0;
        }
    }

    void Pin(ThreadControlBlock* tcb) noexcept {
        tcb->active.store(true, std::memory_order_relaxed);
        // Load global epoch and publish to thread-local state with seq_cst / release ordering
        uint64_t e = global_epoch_.load(std::memory_order_acquire);
        tcb->local_epoch.store(e, std::memory_order_release);
        std::atomic_thread_fence(std::memory_order_seq_cst);
    }

    void Unpin(ThreadControlBlock* tcb) noexcept {
        tcb->local_epoch.store(UINT64_MAX, std::memory_order_release);
        tcb->active.store(false, std::memory_order_release);
    }

    void RetireNode(ThreadControlBlock* tcb, void* ptr, void (*deleter)(void*)) {
        if (!ptr) return;
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t idx = cur_epoch % 3;

        auto* node = new RetiredNode{ptr, deleter, tcb->limbo_lists[idx]};
        tcb->limbo_lists[idx] = node;
        tcb->limbo_counts[idx]++;

        // Attempt reclamation periodically
        if (tcb->limbo_counts[idx] >= 64) {
            TryAdvanceAndReclaim(tcb);
        }
    }

    void TryAdvanceAndReclaim(ThreadControlBlock* tcb) {
        uint64_t cur_e = global_epoch_.load(std::memory_order_acquire);

        // Check if all active threads have witnessed current epoch
        ThreadControlBlock* curr = global_threads_head_.load(std::memory_order_acquire);
        bool can_advance = true;

        while (curr != nullptr) {
            if (curr->active.load(std::memory_order_acquire)) {
                uint64_t thread_e = curr->local_epoch.load(std::memory_order_acquire);
                if (thread_e != UINT64_MAX && thread_e < cur_e) {
                    can_advance = false;
                    break;
                }
            }
            curr = curr->next.load(std::memory_order_relaxed);
        }

        if (can_advance) {
            // Advance global epoch
            if (global_epoch_.compare_exchange_strong(cur_e, cur_e + 1, 
                    std::memory_order_acq_rel, std::memory_order_relaxed)) {
                cur_e++;
            }
        }

        // Reclaim safe epoch slots (epoch - 2)
        // In a 3-epoch scheme (E, E-1, E-2), slot (cur_e + 1) % 3 is strictly (cur_e - 2)
        size_t safe_idx = (cur_e + 1) % 3;
        RetiredNode* reclaim_list = tcb->limbo_lists[safe_idx];
        tcb->limbo_lists[safe_idx] = nullptr;
        tcb->limbo_counts[safe_idx] = 0;

        while (reclaim_list) {
            RetiredNode* next = reclaim_list->next;
            reclaim_list->deleter(reclaim_list->ptr);
            delete reclaim_list;
            reclaim_list = next;
        }
    }

    uint64_t GetMinActiveEpoch() const noexcept {
        uint64_t min_e = global_epoch_.load(std::memory_order_acquire);
        ThreadControlBlock* curr = global_threads_head_.load(std::memory_order_acquire);
        while (curr != nullptr) {
            if (curr->active.load(std::memory_order_acquire)) {
                uint64_t te = curr->local_epoch.load(std::memory_order_acquire);
                if (te != UINT64_MAX) {
                    min_e = std::min(min_e, te);
                }
            }
            curr = curr->next.load(std::memory_order_relaxed);
        }
        return min_e;
    }
};

