using Value = std::string;

struct alignas(HARDWARE_CACHELINE_SIZE) VersionNode {
    HLC commit_hlc;
    std::atomic<VersionNode*> next{nullptr};
    uint64_t key{0};
    uint32_t val_size{0};
    bool is_tombstone{false};
    char payload[1]; // Flexible array / inline buffer

    static VersionNode* Create(uint64_t key, const Value& val, HLC hlc, bool tombstone = false) {
        size_t size = sizeof(VersionNode) + (tombstone ? 0 : val.size());
        // Cacheline-aligned dynamic allocation
        void* raw = ::operator new(size, std::align_val_t(HARDWARE_CACHELINE_SIZE));
        auto* node = new (raw) VersionNode();
        node->key = key;
        node->commit_hlc = hlc;
        node->is_tombstone = tombstone;
        node->next.store(nullptr, std::memory_order_relaxed);
        if (!tombstone) {
            node->val_size = static_cast<uint32_t>(val.size());
            std::memcpy(node->payload, val.data(), val.size());
        } else {
            node->val_size = 0;
        }
        return node;
    }

    static void Destroy(void* ptr) {
        if (!ptr) return;
        auto* node = static_cast<VersionNode*>(ptr);
        node->~VersionNode();
        ::operator delete(node, std::align_val_t(HARDWARE_CACHELINE_SIZE));
    }
};

