#pragma pack(push, 1)
struct LogRecordHeader {
    uint32_t magic;      // 0x57414C52 ('WALR')
    uint32_t crc;        // CRC32C over payload + header (except crc field)
    uint64_t lsn;        // Monotonic Log Sequence Number
    uint64_t key;        // Key
    HLC hlc;             // Hybrid Logical Clock
    uint32_t val_size;   // Size of payload
    uint8_t is_tombstone;// 1 = Tombstone, 0 = Value
};
#pragma pack(pop)

static constexpr uint32_t WAL_MAGIC = 0x57414C52;

// Lock-Free MPSC Ring Buffer for WAL Batching
class LockFreeLogQueue {
public:
    struct Entry {
        uint64_t lsn;
        uint64_t key;
        HLC hlc;
        std::string val;
        bool is_tombstone;
        std::atomic<bool> ready{false};
    };

private:
    static constexpr size_t QUEUE_CAPACITY = 65536;
    std::vector<Entry> entries_;
    alignas(HARDWARE_CACHELINE_SIZE) std::atomic<uint64_t> head_{0};
    alignas(HARDWARE_CACHELINE_SIZE) std::atomic<uint64_t> tail_{0};

public:
    LockFreeLogQueue() : entries_(QUEUE_CAPACITY) {}

    uint64_t Enqueue(uint64_t lsn, uint64_t key, HLC hlc, const Value& val, bool tombstone) {
        uint64_t pos = head_.fetch_add(1, std::memory_order_acq_rel);
        size_t idx = pos % QUEUE_CAPACITY;

        // Spin-wait if wrapped around
        while (entries_[idx].ready.load(std::memory_order_acquire)) {
            std::this_thread::yield();
        }

        entries_[idx].lsn = lsn;
        entries_[idx].key = key;
        entries_[idx].hlc = hlc;
        entries_[idx].val = val;
        entries_[idx].is_tombstone = tombstone;
        entries_[idx].ready.store(true, std::memory_order_release);
        return pos;
    }

    bool TryPopBatch(std::vector<Entry>& batch, size_t max_count) {
        batch.clear();
        uint64_t t = tail_.load(std::memory_order_relaxed);
        while (batch.size() < max_count) {
            size_t idx = t % QUEUE_CAPACITY;
            if (!entries_[idx].ready.load(std::memory_order_acquire)) {
                break;
            }
            batch.push_back(std::move(entries_[idx]));
            entries_[idx].ready.store(false, std::memory_order_release);
            t++;
        }
        if (!batch.empty()) {
            tail_.store(t, std::memory_order_release);
            return true;
        }
        return false;
    }
};

class DirectIOAsyncWAL {
private:
    int wal_fd_{-1};
    int ring_fd_{-1};
    void* ring_sq_ptr_{nullptr};
    void* ring_cq_ptr_{nullptr};
    struct io_uring_sqe* sqes_{nullptr};
    struct io_uring_cqe* cqes_{nullptr};

    uint8_t* direct_io_buffer_{nullptr};
    size_t buffer_offset_{0};
    uint64_t file_offset_{0};

    alignas(HARDWARE_CACHELINE_SIZE) std::atomic<uint64_t> global_lsn_{0};
    alignas(HARDWARE_CACHELINE_SIZE) std::atomic<uint32_t> durable_lsn_{0}; // Low 32 bits for futex wake

    LockFreeLogQueue log_queue_;
    std::atomic<bool> running_{true};
    std::thread flush_thread_;

    // io_uring syscall setup
    void InitIOUring() {
        struct io_uring_params p;
        std::memset(&p, 0, sizeof(p));
        ring_fd_ = syscall(__NR_io_uring_setup, 256, &p);
        if (ring_fd_ < 0) {
            throw std::runtime_error("io_uring_setup failed: " + std::string(strerror(errno)));
        }

        // Map SQ & CQ rings
        size_t sq_size = p.sq_off.array + p.sq_entries * sizeof(uint32_t);
        size_t cq_size = p.cq_off.cqes + p.cq_entries * sizeof(struct io_uring_cqe);

        ring_sq_ptr_ = mmap(nullptr, sq_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_POPULATE, ring_fd_, IORING_OFF_SQ_RING);
        sqes_ = static_cast<struct io_uring_sqe*>(mmap(nullptr, p.sq_entries * sizeof(struct io_uring_sqe),
                                                        PROT_READ | PROT_WRITE, MAP_SHARED | MAP_POPULATE,
                                                        ring_fd_, IORING_OFF_SQES));
        ring_cq_ptr_ = mmap(nullptr, cq_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_POPULATE, ring_fd_, IORING_OFF_CQ_RING);
        cqes_ = reinterpret_cast<struct io_uring_cqe*>(static_cast<char*>(ring_cq_ptr_) + p.cq_off.cqes);
    }

    void WorkerLoop() {
        std::vector<LockFreeLogQueue::Entry> batch;
        batch.reserve(1024);

        while (running_.load(std::memory_order_relaxed) || log_queue_.TryPopBatch(batch, 1024)) {
            if (!log_queue_.TryPopBatch(batch, 1024)) {
                std::this_thread::sleep_for(std::chrono::microseconds(50));
                continue;
            }

            // Serialize batch into direct I/O aligned buffer
            uint64_t max_batch_lsn = 0;
            for (const auto& item : batch) {
                LogRecordHeader hdr;
                hdr.magic = WAL_MAGIC;
                hdr.lsn = item.lsn;
                hdr.key = item.key;
                hdr.hlc = item.hlc;
                hdr.val_size = static_cast<uint32_t>(item.val.size());
                hdr.is_tombstone = item.is_tombstone ? 1 : 0;
                hdr.crc = 0;

                // Compute CRC32C over record
                uint32_t crc = crc32c_hardware(0, reinterpret_cast<const uint8_t*>(&hdr) + sizeof(uint32_t) * 2, 
                                               sizeof(LogRecordHeader) - sizeof(uint32_t) * 2);
                if (hdr.val_size > 0) {
                    crc = crc32c_hardware(crc, reinterpret_cast<const uint8_t*>(item.val.data()), hdr.val_size);
                }
                hdr.crc = crc;

                size_t total_rec_size = sizeof(LogRecordHeader) + hdr.val_size;
                if (buffer_offset_ + total_rec_size > WAL_BUFFER_CAPACITY) {
                    FlushBufferDirect();
                }

                std::memcpy(direct_io_buffer_ + buffer_offset_, &hdr, sizeof(LogRecordHeader));
                if (hdr.val_size > 0) {
                    std::memcpy(direct_io_buffer_ + buffer_offset_ + sizeof(LogRecordHeader), 
                                item.val.data(), hdr.val_size);
                }
                buffer_offset_ += total_rec_size;
                max_batch_lsn = std::max(max_batch_lsn, item.lsn);
            }

            if (buffer_offset_ > 0) {
                FlushBufferDirect();
            }

            // Update durable LSN watermark and wake up all waiting synchronous committers
            durable_lsn_.store(static_cast<uint32_t>(max_batch_lsn), std::memory_order_release);
            futex_wake_all(&durable_lsn_);
        }
    }

    void FlushBufferDirect() {
        if (buffer_offset_ == 0) return;

        // Sector round up for Direct I/O
        size_t aligned_bytes = (buffer_offset_ + DIRECT_IO_ALIGNMENT - 1) & ~(DIRECT_IO_ALIGNMENT - 1);
        // Zero pad tail
        if (aligned_bytes > buffer_offset_) {
            std::memset(direct_io_buffer_ + buffer_offset_, 0, aligned_bytes - buffer_offset_);
        }

        // Direct submission via io_uring SQE
        struct io_uring_sqe* sqe = &sqes_[0];
        std::memset(sqe, 0, sizeof(struct io_uring_sqe));
        sqe->opcode = IORING_OP_WRITE;
        sqe->fd = wal_fd_;
        sqe->addr = reinterpret_cast<uint64_t>(direct_io_buffer_);
        sqe->len = aligned_bytes;
        sqe->off = file_offset_;

        // Direct syscall submission
        syscall(__NR_io_uring_enter, ring_fd_, 1, 1, IORING_ENTER_GETEVENTS, nullptr);

        file_offset_ += aligned_bytes;
        buffer_offset_ = 0;
    }

public:
    DirectIOAsyncWAL(const std::string& path) {
        wal_fd_ = open(path.c_str(), O_DIRECT | O_RDWR | O_CREAT | O_TRUNC, 0644);
        if (wal_fd_ < 0) {
            throw std::runtime_error("Failed to open WAL file with O_DIRECT: " + std::string(strerror(errno)));
        }

        // Allocate 4KB page-aligned buffer for Direct I/O
        if (posix_memalign(reinterpret_cast<void**>(&direct_io_buffer_), DIRECT_IO_ALIGNMENT, WAL_BUFFER_CAPACITY) != 0) {
            throw std::bad_alloc();
        }
        std::memset(direct_io_buffer_, 0, WAL_BUFFER_CAPACITY);

        InitIOUring();
        flush_thread_ = std::thread(&DirectIOAsyncWAL::WorkerLoop, this);
    }

    ~DirectIOAsyncWAL() {
        running_.store(false, std::memory_order_release);
        if (flush_thread_.joinable()) {
            flush_thread_.join();
        }
        if (direct_io_buffer_) {
            free(direct_io_buffer_);
        }
        if (wal_fd_ >= 0) {
            close(wal_fd_);
        }
        if (ring_fd_ >= 0) {
            close(ring_fd_);
        }
    }

    uint64_t AppendAsync(uint64_t key, HLC hlc, const Value& val, bool tombstone) {
        uint64_t lsn = global_lsn_.fetch_add(1, std::memory_order_relaxed) + 1;
        log_queue_.Enqueue(lsn, key, hlc, val, tombstone);
        return lsn;
    }

    void AwaitDurability(uint64_t lsn) {
        uint32_t target = static_cast<uint32_t>(lsn);
        while (true) {
            uint32_t cur = durable_lsn_.load(std::memory_order_acquire);
            if (cur >= target) {
                return;
            }
            futex_wait(&durable_lsn_, cur);
        }
    }
};

// ============================================================================
// 6. LOCK-FREE MVCC ENGINE
// ============================================================================

class MVCCEngine {
private:
    std::array<KeyIndexEntry, NUM_BUCKETS> table_;
    HLCGenerator hlc_;
    std::unique_ptr<DirectIOAsyncWAL> wal_;

    static size_t Hash(uint64_t key) noexcept {
        // Thomas Wang 64-bit integer hash function
        key = (~key) + (key << 21);
        key = key ^ (key >> 24);
        key = (key + (key << 3)) + (key << 8);
        key = key ^ (key >> 14);
        key = (key + (key << 2)) + (key << 4);
        key = key ^ (key >> 28);
        key = key + (key << 31);
        return key % NUM_BUCKETS;
    }

public:
    MVCCEngine(const std::string& wal_path) {
        wal_ = std::make_unique<DirectIOAsyncWAL>(wal_path);
    }

    HLC CurrentHLC() {
        return hlc_.Now();
    }

    // ------------------------------------------------------------------------
    // Read Operation (Strictly Wait-Free / Lock-Free, Zero-Allocation)
    // ------------------------------------------------------------------------
    bool Get(uint64_t key, HLC read_hlc, Value& out_val) {
        // Protect record chain traversal using Thread-Local Epoch Guard
        EpochGuard guard;

        size_t bucket = Hash(key);
        // Acquire memory ordering guarantees that all fields of newly inserted version nodes are visible
        VersionNode* curr = table_[bucket].head.load(std::memory_order_acquire);

        while (curr != nullptr) {
            if (curr->key == key) {
                // If version commit HLC is visible to reader's snapshot
                if (curr->commit_hlc <= read_hlc) {
                    if (curr->is_tombstone) {
                        return false; // Key deleted at or before this snapshot
                    }
                    out_val.assign(curr->payload, curr->val_size);
                    return true;
                }
            }
            curr = curr->next.load(std::memory_order_acquire);
        }
        return false;
    }

    // ------------------------------------------------------------------------
    // Write / Put Operation (Lock-Free CAS prepend with Group-Committed WAL)
    // ------------------------------------------------------------------------
    bool Put(uint64_t key, const Value& val, HLC write_hlc, bool is_tombstone = false) {
        // 1. Asynchronously submit entry to WAL & register LSN
        uint64_t lsn = wal_->AppendAsync(key, write_hlc, val, is_tombstone);

        // 2. Allocate cacheline-aligned version node
        VersionNode* new_node = VersionNode::Create(key, val, write_hlc, is_tombstone);

        size_t bucket = Hash(key);
        std::atomic<VersionNode*>& head_ref = table_[bucket].head;

        // 3. Lock-Free CAS Loop to prepend node into descending-ordered chain
        VersionNode* old_head = head_ref.load(std::memory_order_acquire);
        do {
            new_node->next.store(old_head, std::memory_order_relaxed);
            // Release ordering publishes new_node payload and pointer chain atomically
        } while (!head_ref.compare_exchange_weak(old_head, new_node,
                                                 std::memory_order_release,
                                                 std::memory_order_acquire));

        // 4. Await durable group commit from io_uring worker
        wal_->AwaitDurability(lsn);
        return true;
    }

    bool Delete(uint64_t key, HLC write_hlc) {
        return Put(key, "", write_hlc, true);
    }

    // ------------------------------------------------------------------------
    // Cooperative Version-Chain Pruning / Garbage Collection
    // ------------------------------------------------------------------------
    void PruneOldVersions(uint64_t key, HLC min_active_hlc) {
        EpochGuard guard;
        size_t bucket = Hash(key);
        VersionNode* head = table_[bucket].head.load(std::memory_order_acquire);

        VersionNode* prev = nullptr;
        VersionNode* curr = head;
        bool found_snapshot_baseline = false;

        while (curr != nullptr) {
            if (curr->key == key) {
                if (curr->commit_hlc <= min_active_hlc) {
                    if (!found_snapshot_baseline) {
                        // Retain the very first version <= min_active_hlc as base snapshot
                        found_snapshot_baseline = true;
                        prev = curr;
                        curr = curr->next.load(std::memory_order_acquire);
                        continue;
                    }

                    // All subsequent versions are strictly older than the oldest reader's snapshot
                    // Unlink the tail of the chain
                    if (prev != nullptr) {
                        VersionNode* to_unlink = curr;
                        if (prev->next.compare_exchange_strong(to_unlink, nullptr,
                                                               std::memory_order_release,
                                                               std::memory_order_acquire)) {
                            // Safely retire all unlinked nodes via EBR
                            while (to_unlink != nullptr) {
                                VersionNode* next_node = to_unlink->next.load(std::memory_order_relaxed);
                                EpochManager::Instance().RetireNode(&tls_ebr.tcb, to_unlink, VersionNode::Destroy);
                                to_unlink = next_node;
                            }
                            break;
                        }
                    }
                }
            }
            prev = curr;
            curr = curr->next.load(std::memory_order_acquire);
        }
    }
};

// ============================================================================
// 7. CRASH RECOVERY & INVARIANT VERIFICATION
// ============================================================================

struct CrashRecoveryVerifier {
    static bool RecoverAndVerify(const std::string& wal_path, size_t& valid_records_recovered) {
        valid_records_recovered = 0;
        int fd = open(wal_path.c_str(), O_RDONLY | O_DIRECT);
        if (fd < 0) {
            fd = open(wal_path.c_str(), O_RDONLY); // Fallback if O_DIRECT unsupported by test filesystem
            if (fd < 0) return false;
        }

        void* buf = nullptr;
        if (posix_memalign(&buf, DIRECT_IO_ALIGNMENT, WAL_BUFFER_CAPACITY) != 0) {
            close(fd);
            return false;
        }

        uint64_t last_lsn = 0;
        HLC last_hlc{0, 0};
        ssize_t bytes_read = 0;

        while ((bytes_read = read(fd, buf, WAL_BUFFER_CAPACITY)) > 0) {
            size_t offset = 0;
            const uint8_t* ptr = static_cast<const uint8_t*>(buf);

            while (offset + sizeof(LogRecordHeader) <= static_cast<size_t>(bytes_read)) {
                const auto* hdr = reinterpret_cast<const LogRecordHeader*>(ptr + offset);

                // Zero-filled sector boundary check (end of direct I/O padded batch)
                if (hdr->magic == 0) {
                    offset = (offset + DIRECT_IO_ALIGNMENT - 1) & ~(DIRECT_IO_ALIGNMENT - 1);
                    if (offset >= static_cast<size_t>(bytes_read)) break;
                    continue;
                }

                if (hdr->magic != WAL_MAGIC) {
                    // Torn write detected at non-aligned offset; stop recovery
                    free(buf);
                    close(fd);
                    return true;
                }

                // Check CRC integrity
                uint32_t expected_crc = crc32c_hardware(0, ptr + offset + sizeof(uint32_t) * 2,
                                                        sizeof(LogRecordHeader) - sizeof(uint32_t) * 2);
                if (hdr->val_size > 0) {
                    expected_crc = crc32c_hardware(expected_crc, ptr + offset + sizeof(LogRecordHeader), hdr->val_size);
                }

                if (hdr->crc != expected_crc) {
                    // Torn write detected via corrupted CRC
                    free(buf);
                    close(fd);
                    return true;
                }

                // Verify Invariants: Strict LSN Monotonicity and HLC Causal Ordering
                assert(hdr->lsn > last_lsn && "Invariant Violated: WAL LSN must strictly increase");
                assert((last_hlc < hdr->hlc || last_hlc == HLC{0,0}) && "Invariant Violated: HLC must be causally monotonic");

                last_lsn = hdr->lsn;
                last_hlc = hdr->hlc;
                valid_records_recovered++;

                offset += sizeof(LogRecordHeader) + hdr->val_size;
            }
        }

        free(buf);
        close(fd);
        return true;
    }
};

// ============================================================================
// 8. TEST & BENCHMARK HARNESS
// ============================================================================

int main() {
    const std::string wal_file = "/tmp/mvcc_engine_test.wal";
    std::cout << ">>> Initializing Lock-Free MVCC Storage Engine with io_uring WAL..." << std::endl;

    {
        MVCCEngine engine(wal_file);

        constexpr int NUM_THREADS = 8;
        constexpr int OPS_PER_THREAD = 10000;
        std::vector<std::thread> workers;

        auto start_time = std::chrono::high_resolution_clock::now();

        // Launch concurrent writers & readers
        for (int tid = 0; tid < NUM_THREADS; ++tid) {
            workers.emplace_back([&engine, tid]() {
                for (int i = 0; i < OPS_PER_THREAD; ++i) {
                    uint64_t key = (tid * 1000) + (i % 100);
                    HLC write_hlc = engine.CurrentHLC();
                    std::string val = "value_payload_" + std::to_string(i) + "_thread_" + std::to_string(tid);

                    engine.Put(key, val, write_hlc);

                    // Immediate snapshot read
                    Value read_val;
                    bool found = engine.Get(key, write_hlc, read_val);
                    assert(found && "Read-your-own-writes snapshot violation!");
                    assert(read_val == val && "Data corruption detected!");

                    // Online version pruning
                    if (i % 200 == 0) {
                        engine.PruneOldVersions(key, write_hlc);
                    }
                }
            });
        }

        for (auto& t : workers) {
            t.join();
        }

        auto end_time = std::chrono::high_resolution_clock::now();
        double elapsed_sec = std::chrono::duration<double>(end_time - start_time).count();
        double total_ops = NUM_THREADS * OPS_PER_THREAD;
        std::cout << ">>> Completed " << total_ops << " Pipelined MVCC Transactions in " 
                  << elapsed_sec << " seconds (" << (total_ops / elapsed_sec) << " ops/sec)." << std::endl;
    }

    // Verify durable crash-recovery invariants
    std::cout << ">>> Validating Crash Recovery & WAL Invariants..." << std::endl;
    size_t recovered = 0;
    bool recovery_ok = CrashRecoveryVerifier::RecoverAndVerify(wal_file, recovered);
    assert(recovery_ok && "Recovery verification failed!");
    std::cout << ">>> Successfully recovered and verified " << recovered << " durable WAL records." << std::endl;
    std::cout << ">>> All Lock-Free MVCC & EBR Invariants Verified Successfully." << std::endl;

    unlink(wal_file.c_str());
    return 0;
}
