namespace stream_engine {

// ============================================================================
// Frame Header & Protocol Framing Definitions
// ============================================================================

enum FrameType : uint16_t {
    FRAME_DATA    = 0x0001,
    FRAME_PAD     = 0x0002, // Sentinel frame injected at boundary wrap-around
    FRAME_SKIPPED = 0x0003  // Injected upon dynamic reservation abort
};

enum FrameStatus : uint8_t {
    STATUS_EMPTY     = 0x00,
    STATUS_RESERVED  = 0x01,
    STATUS_COMMITTED = 0x02,
    STATUS_SKIPPED   = 0x03,
    STATUS_PAD       = 0x04,
    STATUS_RELEASED  = 0x05
};

/// Explicit framing header: [length (32b) | type (16b) | epoch (8b) | status (8b)]
/// Total: 8 bytes, aligned to 8-byte boundary.
struct alignas(8) MsgHeader {
    uint32_t length;              // Total frame size in bytes (header + payload + alignment padding)
    uint16_t type;                // Application message type / framing tag
    std::atomic<uint16_t> state;  // High 8b: Epoch tag | Low 8b: FrameStatus

    [[nodiscard]] static constexpr uint16_t encode_state(uint8_t epoch, FrameStatus status) noexcept {
        return static_cast<uint16_t>((static_cast<uint16_t>(epoch) << 8) | static_cast<uint8_t>(status));
    }

    [[nodiscard]] static constexpr uint8_t extract_epoch(uint16_t state_val) noexcept {
        return static_cast<uint8_t>(state_val >> 8);
    }

    [[nodiscard]] static constexpr FrameStatus extract_status(uint16_t state_val) noexcept {
        return static_cast<FrameStatus>(state_val & 0xFF);
    }
};

static_assert(sizeof(MsgHeader) == 8, "MsgHeader must be exactly 8 bytes for cacheline packing");
static_assert(alignof(MsgHeader) == 8, "MsgHeader must be 8-byte aligned");
static_assert(std::atomic<uint16_t>::is_always_lock_free, "atomic<uint16_t> must be lock-free");

// ============================================================================
// Forward Declarations & Zero-Copy Leases
// ============================================================================

template <size_t Capacity>
class TransactionalRingBuffer;

/// Zero-copy mutable reservation handle for producers (2-phase commit).
template <size_t Capacity>
class ProducerLease {
public:
    ProducerLease() noexcept = default;

    ProducerLease(TransactionalRingBuffer<Capacity>* ring,
                  uint64_t pos,
                  uint32_t total_alloc,
                  uint8_t* payload_ptr,
                  uint32_t payload_size,
                  uint16_t msg_type) noexcept
        : ring_(ring),
          pos_(pos),
          total_alloc_(total_alloc),
          payload_ptr_(payload_ptr),
          payload_size_(payload_size),
          msg_type_(msg_type),
          active_(true) {}

    ~ProducerLease() {
        if (active_) {
            abort();
        }
    }

    ProducerLease(const ProducerLease&) = delete;
    ProducerLease& operator=(const ProducerLease&) = delete;

    ProducerLease(ProducerLease&& other) noexcept
        : ring_(other.ring_),
          pos_(other.pos_),
          total_alloc_(other.total_alloc_),
          payload_ptr_(other.payload_ptr_),
          payload_size_(other.payload_size_),
          msg_type_(other.msg_type_),
          active_(other.active_) {
        other.active_ = false;
    }

    ProducerLease& operator=(ProducerLease&& other) noexcept {
        if (this != &other) {
            if (active_) {
                abort();
            }
            ring_ = other.ring_;
            pos_ = other.pos_;
            total_alloc_ = other.total_alloc_;
            payload_ptr_ = other.payload_ptr_;
            payload_size_ = other.payload_size_;
            msg_type_ = other.msg_type_;
            active_ = other.active_;
            other.active_ = false;
        }
        return *this;
    }

    [[nodiscard]] uint8_t* data() noexcept { return payload_ptr_; }
    [[nodiscard]] const uint8_t* data() const noexcept { return payload_ptr_; }
    [[nodiscard]] uint32_t size() const noexcept { return payload_size_; }
    [[nodiscard]] std::span<uint8_t> span() noexcept { return {payload_ptr_, payload_size_}; }

    /// Commit the reserved slot and publish to consumers.
    void commit() noexcept {
        if (!active_) return;
        ring_->commit_reservation(pos_, total_alloc_, msg_type_);
        active_ = false;
    }

    /// Abort the reservation, converting it into a SKIPPED frame.
    void abort() noexcept {
        if (!active_) return;
        ring_->abort_reservation(pos_, total_alloc_);
        active_ = false;
    }

private:
    TransactionalRingBuffer<Capacity>* ring_{nullptr};
    uint64_t pos_{0};
    uint32_t total_alloc_{0};
    uint8_t* payload_ptr_{nullptr};
    uint32_t payload_size_{0};
    uint16_t msg_type_{0};
    bool active_{false};
};

/// Zero-copy read slice exposed to consumers.
struct MsgView {
    uint16_t type{0};
    uint32_t length{0};
    const uint8_t* data{nullptr};

    [[nodiscard]] std::span<const uint8_t> payload() const noexcept {
        return {data, length};
    }
};

/// Batched read lease locking continuous slots until destroyed or released.
template <size_t Capacity>
class ReadLease {
public:
    struct FrameDescriptor {
        uint64_t pos;
        uint32_t total_len;
    };

    ReadLease() noexcept = default;

    ReadLease(TransactionalRingBuffer<Capacity>* ring,
              std::vector<MsgView> views,
              std::vector<FrameDescriptor> frames) noexcept
        : ring_(ring),
          views_(std::move(views)),
          frames_(std::move(frames)),
          active_(true) {}

    ~ReadLease() {
        release();
    }

    ReadLease(const ReadLease&) = delete;
    ReadLease& operator=(const ReadLease&) = delete;

    ReadLease(ReadLease&& other) noexcept
        : ring_(other.ring_),
          views_(std::move(other.views_)),
          frames_(std::move(other.frames_)),
          active_(other.active_) {
        other.active_ = false;
    }

    ReadLease& operator=(ReadLease&& other) noexcept {
        if (this != &other) {
            release();
            ring_ = other.ring_;
            views_ = std::move(other.views_);
            frames_ = std::move(other.frames_);
            active_ = other.active_;
            other.active_ = false;
        }
        return *this;
    }

    [[nodiscard]] bool empty() const noexcept { return views_.empty(); }
    [[nodiscard]] size_t size() const noexcept { return views_.size(); }
    [[nodiscard]] const MsgView& operator[](size_t idx) const noexcept { return views_[idx]; }
    [[nodiscard]] auto begin() const noexcept { return views_.cbegin(); }
    [[nodiscard]] auto end() const noexcept { return views_.cend(); }

    /// Reclaim read slots and advance consumer tail.
    void release() noexcept {
        if (!active_) return;
        ring_->release_frames(frames_);
        active_ = false;
        views_.clear();
        frames_.clear();
    }

private:
    TransactionalRingBuffer<Capacity>* ring_{nullptr};
    std::vector<MsgView> views_;
    std::vector<FrameDescriptor> frames_;
    bool active_{false};
};

// ============================================================================
// Main Transactional Ring Buffer Class Template
// ============================================================================

template <size_t Capacity>
class TransactionalRingBuffer {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of two");
    static_assert(Capacity >= 64, "Capacity must be at least 64 bytes");
    static constexpr uint64_t MASK = Capacity - 1;

public:
    TransactionalRingBuffer() {
        buffer_ = std::make_unique_for_overwrite<uint8_t[]>(Capacity);
        // Clear all frame headers to STATUS_EMPTY
        std::memset(buffer_.get(), 0, Capacity);
    }

    ~TransactionalRingBuffer() = default;

    TransactionalRingBuffer(const TransactionalRingBuffer&) = delete;
    TransactionalRingBuffer& operator=(const TransactionalRingBuffer&) = delete;
    TransactionalRingBuffer(TransactionalRingBuffer&&) = delete;
    TransactionalRingBuffer& operator=(TransactionalRingBuffer&&) = delete;

    // ------------------------------------------------------------------------
    // Producer API
    // ------------------------------------------------------------------------

    /// Reserve contiguous space for a message of `payload_size` bytes.
    [[nodiscard]] std::optional<ProducerLease<Capacity>> reserve(uint32_t payload_size, uint16_t msg_type = FRAME_DATA) noexcept {
        const uint32_t total_alloc = align_to_8(static_cast<uint32_t>(sizeof(MsgHeader)) + payload_size);
        if (total_alloc > Capacity) {
            return std::nullopt; // Frame exceeds total buffer capacity
        }

        // Thread-local cached tail to minimize coherence bus transactions
        thread_local static uint64_t tl_cached_tail = 0;

        while (true) {
            uint64_t cur_head = write_head_.load(std::memory_order_relaxed);
            const uint64_t offset = cur_head & MASK;
            const uint64_t remaining_in_cycle = Capacity - offset;

            uint64_t reservation_bytes = total_alloc;
            bool needs_pad = false;
            uint32_t pad_size = 0;

            if (remaining_in_cycle < total_alloc) {
                // Not enough contiguous space at the end of the ring; inject PAD sentinel frame
                needs_pad = true;
                pad_size = static_cast<uint32_t>(remaining_in_cycle);
                reservation_bytes = pad_size + total_alloc;
            }

            // Check capacity against cached tail view
            if (cur_head + reservation_bytes - tl_cached_tail > Capacity) {
                tl_cached_tail = read_tail_.load(std::memory_order_acquire);
                if (cur_head + reservation_bytes - tl_cached_tail > Capacity) {
                    return std::nullopt; // Buffer full
                }
            }

            // Atomic reservation of contiguous range [cur_head, cur_head + reservation_bytes)
            if (write_head_.compare_exchange_weak(cur_head, cur_head + reservation_bytes,
                                                  std::memory_order_acq_rel,
                                                  std::memory_order_relaxed)) {
                if (needs_pad) {
                    // Initialize PAD sentinel frame at physical end of the circular buffer
                    MsgHeader* pad_hdr = reinterpret_cast<MsgHeader*>(&buffer_[cur_head & MASK]);
                    const uint8_t pad_epoch = static_cast<uint8_t>((cur_head / Capacity) & 0xFF);
                    pad_hdr->length = pad_size;
                    pad_hdr->type = FRAME_PAD;
                    pad_hdr->state.store(MsgHeader::encode_state(pad_epoch, STATUS_PAD), std::memory_order_release);

                    // Message slot begins at index 0 of next physical ring cycle
                    cur_head += pad_size;
                }

                // Initialize reserved frame header
                MsgHeader* msg_hdr = reinterpret_cast<MsgHeader*>(&buffer_[cur_head & MASK]);
                const uint8_t msg_epoch = static_cast<uint8_t>((cur_head / Capacity) & 0xFF);
                msg_hdr->length = total_alloc;
                msg_hdr->type = msg_type;
                msg_hdr->state.store(MsgHeader::encode_state(msg_epoch, STATUS_RESERVED), std::memory_order_relaxed);

                uint8_t* payload_ptr = &buffer_[(cur_head & MASK) + sizeof(MsgHeader)];
                return ProducerLease<Capacity>(this, cur_head, total_alloc, payload_ptr, payload_size, msg_type);
            }
        }
    }

    // ------------------------------------------------------------------------
    // Consumer API
    // ------------------------------------------------------------------------

    /// Acquire a batched zero-copy read lease covering up to `max_msgs` frames.
    [[nodiscard]] std::optional<ReadLease<Capacity>> acquire_read_lease(size_t max_msgs = 32) noexcept {
        if (max_msgs == 0) return std::nullopt;

        thread_local static uint64_t tl_cached_commit = 0;

        while (true) {
            uint64_t cur_read = read_head_.load(std::memory_order_acquire);
            if (cur_read >= tl_cached_commit) {
                tl_cached_commit = write_commit_.load(std::memory_order_acquire);
                if (cur_read >= tl_cached_commit) {
                    return std::nullopt; // No committed frames available
                }
            }

            uint64_t scan_pos = cur_read;
            size_t collected = 0;

            std::vector<MsgView> views;
            std::vector<typename ReadLease<Capacity>::FrameDescriptor> frames;
            views.reserve(max_msgs);
            frames.reserve(max_msgs + 2); // Space for PAD frames

            while (scan_pos < tl_cached_commit && collected < max_msgs) {
                const MsgHeader* hdr = reinterpret_cast<const MsgHeader*>(&buffer_[scan_pos & MASK]);
                const uint16_t st = hdr->state.load(std::memory_order_acquire);
                const uint8_t hdr_epoch = MsgHeader::extract_epoch(st);
                const FrameStatus status = MsgHeader::extract_status(st);
                const uint8_t expected_epoch = static_cast<uint8_t>((scan_pos / Capacity) & 0xFF);

                if (hdr_epoch != expected_epoch) {
                    break;
                }

                const uint32_t len = hdr->length;
                if (len == 0 || scan_pos + len > tl_cached_commit) {
                    break;
                }

                if (status == STATUS_COMMITTED) {
                    const uint8_t* payload_ptr = &buffer_[(scan_pos & MASK) + sizeof(MsgHeader)];
                    const uint32_t payload_len = len - static_cast<uint32_t>(sizeof(MsgHeader));
                    views.push_back({hdr->type, payload_len, payload_ptr});
                    frames.push_back({scan_pos, len});
                    collected++;
                    scan_pos += len;
                } else if (status == STATUS_PAD || status == STATUS_SKIPPED) {
                    frames.push_back({scan_pos, len});
                    scan_pos += len;
                } else {
                    break;
                }
            }

            if (scan_pos == cur_read) {
                return std::nullopt;
            }

            // Lock-free reservation of reader range [cur_read, scan_pos)
            if (read_head_.compare_exchange_weak(cur_read, scan_pos,
                                                 std::memory_order_acq_rel,
                                                 std::memory_order_acquire)) {
                if (views.empty()) {
                    // Contained only PAD / SKIPPED frames; release immediately and loop
                    release_frames(frames);
                    continue;
                }

                return ReadLease<Capacity>(this, std::move(views), std::move(frames));
            }
        }
    }

    // ------------------------------------------------------------------------
    // Internal Lifecycle & Linearization Hooks
    // ------------------------------------------------------------------------

    void commit_reservation(uint64_t pos, uint32_t total_alloc, uint16_t msg_type) noexcept {
        MsgHeader* hdr = reinterpret_cast<MsgHeader*>(&buffer_[pos & MASK]);
        const uint8_t epoch = static_cast<uint8_t>((pos / Capacity) & 0xFF);
        hdr->length = total_alloc;
        hdr->type = msg_type;
        hdr->state.store(MsgHeader::encode_state(epoch, STATUS_COMMITTED), std::memory_order_release);

        cascade_commit();
    }

    void abort_reservation(uint64_t pos, uint32_t total_alloc) noexcept {
        MsgHeader* hdr = reinterpret_cast<MsgHeader*>(&buffer_[pos & MASK]);
        const uint8_t epoch = static_cast<uint8_t>((pos / Capacity) & 0xFF);
        hdr->length = total_alloc;
        hdr->type = FRAME_SKIPPED;
        hdr->state.store(MsgHeader::encode_state(epoch, STATUS_SKIPPED), std::memory_order_release);

        cascade_commit();
    }

    void release_frames(const std::vector<typename ReadLease<Capacity>::FrameDescriptor>& frames) noexcept {
        for (const auto& f : frames) {
            MsgHeader* hdr = reinterpret_cast<MsgHeader*>(&buffer_[f.pos & MASK]);
            const uint8_t epoch = static_cast<uint8_t>((f.pos / Capacity) & 0xFF);
            hdr->state.store(MsgHeader::encode_state(epoch, STATUS_RELEASED), std::memory_order_release);
        }
        cascade_tail();
    }

private:
    [[nodiscard]] static constexpr uint32_t align_to_8(uint32_t size) noexcept {
        return (size + 7u) & ~7u;
    }

    /// Linearizes out-of-order commits and advances `write_commit_` sequentially.
    void cascade_commit() noexcept {
        while (true) {
            uint64_t cur_commit = write_commit_.load(std::memory_order_acquire);
            const uint64_t cur_head = write_head_.load(std::memory_order_relaxed);
            if (cur_commit >= cur_head) {
                break;
            }

            const MsgHeader* hdr = reinterpret_cast<const MsgHeader*>(&buffer_[cur_commit & MASK]);
            const uint16_t st = hdr->state.load(std::memory_order_acquire);
            const uint8_t hdr_epoch = MsgHeader::extract_epoch(st);
            const FrameStatus status = MsgHeader::extract_status(st);
            const uint8_t expected_epoch = static_cast<uint8_t>((cur_commit / Capacity) & 0xFF);

            if (hdr_epoch == expected_epoch &&
                (status == STATUS_COMMITTED || status == STATUS_PAD || status == STATUS_SKIPPED)) {
                const uint32_t len = hdr->length;
                if (len == 0) break;

                if (write_commit_.compare_exchange_weak(cur_commit, cur_commit + len,
                                                        std::memory_order_acq_rel,
                                                        std::memory_order_acquire)) {
                    continue; // Successfully advanced; cascade next frame
                }
                continue;
            }
            break; // Preceding frame in write-in-progress state
        }
    }

    /// Linearizes out-of-order reader releases and advances `read_tail_` to reclaim capacity.
    void cascade_tail() noexcept {
        while (true) {
            uint64_t cur_tail = read_tail_.load(std::memory_order_acquire);
            const uint64_t cur_read = read_head_.load(std::memory_order_relaxed);
            if (cur_tail >= cur_read) {
                break;
            }

            MsgHeader* hdr = reinterpret_cast<MsgHeader*>(&buffer_[cur_tail & MASK]);
            const uint16_t st = hdr->state.load(std::memory_order_acquire);
            const uint8_t hdr_epoch = MsgHeader::extract_epoch(st);
            const FrameStatus status = MsgHeader::extract_status(st);
            const uint8_t expected_epoch = static_cast<uint8_t>((cur_tail / Capacity) & 0xFF);

            if (hdr_epoch == expected_epoch &&
                (status == STATUS_RELEASED || status == STATUS_PAD || status == STATUS_SKIPPED)) {
                const uint32_t len = hdr->length;
                if (len == 0) break;

                // Reset frame state to EMPTY for future ring cycles before advancing tail
                const uint8_t next_epoch = static_cast<uint8_t>((expected_epoch + 1) & 0xFF);
                hdr->state.store(MsgHeader::encode_state(next_epoch, STATUS_EMPTY), std::memory_order_release);

                if (read_tail_.compare_exchange_weak(cur_tail, cur_tail + len,
                                                     std::memory_order_acq_rel,
                                                     std::memory_order_acquire)) {
                    continue;
                }
                continue;
            }
            break;
        }
    }

private:
    // Raw ring memory storage
    std::unique_ptr<uint8_t[]> buffer_;

    // Isolated Cachelines for Atomic State Variables
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> write_head_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> write_commit_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> read_head_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> read_tail_{0};
};

} // namespace stream_engine
```

