### Complete Implementation: `TransactionalRingBuffer.hpp`

```cpp
#pragma once

#include <atomic>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <memory>
#include <new>
#include <optional>
#include <span>
#include <type_traits>
#include <vector>

#ifdef __cpp_lib_hardware_interference_size
using std::hardware_constructive_interference_size;
using std::hardware_destructive_interference_size;
#else
static constexpr size_t hardware_destructive_interference_size = 64;
static constexpr size_t hardware_constructive_interference_size = 64;
#endif

namespace stream_core {

enum FrameStatus : uint16_t {
    STATUS_UNCOMMITTED = 0x0000,
    STATUS_DATA        = 0x0001,
    STATUS_PAD         = 0x0002,
    STATUS_ABORTED     = 0x0003,
};

static constexpr uint16_t MAGIC_MASK   = 0xFF00;
static constexpr uint16_t FRAME_MAGIC  = 0xA500;
static constexpr size_t   FRAME_ALIGN  = 8;

struct alignas(8) MsgHeader {
    std::atomic<uint64_t> sequence{UINT64_MAX}; // Sequence parity tracker
    uint32_t              length{0};            // Payload length
    uint16_t              type_flags{0};        // User-defined message type & flags
    uint16_t              status_magic{0};      // Status & verification magic
};

static_assert(sizeof(MsgHeader) == 16, "MsgHeader must be exactly 16 bytes");
static_assert(alignof(MsgHeader) == 8, "MsgHeader must be 8-byte aligned");

[[nodiscard]] static constexpr uint32_t align_up(uint32_t val, size_t alignment) noexcept {
    return static_cast<uint32_t>((val + (alignment - 1)) & ~(alignment - 1));
}

[[nodiscard]] static constexpr uint32_t calc_total_frame_size(uint32_t payload_len) noexcept {
    return align_up(static_cast<uint32_t>(sizeof(MsgHeader)) + payload_len, FRAME_ALIGN);
}

struct ReadMessage {
    std::span<const uint8_t> payload;
    uint16_t                 type{0};
    uint16_t                 flags{0};
};

template <size_t Capacity>
class TransactionalRingBuffer {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of two");
    static_assert(Capacity >= 1024, "Capacity must be at least 1024 bytes");
    static_assert(Capacity % hardware_destructive_interference_size == 0,
                  "Capacity must be a multiple of cache line size");

    static constexpr size_t BUFFER_MASK = Capacity - 1;

public:
    class Reservation {
    public:
        Reservation() noexcept = default;

        Reservation(TransactionalRingBuffer* ring, uint64_t seq, uint32_t payload_len,
                    uint32_t total_size, uint8_t* payload_ptr, MsgHeader* header) noexcept
            : ring_(ring), seq_(seq), payload_len_(payload_len), total_size_(total_size),
              payload_ptr_(payload_ptr), header_(header), active_(true) {}

        Reservation(const Reservation&) = delete;
        Reservation& operator=(const Reservation&) = delete;

        Reservation(Reservation&& other) noexcept
            : ring_(other.ring_), seq_(other.seq_), payload_len_(other.payload_len_),
              total_size_(other.total_size_), payload_ptr_(other.payload_ptr_),
              header_(other.header_), active_(other.active_) {
            other.active_ = false;
        }

        Reservation& operator=(Reservation&& other) noexcept {
            if (this != &other) {
                if (active_) abort();
                ring_        = other.ring_;
                seq_         = other.seq_;
                payload_len_ = other.payload_len_;
                total_size_  = other.total_size_;
                payload_ptr_ = other.payload_ptr_;
                header_      = other.header_;
                active_      = other.active_;
                other.active_ = false;
            }
            return *this;
        }

        ~Reservation() {
            if (active_) {
                abort();
            }
        }

        [[nodiscard]] uint8_t* data() noexcept { return payload_ptr_; }
        [[nodiscard]] size_t size() const noexcept { return payload_len_; }
        [[nodiscard]] std::span<uint8_t> span() noexcept { return {payload_ptr_, payload_len_}; }

        void commit(uint16_t type = 0, uint16_t flags = 0) noexcept {
            if (!active_) return;
            header_->length       = payload_len_;
            header_->type_flags   = static_cast<uint16_t>((type & 0xFF) | ((flags & 0xFF) << 8));
            header_->status_magic = FRAME_MAGIC | STATUS_DATA;

            // Release payload writes and metadata before sequence is published
            header_->sequence.store(seq_, std::memory_order_release);
            active_ = false;
            ring_->advance_commit_head();
        }

        void abort() noexcept {
            if (!active_) return;
            header_->length       = payload_len_;
            header_->type_flags   = 0;
            header_->status_magic = FRAME_MAGIC | STATUS_ABORTED;

            // Release frame marking as aborted
            header_->sequence.store(seq_, std::memory_order_release);
            active_ = false;
            ring_->advance_commit_head();
        }

    private:
        TransactionalRingBuffer* ring_{nullptr};
        uint64_t                 seq_{0};
        uint32_t                 payload_len_{0};
        uint32_t                 total_size_{0};
        uint8_t*                 payload_ptr_{nullptr};
        MsgHeader*               header_{nullptr};
        bool                     active_{false};
    };

    class ReadLease {
    public:
        ReadLease() noexcept = default;

        ReadLease(TransactionalRingBuffer* ring, uint64_t ticket, uint64_t end_off,
                  std::vector<ReadMessage> msgs) noexcept
            : ring_(ring), ticket_(ticket), end_off_(end_off),
              msgs_(std::move(msgs)), active_(true) {}

        ReadLease(const ReadLease&) = delete;
        ReadLease& operator=(const ReadLease&) = delete;

        ReadLease(ReadLease&& other) noexcept
            : ring_(other.ring_), ticket_(other.ticket_), end_off_(other.end_off_),
              msgs_(std::move(other.msgs_)), active_(other.active_) {
            other.active_ = false;
        }

        ReadLease& operator=(ReadLease&& other) noexcept {
            if (this != &other) {
                release();
                ring_   = other.ring_;
                ticket_ = other.ticket_;
                end_off_= other.end_off_;
                msgs_   = std::move(other.msgs_);
                active_ = other.active_;
                other.active_ = false;
            }
            return *this;
        }

        ~ReadLease() {
            release();
        }

        void release() noexcept {
            if (active_ && ring_) {
                ring_->release_lease(ticket_, end_off_);
                active_ = false;
            }
        }

        [[nodiscard]] bool empty() const noexcept { return msgs_.empty(); }
        [[nodiscard]] size_t size() const noexcept { return msgs_.size(); }
        [[nodiscard]] const std::vector<ReadMessage>& messages() const noexcept { return msgs_; }
        [[nodiscard]] const ReadMessage& operator[](size_t idx) const noexcept { return msgs_[idx]; }

        auto begin() const noexcept { return msgs_.begin(); }
        auto end() const noexcept { return msgs_.end(); }

    private:
        TransactionalRingBuffer* ring_{nullptr};
        uint64_t                 ticket_{0};
        uint64_t                 end_off_{0};
        std::vector<ReadMessage> msgs_{};
        bool                     active_{false};
    };

    TransactionalRingBuffer() {
        buffer_ = std::make_unique<uint8_t[]>(Capacity);
        std::memset(buffer_.get(), 0, Capacity);
        for (size_t i = 0; i < MAX_INFLIGHT_LEASES; ++i) {
            lease_slots_[i].lease_id.store(UINT64_MAX, std::memory_order_relaxed);
            lease_slots_[i].end_offset.store(0, std::memory_order_relaxed);
            lease_slots_[i].ready.store(false, std::memory_order_relaxed);
        }
    }

    ~TransactionalRingBuffer() = default;

    [[nodiscard]] std::optional<Reservation> reserve(uint32_t payload_len) noexcept {
        const uint32_t req_frame_size = calc_total_frame_size(payload_len);
        if (req_frame_size > Capacity - sizeof(MsgHeader)) {
            return std::nullopt; // Payload exceeds total usable capacity
        }

        // Thread-local cached tail to minimize NUMA interconnect traffic
        thread_local uint64_t tl_cached_tail = 0;

        uint64_t cur_head = producer_reserve_head_.load(std::memory_order_relaxed);
        while (true) {
            const size_t phys_offset  = cur_head & BUFFER_MASK;
            const size_t space_to_end = Capacity - phys_offset;

            const bool need_pad = (space_to_end < req_frame_size);
            const uint64_t total_advance = need_pad ? (space_to_end + req_frame_size) : req_frame_size;

            if (cur_head + total_advance - tl_cached_tail > Capacity) {
                tl_cached_tail = consumer_release_tail_.load(std::memory_order_acquire);
                if (cur_head + total_advance - tl_cached_tail > Capacity) {
                    return std::nullopt; // Ring full
                }
            }

            if (producer_reserve_head_.compare_exchange_weak(cur_head, cur_head + total_advance,
                                                             std::memory_order_relaxed,
                                                             std::memory_order_relaxed)) {
                if (need_pad) {
                    // Inject deterministic PAD frame at buffer tail
                    auto* pad_hdr = reinterpret_cast<MsgHeader*>(&buffer_[phys_offset]);
                    pad_hdr->length       = static_cast<uint32_t>(space_to_end - sizeof(MsgHeader));
                    pad_hdr->type_flags   = 0;
                    pad_hdr->status_magic = FRAME_MAGIC | STATUS_PAD;
                    pad_hdr->sequence.store(cur_head, std::memory_order_release);

                    // Allocate actual payload at wrapped index 0
                    const uint64_t data_seq = cur_head + space_to_end;
                    auto* data_hdr = reinterpret_cast<MsgHeader*>(&buffer_[0]);
                    uint8_t* payload_ptr = &buffer_[sizeof(MsgHeader)];

                    return Reservation(this, data_seq, payload_len, req_frame_size, payload_ptr, data_hdr);
                } else {
                    auto* data_hdr = reinterpret_cast<MsgHeader*>(&buffer_[phys_offset]);
                    uint8_t* payload_ptr = &buffer_[phys_offset + sizeof(MsgHeader)];

                    return Reservation(this, cur_head, payload_len, req_frame_size, payload_ptr, data_hdr);
                }
            }
            // CAS failed; cur_head refreshed automatically
        }
    }

    [[nodiscard]] ReadLease acquire_read_lease(size_t max_count = 64, size_t max_bytes = 65536) noexcept {
        if (max_count == 0 || max_bytes == 0) return ReadLease{};

        thread_local uint64_t tl_cached_commit_head = 0;
        uint64_t cur_tail = consumer_reserve_tail_.load(std::memory_order_relaxed);

        while (true) {
            uint64_t commit_pos = tl_cached_commit_head;
            if (cur_tail >= commit_pos) {
                commit_pos = producer_commit_head_.load(std::memory_order_acquire);
                tl_cached_commit_head = commit_pos;
                if (cur_tail >= commit_pos) {
                    return ReadLease{}; // Buffer empty
                }
            }

            uint64_t scan_off = cur_tail;
            size_t count = 0;
            size_t bytes = 0;
            std::vector<ReadMessage> batch_msgs;
            batch_msgs.reserve(std::min(max_count, size_t{64}));

            while (scan_off < commit_pos && count < max_count && bytes < max_bytes) {
                const size_t phys_off = scan_off & BUFFER_MASK;
                const auto* hdr = reinterpret_cast<const MsgHeader*>(&buffer_[phys_off]);

                if (hdr->sequence.load(std::memory_order_acquire) != scan_off) {
                    break;
                }

                const uint32_t chunk_size = calc_total_frame_size(hdr->length);
                const uint16_t status     = hdr->status_magic & 0x00FF;

                if (status == STATUS_DATA) {
                    const uint8_t* payload = &buffer_[phys_off + sizeof(MsgHeader)];
                    batch_msgs.push_back(ReadMessage{
                        .payload = std::span<const uint8_t>(payload, hdr->length),
                        .type    = static_cast<uint16_t>(hdr->type_flags & 0xFF),
                        .flags   = static_cast<uint16_t>((hdr->type_flags >> 8) & 0xFF)
                    });
                    bytes += hdr->length;
                    count++;
                }

                scan_off += chunk_size;
            }

            if (scan_off == cur_tail) {
                return ReadLease{};
            }

            if (consumer_reserve_tail_.compare_exchange_weak(cur_tail, scan_off,
                                                             std::memory_order_acq_rel,
                                                             std::memory_order_relaxed)) {
                const uint64_t ticket   = consumer_lease_ticket_.fetch_add(1, std::memory_order_relaxed);
                const size_t   slot_idx = ticket & LEASE_MASK;

                lease_slots_[slot_idx].end_offset.store(scan_off, std::memory_order_relaxed);
                lease_slots_[slot_idx].ready.store(false, std::memory_order_relaxed);
                lease_slots_[slot_idx].lease_id.store(ticket, std::memory_order_release);

                return ReadLease(this, ticket, scan_off, std::move(batch_msgs));
            }
        }
    }

private:
    void advance_commit_head() noexcept {
        uint64_t cur_commit = producer_commit_head_.load(std::memory_order_relaxed);
        while (true) {
            const uint64_t cur_reserve = producer_reserve_head_.load(std::memory_order_acquire);
            if (cur_commit >= cur_reserve) {
                break;
            }

            const size_t phys_offset = cur_commit & BUFFER_MASK;
            const auto* hdr = reinterpret_cast<const MsgHeader*>(&buffer_[phys_offset]);

            if (hdr->sequence.load(std::memory_order_acquire) != cur_commit) {
                break; // Uncommitted transaction block encountered
            }

            const uint32_t chunk_size = calc_total_frame_size(hdr->length);

            if (producer_commit_head_.compare_exchange_weak(cur_commit, cur_commit + chunk_size,
                                                            std::memory_order_release,
                                                            std::memory_order_relaxed)) {
                cur_commit += chunk_size;
            }
        }
    }

    void release_lease(uint64_t ticket, [[maybe_unused]] uint64_t end_offset) noexcept {
        const size_t slot_idx = ticket & LEASE_MASK;
        lease_slots_[slot_idx].ready.store(true, std::memory_order_release);
        advance_release_tail();
    }

    void advance_release_tail() noexcept {
        uint64_t cur_retire = consumer_retire_ticket_.load(std::memory_order_relaxed);
        while (true) {
            const uint64_t cur_ticket = consumer_lease_ticket_.load(std::memory_order_acquire);
            if (cur_retire >= cur_ticket) {
                break;
            }

            const size_t slot_idx = cur_retire & LEASE_MASK;
            auto& slot = lease_slots_[slot_idx];

            if (slot.lease_id.load(std::memory_order_acquire) != cur_retire) {
                break;
            }
            if (!slot.ready.load(std::memory_order_acquire)) {
                break;
            }

            const uint64_t end_off = slot.end_offset.load(std::memory_order_relaxed);
            consumer_release_tail_.store(end_off, std::memory_order_release);

            if (consumer_retire_ticket_.compare_exchange_weak(cur_retire, cur_retire + 1,
                                                              std::memory_order_release,
                                                              std::memory_order_relaxed)) {
                cur_retire++;
            }
        }
    }

private:
    std::unique_ptr<uint8_t[]> buffer_;

    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> producer_reserve_head_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> producer_commit_head_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> consumer_reserve_tail_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> consumer_release_tail_{0};

    static constexpr size_t MAX_INFLIGHT_LEASES = 65536;
    static constexpr size_t LEASE_MASK          = MAX_INFLIGHT_LEASES - 1;

    struct LeaseSlot {
        std::atomic<uint64_t> lease_id{UINT64_MAX};
        std::atomic<uint64_t> end_offset{0};
        std::atomic<bool>     ready{false};
    };

    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> consumer_lease_ticket_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> consumer_retire_ticket_{0};
    std::unique_ptr<LeaseSlot[]> lease_slots_{std::make_unique<LeaseSlot[]>(MAX_INFLIGHT_LEASES)};
};

} // namespace stream_core
