### Verification Harness & Multi-Threaded Stress Test: `main.cpp`

```cpp
#include "TransactionalRingBuffer.hpp"
#include <chrono>
#include <cstdint>
#include <iostream>
#include <random>
#include <thread>
#include <vector>

namespace {

uint32_t compute_crc32(const uint8_t* data, size_t len) noexcept {
    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int k = 0; k < 8; ++k) {
            crc = (crc >> 1) ^ (0xEDB88320 & (-(crc & 1)));
        }
    }
    return ~crc;
}

#pragma pack(push, 1)
struct TestPayloadHeader {
    uint32_t producer_id;
    uint64_t sequence_num;
    uint32_t payload_len;
    uint32_t checksum;
};
#pragma pack(pop)

static_assert(sizeof(TestPayloadHeader) == 20, "TestPayloadHeader must be packed to 20 bytes");

} // namespace

int main() {
    using namespace stream_core;

    constexpr size_t RING_CAPACITY   = 16 * 1024 * 1024; // 16 MB
    constexpr size_t NUM_PRODUCERS   = 8;
    constexpr size_t NUM_CONSUMERS   = 8;
    constexpr size_t MSGS_PER_PRODUCER = 50'000;
    constexpr double ABORT_RATE      = 0.12; // 12% intentional dynamic rollback

    std::cout << "========================================================\n"
              << "  MPMC Transactional Ring Buffer Stress & Integrity Test\n"
              << "  Capacity: " << (RING_CAPACITY / (1024 * 1024)) << " MB | Producers: " << NUM_PRODUCERS
              << " | Consumers: " << NUM_CONSUMERS << "\n"
              << "  Target Messages: " << (NUM_PRODUCERS * MSGS_PER_PRODUCER) << " with "
              << (ABORT_RATE * 100) << "% Abort Rollbacks\n"
              << "========================================================\n";

    auto ring = std::make_unique<TransactionalRingBuffer<RING_CAPACITY>>();

    std::atomic<bool> producers_done{false};
    std::atomic<uint64_t> total_committed_count{0};
    std::atomic<uint64_t> total_aborted_count{0};
    std::atomic<uint64_t> total_consumed_count{0};
    std::atomic<uint64_t> corruption_errors{0};
    std::atomic<uint64_t> ordering_errors{0};

    // Track expected sequence per producer
    std::vector<std::atomic<uint64_t>> next_expected_seq(NUM_PRODUCERS);
    for (size_t i = 0; i < NUM_PRODUCERS; ++i) {
        next_expected_seq[i].store(0, std::memory_order_relaxed);
    }

    const auto start_time = std::chrono::steady_clock::now();

    // Spawn Producers
    std::vector<std::jthread> producer_threads;
    producer_threads.reserve(NUM_PRODUCERS);

    for (uint32_t p_id = 0; p_id < NUM_PRODUCERS; ++p_id) {
        producer_threads.emplace_back([&, p_id]() {
            std::mt19937_64 rng(1337 + p_id);
            std::uniform_int_distribution<uint32_t> len_dist(sizeof(TestPayloadHeader), 2048);
            std::uniform_real_distribution<double>  abort_dist(0.0, 1.0);

            uint64_t seq = 0;
            while (seq < MSGS_PER_PRODUCER) {
                const uint32_t len = len_dist(rng);
                auto res = ring->reserve(len);

                if (!res.has_value()) {
                    std::this_thread::yield();
                    continue;
                }

                if (abort_dist(rng) < ABORT_RATE) {
                    // Populate with poison pattern and abort
                    std::memset(res->data(), 0xEE, res->size());
                    res->abort();
                    total_aborted_count.fetch_add(1, std::memory_order_relaxed);
                    continue;
                }

                // Format valid frame
                auto* hdr = reinterpret_cast<TestPayloadHeader*>(res->data());
                hdr->producer_id  = p_id;
                hdr->sequence_num = seq;
                hdr->payload_len  = len;

                uint8_t* body = res->data() + sizeof(TestPayloadHeader);
                const size_t body_len = len - sizeof(TestPayloadHeader);
                for (size_t i = 0; i < body_len; ++i) {
                    body[i] = static_cast<uint8_t>((p_id * 31 + seq * 17 + i) & 0xFF);
                }

                hdr->checksum = compute_crc32(body, body_len);
                res->commit(1, 0);

                total_committed_count.fetch_add(1, std::memory_order_relaxed);
                seq++;
            }
        });
    }

    // Spawn Consumers
    std::vector<std::jthread> consumer_threads;
    consumer_threads.reserve(NUM_CONSUMERS);

    for (uint32_t c_id = 0; c_id < NUM_CONSUMERS; ++c_id) {
        consumer_threads.emplace_back([&]() {
            while (!producers_done.load(std::memory_order_acquire) ||
                   total_consumed_count.load(std::memory_order_acquire) < (NUM_PRODUCERS * MSGS_PER_PRODUCER)) {
                auto lease = ring->acquire_read_lease(32, 65536);
                if (lease.empty()) {
                    std::this_thread::yield();
                    continue;
                }

                for (const auto& msg : lease) {
                    if (msg.payload.size() < sizeof(TestPayloadHeader)) {
                        corruption_errors.fetch_add(1, std::memory_order_relaxed);
                        continue;
                    }

                    TestPayloadHeader hdr;
                    std::memcpy(&hdr, msg.payload.data(), sizeof(TestPayloadHeader));

                    if (hdr.producer_id >= NUM_PRODUCERS || hdr.payload_len != msg.payload.size()) {
                        corruption_errors.fetch_add(1, std::memory_order_relaxed);
                        continue;
                    }

                    const uint8_t* body = msg.payload.data() + sizeof(TestPayloadHeader);
                    const size_t body_len = msg.payload.size() - sizeof(TestPayloadHeader);
                    const uint32_t calculated_crc = compute_crc32(body, body_len);

                    if (calculated_crc != hdr.checksum) {
                        corruption_errors.fetch_add(1, std::memory_order_relaxed);
                    }

                    // Check strictly increasing FIFO order per producer
                    uint64_t expected = hdr.sequence_num;
                    if (!next_expected_seq[hdr.producer_id].compare_exchange_strong(
                            expected, hdr.sequence_num + 1, std::memory_order_relaxed)) {
                        // If current seq does not match expected, mark ordering fault
                        if (hdr.sequence_num < expected) {
                            ordering_errors.fetch_add(1, std::memory_order_relaxed);
                        }
                    }

                    total_consumed_count.fetch_add(1, std::memory_order_relaxed);
                }
                lease.release();
            }
        });
    }

    // Await producer completion
    producer_threads.clear();
    producers_done.store(true, std::memory_order_release);

    // Await consumer draining
    consumer_threads.clear();

    const auto end_time = std::chrono::steady_clock::now();
    const auto elapsed_ms = std::chrono::duration_cast<std::chrono::milliseconds>(end_time - start_time).count();

    const uint64_t committed = total_committed_count.load();
    const uint64_t consumed  = total_consumed_count.load();
    const uint64_t aborted   = total_aborted_count.load();
    const uint64_t corrs     = corruption_errors.load();
    const uint64_t ord_errs  = ordering_errors.load();

    std::cout << "\n-------------------- TEST RESULTS --------------------\n"
              << "Elapsed Time:         " << elapsed_ms << " ms\n"
              << "Committed Messages:   " << committed << "\n"
              << "Aborted Reservations: " << aborted << "\n"
              << "Consumed Messages:    " << consumed << "\n"
