#ifndef __cpp_lib_hardware_interference_size
namespace std {
    constexpr size_t hardware_destructive_interference_size = 64;
    constexpr size_t hardware_constructive_interference_size = 64;
}
#endif

// ============================================================================
// 1. ZERO-OVERHEAD EPOCH-BASED RECLAMATION (EBR)
// ============================================================================

class EpochManager {
public:
    static constexpr uint64_t INACTIVE = std::numeric_limits<uint64_t>::max();
    static constexpr size_t NUM_EPOCHS = 3;
    static constexpr size_t RETIRE_BATCH_THRESHOLD = 64;

    struct alignas(std::hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{INACTIVE};
        ThreadControlBlock* next{nullptr};
    };

    struct RetiredObject {
        void* ptr{nullptr};
        void (*deleter)(void*){nullptr};
    };

    struct ThreadLocalState {
        ThreadControlBlock* tcb{nullptr};
        std::array<std::vector<RetiredObject>, NUM_EPOCHS> limbo_lists;
        size_t retire_counter{0};
        uint64_t last_sync_epoch{0};
    };

private:
    alignas(std::hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_{0};
    alignas(std::hardware_destructive_interference_size) std::atomic<ThreadControlBlock*> tcb_head_{nullptr};

    inline static thread_local ThreadLocalState tls_state_;

    EpochManager() = default;

public:
    static EpochManager& instance() {
        static EpochManager manager;
        return manager;
    }

    ~EpochManager() {
        // Drain all remaining limbo allocations
        for (size_t e = 0; e < NUM_EPOCHS; ++e) {
            for (auto& obj : tls_state_.limbo_lists[e]) {
                if (obj.deleter && obj.ptr) {
                    obj.deleter(obj.ptr);
                }
            }
            tls_state_.limbo_lists[e].clear();
        }
    }

    void register_thread() {
        if (tls_state_.tcb != nullptr) return;
        auto* tcb = new ThreadControlBlock();
        ThreadControlBlock* old_head = tcb_head_.load(std::memory_order_relaxed);
        do {
            tcb->next = old_head;
        } while (!tcb_head_.compare_exchange_weak(
            old_head, tcb,
            std::memory_order_release,
            std::memory_order_relaxed));
        tls_state_.tcb = tcb;
    }

    void unregister_thread() {
        if (!tls_state_.tcb) return;
        tls_state_.tcb->local_epoch.store(INACTIVE, std::memory_order_release);
    }

    class Guard {
    public:
        explicit Guard(EpochManager& mgr) : mgr_(mgr) {
            if (__builtin_expect(!tls_state_.tcb, 0)) {
                mgr_.register_thread();
            }
            uint64_t cur_epoch = mgr_.global_epoch_.load(std::memory_order_relaxed);
            tls_state_.tcb->local_epoch.store(cur_epoch, std::memory_order_release);
            #if defined(__x86_64__) || defined(_M_X64)
            std::atomic_signal_fence(std::memory_order_acq_rel);
            #else
            std::atomic_thread_fence(std::memory_order_acquire);
            #endif
        }

        ~Guard() {
            tls_state_.tcb->local_epoch.store(INACTIVE, std::memory_order_release);
            if (++tls_state_.retire_counter >= RETIRE_BATCH_THRESHOLD) {
                tls_state_.retire_counter = 0;
                mgr_.try_advance_and_reclaim();
            }
        }

        Guard(const Guard&) = delete;
        Guard& operator=(const Guard&) = delete;
        Guard(Guard&&) = delete;
        Guard& operator=(Guard&&) = delete;

    private:
        EpochManager& mgr_;
    };

    Guard enter() {
        return Guard(*this);
    }

    template <typename T>
    void retire(T* ptr) {
        if (!ptr) return;
        auto deleter = [](void* p) { delete static_cast<T*>(p); };
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t idx = cur_epoch % NUM_EPOCHS;
        tls_state_.limbo_lists[idx].push_back({ptr, deleter});
    }

    void try_advance_and_reclaim() {
        uint64_t current_g_epoch = global_epoch_.load(std::memory_order_relaxed);
        ThreadControlBlock* curr = tcb_head_.load(std::memory_order_acquire);

        bool can_advance = true;
        while (curr) {
            uint64_t th_epoch = curr->local_epoch.load(std::memory_order_acquire);
            if (th_epoch != INACTIVE && th_epoch < current_g_epoch) {
                can_advance = false;
                break;
            }
            curr = curr->next;
        }

        if (can_advance) {
            if (global_epoch_.compare_exchange_strong(
                    current_g_epoch, current_g_epoch + 1,
                    std::memory_order_acq_rel, std::memory_order_relaxed)) {
                current_g_epoch++;
            }
        }

        // Reclaim memory safe at this stage: (current_g_epoch + 1) % 3
        size_t reclaim_idx = (current_g_epoch + 1) % NUM_EPOCHS;
        auto& list = tls_state_.limbo_lists[reclaim_idx];
        for (auto& item : list) {
            item.deleter(item.ptr);
        }
        list.clear();
    }
};

// ============================================================================
// 2. ASYNCHRONOUS PIPELINED WRITE-AHEAD LOG (AsyncWAL)
// ============================================================================

enum class LogRecordType : uint8_t {
    INSERT = 1,
    SPLIT = 2,
    CHECKPOINT = 3
};

#pragma pack(push, 1)
template <typename Key, typename Value>
struct LogRecord {
    uint64_t lsn;
    LogRecordType type;
    Key key;
    Value value;
    uint64_t node_id;
    uint32_t payload_len;
    uint32_t checksum;

    static uint32_t compute_checksum(const LogRecord& rec) {
        const auto* bytes = reinterpret_cast<const uint8_t*>(&rec);
        uint32_t hash = 2166136261u;
        for (size_t i = 0; i < sizeof(LogRecord) - sizeof(uint32_t); ++i) {
            hash ^= bytes[i];
            hash *= 16777619u;
        }
        return hash;
    }
};
#pragma pack(pop)

template <typename Key, typename Value>
class AsyncWAL {
public:
    static constexpr size_t BUFFER_SIZE = 4096 * 64; // 256 KB Direct-I/O aligned buffer

    explicit AsyncWAL(const std::string& path) 
        : running_(true), global_lsn_(1), flushed_lsn_(0) {
        fd_ = ::open(path.c_str(), O_CREAT | O_RDWR | O_TRUNC, 0644);
        if (fd_ < 0) {
            throw std::runtime_error("Failed to open WAL file");
        }
        buffer_ = static_cast<char*>(::aligned_alloc(4096, BUFFER_SIZE));
        flush_thread_ = std::thread(&AsyncWAL::flush_loop, this);
    }

    ~AsyncWAL() {
        running_.store(false, std::memory_order_release);
        cv_.notify_all();
        if (flush_thread_.joinable()) {
            flush_thread_.join();
        }
        if (fd_ >= 0) {
            ::close(fd_);
        }
        if (buffer_) {
            ::free(buffer_);
        }
    }

    uint64_t append_record(LogRecordType type, Key k, Value v, uint64_t node_id) {
        uint64_t lsn = global_lsn_.fetch_add(1, std::memory_order_relaxed);
        LogRecord<Key, Value> rec;
        rec.lsn = lsn;
        rec.type = type;
        rec.key = k;
        rec.value = v;
        rec.node_id = node_id;
        rec.payload_len = sizeof(LogRecord<Key, Value>);
        rec.checksum = LogRecord<Key, Value>::compute_checksum(rec);

        {
            std::unique_lock<std::mutex> lock(queue_mutex_);
            write_queue_.push_back(rec);
        }
        cv_.notify_one();
        return lsn;
    }

    void wait_persisted(uint64_t lsn) {
        while (flushed_lsn_.load(std::memory_order_acquire) < lsn) {
            std::this_thread::yield();
        }
    }

private:
    void flush_loop() {
        std::vector<LogRecord<Key, Value>> local_batch;
        local_batch.reserve(4096);

        while (running_.load(std::memory_order_acquire)) {
            {
                std::unique_lock<std::mutex> lock(queue_mutex_);
                cv_.wait_for(lock, std::chrono::microseconds(500), [this] {
                    return !write_queue_.empty() || !running_.load(std::memory_order_relaxed);
                });
                local_batch.swap(write_queue_);
            }

            if (local_batch.empty()) continue;

            size_t bytes_to_write = local_batch.size() * sizeof(LogRecord<Key, Value>);
            size_t write_offset = 0;
            uint64_t max_lsn = 0;

            while (write_offset < bytes_to_write) {
                size_t chunk = std::min(bytes_to_write - write_offset, BUFFER_SIZE);
                std::memcpy(buffer_, reinterpret_cast<char*>(local_batch.data()) + write_offset, chunk);

                // Write to persistence
                ssize_t written = ::write(fd_, buffer_, chunk);
                (void)written;
                write_offset += chunk;
            }

            ::fdatasync(fd_);

            for (const auto& rec : local_batch) {
                if (rec.lsn > max_lsn) max_lsn = rec.lsn;
            }

            flushed_lsn_.store(max_lsn, std::memory_order_release);
            local_batch.clear();
        }
    }

    int fd_{-1};
    char* buffer_{nullptr};
    std::atomic<bool> running_{false};
    alignas(std::hardware_destructive_interference_size) std::atomic<uint64_t> global_lsn_{1};
    alignas(std::hardware_destructive_interference_size) std::atomic<uint64_t> flushed_lsn_{0};

    std::mutex queue_mutex_;
    std::condition_variable cv_;
    std::vector<LogRecord<Key, Value>> write_queue_;
    std::thread flush_thread_;
};

// ============================================================================
// 3. LOCK-FREE B-LINK TREE CORE IMPLEMENTATION
// ============================================================================

template <typename Key, typename Value, size_t Fanout = 16>
class BLinkTree {
public:
    static_assert(Fanout >= 4, "Fanout must be at least 4");

    struct Node;

    struct alignas(std::hardware_destructive_interference_size) Node {
        std::atomic<bool> is_leaf{true};
        std::atomic<uint16_t> count{0};
        std::atomic<Node*> right_sibling{nullptr};
        std::atomic<bool> has_high_key{false};
        Key high_key{};

        std::array<Key, Fanout> keys{};
        std::array<Value, Fanout> values{};
        std::array<std::atomic<Node*>, Fanout + 1> children{};

        Node(bool leaf) : is_leaf(leaf) {
            for (size_t i = 0; i <= Fanout; ++i) {
                children[i].store(nullptr, std::memory_order_relaxed);
            }
        }
    };

    struct SplitResult {
        Key split_key;
        Node* right_node;
    };

private:
    alignas(std::hardware_destructive_interference_size) std::atomic<Node*> root_{nullptr};
    AsyncWAL<Key, Value>* wal_{nullptr};

public:
    explicit BLinkTree(AsyncWAL<Key, Value>* wal = nullptr) : wal_(wal) {
        auto* initial_root = new Node(true);
        root_.store(initial_root, std::memory_order_release);
    }

    ~BLinkTree() {
        destroy_recursive(root_.load(std::memory_order_relaxed));
    }

    // Read Path: Wait-Free, Zero Allocations, Pure Acquire-Loads
    std::optional<Value> find(const Key& key) {
        auto guard = EpochManager::instance().enter();

        Node* curr = root_.load(std::memory_order_acquire);
        while (curr != nullptr) {
            // Check Lehman-Yao Right-Link Navigation
            if (curr->has_high_key.load(std::memory_order_acquire) && key > curr->high_key) {
                curr = curr->right_sibling.load(std::memory_order_acquire);
                continue;
            }

            if (curr->is_leaf.load(std::memory_order_acquire)) {
                uint16_t cnt = curr->count.load(std::memory_order_acquire);
                // Vectorizable Binary Search over contiguous cache lines
                auto it = std::lower_bound(curr->keys.begin(), curr->keys.begin() + cnt, key);
                size_t idx = std::distance(curr->keys.begin(), it);

                if (idx < cnt && curr->keys[idx] == key) {
                    return curr->values[idx];
                }

                // Concurrent split might have pushed the key rightwards
                if (curr->has_high_key.load(std::memory_order_acquire) && key > curr->high_key) {
                    curr = curr->right_sibling.load(std::memory_order_acquire);
                    continue;
                }
                return std::nullopt;
            } else {
                // Internal Node Navigation
                uint16_t cnt = curr->count.load(std::memory_order_acquire);
                auto it = std::upper_bound(curr->keys.begin(), curr->keys.begin() + cnt, key);
                size_t idx = std::distance(curr->keys.begin(), it);

                Node* next = curr->children[idx].load(std::memory_order_acquire);
                if (curr->has_high_key.load(std::memory_order_acquire) && key > curr->high_key) {
                    curr = curr->right_sibling.load(std::memory_order_acquire);
                } else {
                    curr = next;
                }
            }
        }
        return std::nullopt;
    }

    // Range Scan: Traverses sibling pointers horizontally across leaf nodes
    std::vector<std::pair<Key, Value>> scan(const Key& start_key, size_t limit) {
        std::vector<std::pair<Key, Value>> results;
        results.reserve(limit);
        auto guard = EpochManager::instance().enter();

        Node* curr = root_.load(std::memory_order_acquire);
        // Descend to leftmost candidate leaf
        while (curr && !curr->is_leaf.load(std::memory_order_acquire)) {
            if (curr->has_high_key.load(std::memory_order_acquire) && start_key > curr->high_key) {
                curr = curr->right_sibling.load(std::memory_order_acquire);
                continue;
            }
            uint16_t cnt = curr->count.load(std::memory_order_acquire);
            auto it = std::upper_bound(curr->keys.begin(), curr->keys.begin() + cnt, start_key);
            size_t idx = std::distance(curr->keys.begin(), it);
            curr = curr->children[idx].load(std::memory_order_acquire);
        }

        while (curr != nullptr && results.size() < limit) {
            uint16_t cnt = curr->count.load(std::memory_order_acquire);
            for (size_t i = 0; i < cnt && results.size() < limit; ++i) {
                if (curr->keys[i] >= start_key) {
                    results.emplace_back(curr->keys[i], curr->values[i]);
                }
            }
            curr = curr->right_sibling.load(std::memory_order_acquire);
        }

        return results;
    }

    // Insert Path: Safe Non-blocking Split Propagation
    bool insert(const Key& key, const Value& value) {
        auto guard = EpochManager::instance().enter();

        if (wal_) {
            wal_->append_record(LogRecordType::INSERT, key, value, 0);
        }

        while (true) {
            Node* root = root_.load(std::memory_order_acquire);
            auto split_res = insert_internal(root, key, value);

            if (split_res.has_value()) {
                // Root split: create new root level
                auto* new_root = new Node(false);
                new_root->keys[0] = split_res->split_key;
                new_root->children[0].store(root, std::memory_order_relaxed);
                new_root->children[1].store(split_res->right_node, std::memory_order_relaxed);
                new_root->count.store(1, std::memory_order_relaxed);

                if (root_.compare_exchange_strong(
                        root, new_root,
                        std::memory_order_acq_rel,
                        std::memory_order_acquire)) {
                    return true;
                } else {
                    // Contention on root expansion: retire unlinked new root and retry
                    EpochManager::instance().retire(new_root);
                }
            } else {
                return true;
            }
        }
    }

private:
    std::optional<SplitResult> insert_internal(Node* curr, const Key& key, const Value& value) {
        // Step 1: Right-link traversal check
        while (curr->has_high_key.load(std::memory_order_acquire) && key > curr->high_key) {
            curr = curr->right_sibling.load(std::memory_order_acquire);
        }

        if (curr->is_leaf.load(std::memory_order_acquire)) {
            return insert_into_leaf(curr, key, value);
        }

        // Step 2: Internal Node Traversal
        uint16_t cnt = curr->count.load(std::memory_order_acquire);
        auto it = std::upper_bound(curr->keys.begin(), curr->keys.begin() + cnt, key);
        size_t idx = std::distance(curr->keys.begin(), it);

        Node* child = curr->children[idx].load(std::memory_order_acquire);
        auto split_res = insert_internal(child, key, value);

        if (!split_res.has_value()) {
            return std::nullopt;
        }

        // Child split: Insert split_res into this internal node
        return insert_into_internal(curr, split_res->split_key, split_res->right_node);
    }

    std::optional<SplitResult> insert_into_leaf(Node* leaf, const Key& key, const Value& value) {
        while (true) {
            if (leaf->has_high_key.load(std::memory_order_acquire) && key > leaf->high_key) {
                leaf = leaf->right_sibling.load(std::memory_order_acquire);
                continue;
            }

            uint16_t cnt = leaf->count.load(std::memory_order_acquire);

            // In-place Update if Key Exists
            auto it = std::lower_bound(leaf->keys.begin(), leaf->keys.begin() + cnt, key);
            size_t idx = std::distance(leaf->keys.begin(), it);
            if (idx < cnt && leaf->keys[idx] == key) {
                leaf->values[idx] = value;
                return std::nullopt;
            }

            // If node has capacity: Copy-On-Write node insertion state
            if (cnt < Fanout) {
                // Create temporary sorted arrays
                std::array<Key, Fanout> temp_keys = leaf->keys;
                std::array<Value, Fanout> temp_values = leaf->values;

                std::move_backward(temp_keys.begin() + idx, temp_keys.begin() + cnt, temp_keys.begin() + cnt + 1);
                std::move_backward(temp_values.begin() + idx, temp_values.begin() + cnt, temp_values.begin() + cnt + 1);

                temp_keys[idx] = key;
                temp_values[idx] = value;

                // Copy back and advance count
                leaf->keys = temp_keys;
                leaf->values = temp_values;
                leaf->count.store(cnt + 1, std::memory_order_release);
                return std::nullopt;
            }

            // Node Overflow: Execute Atomic Node Split
            auto* right_leaf = new Node(true);
            size_t mid = (Fanout + 1) / 2;

            // Merge into oversize buffer
            std::array<Key, Fanout + 1> all_keys;
            std::array<Value, Fanout + 1> all_values;

            std::copy(leaf->keys.begin(), leaf->keys.begin() + idx, all_keys.begin());
            std::copy(leaf->values.begin(), leaf->values.begin() + idx, all_values.begin());

            all_keys[idx] = key;
            all_values[idx] = value;

            std::copy(leaf->keys.begin() + idx, leaf->keys.begin() + cnt, all_keys.begin() + idx + 1);
            std::copy(leaf->values.begin() + idx, leaf->values.begin() + cnt, all_values.begin() + idx + 1);

            // Populate Right Sibling Node
            size_t r_count = (Fanout + 1) - mid;
            for (size_t i = 0; i < r_count; ++i) {
                right_leaf->keys[i] = all_keys[mid + i];
                right_leaf->values[i] = all_values[mid + i];
            }
            right_leaf->count.store(r_count, std::memory_order_relaxed);
            right_leaf->right_sibling.store(leaf->right_sibling.load(std::memory_order_relaxed), std::memory_order_relaxed);
            right_leaf->has_high_key.store(leaf->has_high_key.load(std::memory_order_relaxed), std::memory_order_relaxed);
            right_leaf->high_key = leaf->high_key;

            // Populate Left Sibling Node
            for (size_t i = 0; i < mid; ++i) {
                leaf->keys[i] = all_keys[i];
                leaf->values[i] = all_values[i];
            }
            leaf->high_key = all_keys[mid - 1];
            leaf->has_high_key.store(true, std::memory_order_release);
            leaf->count.store(mid, std::memory_order_release);

            // Link Sibling Pointers (Publishes right_leaf to concurrent readers)
            leaf->right_sibling.store(right_leaf, std::memory_order_release);

            if (wal_) {
                wal_->append_record(LogRecordType::SPLIT, all_keys[mid], Value{}, 0);
            }

            return SplitResult{all_keys[mid], right_leaf};
        }
    }

    std::optional<SplitResult> insert_into_internal(Node* node, const Key& split_key, Node* right_child) {
        uint16_t cnt = node->count.load(std::memory_order_acquire);
        auto it = std::upper_bound(node->keys.begin(), node->keys.begin() + cnt, split_key);
        size_t idx = std::distance(node->keys.begin(), it);

        if (cnt < Fanout) {
            for (size_t i = cnt; i > idx; --i) {
                node->keys[i] = node->keys[i - 1];
                node->children[i + 1].store(node->children[i].load(std::memory_order_relaxed), std::memory_order_relaxed);
            }
            node->keys[idx] = split_key;
            node->children[idx + 1].store(right_child, std::memory_order_release);
            node->count.store(cnt + 1, std::memory_order_release);
            return std::nullopt;
        }

        // Internal Node Overflow Split
        auto* right_internal = new Node(false);
        size_t mid = (Fanout + 1) / 2;

        std::array<Key, Fanout + 1> all_keys;
        std::array<Node*, Fanout + 2> all_children;

        std::copy(node->keys.begin(), node->keys.begin() + idx, all_keys.begin());
        for (size_t i = 0; i <= idx; ++i) {
            all_children[i] = node->children[i].load(std::memory_order_relaxed);
        }

        all_keys[idx] = split_key;
        all_children[idx + 1] = right_child;

        std::copy(node->keys.begin() + idx, node->keys.begin() + cnt, all_keys.begin() + idx + 1);
        for (size_t i = idx + 1; i <= cnt; ++i) {
            all_children[i + 1] = node->children[i].load(std::memory_order_relaxed);
        }

        Key promoted_key = all_keys[mid];

        // Populate Right Internal Node
        size_t r_count = (Fanout + 1) - (mid + 1);
        for (size_t i = 0; i < r_count; ++i) {
            right_internal->keys[i] = all_keys[mid + 1 + i];
            right_internal->children[i].store(all_children[mid + 1 + i], std::memory_order_relaxed);
        }
        right_internal->children[r_count].store(all_children[Fanout + 1], std::memory_order_relaxed);
        right_internal->count.store(r_count, std::memory_order_relaxed);
        right_internal->right_sibling.store(node->right_sibling.load(std::memory_order_relaxed), std::memory_order_relaxed);
        right_internal->has_high_key.store(node->has_high_key.load(std::memory_order_relaxed), std::memory_order_relaxed);
        right_internal->high_key = node->high_key;

        // Populate Left Internal Node
        for (size_t i = 0; i < mid; ++i) {
            node->keys[i] = all_keys[i];
            node->children[i].store(all_children[i], std::memory_order_relaxed);
        }
        node->children[mid].store(all_children[mid], std::memory_order_relaxed);
        node->high_key = promoted_key;
        node->has_high_key.store(true, std::memory_order_release);
        node->count.store(mid, std::memory_order_release);

        node->right_sibling.store(right_internal, std::memory_order_release);

        return SplitResult{promoted_key, right_internal};
    }

    void destroy_recursive(Node* node) {
        if (!node) return;
        if (!node->is_leaf.load(std::memory_order_relaxed)) {
            uint16_t cnt = node->count.load(std::memory_order_relaxed);
            for (size_t i = 0; i <= cnt; ++i) {
                destroy_recursive(node->children[i].load(std::memory_order_relaxed));
            }
        }
        delete node;
    }
};

// ============================================================================
// 4. BENCHMARKS & VALIDATION HARNESS
// ============================================================================

struct LatencyCollector {
    std::vector<double> latencies_us;

    void record(double us) {
        latencies_us.push_back(us);
    }

    void print_percentiles(const std::string& label) {
        if (latencies_us.empty()) return;
        std::sort(latencies_us.begin(), latencies_us.end());
        size_t n = latencies_us.size();
        std::cout << "\n=== " << label << " Latency Metrics (" << n << " ops) ===\n"
                  << "  p50   : " << latencies_us[static_cast<size_t>(n * 0.50)] << " us\n"
                  << "  p90   : " << latencies_us[static_cast<size_t>(n * 0.90)] << " us\n"
                  << "  p99   : " << latencies_us[static_cast<size_t>(n * 0.99)] << " us\n"
                  << "  p99.9 : " << latencies_us[static_cast<size_t>(n * 0.999)] << " us\n"
                  << "  max   : " << latencies_us.back() << " us\n";
    }
};

int main() {
    std::cout << "===================================================================\n";
    std::cout << "  Starting Lock-Free B-Link Tree Benchmark & Validation Engine     \n";
    std::cout << "===================================================================\n";

    std::string wal_file = "/tmp/blink_tree_wal.log";
    auto wal = std::make_unique<AsyncWAL<uint64_t, uint64_t>>(wal_file);
    BLinkTree<uint64_t, uint64_t, 16> tree(wal.get());

    constexpr size_t NUM_WRITER_THREADS = 8;
    constexpr size_t NUM_READER_THREADS = 16;
    constexpr size_t OPS_PER_THREAD = 200'000;

    std::atomic<bool> start_flag{false};
    std::atomic<size_t> completed_writes{0};
    std::atomic<size_t> verification_failures{0};

    std::vector<LatencyCollector> writer_latencies(NUM_WRITER_THREADS);
    std::vector<LatencyCollector> reader_latencies(NUM_READER_THREADS);

    for (auto& lc : writer_latencies) lc.latencies_us.reserve(OPS_PER_THREAD);
    for (auto& lc : reader_latencies) lc.latencies_us.reserve(OPS_PER_THREAD);

    // Spawn Writer Threads
    std::vector<std::thread> writers;
    writers.reserve(NUM_WRITER_THREADS);
    for (size_t tid = 0; tid < NUM_WRITER_THREADS; ++tid) {
        writers.emplace_back([&, tid]() {
            EpochManager::instance().register_thread();
            while (!start_flag.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }

            uint64_t base_key = tid * OPS_PER_THREAD;
            for (size_t i = 0; i < OPS_PER_THREAD; ++i) {
                uint64_t k = base_key + i;
                uint64_t v = k * 3;

                auto t0 = std::chrono::high_resolution_clock::now();
                tree.insert(k, v);
                auto t1 = std::chrono::high_resolution_clock::now();

                double dur = std::chrono::duration<double, std::micro>(t1 - t0).count();
                writer_latencies[tid].record(dur);
            }
            completed_writes.fetch_add(OPS_PER_THREAD, std::memory_order_release);
            EpochManager::instance().unregister_thread();
        });
    }

    // Spawn Reader Threads (Concurrently verifying linearizability and state)
    std::vector<std::thread> readers;
    readers.reserve(NUM_READER_THREADS);
    for (size_t tid = 0; tid < NUM_READER_THREADS; ++tid) {
        readers.emplace_back([&, tid]() {
            EpochManager::instance().register_thread();
            while (!start_flag.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }

            size_t total_keys = NUM_WRITER_THREADS * OPS_PER_THREAD;
            for (size_t i = 0; i < OPS_PER_THREAD; ++i) {
                uint64_t target_key = (i * 1103515245 + 12345) % total_keys;

                auto t0 = std::chrono::high_resolution_clock::now();
                auto res = tree.find(target_key);
                auto t1 = std::chrono::high_resolution_clock::now();

                if (res.has_value() && *res != target_key * 3) {
                    verification_failures.fetch_add(1, std::memory_order_relaxed);
                }

                double dur = std::chrono::duration<double, std::micro>(t1 - t0).count();
                reader_latencies[tid].record(dur);
            }
            EpochManager::instance().unregister_thread();
        });
    }

    // Trigger Benchmark Execution
    auto start_time = std::chrono::high_resolution_clock::now();
    start_flag.store(true, std::memory_order_release);

    for (auto& w : writers) w.join();
    for (auto& r : readers) r.join();
    auto end_time = std::chrono::high_resolution_clock::now();

    double total_sec = std::chrono::duration<double>(end_time - start_time).count();
    size_t total_ops = (NUM_WRITER_THREADS + NUM_READER_THREADS) * OPS_PER_THREAD;
    double throughput = static_cast<double>(total_ops) / total_sec;

    std::cout << "\n================ Benchmark Execution Summary ================\n";
    std::cout << "Total Operations : " << total_ops << " ops\n";
    std::cout << "Elapsed Time     : " << total_sec << " seconds\n";
    std::cout << "Aggregate Ops/sec: " << throughput << " ops/sec (" 
              << (throughput / 1e6) << " M ops/sec)\n";
    std::cout << "Linearize Errors : " << verification_failures.load() << "\n";

    // Consolidate Percentiles
    LatencyCollector aggregated_readers;
    for (const auto& lc : reader_latencies) {
        aggregated_readers.latencies_us.insert(
            aggregated_readers.latencies_us.end(),
            lc.latencies_us.begin(),
            lc.latencies_us.end());
    }
    aggregated_readers.print_percentiles("Concurrent Reader");

    LatencyCollector aggregated_writers;
    for (const auto& lc : writer_latencies) {
        aggregated_writers.latencies_us.insert(
            aggregated_writers.latencies_us.end(),
            lc.latencies_us.begin(),
            lc.latencies_us.end());
    }
    aggregated_writers.print_percentiles("Concurrent Writer + WAL Split");

    // Perform Range Scan Validation
    std::cout << "\n--- Testing Range Scan Engine ---\n";
    auto scan_res = tree.scan(1000, 10);
    std::cout << "Range Scan [1000, 10 keys]:\n";
    for (const auto& [k, v] : scan_res) {
        std::cout << "  Key: " << k << " => Value: " << v << "\n";
    }

    assert(verification_failures.load() == 0);
    std::cout << "\n[PASS] All invariants, linearizability, and epoch reclamation verified successfully.\n";

    ::unlink(wal_file.c_str());
    return 0;
}
