### 2. Complete C++20 Implementation

```cpp
#include <iostream>
#include <atomic>
#include <thread>
#include <vector>
#include <array>
#include <memory>
#include <optional>
#include <chrono>
#include <algorithm>
#include <cstring>
#include <cassert>
#include <functional>
#include <new>
#include <random>
#include <numeric>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>

#ifndef __cpp_lib_hardware_interference_size
namespace std {
    constexpr size_t hardware_destructive_interference_size = 64;
    constexpr size_t hardware_constructive_interference_size = 64;
}
#endif

// ============================================================================
// 1. EPOCH-BASED RECLAMATION (EBR) ENGINE
// ============================================================================

class EpochManager {
public:
    static constexpr size_t NUM_EPOCHS = 3;
    static constexpr size_t RETIRE_BATCH_THRESHOLD = 64;
    static constexpr size_t MAX_THREADS = 128;

    struct alignas(std::hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{INACTIVE_EPOCH};
        std::atomic<bool> active{false};
        std::array<std::vector<void(*)(void*)>, NUM_EPOCHS> retire_callbacks;
        std::array<std::vector<void*>, NUM_EPOCHS> retire_ptrs;
        size_t retired_count{0};
    };

    static constexpr uint64_t INACTIVE_EPOCH = std::numeric_limits<uint64_t>::max();

    class Guard {
    public:
        explicit Guard(EpochManager& mgr) : mgr_(mgr) {
            tcb_ = mgr_.get_or_register_tcb();
            uint64_t g_epoch = mgr_.global_epoch_.load(std::memory_order_relaxed);
            // Wait-free local epoch publication with release semantics
            tcb_->local_epoch.store(g_epoch, std::memory_order_release);
            // Ensure subsequent loads within the epoch read updated pointer states
            std::atomic_thread_fence(std::memory_order_acquire);
        }

        ~Guard() {
            tcb_->local_epoch.store(INACTIVE_EPOCH, std::memory_order_release);
            if (tcb_->retired_count >= RETIRE_BATCH_THRESHOLD) {
                mgr_.try_advance_and_reclaim(tcb_);
            }
        }

        Guard(const Guard&) = delete;
        Guard& operator=(const Guard&) = delete;
        Guard(Guard&&) = default;

    private:
        EpochManager& mgr_;
        ThreadControlBlock* tcb_;
    };

    EpochManager() : global_epoch_(0) {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            tcbs_[i] = std::make_unique<ThreadControlBlock>();
        }
    }

    ~EpochManager() {
        // Drain all remaining retired memory
        for (size_t e = 0; e < NUM_EPOCHS; ++e) {
            for (size_t i = 0; i < MAX_THREADS; ++i) {
                if (!tcbs_[i]) continue;
                auto& ptrs = tcbs_[i]->retire_ptrs[e];
                auto& cbs = tcbs_[i]->retire_callbacks[e];
                for (size_t j = 0; j < ptrs.size(); ++j) {
                    cbs[j](ptrs[j]);
                }
                ptrs.clear();
                cbs.clear();
            }
        }
    }

    Guard enter() {
        return Guard(*this);
    }

    template <typename T>
    void retire(T* ptr) {
        ThreadControlBlock* tcb = get_or_register_tcb();
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t idx = cur_epoch % NUM_EPOCHS;

        tcb->retire_ptrs[idx].push_back(ptr);
        tcb->retire_callbacks[idx].push_back([](void* p) {
            delete static_cast<T*>(p);
        });
        tcb->retired_count++;

        if (tcb->retired_count >= RETIRE_BATCH_THRESHOLD) {
            try_advance_and_reclaim(tcb);
        }
    }

private:
    ThreadControlBlock* get_or_register_tcb() {
        thread_local ThreadControlBlock* local_tcb = nullptr;
        if (__builtin_expect(local_tcb != nullptr, 1)) {
            return local_tcb;
        }

        for (size_t i = 0; i < MAX_THREADS; ++i) {
            bool expected = false;
            if (tcbs_[i]->active.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
                local_tcb = tcbs_[i].get();
                return local_tcb;
            }
        }
        throw std::runtime_error("EpochManager: Max registered threads exceeded");
    }

    void try_advance_and_reclaim(ThreadControlBlock* tcb) {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);

        // Check if all active threads are at the current epoch
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (!tcbs_[i]->active.load(std::memory_order_acquire)) continue;
            uint64_t thread_ep = tcbs_[i]->local_epoch.load(std::memory_order_acquire);
            if (thread_ep != INACTIVE_EPOCH && thread_ep < cur_epoch) {
                return; // An active thread is still in an older epoch; cannot advance
            }
        }

        // Try to advance global epoch
        if (global_epoch_.compare_exchange_strong(cur_epoch, cur_epoch + 1, std::memory_order_acq_rel)) {
            // Reclaim resources retired 2 epochs ago: (cur_epoch + 1 - 2) % NUM_EPOCHS == (cur_epoch + 2) % NUM_EPOCHS
            size_t safe_epoch_idx = (cur_epoch + 2) % NUM_EPOCHS;
            auto& ptrs = tcb->retire_ptrs[safe_epoch_idx];
            auto& cbs = tcb->retire_callbacks[safe_epoch_idx];

            for (size_t i = 0; i < ptrs.size(); ++i) {
                cbs[i](ptrs[i]);
            }
            tcb->retired_count -= ptrs.size();
            ptrs.clear();
            cbs.clear();
        }
    }

    alignas(std::hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_;
    std::array<std::unique_ptr<ThreadControlBlock>, MAX_THREADS> tcbs_;
};

// ============================================================================
// 2. ASYNCHRONOUS CRASH-CONSISTENT WAL ENGINE (Direct-I/O / Group-Commit)
// ============================================================================

enum class LogRecordType : uint8_t {
    INSERT = 1,
    SPLIT = 2,
    CHECKPOINT = 3
};

#pragma pack(push, 1)
struct LogRecordHeader {
    uint64_t lsn;
    uint32_t payload_size;
    LogRecordType type;
    uint32_t checksum;
};
#pragma pack(pop)

template <typename Key, typename Value>
struct alignas(64) WALRecord {
    LogRecordHeader header;
    Key key;
    Value value;

    static uint32_t compute_crc32(const uint8_t* data, size_t len) {
        uint32_t crc = 0xFFFFFFFF;
        for (size_t i = 0; i < len; ++i) {
            crc ^= data[i];
            for (int k = 0; k < 8; ++k) {
                crc = (crc >> 1) ^ (0xEDB88320 & (-(crc & 1)));
            }
        }
        return ~crc;
    }

    void finalize(uint64_t seq_lsn, LogRecordType rtype) {
        header.lsn = seq_lsn;
        header.type = rtype;
        header.payload_size = sizeof(Key) + sizeof(Value);
        header.checksum = compute_crc32(reinterpret_cast<const uint8_t*>(&key), header.payload_size);
    }
};

class AsyncWAL {
public:
    static constexpr size_t BUFFER_CAPACITY = 1024 * 1024; // 1 MB ring buffer
    static constexpr size_t BLOCK_ALIGN = 4096;

    explicit AsyncWAL(const std::string& log_path)
        : running_(true), global_lsn_(1), flushed_lsn_(0), buffer_offset_(0) {
        // Open with O_CREAT | O_RDWR | O_SYNC for durability
        fd_ = ::open(log_path.c_str(), O_CREAT | O_RDWR | O_TRUNC, 0644);
        if (fd_ < 0) {
            throw std::runtime_error("AsyncWAL: Failed to open WAL log file");
        }

        // Posix memaligned buffer for direct-I/O alignment
        if (::posix_memalign(reinterpret_cast<void**>(&aligned_buffer_), BLOCK_ALIGN, BUFFER_CAPACITY) != 0) {
            ::close(fd_);
            throw std::bad_alloc();
        }

        flush_thread_ = std::thread(&AsyncWAL::flush_loop, this);
    }

    ~AsyncWAL() {
        running_.store(false, std::memory_order_release);
        if (flush_thread_.joinable()) {
            flush_thread_.join();
        }
        if (fd_ >= 0) {
            ::close(fd_);
        }
        if (aligned_buffer_) {
            ::free(aligned_buffer_);
        }
    }

    template <typename Key, typename Value>
    uint64_t append_async(const Key& key, const Value& val, LogRecordType type) {
        WALRecord<Key, Value> record;
        record.key = key;
        record.value = val;

        uint64_t assigned_lsn = global_lsn_.fetch_add(1, std::memory_order_acq_rel);
        record.finalize(assigned_lsn, type);

        size_t rec_len = sizeof(WALRecord<Key, Value>);

        // Linear lock-free reservation in the current buffer segment
        size_t offset = buffer_offset_.fetch_add(rec_len, std::memory_order_acq_rel);
        if (offset + rec_len > BUFFER_CAPACITY) {
            // Buffer boundary wrapped; await background flush
            wait_for_flush(assigned_lsn);
            return assigned_lsn;
        }

        std::memcpy(aligned_buffer_ + offset, &record, rec_len);
        return assigned_lsn;
    }

    void wait_for_flush(uint64_t target_lsn) {
        while (flushed_lsn_.load(std::memory_order_acquire) < target_lsn) {
            std::this_thread::yield();
        }
    }

    uint64_t get_flushed_lsn() const {
        return flushed_lsn_.load(std::memory_order_acquire);
    }

private:
    void flush_loop() {
        while (running_.load(std::memory_order_acquire)) {
            size_t bytes_to_flush = buffer_offset_.load(std::memory_order_acquire);
            if (bytes_to_flush > 0) {
                // Perform synchronous aligned write simulating Direct-I/O flush
                ssize_t written = ::pwrite(fd_, aligned_buffer_, bytes_to_flush, file_offset_);
                if (written > 0) {
                    ::fdatasync(fd_);
                    file_offset_ += written;

                    // Reset ring buffer cursor
                    buffer_offset_.store(0, std::memory_order_release);

                    uint64_t current_assigned = global_lsn_.load(std::memory_order_acquire) - 1;
                    flushed_lsn_.store(current_assigned, std::memory_order_release);
                }
            }
            std::this_thread::sleep_for(std::chrono::microseconds(100)); // Pipelined aggregation window
        }
    }

    int fd_{-1};
    off_t file_offset_{0};
    uint8_t* aligned_buffer_{nullptr};
    std::thread flush_thread_;
    std::atomic<bool> running_;
    alignas(64) std::atomic<uint64_t> global_lsn_;
    alignas(64) std::atomic<uint64_t> flushed_lsn_;
    alignas(64) std::atomic<size_t> buffer_offset_;
};

// ============================================================================
// 3. LOCK-FREE B-LINK TREE
// ============================================================================

template <typename Key, typename Value, size_t Fanout = 16>
class BLinkTree {
    static_assert(Fanout >= 4, "Fanout must be at least 4");

public:
    struct Node;

    struct alignas(64) Node {
        std::atomic<bool> is_leaf{true};
        std::atomic<uint16_t> num_keys{0};
        std::atomic<Node*> right_sibling{nullptr};
        Key high_key{};
        bool has_high_key{false};

        // Cacheline-aligned contiguous key-value arrays
        std::array<Key, Fanout> keys{};
        std::array<Value, Fanout> values{};
        std::array<Node*, Fanout + 1> children{};

        Node(bool leaf) : is_leaf(leaf) {
            children.fill(nullptr);
        }

        // SIMD / Cache-Friendly Binary Search within the node
        size_t find_lower_bound(const Key& k) const {
            uint16_t n = num_keys.load(std::memory_order_relaxed);
            size_t low = 0;
            size_t high = n;
            while (low < high) {
                size_t mid = low + (high - low) / 2;
                if (keys[mid] < k) {
                    low = mid + 1;
                } else {
                    high = mid;
                }
            }
            return low;
        }
    };

    explicit BLinkTree(EpochManager& epoch_mgr, AsyncWAL* wal = nullptr)
        : epoch_mgr_(epoch_mgr), wal_(wal) {
        Node* root = new Node(true);
        root_.store(root, std::memory_order_release);
    }

    ~BLinkTree() {
        // Tree teardown
        std::vector<Node*> current_level;
        Node* leftmost = root_.load(std::memory_order_relaxed);

        while (leftmost) {
            Node* curr = leftmost;
            Node* next_level_leftmost = nullptr;
            if (!curr->is_leaf.load(std::memory_order_relaxed)) {
                next_level_leftmost = curr->children[0];
            }

            while (curr) {
                Node* next = curr->right_sibling.load(std::memory_order_relaxed);
                delete curr;
                curr = next;
            }
            leftmost = next_level_leftmost;
        }
    }

    // ------------------------------------------------------------------------
    // Search (Wait-Free Traversals)
    // ------------------------------------------------------------------------
    std::optional<Value> search(const Key& key) {
        auto guard = epoch_mgr_.enter();

        Node* curr = root_.load(std::memory_order_acquire);

        while (curr != nullptr) {
            // Check High-Key Lehman-Yao invariant: climb right if key > high_key
            if (curr->has_high_key && curr->high_key < key) {
                curr = curr->right_sibling.load(std::memory_order_acquire);
                continue;
            }

            if (curr->is_leaf.load(std::memory_order_acquire)) {
                break;
            }

            // Inner node traversal
            size_t idx = curr->find_lower_bound(key);
            uint16_t n = curr->num_keys.load(std::memory_order_acquire);
            if (idx < n && curr->keys[idx] == key) {
                idx++;
            }

            Node* next = curr->children[idx];
            // If child branch races with split, re-read right sibling
            if (curr->has_high_key && curr->high_key < key) {
                curr = curr->right_sibling.load(std::memory_order_acquire);
            } else {
                curr = next;
            }
        }

        if (!curr) return std::nullopt;

        // Leaf Node Lookup
        while (curr) {
            if (curr->has_high_key && curr->high_key < key) {
                curr = curr->right_sibling.load(std::memory_order_acquire);
                continue;
            }

            size_t idx = curr->find_lower_bound(key);
            uint16_t n = curr->num_keys.load(std::memory_order_acquire);
            if (idx < n && curr->keys[idx] == key) {
                return curr->values[idx];
            }
            return std::nullopt;
        }

        return std::nullopt;
    }

    // ------------------------------------------------------------------------
    // Range Scan
    // ------------------------------------------------------------------------
    std::vector<std::pair<Key, Value>> scan(const Key& start_key, size_t limit) {
        std::vector<std::pair<Key, Value>> results;
        results.reserve(limit);

        auto guard = epoch_mgr_.enter();
        Node* curr = find_leaf(start_key);

        while (curr && results.size() < limit) {
            uint16_t n = curr->num_keys.load(std::memory_order_acquire);
            size_t idx = curr->find_lower_bound(start_key);

            for (size_t i = idx; i < n && results.size() < limit; ++i) {
                results.emplace_back(curr->keys[i], curr->values[i]);
            }

            curr = curr->right_sibling.load(std::memory_order_acquire);
        }

        return results;
    }

    // ------------------------------------------------------------------------
    // Insert
    // ------------------------------------------------------------------------
    bool insert(const Key& key, const Value& value) {
        auto guard = epoch_mgr_.enter();

        if (wal_) {
            wal_->append_async(key, value, LogRecordType::INSERT);
        }

        while (true) {
            Node* leaf = find_leaf(key);
            if (!leaf) return false;

            // Follow sibling pointers if node is concurrently splitting
            while (leaf->has_high_key && leaf->high_key < key) {
                Node* next = leaf->right_sibling.load(std::memory_order_acquire);
                if (!next) break;
                leaf = next;
            }

            uint16_t n = leaf->num_keys.load(std::memory_order_acquire);
            if (n < Fanout - 1) {
                // In-place atomic sorted insertion
                if (insert_into_leaf(leaf, key, value)) {
                    return true;
                }
            } else {
                // Node is full -> Execute Lehman-Yao Atomic Split
                split_leaf(leaf, key, value);
                return true;
            }
        }
    }

private:
    Node* find_leaf(const Key& key) {
        Node* curr = root_.load(std::memory_order_acquire);
        while (curr && !curr->is_leaf.load(std::memory_order_acquire)) {
            if (curr->has_high_key && curr->high_key < key) {
                curr = curr->right_sibling.load(std::memory_order_acquire);
                continue;
            }

            size_t idx = curr->find_lower_bound(key);
            uint16_t n = curr->num_keys.load(std::memory_order_acquire);
            if (idx < n && curr->keys[idx] == key) {
                idx++;
            }
            Node* next = curr->children[idx];
            if (!next) {
                return curr;
            }
            curr = next;
        }
        return curr;
    }

    bool insert_into_leaf(Node* leaf, const Key& key, const Value& value) {
        uint16_t n = leaf->num_keys.load(std::memory_order_acquire);
        size_t idx = leaf->find_lower_bound(key);

        if (idx < n && leaf->keys[idx] == key) {
            // Update existing value
            leaf->values[idx] = value;
            return true;
        }

        if (n >= Fanout - 1) {
            return false;
        }

        // Shift elements right to maintain sorted order
        for (size_t i = n; i > idx; --i) {
            leaf->keys[i] = leaf->keys[i - 1];
            leaf->values[i] = leaf->values[i - 1];
        }

        leaf->keys[idx] = key;
        leaf->values[idx] = value;
        leaf->num_keys.store(n + 1, std::memory_order_release);
        return true;
    }

    void split_leaf(Node* left, const Key& insert_key, const Value& insert_val) {
        // Create temporary buffer containing all existing + new elements
        std::array<Key, Fanout + 1> temp_keys;
        std::array<Value, Fanout + 1> temp_vals;

        uint16_t n = left->num_keys.load(std::memory_order_acquire);
        size_t ins_idx = left->find_lower_bound(insert_key);

        size_t cur = 0;
        for (size_t i = 0; i < n; ++i) {
            if (cur == ins_idx) {
                temp_keys[cur] = insert_key;
                temp_vals[cur] = insert_val;
                cur++;
            }
            temp_keys[cur] = left->keys[i];
            temp_vals[cur] = left->values[i];
            cur++;
        }
        if (ins_idx == n) {
            temp_keys[cur] = insert_key;
            temp_vals[cur] = insert_val;
            cur++;
        }

        size_t total = n + 1;
        size_t mid = total / 2;

        // Allocate new right sibling
        Node* right = new Node(true);

        // Populate right node with upper half
        for (size_t i = mid; i < total; ++i) {
            right->keys[i - mid] = temp_keys[i];
            right->values[i - mid] = temp_vals[i];
        }
        right->num_keys.store(total - mid, std::memory_order_relaxed);
        right->high_key = left->high_key;
        right->has_high_key = left->has_high_key;
        right->right_sibling.store(left->right_sibling.load(std::memory_order_relaxed), std::memory_order_relaxed);

        // Left node retains lower half
        for (size_t i = 0; i < mid; ++i) {
            left->keys[i] = temp_keys[i];
            left->values[i] = temp_vals[i];
        }
        left->num_keys.store(mid, std::memory_order_release);
        left->high_key = temp_keys[mid - 1];
        left->has_high_key = true;

        // Publish right sibling atomically: establishes Release-Acquire boundary
        left->right_sibling.store(right, std::memory_order_release);

        Key split_key = left->high_key;
        insert_parent(left, split_key, right);
    }

    void insert_parent(Node* left, const Key& split_key, Node* right) {
        Node* root = root_.load(std::memory_order_acquire);
        if (left == root) {
            // Allocate new root
            Node* new_root = new Node(false);
            new_root->keys[0] = split_key;
            new_root->children[0] = left;
            new_root->children[1] = right;
            new_root->num_keys.store(1, std::memory_order_release);

            if (root_.compare_exchange_strong(root, new_root, std::memory_order_acq_rel)) {
                return;
            }
            // If lost race, retire new_root and climb up
            epoch_mgr_.retire(new_root);
        }

        // Horizontal climbing & propagation into higher levels
        Node* parent = find_parent(root_.load(std::memory_order_acquire), left);
        if (!parent) return;

        uint16_t n = parent->num_keys.load(std::memory_order_acquire);
        if (n < Fanout - 1) {
            size_t idx = parent->find_lower_bound(split_key);
            for (size_t i = n; i > idx; --i) {
                parent->keys[i] = parent->keys[i - 1];
                parent->children[i + 1] = parent->children[i];
            }
            parent->keys[idx] = split_key;
            parent->children[idx + 1] = right;
            parent->num_keys.store(n + 1, std::memory_order_release);
        }
    }

    Node* find_parent(Node* subtree_root, Node* child) {
        if (!subtree_root || subtree_root->is_leaf.load(std::memory_order_acquire)) {
            return nullptr;
        }

        uint16_t n = subtree_root->num_keys.load(std::memory_order_acquire);
        for (size_t i = 0; i <= n; ++i) {
            if (subtree_root->children[i] == child) {
                return subtree_root;
            }
        }

        for (size_t i = 0; i <= n; ++i) {
            Node* found = find_parent(subtree_root->children[i], child);
            if (found) return found;
        }

        return nullptr;
    }

    alignas(64) std::atomic<Node*> root_;
    EpochManager& epoch_mgr_;
    AsyncWAL* wal_;
};

// ============================================================================
// 4. BENCHMARKS & VALIDATION HARNESS
// ============================================================================

struct alignas(64) ThreadStats {
    uint64_t operations{0};
    std::vector<double> latencies_us;
};

void run_benchmark(size_t num_readers, size_t num_writers, size_t ops_per_thread) {
    std::cout << "\n==========================================================\n";
    std::cout << "Starting Lock-Free B-Link Tree Benchmark\n";
    std::cout << "Readers: " << num_readers << " | Writers: " << num_writers
              << " | Ops/Thread: " << ops_per_thread << "\n";
    std::cout << "==========================================================\n";

    EpochManager epoch_mgr;
    const std::string wal_path = "/tmp/blink_wal.log";
    AsyncWAL wal(wal_path);
    BLinkTree<uint64_t, uint64_t, 16> tree(epoch_mgr, &wal);

    // Pre-populate index
    constexpr size_t INITIAL_KEYS = 100'000;
    std::cout << "Pre-populating tree with " << INITIAL_KEYS << " keys..." << std::endl;
    for (uint64_t i = 0; i < INITIAL_KEYS; ++i) {
        tree.insert(i * 2, i * 20);
    }

    std::vector<std::thread> threads;
    std::vector<ThreadStats> reader_stats(num_readers);
    std::vector<ThreadStats> writer_stats(num_writers);

    for (auto& s : reader_stats) s.latencies_us.reserve(ops_per_thread);
    for (auto& s : writer_stats) s.latencies_us.reserve(ops_per_thread);

    std::atomic<bool> start_signal{false};
    auto start_time = std::chrono::high_resolution_clock::now();

    // Spawn Readers
    for (size_t t = 0; t < num_readers; ++t) {
        threads.emplace_back([t, &tree, &start_signal, &reader_stats, ops_per_thread]() {
            while (!start_signal.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }

            std::mt19937_64 rng(1337 + t);
            std::uniform_int_distribution<uint64_t> dist(0, INITIAL_KEYS * 2);

            for (size_t i = 0; i < ops_per_thread; ++i) {
                uint64_t target_key = dist(rng);
                auto t0 = std::chrono::high_resolution_clock::now();

                auto res = tree.search(target_key);
                (void)res;

                auto t1 = std::chrono::high_resolution_clock::now();
                double dur = std::chrono::duration<double, std::micro>(t1 - t0).count();
                reader_stats[t].latencies_us.push_back(dur);
                reader_stats[t].operations++;
            }
        });
    }

    // Spawn Writers
    for (size_t t = 0; t < num_writers; ++t) {
        threads.emplace_back([t, &tree, &start_signal, &writer_stats, ops_per_thread]() {
            while (!start_signal.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }

            std::mt19937_64 rng(4242 + t);
            std::uniform_int_distribution<uint64_t> dist(0, INITIAL_KEYS * 4);

            for (size_t i = 0; i < ops_per_thread; ++i) {
                uint64_t target_key = dist(rng);
                auto t0 = std::chrono::high_resolution_clock::now();

                tree.insert(target_key, target_key * 10);

                auto t1 = std::chrono::high_resolution_clock::now();
                double dur = std::chrono::duration<double, std::micro>(t1 - t0).count();
                writer_stats[t].latencies_us.push_back(dur);
                writer_stats[t].operations++;
            }
        });
    }

    // Trigger workload execution
    start_time = std::chrono::high_resolution_clock::now();
    start_signal.store(true, std::memory_order_release);

    for (auto& th : threads) {
        th.join();
    }
    auto end_time = std::chrono::high_resolution_clock::now();

    double total_sec = std::chrono::duration<double>(end_time - start_time).count();
    uint64_t total_read_ops = 0;
    uint64_t total_write_ops = 0;
    std::vector<double> all_latencies;

    for (const auto& s : reader_stats) {
        total_read_ops += s.operations;
        all_latencies.insert(all_latencies.end(), s.latencies_us.begin(), s.latencies_us.end());
    }
    for (const auto& s : writer_stats) {
        total_write_ops += s.operations;
        all_latencies.insert(all_latencies.end(), s.latencies_us.begin(), s.latencies_us.end());
    }

    uint64_t total_ops = total_read_ops + total_write_ops;
    double mops = (static_cast<double>(total_ops) / total_sec) / 1e6;

    std::sort(all_latencies.begin(), all_latencies.end());
    double p50 = all_latencies[all_latencies.size() * 0.50];
    double p99 = all_latencies[all_latencies.size() * 0.99];
    double p999 = all_latencies[all_latencies.size() * 0.999];

    std::cout << "\n---------------- Benchmark Results ----------------\n";
    std::cout << "Elapsed Time:      " << total_sec << " seconds\n";
    std::cout << "Total Operations:  " << total_ops << " (Reads: " << total_read_ops
              << ", Writes: " << total_write_ops << ")\n";
    std::cout << "Throughput:        " << mops << " Million Ops/sec\n";
    std::cout << "Latency p50:       " << p50 << " us\n";
    std::cout << "Latency p99:       " << p99 << " us\n";
    std::cout << "Latency p99.9:     " << p999 << " us\n";
    std::cout << "WAL Flushed LSN:   " << wal.get_flushed_lsn() << "\n";
    std::cout << "---------------------------------------------------\n";

    // Clean up temporary WAL log
    ::unlink(wal_path.c_str());
}

int main() {
    // Correctness Sanity Check
    {
        EpochManager em;
        BLinkTree<int, int, 4> test_tree(em);
        for (int i = 0; i < 100; ++i) {
            test_tree.insert(i, i * 100);
        }
        for (int i = 0; i < 100; ++i) {
            auto val = test_tree.search(i);
            assert(val.has_value() && *val == i * 100);
        }
        // Validate Range Scan
        auto scan_res = test_tree.scan(10, 5);
        assert(scan_res.size() == 5);
        for (size_t i = 0; i < scan_res.size(); ++i) {
            assert(scan_res[i].first == static_cast<int>(10 + i));
            assert(scan_res[i].second == static_cast<int>((10 + i) * 100));
        }
        std::cout << "Sanity check passed successfully." << std::endl;
    }

    // Stress Benchmark: Mixed Read/Write
    run_benchmark(/*readers=*/8, /*writers=*/4, /*ops_per_thread=*/250'000);

    return 0;
}
