#include <array>
#include <span>

#if defined(__x86_64__) || defined(_M_X64)
#include <emmintrin.h>
#define CPU_PAUSE() _mm_pause()
#else
#define CPU_PAUSE() do {} while (0)
#endif

// Hardware destructive interference size
#ifdef __cpp_lib_hardware_interference_size
using std::hardware_destructive_interference_size;
#else
constexpr size_t hardware_destructive_interference_size = 64;
#endif

// ============================================================================
// 1. EPOCH-BASED RECLAMATION (EBR) SUBSYSTEM
// ============================================================================

class EpochManager {
public:
    static constexpr uint64_t EPOCH_INACTIVE = std::numeric_limits<uint64_t>::max();
    static constexpr size_t RETIRE_BATCH_SIZE = 64;

    struct RetiredNode {
        void* data{nullptr};
        void (*deleter)(void*){nullptr};
        uint64_t epoch{0};
        RetiredNode* next{nullptr};
    };

    struct alignas(hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{EPOCH_INACTIVE};
        std::atomic<bool> is_active{false};
        std::atomic<ThreadControlBlock*> next{nullptr};

        RetiredNode* retired_head{nullptr};
        size_t retired_count{0};
    };

private:
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_{0};
    alignas(hardware_destructive_interference_size) std::atomic<ThreadControlBlock*> global_tcb_head_{nullptr};
    alignas(hardware_destructive_interference_size) std::atomic<RetiredNode*> orphan_list_{nullptr};

public:
    EpochManager() = default;
    ~EpochManager() {
        // Collect all orphaned nodes and finalize cleanup
        collect_orphans();
        flush_all_retired();
    }

    static EpochManager& instance() {
        static EpochManager mgr;
        return mgr;
    }

    ThreadControlBlock* register_thread() {
        auto* tcb = new ThreadControlBlock();
        ThreadControlBlock* old_head = global_tcb_head_.load(std::memory_order_relaxed);
        do {
            tcb->next.store(old_head, std::memory_order_relaxed);
        } while (!global_tcb_head_.compare_exchange_weak(
            old_head, tcb, std::memory_order_release, std::memory_order_relaxed));
        return tcb;
    }

    void unregister_thread(ThreadControlBlock* tcb) {
        if (!tcb) return;
        tcb->is_active.store(false, std::memory_order_release);
        tcb->local_epoch.store(EPOCH_INACTIVE, std::memory_order_release);

        // Move thread's remaining retired nodes into global orphan list
        if (tcb->retired_head) {
            RetiredNode* last = tcb->retired_head;
            while (last->next) {
                last = last->next;
            }
            RetiredNode* cur_orphan = orphan_list_.load(std::memory_order_relaxed);
            do {
                last->next = cur_orphan;
            } while (!orphan_list_.compare_exchange_weak(
                cur_orphan, tcb->retired_head, std::memory_order_release, std::memory_order_relaxed));
            tcb->retired_head = nullptr;
            tcb->retired_count = 0;
        }
    }

    void enter_critical(ThreadControlBlock* tcb) noexcept {
        tcb->is_active.store(true, std::memory_order_relaxed);
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        tcb->local_epoch.store(cur_epoch, std::memory_order_release);
    }

    void leave_critical(ThreadControlBlock* tcb) noexcept {
        tcb->local_epoch.store(EPOCH_INACTIVE, std::memory_order_release);
        tcb->is_active.store(false, std::memory_order_relaxed);

        if (tcb->retired_count >= RETIRE_BATCH_SIZE) {
            try_advance_and_reclaim(tcb);
        }
    }

    template <typename T>
    void retire(ThreadControlBlock* tcb, T* ptr) {
        if (!ptr) return;
        auto* node = new RetiredNode{
            .data = ptr,
            .deleter = [](void* p) { delete static_cast<T*>(p); },
            .epoch = global_epoch_.load(std::memory_order_relaxed),
            .next = tcb->retired_head
        };
        tcb->retired_head = node;
        tcb->retired_count++;

        if (tcb->retired_count >= RETIRE_BATCH_SIZE) {
            try_advance_and_reclaim(tcb);
        }
    }

    void try_advance_and_reclaim(ThreadControlBlock* tcb) {
        collect_orphans_to(tcb);

        uint64_t cur_epoch = global_epoch_.load(std::memory_order_acquire);
        bool can_advance = true;

        ThreadControlBlock* curr = global_tcb_head_.load(std::memory_order_acquire);
        while (curr != nullptr) {
            if (curr->is_active.load(std::memory_order_acquire)) {
                uint64_t th_epoch = curr->local_epoch.load(std::memory_order_acquire);
                if (th_epoch != EPOCH_INACTIVE && th_epoch < cur_epoch) {
                    can_advance = false;
                    break;
                }
            }
            curr = curr->next.load(std::memory_order_acquire);
        }

        if (can_advance) {
            global_epoch_.fetch_add(1, std::memory_order_acq_rel);
            cur_epoch++;
        }

        // Reclaim memory older than (cur_epoch - 2)
        RetiredNode** prev_link = &tcb->retired_head;
        RetiredNode* node = tcb->retired_head;

        while (node != nullptr) {
            if (cur_epoch >= node->epoch + 2) {
                RetiredNode* to_delete = node;
                *prev_link = node->next;
                node = node->next;

                to_delete->deleter(to_delete->data);
                delete to_delete;
                tcb->retired_count--;
            } else {
                prev_link = &node->next;
                node = node->next;
            }
        }
    }

private:
    void collect_orphans_to(ThreadControlBlock* tcb) {
        if (orphan_list_.load(std::memory_order_relaxed) == nullptr) return;
        RetiredNode* orphans = orphan_list_.exchange(nullptr, std::memory_order_acquire);
        while (orphans) {
            RetiredNode* next = orphans->next;
            orphans->next = tcb->retired_head;
            tcb->retired_head = orphans;
            tcb->retired_count++;
            orphans = next;
        }
    }

    void collect_orphans() {
        RetiredNode* orphans = orphan_list_.exchange(nullptr, std::memory_order_acquire);
        while (orphans) {
            RetiredNode* next = orphans->next;
            orphans->deleter(orphans->data);
            delete orphans;
            orphans = next;
        }
    }

    void flush_all_retired() {
        ThreadControlBlock* curr = global_tcb_head_.load(std::memory_order_acquire);
        while (curr != nullptr) {
            RetiredNode* node = curr->retired_head;
            while (node != nullptr) {
                RetiredNode* next = node->next;
                node->deleter(node->data);
                delete node;
                node = next;
            }
            curr->retired_head = nullptr;
            curr->retired_count = 0;
            ThreadControlBlock* next_tcb = curr->next.load(std::memory_order_acquire);
            delete curr;
            curr = next_tcb;
        }
        global_tcb_head_.store(nullptr, std::memory_order_relaxed);
    }
};

// RAII Epoch Guard
class EpochGuard {
    EpochManager::ThreadControlBlock* tcb_;
public:
    explicit EpochGuard(EpochManager::ThreadControlBlock* tcb) noexcept : tcb_(tcb) {
        EpochManager::instance().enter_critical(tcb_);
    }
    ~EpochGuard() noexcept {
        EpochManager::instance().leave_critical(tcb_);
    }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
};

// ============================================================================
// 2. LOCK-FREE BOUNDED RING BUFFER LANE
// ============================================================================

template <typename T, size_t Capacity>
class alignas(hardware_destructive_interference_size) LockFreeLane {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of 2");
    static constexpr size_t BUFFER_MASK = Capacity - 1;

    struct alignas(hardware_destructive_interference_size) Cell {
        std::atomic<uint64_t> sequence;
        T storage;
    };

    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> enqueue_pos_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> dequeue_pos_{0};
    alignas(hardware_destructive_interference_size) std::atomic<size_t> approx_size_{0};

    std::unique_ptr<Cell[]> buffer_;

public:
    LockFreeLane() : buffer_(std::make_unique<Cell[]>(Capacity)) {
        for (size_t i = 0; i < Capacity; ++i) {
            buffer_[i].sequence.store(i, std::memory_order_relaxed);
        }
    }

    bool try_push(T&& value) noexcept {
        Cell* cell;
        uint64_t pos = enqueue_pos_.load(std::memory_order_relaxed);
        for (;;) {
            cell = &buffer_[pos & BUFFER_MASK];
            uint64_t seq = cell->sequence.load(std::memory_order_acquire);
            int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(pos);

            if (diff == 0) {
                if (enqueue_pos_.compare_exchange_weak(
                        pos, pos + 1, std::memory_order_relaxed, std::memory_order_relaxed)) {
                    break;
                }
            } else if (diff < 0) {
                return false; // Lane full
            } else {
                pos = enqueue_pos_.load(std::memory_order_relaxed);
            }
        }

        cell->storage = std::move(value);
        cell->sequence.store(pos + 1, std::memory_order_release);
        approx_size_.fetch_add(1, std::memory_order_relaxed);
        return true;
    }

    std::optional<T> try_pop() noexcept {
        Cell* cell;
        uint64_t pos = dequeue_pos_.load(std::memory_order_relaxed);
        for (;;) {
            cell = &buffer_[pos & BUFFER_MASK];
            uint64_t seq = cell->sequence.load(std::memory_order_acquire);
            int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(pos + 1);

            if (diff == 0) {
                if (dequeue_pos_.compare_exchange_weak(
                        pos, pos + 1, std::memory_order_relaxed, std::memory_order_relaxed)) {
                    break;
                }
            } else if (diff < 0) {
                return std::nullopt; // Lane empty
            } else {
                pos = dequeue_pos_.load(std::memory_order_relaxed);
            }
        }

        T res = std::move(cell->storage);
        cell->sequence.store(pos + BUFFER_MASK + 1, std::memory_order_release);
        approx_size_.fetch_sub(1, std::memory_order_relaxed);
        return res;
    }

    [[nodiscard]] size_t approx_size() const noexcept {
        return approx_size_.load(std::memory_order_relaxed);
    }
};

// ============================================================================
// 3. NUMA-AWARE MULTI-LANE RELAXED PRIORITY QUEUE
// ============================================================================

template <typename T, size_t NumPriorities = 256, size_t LanesPerPriority = 8, size_t LaneCapacity = 1024>
class MultiLanePriorityQueue {
    static_assert(NumPriorities > 0 && (NumPriorities % 64 == 0), "NumPriorities must be multiple of 64");
    static constexpr size_t BITMAP_WORDS = NumPriorities / 64;

    struct PriorityBand {
        alignas(hardware_destructive_interference_size) 
        std::array<LockFreeLane<T, LaneCapacity>, LanesPerPriority> lanes;
    };

    std::array<PriorityBand, NumPriorities> priority_bands_;

    // Hierarchical active priority bitset
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> active_summary_{0};
    alignas(hardware_destructive_interference_size) std::array<std::atomic<uint64_t>, BITMAP_WORDS> active_bitmaps_{};

public:
    using Priority = uint16_t;

    struct ThreadHandle {
        EpochManager::ThreadControlBlock* tcb{nullptr};
        uint32_t thread_id{0};
        uint32_t numa_hint{0};
        std::mt19937 rng;

        explicit ThreadHandle(uint32_t tid = 0, uint32_t numa = 0)
            : tcb(EpochManager::instance().register_thread()),
              thread_id(tid),
              numa_hint(numa),
              rng(tid ^ 0x9E3779B97F4A7C15ULL) {}

        ~ThreadHandle() {
            if (tcb) {
                EpochManager::instance().unregister_thread(tcb);
            }
        }

        ThreadHandle(const ThreadHandle&) = delete;
        ThreadHandle& operator=(const ThreadHandle&) = delete;
        ThreadHandle(ThreadHandle&& o) noexcept : tcb(o.tcb), thread_id(o.thread_id), numa_hint(o.numa_hint), rng(std::move(o.rng)) {
            o.tcb = nullptr;
        }
    };

    MultiLanePriorityQueue() {
        for (size_t i = 0; i < BITMAP_WORDS; ++i) {
            active_bitmaps_[i].store(0, std::memory_order_relaxed);
        }
    }

    [[nodiscard]] ThreadHandle create_handle(uint32_t tid = 0, uint32_t numa = 0) {
        return ThreadHandle(tid, numa);
    }

    bool try_push(Priority prio, T value, ThreadHandle& handle) {
        if (prio >= NumPriorities) return false;

        EpochGuard guard(handle.tcb);

        size_t start_lane = (handle.numa_hint + handle.thread_id) % LanesPerPriority;
        bool pushed = false;

        // Try primary lane, then probe neighboring lanes in the same band
        for (size_t attempt = 0; attempt < LanesPerPriority; ++attempt) {
            size_t lane_idx = (start_lane + attempt) % LanesPerPriority;
            if (priority_bands_[prio].lanes[lane_idx].try_push(std::move(value))) {
                pushed = true;
                break;
            }
        }

        if (pushed) {
            mark_active_priority(prio);
            return true;
        }

        return false;
    }

    std::optional<T> try_pop(ThreadHandle& handle, size_t epsilon = 2) {
        EpochGuard guard(handle.tcb);

        size_t prio_cursor = 0;
        while (find_next_active_priority(prio_cursor)) {
            size_t search_end = std::min(prio_cursor + epsilon + 1, NumPriorities);

            for (size_t p = prio_cursor; p < search_end; ++p) {
                // Power-of-two lane selection for staleness bounded load-balancing
                size_t l1 = handle.rng() % LanesPerPriority;
                size_t l2 = handle.rng() % LanesPerPriority;

                size_t sz1 = priority_bands_[p].lanes[l1].approx_size();
                size_t sz2 = priority_bands_[p].lanes[l2].approx_size();
                size_t chosen = (sz1 >= sz2) ? l1 : l2;

                auto item = priority_bands_[p].lanes[chosen].try_pop();
                if (item.has_value()) {
                    return item;
                }

                // Work-steal across all remaining lanes in this priority band
                for (size_t i = 0; i < LanesPerPriority; ++i) {
                    if (i == chosen) continue;
                    item = priority_bands_[p].lanes[i].try_pop();
                    if (item.has_value()) {
                        return item;
                    }
                }

                // Band appears exhausted; clear active bit
                clear_active_priority(p);
            }

            prio_cursor = search_end;
        }

        return std::nullopt;
    }

private:
    void mark_active_priority(Priority prio) noexcept {
        size_t word_idx = prio / 64;
        uint64_t bit_mask = 1ULL << (prio % 64);

        uint64_t old = active_bitmaps_[word_idx].fetch_or(bit_mask, std::memory_order_release);
        if ((old & bit_mask) == 0) {
            active_summary_.fetch_or(1ULL << word_idx, std::memory_order_release);
        }
    }

    void clear_active_priority(Priority prio) noexcept {
        size_t word_idx = prio / 64;
        uint64_t bit_mask = 1ULL << (prio % 64);

        uint64_t prev = active_bitmaps_[word_idx].fetch_and(~bit_mask, std::memory_order_release);
        if ((prev & ~bit_mask) == 0) {
            active_summary_.fetch_and(~(1ULL << word_idx), std::memory_order_release);
        }
    }

    bool find_next_active_priority(size_t& out_prio) noexcept {
        uint64_t summary = active_summary_.load(std::memory_order_acquire);
        if (summary == 0) return false;

        size_t start_word = out_prio / 64;
        summary >>= start_word;
        if (summary == 0) return false;

        size_t word_offset = __builtin_ctzll(summary);
        size_t word_idx = start_word + word_offset;

        uint64_t bitmap = active_bitmaps_[word_idx].load(std::memory_order_acquire);
        if (word_idx == start_word) {
            size_t bit_offset = out_prio % 64;
            bitmap &= (~0ULL << bit_offset);
        }

        while (bitmap == 0) {
            word_idx++;
            if (word_idx >= BITMAP_WORDS) return false;
            bitmap = active_bitmaps_[word_idx].load(std::memory_order_acquire);
        }

        size_t bit_idx = __builtin_ctzll(bitmap);
        out_prio = word_idx * 64 + bit_idx;
        return true;
    }
};

// ============================================================================
// 4. SYNTHETIC BENCHMARK & TAIL LATENCY FIXTURE
// ============================================================================

struct LatencyTracker {
    static constexpr size_t MAX_LATENCY_NS = 10'000'000; // 10ms
    static constexpr size_t NUM_BUCKETS = 100'000;       // 100ns buckets
    std::vector<uint32_t> buckets;

    LatencyTracker() : buckets(NUM_BUCKETS, 0) {}

    void record(uint64_t duration_ns) {
        size_t bucket = duration_ns / 100;
        if (bucket >= NUM_BUCKETS) bucket = NUM_BUCKETS - 1;
        buckets[bucket]++;
    }

    [[nodiscard]] double percentile(double pct) const {
        uint64_t total = 0;
        for (auto count : buckets) total += count;
        if (total == 0) return 0.0;

        uint64_t target = static_cast<uint64_t>(pct * static_cast<double>(total));
        uint64_t accum = 0;
        for (size_t i = 0; i < NUM_BUCKETS; ++i) {
            accum += buckets[i];
            if (accum >= target) {
                return static_cast<double>(i * 100) / 1000.0; // Return in microseconds
            }
        }
        return static_cast<double>((NUM_BUCKETS - 1) * 100) / 1000.0;
    }
};

void run_high_contention_benchmark(size_t num_threads = 64, size_t ops_per_thread = 200'000) {
    std::cout << "=================================================================\n";
    std::cout << " NUMA-Aware Lock-Free Multi-Lane Priority Queue Benchmark\n";
    std::cout << " Configuration: " << num_threads << " Threads | " 
              << ops_per_thread << " Ops/Thread (80% Push / 20% Pop)\n";
    std::cout << "=================================================================\n";

    MultiLanePriorityQueue<uint64_t, 256, 8, 2048> queue;
    std::vector<std::thread> workers;
    workers.reserve(num_threads);

    std::atomic<bool> start_signal{false};
    std::atomic<uint64_t> total_pushed{0};
    std::atomic<uint64_t> total_popped{0};

    std::vector<LatencyTracker> push_latencies(num_threads);
    std::vector<LatencyTracker> pop_latencies(num_threads);

    for (size_t t = 0; t < num_threads; ++t) {
        workers.emplace_back([&, t]() {
            auto handle = queue.create_handle(static_cast<uint32_t>(t), static_cast<uint32_t>(t % 4));

            while (!start_signal.load(std::memory_order_acquire)) {
                CPU_PAUSE();
            }

            uint64_t local_push = 0;
            uint64_t local_pop = 0;
            std::mt19937_64 rng(1337 + t);
            std::uniform_int_distribution<uint16_t> prio_dist(0, 255);
            std::uniform_int_distribution<uint32_t> op_dist(0, 99);

            for (size_t i = 0; i < ops_per_thread; ++i) {
                if (op_dist(rng) < 80) {
                    // 80% Push
                    uint16_t prio = prio_dist(rng);
                    uint64_t val = (static_cast<uint64_t>(prio) << 32) | i;

                    auto t0 = std::chrono::steady_clock::now();
                    bool ok = queue.try_push(prio, val, handle);
                    auto t1 = std::chrono::steady_clock::now();

                    if (ok) {
                        local_push++;
                        push_latencies[t].record(
                            std::chrono::duration_cast<std::chrono::nanoseconds>(t1 - t0).count());
                    }
                } else {
                    // 20% Pop
                    auto t0 = std::chrono::steady_clock::now();
                    auto item = queue.try_pop(handle);
                    auto t1 = std::chrono::steady_clock::now();

                    if (item.has_value()) {
                        local_pop++;
                        pop_latencies[t].record(
                            std::chrono::duration_cast<std::chrono::nanoseconds>(t1 - t0).count());
                    }
                }
            }

            total_pushed.fetch_add(local_push, std::memory_order_relaxed);
            total_popped.fetch_add(local_pop, std::memory_order_relaxed);
        });
    }

    auto start_time = std::chrono::high_resolution_clock::now();
    start_signal.store(true, std::memory_order_release);

    for (auto& w : workers) {
        w.join();
    }
    auto end_time = std::chrono::high_resolution_clock::now();

    double elapsed_sec = std::chrono::duration<double>(end_time - start_time).count();
    uint64_t total_ops = total_pushed.load() + total_popped.load();
    double throughput_mops = (static_cast<double>(total_ops) / elapsed_sec) / 1e6;

    // Aggregate tail latencies
    LatencyTracker agg_push, agg_pop;
    for (size_t t = 0; t < num_threads; ++t) {
        for (size_t b = 0; b < LatencyTracker::NUM_BUCKETS; ++b) {
            agg_push.buckets[b] += push_latencies[t].buckets[b];
            agg_pop.buckets[b] += pop_latencies[t].buckets[b];
        }
    }

    std::cout << "\n--- Performance Summary ---\n";
    std::cout << "Elapsed Time        : " << elapsed_sec << " s\n";
    std::cout << "Total Operations    : " << total_ops << " (Push: " << total_pushed.load() 
              << ", Pop: " << total_popped.load() << ")\n";
    std::cout << "Throughput          : " << throughput_mops << " MOps/sec\n\n";

    std::cout << "--- Latency Profile (Microseconds) ---\n";
    std::cout << "Push p50   : " << agg_push.percentile(0.50) << " us\n";
    std::cout << "Push p99   : " << agg_push.percentile(0.99) << " us\n";
    std::cout << "Push p99.99: " << agg_push.percentile(0.9999) << " us\n";
    std::cout << "Pop  p50   : " << agg_pop.percentile(0.50) << " us\n";
    std::cout << "Pop  p99   : " << agg_pop.percentile(0.99) << " us\n";
    std::cout << "Pop  p99.99: " << agg_pop.percentile(0.9999) << " us\n";
    std::cout << "=================================================================\n";
}

int main() {
    // Launch benchmark with 64 concurrent threads
    unsigned int hardware_threads = std::thread::hardware_concurrency();
    size_t test_threads = std::max(64u, hardware_threads);
    run_high_contention_benchmark(test_threads, 100'000);
    return 0;
}
