// Hardware interference cacheline constant
#if defined(__cpp_lib_hardware_interference_size)
    using std::hardware_destructive_interference_size;
#else
    constexpr size_t hardware_destructive_interference_size = 64;
#endif

namespace lockfree {

// ============================================================================
// 1. EPOCH-BASED RECLAMATION (EBR) SUBSYSTEM
// ============================================================================

class EpochManager {
public:
    static constexpr uint64_t INACTIVE_EPOCH = UINT64_MAX;
    static constexpr size_t RETIRED_BATCH_THRESHOLD = 64;
    static constexpr size_t MAX_THREADS = 256;

    struct RetiredNode {
        void* data{nullptr};
        void (*deleter)(void*){nullptr};
        RetiredNode* next{nullptr};
    };

    struct alignas(hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{INACTIVE_EPOCH};
        std::atomic<bool> in_use{false};
        std::atomic<ThreadControlBlock*> next{nullptr};

        // Thread-local retired list buckets indexed by (epoch % 3)
        std::array<RetiredNode*, 3> retired_buckets{nullptr, nullptr, nullptr};
        size_t retired_count{0};
    };

private:
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_{0};
    alignas(hardware_destructive_interference_size) std::atomic<ThreadControlBlock*> tcbs_head_{nullptr};
    std::array<ThreadControlBlock, MAX_THREADS> tcb_pool_;

    EpochManager() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            tcb_pool_[i].in_use.store(false, std::memory_order_relaxed);
            tcb_pool_[i].local_epoch.store(INACTIVE_EPOCH, std::memory_order_relaxed);
        }
    }

public:
    static EpochManager& instance() {
        static EpochManager mgr;
        return mgr;
    }

    ThreadControlBlock* register_thread() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            bool expected = false;
            if (tcb_pool_[i].in_use.compare_exchange_strong(expected, true, 
                    std::memory_order_acq_rel, std::memory_order_relaxed)) {

                // Prepend to active TCB list
                ThreadControlBlock* old_head = tcbs_head_.load(std::memory_order_relaxed);
                do {
                    tcb_pool_[i].next.store(old_head, std::memory_order_relaxed);
                } while (!tcbs_head_.compare_exchange_weak(old_head, &tcb_pool_[i], 
                            std::memory_order_release, std::memory_order_relaxed));

                return &tcb_pool_[i];
            }
        }
        throw std::runtime_error("EpochManager: Max registered threads exceeded.");
    }

    void unregister_thread(ThreadControlBlock* tcb) {
        if (!tcb) return;
        // Reclaim all remaining nodes if safe or flush
        for (size_t i = 0; i < 3; ++i) {
            RetiredNode* curr = tcb->retired_buckets[i];
            while (curr) {
                RetiredNode* next = curr->next;
                if (curr->deleter && curr->data) {
                    curr->deleter(curr->data);
                }
                delete curr;
                curr = next;
            }
            tcb->retired_buckets[i] = nullptr;
        }
        tcb->local_epoch.store(INACTIVE_EPOCH, std::memory_order_release);
        tcb->in_use.store(false, std::memory_order_release);
    }

    void enter_quiescent(ThreadControlBlock* tcb) {
        tcb->local_epoch.store(INACTIVE_EPOCH, std::memory_order_release);
    }

    void enter_critical(ThreadControlBlock* tcb) {
        uint64_t ge = global_epoch_.load(std::memory_order_relaxed);
        tcb->local_epoch.store(ge, std::memory_order_release);
    }

    template <typename T>
    void retire(ThreadControlBlock* tcb, T* ptr) {
        if (!ptr) return;
        auto* node = new RetiredNode{
            .data = static_cast<void*>(ptr),
            .deleter = [](void* p) { delete static_cast<T*>(p); },
            .next = nullptr
        };

        uint64_t ge = global_epoch_.load(std::memory_order_relaxed);
        size_t bucket_idx = ge % 3;
        node->next = tcb->retired_buckets[bucket_idx];
        tcb->retired_buckets[bucket_idx] = node;
        tcb->retired_count++;

        if (tcb->retired_count >= RETIRED_BATCH_THRESHOLD) {
            try_advance_and_reclaim(tcb);
        }
    }

    void try_advance_and_reclaim(ThreadControlBlock* tcb) {
        uint64_t ge = global_epoch_.load(std::memory_order_acquire);

        // Check if all active threads are at the current global epoch
        ThreadControlBlock* curr = tcbs_head_.load(std::memory_order_acquire);
        bool can_advance = true;
        while (curr != nullptr) {
            if (curr->in_use.load(std::memory_order_acquire)) {
                uint64_t le = curr->local_epoch.load(std::memory_order_acquire);
                if (le != INACTIVE_EPOCH && le < ge) {
                    can_advance = false;
                    break;
                }
            }
            curr = curr->next.load(std::memory_order_acquire);
        }

        if (can_advance) {
            global_epoch_.compare_exchange_strong(ge, ge + 1, std::memory_order_acq_rel);
            ge = ge + 1;
        }

        // Safe to reclaim bucket (ge + 1) % 3 since no thread is at (ge - 2)
        size_t safe_bucket = (ge + 1) % 3;
        RetiredNode* to_free = tcb->retired_buckets[safe_bucket];
        tcb->retired_buckets[safe_bucket] = nullptr;

        while (to_free) {
            RetiredNode* next = to_free->next;
            if (to_free->deleter && to_free->data) {
                to_free->deleter(to_free->data);
            }
            delete to_free;
            tcb->retired_count--;
            to_free = next;
        }
    }
};

class EpochGuard {
    EpochManager::ThreadControlBlock* tcb_;
public:
    explicit EpochGuard(EpochManager::ThreadControlBlock* tcb) : tcb_(tcb) {
        if (tcb_) EpochManager::instance().enter_critical(tcb_);
    }
    ~EpochGuard() {
        if (tcb_) EpochManager::instance().enter_quiescent(tcb_);
    }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
};

// ============================================================================
// 2. LOCK-FREE BOUNDED RING BUFFER LANE WITH MONOTONIC SEQUENCE TICKETS
// ============================================================================

template <typename T, size_t Capacity>
class alignas(hardware_destructive_interference_size) LockFreeLane {
    static_assert((Capacity & (Capacity - 1)) == 0, "Lane Capacity must be a power of 2");

    struct Cell {
        std::atomic<uint64_t> sequence;
        T storage;
    };

    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> enqueue_pos_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> dequeue_pos_{0};

    std::unique_ptr<Cell[]> buffer_;
    static constexpr size_t BufferMask = Capacity - 1;

public:
    LockFreeLane() : buffer_(std::make_unique<Cell[]>(Capacity)) {
        for (size_t i = 0; i < Capacity; ++i) {
            buffer_[i].sequence.store(i, std::memory_order_relaxed);
        }
    }

    bool try_push(const T& val) {
        Cell* cell;
        uint64_t pos = enqueue_pos_.load(std::memory_order_relaxed);

        for (;;) {
            cell = &buffer_[pos & BufferMask];
            uint64_t seq = cell->sequence.load(std::memory_order_acquire);
            int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(pos);

            if (diff == 0) {
                // Slot is ready for write
                if (enqueue_pos_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed)) {
                    break;
                }
            } else if (diff < 0) {
                // Buffer full
                return false;
            } else {
                pos = enqueue_pos_.load(std::memory_order_relaxed);
            }
        }

        cell->storage = val;
        cell->sequence.store(pos + 1, std::memory_order_release);
        return true;
    }

    std::optional<T> try_pop() {
        Cell* cell;
        uint64_t pos = dequeue_pos_.load(std::memory_order_relaxed);

        for (;;) {
            cell = &buffer_[pos & BufferMask];
            uint64_t seq = cell->sequence.load(std::memory_order_acquire);
            int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(pos + 1);

            if (diff == 0) {
                // Slot has unread data
                if (dequeue_pos_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed)) {
                    break;
                }
            } else if (diff < 0) {
                // Buffer empty
                return std::nullopt;
            } else {
                pos = dequeue_pos_.load(std::memory_order_relaxed);
            }
        }

        T result = std::move(cell->storage);
        cell->sequence.store(pos + BufferMask + 1, std::memory_order_release);
        return result;
    }

    bool is_approx_empty() const noexcept {
        uint64_t d = dequeue_pos_.load(std::memory_order_relaxed);
        uint64_t e = enqueue_pos_.load(std::memory_order_relaxed);
        return d >= e;
    }
};

// ============================================================================
// 3. NUMA-AWARE MULTI-LANE PRIORITY QUEUE
// ============================================================================

template <typename T, size_t PriorityLevels = 256, size_t LanesPerPriority = 8, size_t LaneCapacity = 1024>
class MultiLanePriorityQueue {
    static_assert(PriorityLevels % 64 == 0, "Priority levels must be a multiple of 64 for bitmap.");

    struct alignas(hardware_destructive_interference_size) PriorityBand {
        std::array<LockFreeLane<T, LaneCapacity>, LanesPerPriority> lanes;
        std::atomic<int64_t> active_count{0};
    };

    // Hierarchical active priority tracking: 256 priorities / 64 bits = 4 bitmap words
    static constexpr size_t BitmapWords = PriorityLevels / 64;
    alignas(hardware_destructive_interference_size) std::array<std::atomic<uint64_t>, BitmapWords> active_bitmap_;

    std::array<PriorityBand, PriorityLevels> bands_;

    void mark_priority_active(size_t prio) noexcept {
        size_t word_idx = prio / 64;
        uint64_t bit_mask = 1ULL << (prio % 64);
        active_bitmap_[word_idx].fetch_or(bit_mask, std::memory_order_release);
    }

    void mark_priority_inactive(size_t prio) noexcept {
        size_t word_idx = prio / 64;
        uint64_t bit_mask = ~(1ULL << (prio % 64));
        active_bitmap_[word_idx].fetch_and(bit_mask, std::memory_order_release);
    }

public:
    MultiLanePriorityQueue() {
        for (size_t i = 0; i < BitmapWords; ++i) {
            active_bitmap_[i].store(0, std::memory_order_relaxed);
        }
    }

    struct ThreadHandle {
        EpochManager::ThreadControlBlock* tcb{nullptr};
        uint32_t numa_node{0};
        uint32_t thread_id{0};
        std::minstd_rand rng;

        ThreadHandle(uint32_t numa = 0, uint32_t tid = 0) 
            : numa_node(numa), thread_id(tid), rng(tid ^ 0x9e3779b9) {
            tcb = EpochManager::instance().register_thread();
        }

        ~ThreadHandle() {
            if (tcb) {
                EpochManager::instance().unregister_thread(tcb);
            }
        }
    };

    bool try_push(ThreadHandle& handle, size_t priority, const T& val) {
        if (priority >= PriorityLevels) return false;

        EpochGuard guard(handle.tcb);

        // NUMA & Thread affinity hashing for lane target
        size_t lane_target = (handle.numa_node * 31 + handle.thread_id * 17 + priority) % LanesPerPriority;

        // Try primary lane, fall back across remaining lanes on contention
        for (size_t attempt = 0; attempt < LanesPerPriority; ++attempt) {
            size_t lane_idx = (lane_target + attempt) % LanesPerPriority;
            if (bands_[priority].lanes[lane_idx].try_push(val)) {
                if (bands_[priority].active_count.fetch_add(1, std::memory_order_release) == 0) {
                    mark_priority_active(priority);
                }
                return true;
            }
        }
        return false; // All lanes in this priority band are at capacity
    }

    std::optional<T> try_pop(ThreadHandle& handle) {
        EpochGuard guard(handle.tcb);

        // O(1) Search for highest priority non-empty band using countr_zero (CTZ)
        for (size_t w = 0; w < BitmapWords; ++w) {
            uint64_t mask = active_bitmap_[w].load(std::memory_order_acquire);
            while (mask != 0) {
                int bit_idx = std::countr_zero(mask);
                size_t priority = w * 64 + bit_idx;

                // Power-of-Two Random Choice for Bounded Staleness
                size_t l1 = (handle.numa_node * 7 + (handle.rng() % LanesPerPriority)) % LanesPerPriority;
                size_t l2 = (handle.rng() % LanesPerPriority);

                // Try chosen lane 1
                auto item = bands_[priority].lanes[l1].try_pop();
                if (!item) {
                    // Try chosen lane 2
                    item = bands_[priority].lanes[l2].try_pop();
                }

                // If power-of-two samples missed due to concurrent extraction, try sequential scan
                if (!item) {
                    for (size_t l = 0; l < LanesPerPriority; ++l) {
                        item = bands_[priority].lanes[l].try_pop();
                        if (item) break;
                    }
                }

                if (item) {
                    int64_t prev = bands_[priority].active_count.fetch_sub(1, std::memory_order_acq_rel);
                    if (prev <= 1) {
                        mark_priority_inactive(priority);
                    }
                    return item;
                } else {
                    // Band was empty; clear bit and advance
                    mark_priority_inactive(priority);
                    mask &= ~(1ULL << bit_idx);
                }
            }
        }
        return std::nullopt;
    }
};

