struct LatencyStats {
    std::vector<double> latencies_ns;

    void record(double ns) {
        latencies_ns.push_back(ns);
    }

    void report() {
        if (latencies_ns.empty()) return;
        std::sort(latencies_ns.begin(), latencies_ns.end());
        size_t n = latencies_ns.size();

        std::cout << std::fixed << std::setprecision(2);
        std::cout << "      Min:     " << latencies_ns[0] << " ns\n";
        std::cout << "      p50:     " << latencies_ns[n * 50 / 100] << " ns\n";
        std::cout << "      p90:     " << latencies_ns[n * 90 / 100] << " ns\n";
        std::cout << "      p99:     " << latencies_ns[n * 99 / 100] << " ns\n";
        std::cout << "      p99.9:   " << latencies_ns[n * 999 / 1000] << " ns\n";
        std::cout << "      p99.99:  " << latencies_ns[n * 9999 / 10000] << " ns\n";
        std::cout << "      Max:     " << latencies_ns.back() << " ns\n";
    }
};

int main() {
    std::cout << "========================================================================\n";
    std::cout << " NUMA-Aware Lock-Free Multi-Lane Priority Queue Benchmark\n";
    std::cout << " C++20 | Power-of-Two Choices | Epoch-Based Reclamation\n";
    std::cout << "========================================================================\n\n";

    constexpr size_t THREAD_COUNT = 64;
    constexpr size_t OPS_PER_THREAD = 100'000;
    constexpr size_t PRIORITY_LEVELS = 256;
    constexpr size_t LANES_PER_PRIO = 8;
    constexpr size_t LANE_CAPACITY = 2048;

    using QueueType = lockfree::MultiLanePriorityQueue<uint64_t, PRIORITY_LEVELS, LANES_PER_PRIO, LANE_CAPACITY>;
    auto pq = std::make_unique<QueueType>();

    std::atomic<bool> start_flag{false};
    std::vector<std::thread> workers;
    workers.reserve(THREAD_COUNT);

    std::vector<LatencyStats> stats(THREAD_COUNT);
    std::atomic<uint64_t> total_pushes{0};
    std::atomic<uint64_t> total_pops{0};

    auto worker_func = [&](size_t tid) {
        uint32_t numa_node = static_cast<uint32_t>(tid % 4); // Simulate 4 NUMA domains
        typename QueueType::ThreadHandle handle(numa_node, static_cast<uint32_t>(tid));
        std::minstd_rand rng(static_cast<uint32_t>(tid * 1337 + 7));
        std::uniform_int_distribution<size_t> prio_dist(0, PRIORITY_LEVELS - 1);
        std::uniform_int_distribution<int> op_dist(1, 100);

        stats[tid].latencies_ns.reserve(OPS_PER_THREAD);

        // Spin-wait for global trigger
        while (!start_flag.load(std::memory_order_acquire)) {
            std::this_thread::yield();
        }

        uint64_t local_push = 0;
        uint64_t local_pop = 0;

        for (size_t op = 0; op < OPS_PER_THREAD; ++op) {
            int op_type = op_dist(rng);
            size_t prio = prio_dist(rng);

            auto t0 = std::chrono::high_resolution_clock::now();
            if (op_type <= 80) {
                // 80% Push Workload
                bool ok = pq->try_push(handle, prio, static_cast<uint64_t>(tid * 1'000'000 + op));
                if (ok) local_push++;
            } else {
                // 20% Pop Workload
                auto val = pq->try_pop(handle);
                if (val.has_value()) local_pop++;
            }
            auto t1 = std::chrono::high_resolution_clock::now();

            double elapsed_ns = std::chrono::duration<double, std::nano>(t1 - t0).count();
            stats[tid].record(elapsed_ns);
        }

        total_pushes.fetch_add(local_push, std::memory_order_relaxed);
        total_pops.fetch_add(local_pop, std::memory_order_relaxed);
    };

    for (size_t i = 0; i < THREAD_COUNT; ++i) {
        workers.emplace_back(worker_func, i);
    }

    auto start_time = std::chrono::high_resolution_clock::now();
    start_flag.store(true, std::memory_order_release);

    for (auto& w : workers) {
        w.join();
    }
    auto end_time = std::chrono::high_resolution_clock::now();

    double total_sec = std::chrono::duration<double>(end_time - start_time).count();
    uint64_t total_ops = total_pushes.load() + total_pops.load();
    double throughput_mops = (static_cast<double>(total_ops) / total_sec) / 1e6;

    // Aggregate latency statistics
    LatencyStats global_stats;
    for (const auto& s : stats) {
        global_stats.latencies_ns.insert(
            global_stats.latencies_ns.end(),
            s.latencies_ns.begin(),
            s.latencies_ns.end()
        );
    }

    std::cout << "--- Benchmark Results (" << THREAD_COUNT << " Threads, 80% Push / 20% Pop) ---\n";
    std::cout << "Total Operations:       " << total_ops << " ops (" 
              << total_pushes.load() << " pushes, " << total_pops.load() << " pops)\n";
    std::cout << "Execution Elapsed:      " << total_sec << " s\n";
    std::cout << "Throughput:             " << throughput_mops << " Mops/sec\n\n";

    std::cout << "Latency Distribution Profile:\n";
    global_stats.report();

    std::cout << "\n========================================================================\n";
    return 0;
}
