#include <random>
#include <cstdint>
#include <new>
#include <cassert>
#include <algorithm>

#if defined(__x86_64__) || defined(_M_X64)
#include <immintrin.h>
#define HARDWARE_PAUSE() _mm_pause()
#else
#define HARDWARE_PAUSE() do {} while(0)
#endif

// ============================================================================
// Hardware Interference & Memory Layout Configurations
// ============================================================================
#ifdef __cpp_lib_hardware_interference_size
using std::hardware_destructive_interference_size;
#else
constexpr size_t hardware_destructive_interference_size = 64;
#endif

// ============================================================================
// Lock-Free Epoch-Based Reclamation (EBR) Subsystem
// ============================================================================
namespace MemoryManagement {

constexpr uint64_t EPOCH_INACTIVE = UINT64_MAX;
constexpr size_t RETIRED_BATCH_THRESHOLD = 64;

struct RetiredNode {
    void* ptr;
    void (*deleter)(void*);
    uint64_t epoch;
    RetiredNode* next;
};

struct alignas(hardware_destructive_interference_size) ThreadControlBlock {
    std::atomic<uint64_t> active_epoch{EPOCH_INACTIVE};
    std::atomic<ThreadControlBlock*> next{nullptr};
    std::atomic<bool> in_use{false};

    // Per-thread retired node chain (Thread-Local)
    RetiredNode* retired_head{nullptr};
    size_t retired_count{0};
};

class EpochManager {
public:
    static EpochManager& instance() {
        static EpochManager inst;
        return inst;
    }

    ThreadControlBlock* register_thread() {
        // Recycle unused existing TCBs or allocate new one
        for (ThreadControlBlock* curr = tcb_head_.load(std::memory_order_acquire); 
             curr != nullptr; 
             curr = curr->next.load(std::memory_order_acquire)) {
            bool expected = false;
            if (curr->in_use.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
                return curr;
            }
        }

        auto* new_tcb = new ThreadControlBlock();
        new_tcb->in_use.store(true, std::memory_order_relaxed);

        ThreadControlBlock* old_head = tcb_head_.load(std::memory_order_acquire);
        do {
            new_tcb->next.store(old_head, std::memory_order_relaxed);
        } while (!tcb_head_.compare_exchange_weak(old_head, new_tcb, 
                                                   std::memory_order_release, 
                                                   std::memory_order_acquire));
        return new_tcb;
    }

    void unregister_thread(ThreadControlBlock* tcb) {
        if (!tcb) return;

        // Evacuate remaining retired elements immediately before exiting
        tcb->active_epoch.store(EPOCH_INACTIVE, std::memory_order_release);
        flush_retired(tcb, true);
        tcb->in_use.store(false, std::memory_order_release);
    }

    void enter_critical(ThreadControlBlock* tcb) noexcept {
        uint64_t g_epoch = global_epoch_.load(std::memory_order_relaxed);
        tcb->active_epoch.store(g_epoch, std::memory_order_release);
    }

    void leave_critical(ThreadControlBlock* tcb) noexcept {
        tcb->active_epoch.store(EPOCH_INACTIVE, std::memory_order_release);
        if (tcb->retired_count >= RETIRED_BATCH_THRESHOLD) {
            try_advance_and_reclaim(tcb);
        }
    }

    template <typename T>
    void retire(ThreadControlBlock* tcb, T* ptr) {
        if (!ptr) return;
        auto* node = new RetiredNode{
            .ptr = static_cast<void*>(ptr),
            .deleter = [](void* p) { delete static_cast<T*>(p); },
            .epoch = global_epoch_.load(std::memory_order_relaxed),
            .next = tcb->retired_head
        };
        tcb->retired_head = node;
        tcb->retired_count++;

        if (tcb->retired_count >= RETIRED_BATCH_THRESHOLD) {
            try_advance_and_reclaim(tcb);
        }
    }

    void try_advance_and_reclaim(ThreadControlBlock* tcb) {
        uint64_t curr_g_epoch = global_epoch_.load(std::memory_order_relaxed);

        // Verify if all active threads have reached the current global epoch
        bool can_advance = true;
        for (ThreadControlBlock* curr = tcb_head_.load(std::memory_order_acquire); 
             curr != nullptr; 
             curr = curr->next.load(std::memory_order_acquire)) {
            if (!curr->in_use.load(std::memory_order_relaxed)) continue;

            uint64_t th_epoch = curr->active_epoch.load(std::memory_order_acquire);
            if (th_epoch != EPOCH_INACTIVE && th_epoch < curr_g_epoch) {
                can_advance = false;
                break;
            }
        }

        if (can_advance) {
            global_epoch_.fetch_add(1, std::memory_order_acq_rel);
        }

        flush_retired(tcb, false);
    }

private:
    EpochManager() = default;
    ~EpochManager() {
        for (ThreadControlBlock* curr = tcb_head_.load(std::memory_order_acquire); curr != nullptr;) {
            ThreadControlBlock* next = curr->next.load(std::memory_order_acquire);
            flush_retired(curr, true);
            delete curr;
            curr = next;
        }
    }

    void flush_retired(ThreadControlBlock* tcb, bool force_all) {
        uint64_t safe_epoch = global_epoch_.load(std::memory_order_acquire);
        RetiredNode** curr = &tcb->retired_head;
        while (*curr != nullptr) {
            RetiredNode* node = *curr;
            // Epoch diff >= 2 guarantees that no active thread can hold references
            if (force_all || (safe_epoch > node->epoch + 1)) {
                *curr = node->next;
                node->deleter(node->ptr);
                delete node;
                tcb->retired_count--;
            } else {
                curr = &((*curr)->next);
            }
        }
    }

    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_{0};
    alignas(hardware_destructive_interference_size) std::atomic<ThreadControlBlock*> tcb_head_{nullptr};
};

struct EpochGuard {
    ThreadControlBlock* tcb;
    explicit EpochGuard(ThreadControlBlock* block) noexcept : tcb(block) {
        EpochManager::instance().enter_critical(tcb);
    }
    ~EpochGuard() noexcept {
        EpochManager::instance().leave_critical(tcb);
    }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
};

} // namespace MemoryManagement

// ============================================================================
// Lock-Free Multi-Lane Priority Queue Implementation
// ============================================================================

template <typename T, size_t PriorityLevels = 256, size_t LanesPerBand = 8, size_t LaneCapacity = 1024>
class NUMAPriorityQueue {
    static_assert((LaneCapacity & (LaneCapacity - 1)) == 0, "LaneCapacity must be a power of 2");
    static_assert(PriorityLevels % 64 == 0, "PriorityLevels must be a multiple of 64");

public:
    using Priority = uint32_t;

    struct alignas(hardware_destructive_interference_size) Slot {
        std::atomic<uint64_t> turn{0};
        T storage;
    };

    struct alignas(hardware_destructive_interference_size) MPMCQueueLane {
        alignas(hardware_destructive_interference_size) std::atomic<uint64_t> head{0};
        alignas(hardware_destructive_interference_size) std::atomic<uint64_t> tail{0};
        Slot slots[LaneCapacity];

        MPMCQueueLane() {
            for (size_t i = 0; i < LaneCapacity; ++i) {
                slots[i].turn.store(i, std::memory_order_relaxed);
            }
        }

        bool try_enqueue(const T& value) {
            uint64_t t = tail.load(std::memory_order_relaxed);
            while (true) {
                Slot& slot = slots[t & (LaneCapacity - 1)];
                uint64_t turn = slot.turn.load(std::memory_order_acquire);
                int64_t diff = static_cast<int64_t>(turn) - static_cast<int64_t>(t);

                if (diff == 0) {
                    if (tail.compare_exchange_weak(t, t + 1, std::memory_order_relaxed)) {
                        slot.storage = value;
                        slot.turn.store(t + 1, std::memory_order_release);
                        return true;
                    }
                } else if (diff < 0) {
                    // Full buffer condition
                    return false;
                } else {
                    t = tail.load(std::memory_order_relaxed);
                }
            }
        }

        bool try_dequeue(T& result) {
            uint64_t h = head.load(std::memory_order_relaxed);
            while (true) {
                Slot& slot = slots[h & (LaneCapacity - 1)];
                uint64_t turn = slot.turn.load(std::memory_order_acquire);
                int64_t diff = static_cast<int64_t>(turn) - static_cast<int64_t>(h + 1);

                if (diff == 0) {
                    if (head.compare_exchange_weak(h, h + 1, std::memory_order_relaxed)) {
                        result = std::move(slot.storage);
                        slot.turn.store(h + LaneCapacity, std::memory_order_release);
                        return true;
                    }
                } else if (diff < 0) {
                    // Empty buffer condition
                    return false;
                } else {
                    h = head.load(std::memory_order_relaxed);
                }
            }
        }

        [[nodiscard]] bool empty() const noexcept {
            uint64_t h = head.load(std::memory_order_relaxed);
            uint64_t t = tail.load(std::memory_order_relaxed);
            return h >= t;
        }
    };

    struct alignas(hardware_destructive_interference_size) PriorityBand {
        MPMCQueueLane lanes[LanesPerBand];
    };

public:
    NUMAPriorityQueue() {
        for (size_t i = 0; i < BITMASK_WORDS; ++i) {
            active_bitmask_[i].store(0, std::memory_order_relaxed);
        }
        summary_bitmask_.store(0, std::memory_order_relaxed);
    }

    ~NUMAPriorityQueue() = default;

    MemoryManagement::ThreadControlBlock* register_thread() {
        return MemoryManagement::EpochManager::instance().register_thread();
    }

    void unregister_thread(MemoryManagement::ThreadControlBlock* tcb) {
        MemoryManagement::EpochManager::instance().unregister_thread(tcb);
    }

    // ========================================================================
    // Push Operation
    // ========================================================================
    bool try_push(Priority priority, T value, MemoryManagement::ThreadControlBlock* tcb) {
        if (priority >= PriorityLevels) return false;

        MemoryManagement::EpochGuard guard(tcb);

        size_t lane_idx = get_thread_lane_hint();
        PriorityBand& band = bands_[priority];

        // Try primary NUMA-local lane, then probe alternative lanes
        for (size_t attempt = 0; attempt < LanesPerBand; ++attempt) {
            size_t target_lane = (lane_idx + attempt) % LanesPerBand;
            if (band.lanes[target_lane].try_enqueue(value)) {
                mark_active(priority);
                return true;
            }
        }
        return false; // All lanes saturated for this priority band
    }

    // ========================================================================
    // Pop Min Operation (with Bounded Staleness Window epsilon)
    // ========================================================================
    std::optional<T> try_pop(MemoryManagement::ThreadControlBlock* tcb, size_t epsilon = 2) {
        MemoryManagement::EpochGuard guard(tcb);

        while (true) {
            int highest_prio = find_highest_active_priority();
            if (highest_prio < 0) {
                return std::nullopt; // Safely detected empty queue
            }

            size_t max_prio_bound = std::min(static_cast<size_t>(highest_prio) + epsilon, PriorityLevels - 1);
            size_t start_lane = get_thread_lane_hint();

            // Power-of-two choice across lanes in highest eligible priority bands
            for (size_t p = static_cast<size_t>(highest_prio); p <= max_prio_bound; ++p) {
                PriorityBand& band = bands_[p];

                // Randomized 2-choice exploration
                size_t l1 = (start_lane + (p * 3)) % LanesPerBand;
                size_t l2 = (start_lane + (p * 7) + 1) % LanesPerBand;

                T item;
                if (band.lanes[l1].try_dequeue(item)) {
                    check_and_clear_empty_band(p);
                    return item;
                }
                if (band.lanes[l2].try_dequeue(item)) {
                    check_and_clear_empty_band(p);
                    return item;
                }

                // Exhaustive pass on this band if 2-choice suffered contention
                for (size_t l = 0; l < LanesPerBand; ++l) {
                    if (l == l1 || l == l2) continue;
                    if (band.lanes[l].try_dequeue(item)) {
                        check_and_clear_empty_band(p);
                        return item;
                    }
                }
            }

            // Band was observed active but lanes were empty during scan; reconcile bitmask
            check_and_clear_empty_band(static_cast<size_t>(highest_prio));

            // Check top summary mask to avoid livelocks on empty state
            if (summary_bitmask_.load(std::memory_order_acquire) == 0) {
                return std::nullopt;
            }
        }
    }

private:
    static constexpr size_t BITMASK_WORDS = PriorityLevels / 64;

    inline size_t get_thread_lane_hint() noexcept {
        static thread_local size_t hint = std::hash<std::thread::id>{}(std::this_thread::get_id());
        return hint;
    }

    inline void mark_active(Priority p) noexcept {
        size_t word_idx = p / 64;
        uint64_t bit = 1ULL << (p % 64);

        uint64_t prev = active_bitmask_[word_idx].fetch_or(bit, std::memory_order_release);
        if (prev == 0) {
            summary_bitmask_.fetch_or(1ULL << word_idx, std::memory_order_release);
        }
    }

    inline void check_and_clear_empty_band(size_t p) noexcept {
        PriorityBand& band = bands_[p];
        for (size_t l = 0; l < LanesPerBand; ++l) {
            if (!band.lanes[l].empty()) {
                return;
            }
        }

        // All lanes are empty; clear band bit
        size_t word_idx = p / 64;
        uint64_t bit = 1ULL << (p % 64);
        uint64_t old_mask = active_bitmask_[word_idx].fetch_and(~bit, std::memory_order_acq_rel);

        if ((old_mask & ~bit) == 0) {
            summary_bitmask_.fetch_and(~(1ULL << word_idx), std::memory_order_acq_rel);
        }
    }

    inline int find_highest_active_priority() const noexcept {
        uint64_t summary = summary_bitmask_.load(std::memory_order_acquire);
        if (summary == 0) return -1;

#if defined(__GNUC__) || defined(__clang__)
        int summary_idx = __builtin_ctzll(summary);
#else
        unsigned long summary_idx;
        _BitScanForward64(&summary_idx, summary);
#endif

        uint64_t word = active_bitmask_[summary_idx].load(std::memory_order_acquire);
        if (word == 0) return -1;

#if defined(__GNUC__) || defined(__clang__)
        int bit_idx = __builtin_ctzll(word);
#else
        unsigned long bit_idx;
        _BitScanForward64(&bit_idx, word);
#endif

        return (summary_idx * 64) + bit_idx;
    }

private:
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> summary_bitmask_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> active_bitmask_[BITMASK_WORDS];
    alignas(hardware_destructive_interference_size) PriorityBand bands_[PriorityLevels];
};

