struct LatencyHistogram {
    static constexpr size_t BUCKETS = 10000;
    std::vector<uint64_t> latencies;

    LatencyHistogram() { latencies.reserve(1'000'000); }

    void record(uint64_t nanos) {
        latencies.push_back(nanos);
    }

    void print_percentiles() {
        if (latencies.empty()) return;
        std::sort(latencies.begin(), latencies.end());
        auto size = latencies.size();
        std::cout << "  Latencies (ns): "
                  << "p50: " << latencies[size * 0.50] << " ns | "
                  << "p90: " << latencies[size * 0.90] << " ns | "
                  << "p99: " << latencies[size * 0.99] << " ns | "
                  << "p99.99: " << latencies[std::min(size - 1, static_cast<size_t>(size * 0.9999))] << " ns\n";
    }
};

int main() {
    std::cout << "===================================================================\n";
    std::cout << "NUMA-Aware Multi-Lane Lock-Free Priority Queue Benchmark (C++20)\n";
    std::cout << "===================================================================\n";

    constexpr size_t THREAD_COUNT = 64;
    constexpr size_t OPS_PER_THREAD = 200'000;
    constexpr size_t TOTAL_OPS = THREAD_COUNT * OPS_PER_THREAD;

    using QueueType = NUMAPriorityQueue<uint64_t, 256, 8, 1024>;
    auto pq = std::make_unique<QueueType>();

    std::atomic<bool> start_flag{false};
    std::atomic<size_t> completed_pushes{0};
    std::atomic<size_t> completed_pops{0};

    std::vector<LatencyHistogram> histograms(THREAD_COUNT);
    std::vector<std::thread> workers;
    workers.reserve(THREAD_COUNT);

    for (size_t t = 0; t < THREAD_COUNT; ++t) {
        workers.emplace_back([&, t]() {
            auto* tcb = pq->register_thread();
            std::mt19937_64 rng(1337 + t);
            std::uniform_int_distribution<uint32_t> prio_dist(0, 255);
            std::uniform_int_distribution<uint32_t> op_dist(0, 99);

            // Wait for test barrier
            while (!start_flag.load(std::memory_order_relaxed)) {
                HARDWARE_PAUSE();
            }

            auto& hist = histograms[t];

            for (size_t i = 0; i < OPS_PER_THREAD; ++i) {
                bool is_push = (op_dist(rng) < 80); // 80% push, 20% pop workload
                auto t0 = std::chrono::steady_clock::now();

                if (is_push) {
                    uint32_t prio = prio_dist(rng);
                    uint64_t payload = (static_cast<uint64_t>(prio) << 32) | i;
                    if (pq->try_push(prio, payload, tcb)) {
                        completed_pushes.fetch_add(1, std::memory_order_relaxed);
                    }
                } else {
                    auto res = pq->try_pop(tcb, 2);
                    if (res.has_value()) {
                        completed_pops.fetch_add(1, std::memory_order_relaxed);
                    }
                }

                auto t1 = std::chrono::steady_clock::now();
                uint64_t elapsed_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(t1 - t0).count();
                if (i % 2 == 0) hist.record(elapsed_ns);
            }

            pq->unregister_thread(tcb);
        });
    }

    auto start_time = std::chrono::high_resolution_clock::now();
    start_flag.store(true, std::memory_order_release);

    for (auto& w : workers) {
        w.join();
    }
    auto end_time = std::chrono::high_resolution_clock::now();

    double total_sec = std::chrono::duration<double>(end_time - start_time).count();
    double mops = (static_cast<double>(TOTAL_OPS) / total_sec) / 1'000'000.0;

    std::cout << "Threads:               " << THREAD_COUNT << "\n";
    std::cout << "Total Operations:      " << TOTAL_OPS << "\n";
    std::cout << "Successful Pushes:     " << completed_pushes.load() << "\n";
    std::cout << "Successful Pops:       " << completed_pops.load() << "\n";
    std::cout << "Elapsed Time:          " << total_sec << " seconds\n";
    std::cout << "Throughput:            " << mops << " Million Ops/sec (Mops/s)\n\n";

    // Merge and compute global latency profile
    LatencyHistogram global_hist;
    for (auto& h : histograms) {
        global_hist.latencies.insert(global_hist.latencies.end(), h.latencies.begin(), h.latencies.end());
    }
    global_hist.print_percentiles();
    std::cout << "===================================================================\n";

    return 0;
}
