### 3. Crash Recovery Engine & Verification Pipeline

The recovery engine reads pre-existing segment files directly, verifies CRC32C framing integrity across individual records, identifies torn writes at the 4096-byte sector boundary, and reconstructs the High-Water Mark (HWM) LSN.

```cpp
#ifndef WAL_RECOVERY_HPP
#define WAL_RECOVERY_HPP

#include "wal_engine.hpp"
#include <filesystem>
#include <fstream>
#include <algorithm>
#include <functional>

namespace wal {

namespace fs = std::filesystem;

struct RecoveryResult {
    uint64_t last_valid_lsn{0};
    uint64_t total_records_recovered{0};
    size_t corrupted_bytes_truncated{0};
    bool clean_shutdown{true};
};

class WALRecoveryEngine {
public:
    using RecordCallback = std::function<void(const RecordHeader&, std::span<const uint8_t>)>;

    static RecoveryResult recover_and_repair(const std::string& log_dir, RecordCallback apply_record_cb) {
        RecoveryResult result{};
        if (!fs::exists(log_dir)) {
            return result;
        }

        // Collect and sort all segment files monotonically by starting LSN
        std::vector<fs::path> segment_files;
        for (const auto& entry : fs::directory_iterator(log_dir)) {
            if (entry.is_regular_file() && entry.path().extension() == ".wal") {
                segment_files.push_back(entry.path());
            }
        }
        std::sort(segment_files.begin(), segment_files.end());

        uint64_t expected_next_lsn = 0;
        bool first_record = true;

        for (const auto& seg_path : segment_files) {
            int fd = ::open(seg_path.c_str(), O_RDONLY | O_DIRECT);
            if (fd < 0) {
                // Fallback to standard buffered read if direct I/O fails during recovery inspection
                fd = ::open(seg_path.c_str(), O_RDONLY);
                if (fd < 0) continue;
            }

            const size_t file_size = fs::file_size(seg_path);
            if (file_size == 0) {
                ::close(fd);
                continue;
            }

            // Read segment in 4KB aligned blocks
            void* raw_aligned_buf = nullptr;
            if (posix_memalign(&raw_aligned_buf, DIRECT_IO_ALIGNMENT, DIRECT_IO_ALIGNMENT) != 0) {
                ::close(fd);
                throw std::runtime_error("Memory allocation failed during recovery");
            }
            auto* block_buf = static_cast<uint8_t*>(raw_aligned_buf);

            size_t file_offset = 0;
            bool segment_corrupted = false;

            while (file_offset < file_size && !segment_corrupted) {
                const ssize_t bytes_read = ::pread(fd, block_buf, DIRECT_IO_ALIGNMENT, file_offset);
                if (bytes_read <= 0) break;

                size_t block_cursor = 0;
                while (block_cursor < static_cast<size_t>(bytes_read)) {
                    // Check for zero-padded sector termination
                    if (block_cursor + sizeof(RecordHeader) > static_cast<size_t>(bytes_read)) {
                        break;
                    }

                    const auto* header = reinterpret_cast<const RecordHeader*>(block_buf + block_cursor);

                    // Check for end of written data in direct-allocated blocks (zeroed magic)
                    if (header->magic == 0) {
                        break;
                    }

                    // Validate Magic Header Identifier
                    if (header->magic != WAL_RECORD_MAGIC) {
                        result.clean_shutdown = false;
                        segment_corrupted = true;
                        break;
                    }

                    // Check payload bounds
                    if (header->payload_len > MAX_RECORD_PAYLOAD || 
                        block_cursor + sizeof(RecordHeader) + header->payload_len > static_cast<size_t>(bytes_read)) {
                        result.clean_shutdown = false;
                        segment_corrupted = true;
                        break;
                    }

                    // Validate LSN Sequence Continuity
                    if (!first_record && header->lsn != expected_next_lsn) {
                        result.clean_shutdown = false;
                        segment_corrupted = true;
                        break;
                    }

                    // Validate Checksum Integrity across payload + header
                    const uint8_t* payload_ptr = block_buf + block_cursor + sizeof(RecordHeader);
                    uint32_t expected_crc = calculate_crc32c(reinterpret_cast<const uint8_t*>(&header->lsn), 
                                                             sizeof(RecordHeader) - 8);
                    expected_crc = calculate_crc32c(payload_ptr, header->payload_len, expected_crc);

                    if (header->checksum != expected_crc) {
                        // Torn write detected across block boundary
                        result.clean_shutdown = false;
                        segment_corrupted = true;
                        break;
                    }

                    // Emit valid record to caller
                    apply_record_cb(*header, std::span<const uint8_t>(payload_ptr, header->payload_len));

                    expected_next_lsn = header->lsn + 1;
                    result.last_valid_lsn = header->lsn;
                    result.total_records_recovered++;
                    first_record = false;

                    block_cursor += sizeof(RecordHeader) + header->payload_len;
                }

                file_offset += bytes_read;
            }

            free(raw_aligned_buf);
            ::close(fd);

            if (segment_corrupted) {
                // Truncate corrupted trailing data to last valid 4096-aligned boundary
                fs::resize_file(seg_path, file_offset);
                break;
            }
        }

        return result;
    }
};

} // namespace wal

#endif // WAL_RECOVERY_HPP
```

