# 3. Crash Recovery & Segment Verification Engine

Below is the standalone production-grade WAL segment reader and recovery engine. It parses 4KB aligned physical segments, handles torn blocks at sector boundaries, verifies individual record checksums, and restores the exact High-Water Mark (HWM) LSN.

```cpp
#include <iostream>
#include <vector>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <cstring>

namespace wal {

struct RecoveredRecord {
    uint64_t lsn;
    std::vector<uint8_t> payload;
};

class WalRecoveryEngine {
public:
    static bool RecoverSegment(const std::string& segment_path, 
                              std::vector<RecoveredRecord>& out_records, 
                              uint64_t& out_hwm_lsn) {
        out_records.clear();
        out_hwm_lsn = 0;

        int fd = open(segment_path.c_str(), O_RDONLY | O_DIRECT);
        if (fd < 0) {
            // Fallback without O_DIRECT if filesystem restricts it on non-aligned file sizes
            fd = open(segment_path.c_str(), O_RDONLY);
            if (fd < 0) {
                std::cerr << "[Recovery] Cannot open file: " << segment_path << std::endl;
                return false;
            }
        }

        struct stat st;
        if (fstat(fd, &st) != 0) {
            close(fd);
            return false;
        }

        size_t file_size = st.st_size;
        if (file_size == 0) {
            close(fd);
            return true; // Clean, empty log
        }

        // Align read buffer to 4096 bytes
        size_t buffer_size = 1024 * 1024; // 1MB reading chunk
        uint8_t* buffer = nullptr;
        if (posix_memalign(reinterpret_cast<void**>(&buffer), SECTOR_SIZE, buffer_size) != 0) {
            close(fd);
            return false;
        }

        size_t file_offset = 0;
        uint64_t expected_lsn = 0;
        bool torn_write_encountered = false;

        while (file_offset < file_size && !torn_write_encountered) {
            ssize_t bytes_read = pread(fd, buffer, buffer_size, file_offset);
            if (bytes_read <= 0) break;

            size_t cursor = 0;
            while (cursor < static_cast<size_t>(bytes_read)) {
                // Ensure we have enough data to read a header
                if (cursor + sizeof(RecordHeader) > static_cast<size_t>(bytes_read)) {
                    break;
                }

                const RecordHeader* header = reinterpret_cast<const RecordHeader*>(buffer + cursor);

                // 1. Check for Zero-filled unwritten sector tail
                if (header->magic == 0 && header->lsn == 0) {
                    torn_write_encountered = true;
                    break;
                }

                // 2. Validate Magic Header
                if (header->magic != WAL_MAGIC) {
                    std::cerr << "[Recovery] Corrupted header magic at offset: " << (file_offset + cursor) << std::endl;
                    torn_write_encountered = true;
                    break;
                }

                // 3. Boundary validation for payload
                if (cursor + sizeof(RecordHeader) + header->payload_size > static_cast<size_t>(bytes_read)) {
                    // Crosses read-buffer chunk: handle partial buffer boundary
                    break;
                }

                const uint8_t* payload_ptr = buffer + cursor + sizeof(RecordHeader);

                // 4. Verify Checksum Integrity
                uint32_t computed_crc = compute_crc32c(payload_ptr, header->payload_size);
                if (computed_crc != header->crc32c) {
                    std::cerr << "[Recovery] CRC mismatch at LSN " << header->lsn 
                              << ". Expected: " << header->crc32c 
                              << ", Computed: " << computed_crc << " (Torn write detected)." << std::endl;
                    torn_write_encountered = true;
                    break;
                }

                // 5. Causal Sequence Validation
                if (expected_lsn != 0 && header->lsn <= expected_lsn) {
                    std::cerr << "[Recovery] Non-monotonic LSN detected: " << header->lsn << " <= " << expected_lsn << std::endl;
                    torn_write_encountered = true;
                    break;
                }

                // 6. Record successfully verified
                if (header->flags == 0x1) { // Regular valid record
                    RecoveredRecord record;
                    record.lsn = header->lsn;
                    record.payload.assign(payload_ptr, payload_ptr + header->payload_size);
                    out_records.push_back(std::move(record));
                    out_hwm_lsn = header->lsn;
                    expected_lsn = header->lsn;
                }

                cursor += sizeof(RecordHeader) + header->payload_size;
            }

            file_offset += cursor;
            if (cursor == 0) {
                // Prevent infinite loop if unable to progress
                break;
            }
        }

        free(buffer);
        close(fd);
        std::cout << "[Recovery] Successfully parsed " << out_records.size() 
                  << " records. Recovered High-Water Mark LSN: " << out_hwm_lsn << std::endl;
        return true;
    }
};

} // namespace wal
```

