#include <numeric>
#include <iostream>
#include <cassert>

int main() {
    wal::EngineOptions opts;
    opts.ring_capacity_bytes = 32 * 1024 * 1024; // 32MB
    opts.max_batch_bytes = 512 * 1024;           // 512KB
    opts.max_batch_delay_us = 10;
    opts.wal_directory = "./wal_test_data";

    std::cout << "[+] Initializing Ultra-Low Latency io_uring WAL Subsystem..." << std::endl;
    auto engine = std::make_unique<wal::WriteAheadLogEngine>(opts);

    constexpr size_t NUM_THREADS = 8;
    constexpr size_t OPS_PER_THREAD = 100'000;
    constexpr size_t RECORD_SIZE = 128;

    std::vector<uint8_t> payload_template(RECORD_SIZE, 0xAB);
    std::vector<std::thread> workers;
    workers.reserve(NUM_THREADS);

    std::atomic<bool> start_signal{false};
    auto start_time = std::chrono::high_resolution_clock::now();

    for (size_t t = 0; t < NUM_THREADS; ++t) {
        workers.emplace_back([&, t]() {
            while (!start_signal.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }

            std::vector<uint8_t> thread_payload = payload_template;
            thread_payload[0] = static_cast<uint8_t>(t); // Unique producer signature

            for (size_t i = 0; i < OPS_PER_THREAD; ++i) {
                // Ingest record
                wal::LSN lsn = engine->append(thread_payload);
                // Synchronously await durability (Group Commit)
                engine->wait_durable(lsn);
            }
        });
    }

    start_time = std::chrono::high_resolution_clock::now();
    start_signal.store(true, std::memory_order_release);

    for (auto& w : workers) {
        w.join();
    }
    auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(
        std::chrono::high_resolution_clock::now() - start_time
    ).count();

    const size_t total_ops = NUM_THREADS * OPS_PER_THREAD;
    const double ops_per_sec = (static_cast<double>(total_ops) / elapsed) * 1'000'000.0;
    const double avg_latency_us = static_cast<double>(elapsed) / total_ops;

    std::cout << "========================================" << std::endl;
    std::cout << " Benchmark Results (O_DIRECT + io_uring)" << std::endl;
    std::cout << "========================================" << std::endl;
    std::cout << " Total Committed Records: " << total_ops << std::endl;
    std::cout << " Total Time Elapsed:     " << elapsed / 1000.0 << " ms" << std::endl;
    std::cout << " Throughput:             " << ops_per_sec << " ops/sec" << std::endl;
    std::cout << " Average Latency:        " << avg_latency_us << " us/op" << std::endl;
    std::cout << " High Water Mark LSN:    " << engine->get_durable_lsn() << std::endl;

    engine->shutdown();
    return 0;
}
