### 3. Crash Recovery & Segment Verification Implementation

Below is the recovery engine that traverses log segments on disk, validating Direct I/O 4KB blocks, verifying Castagnoli CRC32C framing integrity, identifying torn zero-pad pages, and establishing the exact high-water mark (HWM) LSN.

Save this implementation as `wal_recovery.hpp`.

```cpp
#pragma once

#include "wal_engine.hpp"
#include <string>
#include <vector>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <algorithm>

namespace wal {

struct RecoveryReport {
    LSN last_valid_lsn{0};
    uint64_t valid_records_recovered{0};
    uint64_t corrupted_records_detected{0};
    uint64_t torn_pages_truncated{0};
    bool clean_recovery{false};
};

class CrashRecoveryEngine {
public:
    explicit CrashRecoveryEngine(std::string wal_directory)
        : wal_dir_(std::move(wal_directory)) {}

    /**
     * @brief Deterministic recovery sweep across ordered WAL segments.
     */
    RecoveryReport run_recovery() {
        RecoveryReport report{};
        std::vector<std::filesystem::path> segment_files;

        for (const auto& entry : std::filesystem::directory_iterator(wal_dir_)) {
            if (entry.path().extension() == ".wal") {
                segment_files.push_back(entry.path());
            }
        }

        // Sort segments chronologically
        std::sort(segment_files.begin(), segment_files.end());

        LSN expected_lsn = 0;
        std::vector<uint8_t> block_buffer(SECTOR_ALIGNMENT);

        for (const auto& seg_path : segment_files) {
            int fd = ::open(seg_path.c_str(), O_RDONLY | O_DIRECT);
            if (fd < 0) {
                // Fallback without O_DIRECT if filesystem constraints reject alignment
                fd = ::open(seg_path.c_str(), O_RDONLY);
                if (fd < 0) continue;
            }

            off_t file_offset = 0;
            bool segment_exhausted = false;

            while (!segment_exhausted) {
                ssize_t bytes_read = ::pread(fd, block_buffer.data(), SECTOR_ALIGNMENT, file_offset);
                if (bytes_read <= 0) {
                    break; // EOF
                }

                size_t block_cursor = 0;
                while (block_cursor < static_cast<size_t>(bytes_read)) {
                    // Check for trailing zero padding (unwritten Direct-I/O sector space)
                    if (is_zero_page(&block_buffer[block_cursor], bytes_read - block_cursor)) {
                        segment_exhausted = true;
                        break;
                    }

                    if (block_cursor + sizeof(LogRecordHeader) > static_cast<size_t>(bytes_read)) {
                        // Torn header across sector boundary
                        report.torn_pages_truncated++;
                        segment_exhausted = true;
                        break;
                    }

                    const auto* header = reinterpret_cast<const LogRecordHeader*>(&block_buffer[block_cursor]);

                    // Verify magic framing
                    if (header->magic != WAL_MAGIC_V1) {
                        report.corrupted_records_detected++;
                        segment_exhausted = true;
                        break;
                    }

                    // Verify Header Checksum
                    uint32_t computed_h_crc = compute_crc32c(&header->lsn, sizeof(LogRecordHeader) - 8);
                    if (computed_h_crc != header->header_crc) {
                        report.corrupted_records_detected++;
                        segment_exhausted = true;
                        break;
                    }

                    // Verify causal monotonic continuity
                    if (header->lsn != expected_lsn && expected_lsn != 0) {
                        std::cerr << "[-] LSN Gap Detected! Expected: " << expected_lsn 
                                  << " Encountered: " << header->lsn << std::endl;
                        report.corrupted_records_detected++;
                        segment_exhausted = true;
                        break;
                    }

                    // Validate Payload CRC
                    const uint8_t* payload_ptr = &block_buffer[block_cursor + sizeof(LogRecordHeader)];
                    uint32_t computed_p_crc = compute_crc32c(payload_ptr, header->payload_size);
                    if (computed_p_crc != header->payload_crc) {
                        report.corrupted_records_detected++;
                        segment_exhausted = true;
                        break;
                    }

                    // Record successfully validated
                    expected_lsn = header->lsn + header->total_size;
                    report.last_valid_lsn = expected_lsn;
                    report.valid_records_recovered++;

                    block_cursor += header->total_size;
                }

                file_offset += bytes_read;
            }

            ::close(fd);
        }

        report.clean_recovery = (report.corrupted_records_detected == 0);
        return report;
    }

private:
    static bool is_zero_page(const uint8_t* buf, size_t len) noexcept {
        const auto* p64 = reinterpret_cast<const uint64_t*>(buf);
        size_t words = len / 8;
        for (size_t i = 0; i < words; ++i) {
            if (p64[i] != 0) return false;
        }
        for (size_t i = words * 8; i < len; ++i) {
            if (buf[i] != 0) return false;
        }
        return true;
    }

    std::string wal_dir_;
};

} // namespace wal
```

