// Maximum height of skip-list towers
constexpr size_t MAX_HEIGHT = 32;
constexpr float PROBABILITY = 0.5f;
constexpr size_t RETIRE_THRESHOLD = 1024;
constexpr size_t MAX_HAZARD_PER_THREAD = 4;
constexpr uint64_t INF_TX_ID = UINT64_MAX;
constexpr uint64_t TOMBSTONE_BIT = (1ULL << 63);

// ============================================================================
// 1. Tagged Pointer (48-bit Virtual Address + 1-bit Mark + 15-bit ABA Tag)
// ============================================================================
template <typename T>
class TaggedPointer {
private:
    uint64_t bits_{0};

    static constexpr uint64_t PTR_MASK  = 0x00007FFFFFFFFFF8ULL;
    static constexpr uint64_t MARK_MASK = 0x0000000000000001ULL;
    static constexpr uint64_t TAG_MASK  = 0xFFFF000000000000ULL;
    static constexpr uint64_t TAG_SHIFT = 48;

public:
    constexpr TaggedPointer() noexcept : bits_(0) {}
    constexpr TaggedPointer(T* ptr, bool mark = false, uint16_t tag = 0) noexcept {
        uint64_t p = reinterpret_cast<uint64_t>(ptr);
        bits_ = (p & PTR_MASK) | (mark ? MARK_MASK : 0) | (static_cast<uint64_t>(tag) << TAG_SHIFT);
    }
    explicit constexpr TaggedPointer(uint64_t raw) noexcept : bits_(raw) {}

    [[nodiscard]] inline T* GetPtr() const noexcept {
        return reinterpret_cast<T*>(bits_ & PTR_MASK);
    }

    [[nodiscard]] inline bool IsMarked() const noexcept {
        return (bits_ & MARK_MASK) != 0;
    }

    [[nodiscard]] inline uint16_t GetTag() const noexcept {
        return static_cast<uint16_t>((bits_ & TAG_MASK) >> TAG_SHIFT);
    }

    [[nodiscard]] inline TaggedPointer WithMark(bool mark) const noexcept {
        return TaggedPointer((bits_ & ~MARK_MASK) | (mark ? MARK_MASK : 0));
    }

    [[nodiscard]] inline TaggedPointer WithIncTag() const noexcept {
        uint16_t next_tag = GetTag() + 1;
        return TaggedPointer((bits_ & ~TAG_MASK) | (static_cast<uint64_t>(next_tag) << TAG_SHIFT));
    }

    [[nodiscard]] inline uint64_t GetRaw() const noexcept { return bits_; }
    constexpr bool operator==(const TaggedPointer& o) const noexcept { return bits_ == o.bits_; }
    constexpr bool operator!=(const TaggedPointer& o) const noexcept { return bits_ != o.bits_; }
    explicit constexpr operator bool() const noexcept { return GetPtr() != nullptr; }
};

// ============================================================================
// 2. MVCC Version Chain Node
// ============================================================================
template <typename Value>
struct alignas(hardware_destructive_interference_size) VersionNode {
    uint64_t tx_begin{0};
    std::atomic<uint64_t> tx_end{INF_TX_ID};
    bool is_tombstone{false};
    Value value;
    std::atomic<VersionNode<Value>*> next_version{nullptr};

    VersionNode(uint64_t tx_id, Value val, bool tombstone = false)
        : tx_begin(tx_id), tx_end(INF_TX_ID), is_tombstone(tombstone), value(std::move(val)), next_version(nullptr) {}
};

// ============================================================================
// 3. Skip-List Node
// ============================================================================
template <typename Key, typename Value>
struct alignas(hardware_destructive_interference_size) Node {
    Key key;
    size_t height;
    std::atomic<VersionNode<Value>*> version_head{nullptr};
    std::atomic<TaggedPointer<Node<Key, Value>>> next[MAX_HEIGHT];

    Node(Key k, size_t h) : key(std::move(k)), height(h) {
        for (size_t i = 0; i < MAX_HEIGHT; ++i) {
            next[i].store(TaggedPointer<Node<Key, Value>>(nullptr), std::memory_order_relaxed);
        }
        version_head.store(nullptr, std::memory_order_relaxed);
    }
};

// ============================================================================
// 4. Hybrid Epoch-Hazard Reclamation Subsystem (HEHR)
// ============================================================================
class HEHRManager {
public:
    struct alignas(hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<uint64_t> epoch{INF_TX_ID};
        std::atomic<void*> hazard_pointers[MAX_HAZARD_PER_THREAD];
        std::atomic<bool> active{false};

        ThreadControlBlock() {
            for (size_t i = 0; i < MAX_HAZARD_PER_THREAD; ++i) {
                hazard_pointers[i].store(nullptr, std::memory_order_relaxed);
            }
        }
    };

    struct RetiredNode {
        void* ptr;
        uint64_t retire_epoch;
        std::function<void(void*)> deleter;
    };

private:
    std::atomic<uint64_t> global_epoch_{0};
    size_t max_threads_;
    std::unique_ptr<ThreadControlBlock[]> tcbs_;

public:
    explicit HEHRManager(size_t max_threads)
        : max_threads_(max_threads),
          tcbs_(std::make_unique<ThreadControlBlock[]>(max_threads)) {}

    ~HEHRManager() {
        for (size_t i = 0; i < max_threads_; ++i) {
            tcbs_[i].active.store(false, std::memory_order_relaxed);
        }
    }

    void RegisterThread(size_t tid) {
        assert(tid < max_threads_);
        tcbs_[tid].epoch.store(INF_TX_ID, std::memory_order_relaxed);
        for (size_t i = 0; i < MAX_HAZARD_PER_THREAD; ++i) {
            tcbs_[tid].hazard_pointers[i].store(nullptr, std::memory_order_relaxed);
        }
        tcbs_[tid].active.store(true, std::memory_order_release);
    }

    void UnregisterThread(size_t tid) {
        assert(tid < max_threads_);
        tcbs_[tid].epoch.store(INF_TX_ID, std::memory_order_release);
        for (size_t i = 0; i < MAX_HAZARD_PER_THREAD; ++i) {
            tcbs_[tid].hazard_pointers[i].store(nullptr, std::memory_order_release);
        }
        tcbs_[tid].active.store(false, std::memory_order_release);
    }

    // Fast-path Epoch Guard
    inline uint64_t EnterEpoch(size_t tid) noexcept {
        uint64_t e = global_epoch_.load(std::memory_order_acquire);
        tcbs_[tid].epoch.store(e, std::memory_order_release);
        return e;
    }

    inline void LeaveEpoch(size_t tid) noexcept {
        tcbs_[tid].epoch.store(INF_TX_ID, std::memory_order_release);
    }

    // Hazard Pointer Escalation (Slow-path for long range scans)
    inline void SetHazard(size_t tid, size_t slot_idx, void* ptr) noexcept {
        assert(slot_idx < MAX_HAZARD_PER_THREAD);
        tcbs_[tid].hazard_pointers[slot_idx].store(ptr, std::memory_order_release);
        std::atomic_thread_fence(std::memory_order_seq_cst);
    }

    inline void ClearHazard(size_t tid, size_t slot_idx) noexcept {
        assert(slot_idx < MAX_HAZARD_PER_THREAD);
        tcbs_[tid].hazard_pointers[slot_idx].store(nullptr, std::memory_order_release);
    }

    inline void ClearAllHazards(size_t tid) noexcept {
        for (size_t i = 0; i < MAX_HAZARD_PER_THREAD; ++i) {
            tcbs_[tid].hazard_pointers[i].store(nullptr, std::memory_order_relaxed);
        }
        std::atomic_thread_fence(std::memory_order_release);
    }

    inline uint64_t GetGlobalEpoch() const noexcept {
        return global_epoch_.load(std::memory_order_acquire);
    }

    // Advance epoch if safe
    void TryAdvanceEpoch() noexcept {
        uint64_t cur_e = global_epoch_.load(std::memory_order_relaxed);
        for (size_t i = 0; i < max_threads_; ++i) {
            if (!tcbs_[i].active.load(std::memory_order_acquire)) continue;
            uint64_t th_e = tcbs_[i].epoch.load(std::memory_order_acquire);
            if (th_e != INF_TX_ID && th_e < cur_e) {
                return; // Stalled by an epoch reader
            }
        }
        global_epoch_.compare_exchange_strong(cur_e, cur_e + 1, std::memory_order_acq_rel);
    }

    // Check if node is protected by any hazard pointer
    bool IsHazardProtected(void* ptr) const noexcept {
        for (size_t i = 0; i < max_threads_; ++i) {
            if (!tcbs_[i].active.load(std::memory_order_acquire)) continue;
            for (size_t h = 0; h < MAX_HAZARD_PER_THREAD; ++h) {
                if (tcbs_[i].hazard_pointers[h].load(std::memory_order_acquire) == ptr) {
                    return true;
                }
            }
        }
        return false;
    }

    // Reclaim retired batch
    void ReclaimList(std::vector<RetiredNode>& retired_list) {
        TryAdvanceEpoch();
        uint64_t min_epoch = INF_TX_ID;
        for (size_t i = 0; i < max_threads_; ++i) {
            if (!tcbs_[i].active.load(std::memory_order_acquire)) continue;
            uint64_t th_e = tcbs_[i].epoch.load(std::memory_order_acquire);
            if (th_e < min_epoch) {
                min_epoch = th_e;
            }
        }

        auto it = retired_list.begin();
        while (it != retired_list.end()) {
            bool safe_epoch = (it->retire_epoch < min_epoch);
            if (safe_epoch && !IsHazardProtected(it->ptr)) {
                it->deleter(it->ptr);
                it = retired_list.erase(it);
            } else {
                ++it;
            }
        }
    }
};

// ============================================================================
// 5. Lock-Free MVCC Skip-List Implementation
// ============================================================================
template <typename Key, typename Value, typename KeyComparator = std::less<Key>>
class LockFreeMVCCSkipList {
public:
    using NodeType = Node<Key, Value>;
    using VersionType = VersionNode<Value>;
    using TaggedNodePtr = TaggedPointer<NodeType>;

private:
    KeyComparator comp_;
    size_t max_threads_;
    HEHRManager hehr_;

    NodeType* head_;
    NodeType* tail_;

    // Thread-local retired node buffer
    static thread_local size_t tl_thread_id;
    static thread_local std::vector<HEHRManager::RetiredNode> tl_retired;
    static thread_local std::mt19937 tl_rng;
    static thread_local std::uniform_real_distribution<float> tl_dist;

    inline bool KeyLess(const Key& a, const Key& b) const noexcept {
        return comp_(a, b);
    }

    inline bool KeyEqual(const Key& a, const Key& b) const noexcept {
        return !comp_(a, b) && !comp_(b, a);
    }

    size_t GenerateRandomHeight() noexcept {
        size_t h = 1;
        while (h < MAX_HEIGHT && tl_dist(tl_rng) < PROBABILITY) {
            ++h;
        }
        return h;
    }

    void DeferReclaimNode(NodeType* node) {
        tl_retired.push_back({
            static_cast<void*>(node),
            hehr_.GetGlobalEpoch(),
            [](void* p) {
                auto* n = static_cast<NodeType*>(p);
                // Free version chain
                auto* cur_v = n->version_head.load(std::memory_order_relaxed);
                while (cur_v) {
                    auto* next_v = cur_v->next_version.load(std::memory_order_relaxed);
                    delete cur_v;
                    cur_v = next_v;
                }
                delete n;
            }
        });
        if (tl_retired.size() >= RETIRE_THRESHOLD) {
            hehr_.ReclaimList(tl_retired);
        }
    }

    void DeferReclaimVersion(VersionType* v) {
        tl_retired.push_back({
            static_cast<void*>(v),
            hehr_.GetGlobalEpoch(),
            [](void* p) {
                delete static_cast<VersionType*>(p);
            }
        });
        if (tl_retired.size() >= RETIRE_THRESHOLD) {
            hehr_.ReclaimList(tl_retired);
        }
    }

public:
    explicit LockFreeMVCCSkipList(size_t max_threads, Key min_key = Key{}, Key max_key = Key{})
        : max_threads_(max_threads), hehr_(max_threads) {

        head_ = new NodeType(min_key, MAX_HEIGHT);
        tail_ = new NodeType(max_key, MAX_HEIGHT);

        for (size_t i = 0; i < MAX_HEIGHT; ++i) {
            head_->next[i].store(TaggedNodePtr(tail_, false, 0), std::memory_order_relaxed);
            tail_->next[i].store(TaggedNodePtr(nullptr, false, 0), std::memory_order_relaxed);
        }
    }

    ~LockFreeMVCCSkipList() {
        // Physical sweep of all remaining nodes
        NodeType* curr = head_->next[0].load(std::memory_order_relaxed).GetPtr();
        while (curr && curr != tail_) {
            NodeType* nxt = curr->next[0].load(std::memory_order_relaxed).GetPtr();
            auto* v = curr->version_head.load(std::memory_order_relaxed);
            while (v) {
                auto* nv = v->next_version.load(std::memory_order_relaxed);
                delete v;
                v = nv;
            }
            delete curr;
            curr = nxt;
        }
        delete head_;
        delete tail_;
    }

    void RegisterThread(size_t thread_id) {
        tl_thread_id = thread_id;
        hehr_.RegisterThread(thread_id);
    }

    void UnregisterThread(size_t thread_id) {
        hehr_.ReclaimList(tl_retired);
        hehr_.UnregisterThread(thread_id);
    }

private:
    // ========================================================================
    // Internal Search & Cooperative Clean-up
    // ========================================================================
    bool Search(const Key& key,
                std::array<NodeType*, MAX_HEIGHT>& preds,
                std::array<NodeType*, MAX_HEIGHT>& succs) {
    retry:
        NodeType* pred = head_;
        for (int level = static_cast<int>(MAX_HEIGHT) - 1; level >= 0; --level) {
            TaggedNodePtr curr_tagged = pred->next[level].load(std::memory_order_acquire);

            while (true) {
                NodeType* curr = curr_tagged.GetPtr();
                if (curr == nullptr) break;

                TaggedNodePtr succ_tagged = curr->next[level].load(std::memory_order_acquire);

                // Check if current node is marked for deletion at this level
                while (succ_tagged.IsMarked()) {
                    // Help physical removal
                    TaggedNodePtr desired(succ_tagged.GetPtr(), false, curr_tagged.GetTag() + 1);
                    if (!pred->next[level].compare_exchange_strong(
                            curr_tagged, desired,
                            std::memory_order_acq_rel,
                            std::memory_order_acquire)) {
                        goto retry; // CAS failed; re-read from top
                    }
                    // Successfully unlinked curr from level
                    if (level == 0) {
                        DeferReclaimNode(curr);
                    }
                    curr = succ_tagged.GetPtr();
                    if (curr == nullptr) break;
                    succ_tagged = curr->next[level].load(std::memory_order_acquire);
                }

                if (curr == tail_ || !KeyLess(curr->key, key)) {
                    preds[level] = pred;
                    succs[level] = curr;
                    break;
                }

                pred = curr;
                curr_tagged = succ_tagged;
            }
        }

        return (succs[0] != tail_ && KeyEqual(succs[0]->key, key));
    }

public:
    // ========================================================================
    // Writer Operations
    // ========================================================================
    bool Insert(const Key& key, const Value& val, uint64_t tx_id) {
        hehr_.EnterEpoch(tl_thread_id);
        std::array<NodeType*, MAX_HEIGHT> preds;
        std::array<NodeType*, MAX_HEIGHT> succs;

        while (true) {
            if (Search(key, preds, succs)) {
                // Key exists: atomically prepend a new version to the existing node
                NodeType* target_node = succs[0];
                auto* new_version = new VersionType(tx_id, val, false);

                while (true) {
                    VersionType* old_head = target_node->version_head.load(std::memory_order_acquire);

                    // Validate monotonicity of tx_id
                    if (old_head && old_head->tx_begin >= tx_id) {
                        delete new_version;
                        hehr_.LeaveEpoch(tl_thread_id);
                        return false; // Stale transaction ID
                    }

                    new_version->next_version.store(old_head, std::memory_order_relaxed);

                    if (target_node->version_head.compare_exchange_weak(
                            old_head, new_version,
                            std::memory_order_release,
                            std::memory_order_acquire)) {

                        // Close previous version lifetime
                        if (old_head) {
                            old_head->tx_end.store(tx_id, std::memory_order_release);
                        }
                        hehr_.LeaveEpoch(tl_thread_id);
                        return true;
                    }
                    HEHR_PAUSE();
                }
            }

            // Key does not exist: create new skip-list node
            size_t height = GenerateRandomHeight();
            auto* new_node = new NodeType(key, height);
            auto* initial_version = new VersionType(tx_id, val, false);
            new_node->version_head.store(initial_version, std::memory_order_relaxed);

            // Step 1: Link bottom level
            new_node->next[0].store(TaggedNodePtr(succs[0], false, 0), std::memory_order_relaxed);
            TaggedNodePtr expected_pred_next(succs[0], false, preds[0]->next[0].load(std::memory_order_relaxed).GetTag());
            TaggedNodePtr new_pred_next(new_node, false, expected_pred_next.GetTag() + 1);

            if (!preds[0]->next[0].compare_exchange_strong(
                    expected_pred_next, new_pred_next,
                    std::memory_order_release,
                    std::memory_order_acquire)) {
                delete initial_version;
                delete new_node;
                continue; // Collision at level 0; retry search
            }

            // Step 2: Splice upper levels
            for (size_t lvl = 1; lvl < height; ++lvl) {
                while (true) {
                    Search(key, preds, succs); // Re-locate exact predecessors for upper level
                    new_node->next[lvl].store(TaggedNodePtr(succs[lvl], false, 0), std::memory_order_relaxed);

                    TaggedNodePtr exp(succs[lvl], false, preds[lvl]->next[lvl].load(std::memory_order_relaxed).GetTag());
                    TaggedNodePtr des(new_node, false, exp.GetTag() + 1);

                    if (preds[lvl]->next[lvl].compare_exchange_strong(
                            exp, des,
                            std::memory_order_release,
                            std::memory_order_acquire)) {
                        break; // Spliced successfully at this level
                    }

                    // Check if node was concurrently marked
                    if (new_node->next[lvl].load(std::memory_order_acquire).IsMarked()) {
                        break;
                    }
                    HEHR_PAUSE();
                }
            }

            hehr_.LeaveEpoch(tl_thread_id);
            return true;
        }
    }

    bool Delete(const Key& key, uint64_t tx_id) {
        hehr_.EnterEpoch(tl_thread_id);
        std::array<NodeType*, MAX_HEIGHT> preds;
        std::array<NodeType*, MAX_HEIGHT> succs;

        while (true) {
            if (!Search(key, preds, succs)) {
                hehr_.LeaveEpoch(tl_thread_id);
                return false; // Key does not exist
            }

            NodeType* target_node = succs[0];
            // Append a tombstone version to the MVCC chain
            auto* tombstone = new VersionType(tx_id, Value{}, true);

            while (true) {
                VersionType* old_head = target_node->version_head.load(std::memory_order_acquire);
                if (old_head && old_head->tx_begin >= tx_id) {
                    delete tombstone;
                    hehr_.LeaveEpoch(tl_thread_id);
                    return false;
                }

                if (old_head && old_head->is_tombstone) {
                    // Already deleted at this or later logical time
                    delete tombstone;
                    hehr_.LeaveEpoch(tl_thread_id);
                    return false;
                }

                tombstone->next_version.store(old_head, std::memory_order_relaxed);

                if (target_node->version_head.compare_exchange_weak(
                        old_head, tombstone,
                        std::memory_order_release,
                        std::memory_order_acquire)) {
                    if (old_head) {
                        old_head->tx_end.store(tx_id, std::memory_order_release);
                    }
                    hehr_.LeaveEpoch(tl_thread_id);
                    return true;
                }
                HEHR_PAUSE();
            }
        }
    }

    // ========================================================================
    // Reader Operations
    // ========================================================================
    bool Get(const Key& key, uint64_t snapshot_tx_id, Value& out_val) {
        hehr_.EnterEpoch(tl_thread_id);

        NodeType* pred = head_;
        NodeType* curr = nullptr;

        for (int level = static_cast<int>(MAX_HEIGHT) - 1; level >= 0; --level) {
            TaggedNodePtr curr_tagged = pred->next[level].load(std::memory_order_acquire);
            while (true) {
                curr = curr_tagged.GetPtr();
                if (curr == tail_ || curr == nullptr) break;

                TaggedNodePtr succ_tagged = curr->next[level].load(std::memory_order_acquire);
                if (KeyLess(curr->key, key)) {
                    pred = curr;
                    curr_tagged = succ_tagged;
                } else {
                    break;
                }
            }
        }

        if (curr != nullptr && curr != tail_ && KeyEqual(curr->key, key)) {
            // Traverse MVCC version chain
            VersionType* v = curr->version_head.load(std::memory_order_acquire);
            while (v != nullptr) {
                uint64_t begin = v->tx_begin;
                uint64_t end = v->tx_end.load(std::memory_order_acquire);

                if (begin <= snapshot_tx_id && snapshot_tx_id < end) {
                    if (v->is_tombstone) {
                        hehr_.LeaveEpoch(tl_thread_id);
                        return false; // Deleted as of snapshot
                    }
                    out_val = v->value;
                    hehr_.LeaveEpoch(tl_thread_id);
                    return true;
                }
                v = v->next_version.load(std::memory_order_acquire);
            }
        }

        hehr_.LeaveEpoch(tl_thread_id);
        return false;
    }

    // ========================================================================
    // Range Scan with Hazard Escalation
    // ========================================================================
    size_t RangeScan(const Key& start_key,
                     const Key& end_key,
                     uint64_t snapshot_tx_id,
                     std::vector<std::pair<Key, Value>>& results,
                     size_t max_records) {
        results.clear();
        if (max_records == 0) return 0;

        hehr_.EnterEpoch(tl_thread_id);

        // 1. Locate start node
        NodeType* pred = head_;
        NodeType* curr = nullptr;
        for (int level = static_cast<int>(MAX_HEIGHT) - 1; level >= 0; --level) {
            TaggedNodePtr curr_tagged = pred->next[level].load(std::memory_order_acquire);
            while (true) {
                curr = curr_tagged.GetPtr();
                if (curr == tail_ || curr == nullptr) break;

                TaggedNodePtr succ_tagged = curr->next[level].load(std::memory_order_acquire);
                if (KeyLess(curr->key, start_key)) {
                    pred = curr;
                    curr_tagged = succ_tagged;
                } else {
                    break;
                }
            }
        }

        curr = (curr == nullptr) ? tail_ : curr;

        // 2. Iterate across level 0 with Hazard Pointer handshakes
        size_t hazard_idx = 0;
        while (curr != tail_ && curr != nullptr && results.size() < max_records) {
            if (KeyLess(end_key, curr->key)) {
                break; // Out of requested range
            }

            // Hazard escalation on current node to protect across epoch advancements
            hehr_.SetHazard(tl_thread_id, hazard_idx, curr);

            // Re-verify node integrity
            TaggedNodePtr next_tagged = curr->next[0].load(std::memory_order_acquire);
            if (next_tagged.IsMarked()) {
                // Node is unlinked; advance safely using the tagged pointer successor
                curr = next_tagged.GetPtr();
                continue;
            }

            // Version lookup
            VersionType* v = curr->version_head.load(std::memory_order_acquire);
            while (v != nullptr) {
                uint64_t begin = v->tx_begin;
                uint64_t end = v->tx_end.load(std::memory_order_acquire);

                if (begin <= snapshot_tx_id && snapshot_tx_id < end) {
                    if (!v->is_tombstone) {
                        results.emplace_back(curr->key, v->value);
                    }
                    break;
                }
                v = v->next_version.load(std::memory_order_acquire);
            }

            // Advance pointer to next
            NodeType* next_node = next_tagged.GetPtr();
            hazard_idx = (hazard_idx + 1) % MAX_HAZARD_PER_THREAD;
            curr = next_node;
        }

        hehr_.ClearAllHazards(tl_thread_id);
        hehr_.LeaveEpoch(tl_thread_id);
        return results.size();
    }

    // ========================================================================
    // Garbage Collection for Obsolete Versions
    // ========================================================================
    void TriggerGarbageCollection(uint64_t oldest_active_tx_id) {
        hehr_.EnterEpoch(tl_thread_id);

        NodeType* curr = head_->next[0].load(std::memory_order_acquire).GetPtr();
        while (curr != tail_ && curr != nullptr) {
            VersionType* v = curr->version_head.load(std::memory_order_acquire);
            VersionType* prev_visible = nullptr;

            while (v != nullptr) {
                uint64_t end = v->tx_end.load(std::memory_order_acquire);
                VersionType* nxt_v = v->next_version.load(std::memory_order_acquire);

                // If version is completely obscured by an older active snapshot
                if (end <= oldest_active_tx_id) {
                    if (prev_visible != nullptr) {
                        // Unlink obsolete suffix of version chain
                        if (prev_visible->next_version.compare_exchange_strong(
                                v, nullptr,
                                std::memory_order_acq_rel,
                                std::memory_order_acquire)) {
                            // Reclaim detached chain
                            VersionType* to_free = v;
                            while (to_free) {
                                VersionType* n = to_free->next_version.load(std::memory_order_relaxed);
                                DeferReclaimVersion(to_free);
                                to_free = n;
                            }
                            break;
                        }
                    }
                }

                prev_visible = v;
                v = nxt_v;
            }

            // Check if node is fully dead (tombstone is oldest and only version)
            VersionType* head_v = curr->version_head.load(std::memory_order_acquire);
            if (head_v && head_v->is_tombstone && head_v->tx_begin <= oldest_active_tx_id &&
                head_v->next_version.load(std::memory_order_relaxed) == nullptr) {

                // Mark node logically dead at level 0 to initiate physical removal
                for (int lvl = static_cast<int>(curr->height) - 1; lvl >= 0; --lvl) {
                    TaggedNodePtr cur_next = curr->next[lvl].load(std::memory_order_acquire);
                    while (!cur_next.IsMarked()) {
                        TaggedNodePtr marked_next = cur_next.WithMark(true);
                        if (curr->next[lvl].compare_exchange_weak(
                                cur_next, marked_next,
                                std::memory_order_acq_rel,
                                std::memory_order_acquire)) {
                            break;
                        }
                    }
                }
            }

            curr = curr->next[0].load(std::memory_order_acquire).GetPtr();
        }

        hehr_.LeaveEpoch(tl_thread_id);
    }
};

// Thread-local definitions
template <typename K, typename V, typename C>
thread_local size_t LockFreeMVCCSkipList<K, V, C>::tl_thread_id = 0;

template <typename K, typename V, typename C>
thread_local std::vector<HEHRManager::RetiredNode> LockFreeMVCCSkipList<K, V, C>::tl_retired{};

template <typename K, typename V, typename C>
thread_local std::mt19937 LockFreeMVCCSkipList<K, V, C>::tl_rng{std::random_device{}()};

template <typename K, typename V, typename C>
thread_local std::uniform_real_distribution<float> LockFreeMVCCSkipList<K, V, C>::tl_dist{0.0f, 1.0f};

} // namespace mvcc_index
```

