#if defined(__cpp_lib_hardware_interference_size)
    using std::hardware_destructive_interference_size;
#else
    // Standard L1 cache line size for modern x86_64 and AArch64
    constexpr size_t hardware_destructive_interference_size = 64;
#endif

static constexpr size_t MAX_SKIPLIST_HEIGHT = 32;
static constexpr size_t MAX_HAZARD_PER_THREAD = 4;
static constexpr size_t RETIRED_BATCH_THRESHOLD = 1024;
static constexpr uint64_t INF_TX_ID = UINT64_MAX;

// ============================================================================
// 1. Tagged Pointer Primitive (48-bit ptr, 1-bit mark, 15-bit ABA sequence)
// ============================================================================
template <typename T>
class TaggedPointer {
private:
    uint64_t raw_value_{0};

    static constexpr uint64_t MARK_MASK = 0x0000000000000001ULL;
    static constexpr uint64_t PTR_MASK  = 0x0000FFFFFFFFFFF8ULL; // 8-byte aligned
    static constexpr uint64_t TAG_MASK  = 0xFFFF000000000000ULL;
    static constexpr uint32_t TAG_SHIFT = 48;

public:
    constexpr TaggedPointer() noexcept : raw_value_(0) {}

    explicit constexpr TaggedPointer(uint64_t raw) noexcept : raw_value_(raw) {}

    TaggedPointer(T* ptr, bool marked, uint16_t tag = 0) noexcept {
        uint64_t p = reinterpret_cast<uint64_t>(ptr);
        raw_value_ = (p & PTR_MASK) | (marked ? MARK_MASK : 0ULL) | (static_cast<uint64_t>(tag) << TAG_SHIFT);
    }

    [[nodiscard]] inline T* GetPtr() const noexcept {
        return reinterpret_cast<T*>(raw_value_ & PTR_MASK);
    }

    [[nodiscard]] inline bool IsMarked() const noexcept {
        return (raw_value_ & MARK_MASK) != 0;
    }

    [[nodiscard]] inline uint16_t GetTag() const noexcept {
        return static_cast<uint16_t>((raw_value_ & TAG_MASK) >> TAG_SHIFT);
    }

    [[nodiscard]] inline TaggedPointer<T> WithMark(bool mark) const noexcept {
        uint64_t nv = (raw_value_ & ~MARK_MASK) | (mark ? MARK_MASK : 0ULL);
        return TaggedPointer<T>(nv);
    }

    [[nodiscard]] inline TaggedPointer<T> IncrementTag() const noexcept {
        uint16_t tag = GetTag();
        tag = static_cast<uint16_t>((tag + 1) & 0xFFFF);
        uint64_t nv = (raw_value_ & ~TAG_MASK) | (static_cast<uint64_t>(tag) << TAG_SHIFT);
        return TaggedPointer<T>(nv);
    }

    [[nodiscard]] inline uint64_t GetRaw() const noexcept {
        return raw_value_;
    }

    bool operator==(const TaggedPointer& o) const noexcept { return raw_value_ == o.raw_value_; }
    bool operator!=(const TaggedPointer& o) const noexcept { return raw_value_ != o.raw_value_; }
};

