// ============================================================================
// 3. Hybrid Epoch-Hazard Reclamation Engine (HEHR)
// ============================================================================
class HybridEBRHazardEngine {
public:
    struct alignas(hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<bool> active{false};
        std::atomic<uint64_t> local_epoch{0};
        std::atomic<bool> in_hazard_mode{false};
        std::array<std::atomic<void*>, MAX_HAZARD_PER_THREAD> hazard_ptrs{};

        // Thread-local retired nodes queue
        struct RetiredNode {
            void* ptr{nullptr};
            void (*deleter)(void*){nullptr};
            uint64_t epoch{0};
        };

        std::vector<RetiredNode> retired_queue;

        ThreadControlBlock() {
            for (auto& hp : hazard_ptrs) {
                hp.store(nullptr, std::memory_order_relaxed);
            }
            retired_queue.reserve(RETIRED_BATCH_THRESHOLD * 2);
        }
    };

private:
    std::atomic<uint64_t> global_epoch_{0};
    size_t max_threads_;
    std::unique_ptr<ThreadControlBlock[]> tcbs_;

public:
    explicit HybridEBRHazardEngine(size_t max_threads)
        : max_threads_(max_threads),
          tcbs_(new ThreadControlBlock[max_threads]) {
        global_epoch_.store(1, std::memory_order_release);
    }

    ~HybridEBRHazardEngine() {
        for (size_t i = 0; i < max_threads_; ++i) {
            FlushRetiredQueue(i, true);
        }
    }

    void RegisterThread(size_t thread_id) {
        assert(thread_id < max_threads_);
        tcbs_[thread_id].active.store(true, std::memory_order_release);
    }

    void UnregisterThread(size_t thread_id) {
        assert(thread_id < max_threads_);
        FlushRetiredQueue(thread_id, true);
        tcbs_[thread_id].in_hazard_mode.store(false, std::memory_order_relaxed);
        for (auto& hp : tcbs_[thread_id].hazard_ptrs) {
            hp.store(nullptr, std::memory_order_relaxed);
        }
        tcbs_[thread_id].active.store(false, std::memory_order_release);
    }

    // --- Fast-Path Epoch Protection ---
    void EnterCriticalSection(size_t thread_id) {
        assert(thread_id < max_threads_);
        auto& tcb = tcbs_[thread_id];
        tcb.in_hazard_mode.store(false, std::memory_order_relaxed);
        uint64_t e = global_epoch_.load(std::memory_order_acquire);
        tcb.local_epoch.store(e, std::memory_order_release);
        // Acquire-Release barrier to ensure loads in critical section do not reorder above local_epoch store
        #if defined(__x86_64__) || defined(_M_X64)
        _mm_pause();
        #endif
    }

    void ExitCriticalSection(size_t thread_id) {
        assert(thread_id < max_threads_);
        auto& tcb = tcbs_[thread_id];
        tcb.local_epoch.store(0, std::memory_order_release);
    }

    // --- Slow-Path Hazard Pointer Handover for Long Scans ---
    void EscalateToHazardPointer(size_t thread_id, size_t slot, void* ptr) {
        assert(thread_id < max_threads_);
        assert(slot < MAX_HAZARD_PER_THREAD);
        auto& tcb = tcbs_[thread_id];
        tcb.hazard_ptrs[slot].store(ptr, std::memory_order_release);
        std::atomic_thread_fence(std::memory_order_seq_cst);
        tcb.in_hazard_mode.store(true, std::memory_order_release);
    }

    void ClearHazardPointer(size_t thread_id, size_t slot) {
        assert(thread_id < max_threads_);
        assert(slot < MAX_HAZARD_PER_THREAD);
        tcbs_[thread_id].hazard_ptrs[slot].store(nullptr, std::memory_order_release);
    }

    void ClearAllHazardPointers(size_t thread_id) {
        assert(thread_id < max_threads_);
        auto& tcb = tcbs_[thread_id];
        for (auto& hp : tcb.hazard_ptrs) {
            hp.store(nullptr, std::memory_order_relaxed);
        }
        tcb.in_hazard_mode.store(false, std::memory_order_release);
    }

    // --- Retirement and Dynamic GC ---
    template <typename T>
    void RetireNode(size_t thread_id, T* ptr) {
        if (!ptr) return;
        assert(thread_id < max_threads_);
        auto& tcb = tcbs_[thread_id];
        uint64_t current_epoch = global_epoch_.load(std::memory_order_relaxed);

        tcb.retired_queue.push_back({
            ptr,
            [](void* p) { delete static_cast<T*>(p); },
            current_epoch
        });

        if (tcb.retired_queue.size() >= RETIRED_BATCH_THRESHOLD) {
            TryAdvanceEpochAndReclaim(thread_id);
        }
    }

    void TryAdvanceEpochAndReclaim(size_t thread_id) {
        uint64_t g_epoch = global_epoch_.load(std::memory_order_acquire);

        // Check if all active threads have witnessed the current epoch
        bool can_advance = true;
        for (size_t i = 0; i < max_threads_; ++i) {
            if (tcbs_[i].active.load(std::memory_order_acquire)) {
                uint64_t le = tcbs_[i].local_epoch.load(std::memory_order_acquire);
                bool in_hp = tcbs_[i].in_hazard_mode.load(std::memory_order_acquire);
                if (!in_hp && le != 0 && le < g_epoch) {
                    can_advance = false;
                    break;
                }
            }
        }

        if (can_advance) {
            global_epoch_.compare_exchange_strong(g_epoch, g_epoch + 1, std::memory_order_acq_rel);
        }

        FlushRetiredQueue(thread_id, false);
    }

private:
    void FlushRetiredQueue(size_t thread_id, bool force) {
        auto& tcb = tcbs_[thread_id];
        if (tcb.retired_queue.empty()) return;

        uint64_t cur_epoch = global_epoch_.load(std::memory_order_acquire);

        // Collect all protected hazard pointers across threads
        std::vector<void*> protected_ptrs;
        protected_ptrs.reserve(max_threads_ * MAX_HAZARD_PER_THREAD);
        for (size_t i = 0; i < max_threads_; ++i) {
            if (tcbs_[i].active.load(std::memory_order_acquire)) {
                for (size_t h = 0; h < MAX_HAZARD_PER_THREAD; ++h) {
                    void* hp = tcbs_[i].hazard_ptrs[h].load(std::memory_order_acquire);
                    if (hp) {
                        protected_ptrs.push_back(hp);
                    }
                }
            }
        }

        auto it = tcb.retired_queue.begin();
        while (it != tcb.retired_queue.end()) {
            bool is_protected = false;
            if (!force) {
                // Rule 1: Epoch safety check (retired 2 epochs prior to current)
                bool epoch_safe = (cur_epoch >= it->epoch + 2);
                if (!epoch_safe) {
                    ++it;
                    continue;
                }
                // Rule 2: Hazard pointer check
                for (void* php : protected_ptrs) {
                    if (php == it->ptr) {
                        is_protected = true;
                        break;
                    }
                }
            }

            if (!is_protected || force) {
                it->deleter(it->ptr);
                it = tcb.retired_queue.erase(it);
            } else {
                ++it;
            }
        }
    }
};

// ============================================================================
// 4. MVCC Skip-List Node
// ============================================================================
template <typename Key, typename Value>
struct alignas(hardware_destructive_interference_size) SkipListNode {
    Key key;
    size_t height;
    std::atomic<VersionNode<Value>*> version_head{nullptr};
    std::array<std::atomic<TaggedPointer<SkipListNode<Key, Value>>>, MAX_SKIPLIST_HEIGHT> next;

    SkipListNode(Key k, size_t h, VersionNode<Value>* v_head = nullptr)
        : key(std::move(k)), height(h), version_head(v_head) {
        for (size_t i = 0; i < MAX_SKIPLIST_HEIGHT; ++i) {
            next[i].store(TaggedPointer<SkipListNode<Key, Value>>(nullptr, false, 0), std::memory_order_relaxed);
        }
    }
};

// ============================================================================
// 5. Lock-Free MVCC Skip-List Implementation
// ============================================================================
template <typename Key, typename Value, typename KeyComparator = std::less<Key>>
class LockFreeMVCCSkipList {
public:
    using Node = SkipListNode<Key, Value>;
    using TaggedNodePtr = TaggedPointer<Node>;

private:
    KeyComparator comp_;
    size_t max_threads_;
    std::unique_ptr<HybridEBRHazardEngine> smr_;

    alignas(hardware_destructive_interference_size) Node* head_{nullptr};
    alignas(hardware_destructive_interference_size) Node* tail_{nullptr};

    thread_local static inline size_t tls_thread_id = SIZE_MAX;
    thread_local static inline std::mt19937_64 tls_rng{std::random_device{}()};

private:
    size_t GenerateRandomHeight() {
        size_t h = 1;
        while (h < MAX_SKIPLIST_HEIGHT && (tls_rng() & 1)) {
            h++;
        }
        return h;
    }

    bool KeyEqual(const Key& a, const Key& b) const {
        return !comp_(a, b) && !comp_(b, a);
    }

    bool KeyLess(const Key& a, const Key& b) const {
        return comp_(a, b);
    }

    bool SearchInternal(const Key& key,
                        std::array<Node*, MAX_SKIPLIST_HEIGHT>& preds,
                        std::array<Node*, MAX_SKIPLIST_HEIGHT>& succs,
                        size_t thread_id) {
        Node* pred = nullptr;
        Node* curr = nullptr;
        Node* succ = nullptr;

    retry:
        pred = head_;
        for (int l = static_cast<int>(MAX_SKIPLIST_HEIGHT) - 1; l >= 0; --l) {
            TaggedNodePtr curr_tagged = pred->next[l].load(std::memory_order_acquire);
            curr = curr_tagged.GetPtr();

            while (true) {
                if (!curr) break;
                TaggedNodePtr succ_tagged = curr->next[l].load(std::memory_order_acquire);
                succ = succ_tagged.GetPtr();

                // Snip logically deleted nodes along the path
                while (succ_tagged.IsMarked()) {
                    TaggedNodePtr expected(curr, false, curr_tagged.GetTag());
                    TaggedNodePtr desired(succ, false, curr_tagged.GetTag() + 1);

                    if (!pred->next[l].compare_exchange_weak(
                            expected, desired,
                            std::memory_order_acq_rel,
                            std::memory_order_acquire)) {
                        goto retry;
                    }

                    // If unlinked at level 0, retire the physical node
                    if (l == 0) {
                        smr_->RetireNode(thread_id, curr);
                    }

                    curr = succ;
                    if (!curr) break;
                    succ_tagged = curr->next[l].load(std::memory_order_acquire);
                    succ = succ_tagged.GetPtr();
                }

                if (!curr || curr == tail_) break;

                if (KeyLess(curr->key, key)) {
                    pred = curr;
                    curr = succ;
                } else {
                    break;
                }
            }
            preds[l] = pred;
            succs[l] = curr;
        }

        return (curr != nullptr && curr != tail_ && KeyEqual(curr->key, key));
    }

public:
    explicit LockFreeMVCCSkipList(size_t max_threads)
        : max_threads_(max_threads),
          smr_(std::make_unique<HybridEBRHazardEngine>(max_threads)) {

        // Sentinel allocation
        head_ = new Node(Key{}, MAX_SKIPLIST_HEIGHT);
        tail_ = new Node(Key{}, MAX_SKIPLIST_HEIGHT);

        for (size_t i = 0; i < MAX_SKIPLIST_HEIGHT; ++i) {
            head_->next[i].store(TaggedNodePtr(tail_, false, 0), std::memory_order_relaxed);
            tail_->next[i].store(TaggedNodePtr(nullptr, false, 0), std::memory_order_relaxed);
        }
    }

    ~LockFreeMVCCSkipList() {
        Node* curr = head_;
        while (curr) {
            Node* next = curr->next[0].load(std::memory_order_relaxed).GetPtr();

            // Clean version chain
            VersionNode<Value>* v = curr->version_head.load(std::memory_order_relaxed);
            while (v) {
                VersionNode<Value>* pv = v->prev_version.load(std::memory_order_relaxed);
                delete v;
                v = pv;
            }
            delete curr;
            curr = next;
        }
    }

    void RegisterThread(size_t thread_id) {
        tls_thread_id = thread_id;
        smr_->RegisterThread(thread_id);
    }

    void UnregisterThread(size_t thread_id) {
        smr_->UnregisterThread(thread_id);
        tls_thread_id = SIZE_MAX;
    }

    // ========================================================================
    // Writer Operations
    // ========================================================================
    bool Insert(const Key& key, const Value& val, uint64_t tx_id) {
        size_t tid = tls_thread_id;
        assert(tid != SIZE_MAX && "Thread must be registered");

        smr_->EnterCriticalSection(tid);

        std::array<Node*, MAX_SKIPLIST_HEIGHT> preds{};
        std::array<Node*, MAX_SKIPLIST_HEIGHT> succs{};

        while (true) {
            bool found = SearchInternal(key, preds, succs, tid);
            if (found) {
                Node* target = succs[0];
                auto* new_vnode = new VersionNode<Value>(tx_id, false, val);

                // Linearize MVCC Version Append
                while (true) {
                    VersionNode<Value>* cur_head = target->version_head.load(std::memory_order_acquire);

                    if (cur_head && cur_head->tx_begin >= tx_id) {
                        // Strict timestamp serialization violation
                        delete new_vnode;
                        smr_->ExitCriticalSection(tid);
                        return false;
                    }

                    new_vnode->prev_version.store(cur_head, std::memory_order_relaxed);

                    if (target->version_head.compare_exchange_weak(
                            cur_head, new_vnode,
                            std::memory_order_release,
                            std::memory_order_acquire)) {

                        if (cur_head) {
                            cur_head->tx_end = tx_id; // Logical close
                        }
                        smr_->ExitCriticalSection(tid);
                        return true;
                    }
                }
            } else {
                // Key does not exist: Splice a new index node
                size_t height = GenerateRandomHeight();
                auto* new_vnode = new VersionNode<Value>(tx_id, false, val);
                auto* new_node = new Node(key, height, new_vnode);

                for (size_t i = 0; i < height; ++i) {
                    new_node->next[i].store(TaggedNodePtr(succs[i], false, 0), std::memory_order_relaxed);
                }

                // Splicing level 0 (Linearization Point of Index Insertion)
                TaggedNodePtr expected(succs[0], false, preds[0]->next[0].load(std::memory_order_relaxed).GetTag());
                TaggedNodePtr desired(new_node, false, expected.GetTag() + 1);

                if (!preds[0]->next[0].compare_exchange_strong(
                        expected, desired,
                        std::memory_order_release,
                        std::memory_order_acquire)) {
                    // Splicing failed at level 0; retry
                    delete new_vnode;
                    delete new_node;
                    continue;
                }

                // Splice upper levels cooperatively
                for (size_t l = 1; l < height; ++l) {
                    while (true) {
                        TaggedNodePtr cur_target = new_node->next[l].load(std::memory_order_acquire);
                        if (cur_target.IsMarked()) break; // Node deleted concurrently

                        TaggedNodePtr pred_tag = preds[l]->next[l].load(std::memory_order_acquire);
                        TaggedNodePtr pred_desired(new_node, false, pred_tag.GetTag() + 1);
                        TaggedNodePtr exp(succs[l], false, pred_tag.GetTag());

                        if (preds[l]->next[l].compare_exchange_strong(
                                exp, pred_desired,
                                std::memory_order_release,
                                std::memory_order_acquire)) {
                            break;
                        }

                        // Re-search predecessors to adapt to concurrent structural modifications
                        SearchInternal(key, preds, succs, tid);
                    }
                }

                smr_->ExitCriticalSection(tid);
                return true;
            }
        }
    }

    bool Delete(const Key& key, uint64_t tx_id) {
        size_t tid = tls_thread_id;
        assert(tid != SIZE_MAX && "Thread must be registered");

        smr_->EnterCriticalSection(tid);

        std::array<Node*, MAX_SKIPLIST_HEIGHT> preds{};
        std::array<Node*, MAX_SKIPLIST_HEIGHT> succs{};

        while (true) {
            bool found = SearchInternal(key, preds, succs, tid);
            if (!found) {
                smr_->ExitCriticalSection(tid);
                return false;
            }

            Node* target = succs[0];
            auto* tombstone_vnode = new VersionNode<Value>(tx_id, true, Value{});

            while (true) {
                VersionNode<Value>* cur_head = target->version_head.load(std::memory_order_acquire);
                if (cur_head && cur_head->tx_begin >= tx_id) {
                    delete tombstone_vnode;
                    smr_->ExitCriticalSection(tid);
                    return false;
                }

                tombstone_vnode->prev_version.store(cur_head, std::memory_order_relaxed);

                if (target->version_head.compare_exchange_weak(
                        cur_head, tombstone_vnode,
                        std::memory_order_release,
                        std::memory_order_acquire)) {

                    if (cur_head) {
                        cur_head->tx_end = tx_id;
                    }
                    smr_->ExitCriticalSection(tid);
                    return true;
                }
            }
        }
    }

    // ========================================================================
    // Reader Operations
    // ========================================================================
    bool Get(const Key& key, uint64_t snapshot_tx_id, Value& out_val) {
        size_t tid = tls_thread_id;
        assert(tid != SIZE_MAX && "Thread must be registered");

        smr_->EnterCriticalSection(tid);

        Node* pred = head_;
        Node* curr = nullptr;

        for (int l = static_cast<int>(MAX_SKIPLIST_HEIGHT) - 1; l >= 0; --l) {
            TaggedNodePtr curr_tagged = pred->next[l].load(std::memory_order_acquire);
            curr = curr_tagged.GetPtr();

            while (curr && curr != tail_) {
                if (KeyLess(curr->key, key)) {
                    pred = curr;
                    curr = curr->next[l].load(std::memory_order_acquire).GetPtr();
                } else {
                    break;
                }
            }
        }

        if (curr && curr != tail_ && KeyEqual(curr->key, key)) {
            VersionNode<Value>* vnode = curr->version_head.load(std::memory_order_acquire);
            while (vnode) {
                if (vnode->tx_begin <= snapshot_tx_id && snapshot_tx_id < vnode->tx_end) {
                    if (vnode->is_tombstone) {
                        smr_->ExitCriticalSection(tid);
                        return false; // Deleted at snapshot
                    }
                    out_val = vnode->value;
                    smr_->ExitCriticalSection(tid);
                    return true;
                }
                vnode = vnode->prev_version.load(std::memory_order_acquire);
            }
        }

        smr_->ExitCriticalSection(tid);
        return false;
    }

    size_t RangeScan(const Key& start_key,
                      const Key& end_key,
                      uint64_t snapshot_tx_id,
                      std::vector<std::pair<Key, Value>>& results,
                      size_t max_records) {
        size_t tid = tls_thread_id;
        assert(tid != SIZE_MAX && "Thread must be registered");

        smr_->EnterCriticalSection(tid);
        results.clear();

        // 1. Locate starting predecessor
        Node* pred = head_;
        Node* curr = nullptr;

        for (int l = static_cast<int>(MAX_SKIPLIST_HEIGHT) - 1; l >= 0; --l) {
            TaggedNodePtr curr_tagged = pred->next[l].load(std::memory_order_acquire);
            curr = curr_tagged.GetPtr();

            while (curr && curr != tail_) {
                if (KeyLess(curr->key, start_key)) {
                    pred = curr;
                    curr = curr->next[l].load(std::memory_order_acquire).GetPtr();
                } else {
                    break;
                }
            }
        }

        curr = pred->next[0].load(std::memory_order_acquire).GetPtr();

        // 2. Scan Level 0 with Hybrid Hazard Pointer Escalation
        size_t matched_count = 0;
        size_t hp_slot = 0;

        while (curr && curr != tail_ && matched_count < max_records) {
            // Escalate current node into hazard pointer table to prevent reclamation during scan
            smr_->EscalateToHazardPointer(tid, hp_slot, curr);

            // Re-validate that curr was not physically snipped before HP registration
            TaggedNodePtr next_tagged = curr->next[0].load(std::memory_order_acquire);
            if (next_tagged.IsMarked()) {
                // Advance past logically deleted node
                curr = next_tagged.GetPtr();
                continue;
            }

            if (KeyLess(end_key, curr->key)) {
                break; // Out of range
            }

            if (!KeyLess(curr->key, start_key)) {
                // Inspect MVCC Chain
                VersionNode<Value>* vnode = curr->version_head.load(std::memory_order_acquire);
                while (vnode) {
                    if (vnode->tx_begin <= snapshot_tx_id && snapshot_tx_id < vnode->tx_end) {
                        if (!vnode->is_tombstone) {
                            results.emplace_back(curr->key, vnode->value);
                            matched_count++;
                        }
                        break;
                    }
                    vnode = vnode->prev_version.load(std::memory_order_acquire);
                }
            }

            // Step forward
            Node* next_node = next_tagged.GetPtr();
            hp_slot = (hp_slot + 1) % MAX_HAZARD_PER_THREAD;
            curr = next_node;
        }

        smr_->ClearAllHazardPointers(tid);
        smr_->ExitCriticalSection(tid);
        return matched_count;
    }

    // ========================================================================
    // Maintenance & Garbage Collection
    // ========================================================================
    void TriggerGarbageCollection(uint64_t oldest_active_tx_id) {
        size_t tid = tls_thread_id;
        assert(tid != SIZE_MAX && "Thread must be registered");

        smr_->EnterCriticalSection(tid);

        Node* curr = head_->next[0].load(std::memory_order_acquire).GetPtr();
        while (curr && curr != tail_) {
            TaggedNodePtr next_tagged = curr->next[0].load(std::memory_order_acquire);

            if (!next_tagged.IsMarked()) {
                // Prune obsolete versions in MVCC chain
                VersionNode<Value>* vnode = curr->version_head.load(std::memory_order_acquire);
                VersionNode<Value>* prev_live = nullptr;

                while (vnode) {
                    // If this version became obsolete before the oldest active transaction
                    if (vnode->tx_end <= oldest_active_tx_id) {
                        // All versions strictly older than this one are dead
                        VersionNode<Value>* dead_chain = vnode->prev_version.load(std::memory_order_relaxed);
                        vnode->prev_version.store(nullptr, std::memory_order_release);

                        while (dead_chain) {
                            VersionNode<Value>* next_dead = dead_chain->prev_version.load(std::memory_order_relaxed);
                            smr_->RetireNode(tid, dead_chain);
                            dead_chain = next_dead;
                        }

                        if (vnode->is_tombstone && prev_live == nullptr) {
                            // The latest committed version is a tombstone and is obsolete: Mark index node
                            for (size_t l = 0; l < curr->height; ++l) {
                                TaggedNodePtr cur_succ = curr->next[l].load(std::memory_order_acquire);
                                while (!cur_succ.IsMarked()) {
                                    TaggedNodePtr marked_succ = cur_succ.WithMark(true);
                                    if (curr->next[l].compare_exchange_weak(
                                            cur_succ, marked_succ,
                                            std::memory_order_release,
                                            std::memory_order_acquire)) {
                                        break;
                                    }
                                }
                            }
                        }
                        break;
                    }
                    prev_live = vnode;
                    vnode = vnode->prev_version.load(std::memory_order_acquire);
                }
            }

            curr = next_tagged.GetPtr();
        }

        smr_->TryAdvanceEpochAndReclaim(tid);
        smr_->ExitCriticalSection(tid);
    }
};

#endif // LOCK_FREE_MVCC_SKIPLIST_HPP
```

---

### Algorithmic Complexity & Benchmark Analysis

#### 1. Theoretical Time and Space Complexity

| Operation | Best-Case Time | Average-Case Time | Worst-Case Time | Memory / Structural Invariants |
| :--- | :--- | :--- | :--- | :--- |
| **Point Lookup (`Get`)** | $O(1)$ | $O(\log N + V_k)$ | $O(N + V_k)$ | Wait-free on search traversal; lock-free on version list. |
| **Snapshot Range Scan (`Scan`)** | $O(K + V_k)$ | $O(\log N + K \cdot V_k)$ | $O(N + K \cdot V_k)$ | Pin-protected via $O(1)$ Hazard Pointer escalation per step. |
| **Insert / Version Prepend** | $O(\log N)$ | $O(\log N + V_k)$ | $O(N + V_k)$ | $O(1)$ CAS for existing key; $O(H)$ CAS steps for new key tower. |
| **Prune GC (`TriggerGC`)** | $O(N)$ | $O(N \cdot V_k)$ | $O(N \cdot V_k)$ | Lock-free version unlinking and deferred SMR epoch reclamation. |

*where $N$ is the count of distinct index keys, $H \le 32$ is skip-list tower height, $K$ is the number of range elements scanned, and $V_k$ is the average active MVCC chain depth for key $k$.*

---

#### 2. Per-Node Memory Overhead Breakdown (64-bit Architecture)

```
SkipListNode Layout:
+------------------------------------+-----------------------+
| Field                              | Size (Bytes)          |
+------------------------------------+-----------------------+
| Key key                            | sizeof(Key)           |
| size_t height                      | 8 bytes               |
| std::atomic<VersionNode*> head     | 8 bytes               |
| std::array<TaggedPointer, 32> next | 256 bytes (32 * 8B)   |
| Padding to 64B cache line boundary | Dynamic               |
+------------------------------------+-----------------------+
Total Index Node Footprint: ~272 - 320 Bytes

VersionNode Layout:
+------------------------------------+-----------------------+
| uint64_t tx_begin, tx_end          | 16 bytes              |
| bool is_tombstone                  | 1 byte                |
| Value value                        | sizeof(Value)         |
| std::atomic<VersionNode*> prev     | 8 bytes               |
+------------------------------------+-----------------------+
Total Version Node Footprint: ~32 - 64 Bytes
```

With geometric height distribution ($p = 0.5$), the mathematical expectation of tower height is:
$$\mathbb{E}[H] = \sum_{h=1}^{32} h \cdot p^{h-1}(1-p) = \frac{1}{1-p} = 2$$

Thus, dynamic tail-allocated node designs amortize to $\sim 48$ bytes of tower pointers per key index entry.

---

#### 3. NUMA-Scale Contention Bottlenecks & Mitigations

```
NUMA Node 0 (Cores 0-31)                     NUMA Node 1 (Cores 32-63)
+----------------------------------+         +----------------------------------+
| Local Epoch: [TCB 0] ... [TCB 31]|         | Local Epoch: [TCB 32]... [TCB 63]|
+----------------------------------+         +----------------------------------+
                 │                                            │
                 └───────────────► Interconnect ◄─────────────┘
                                  (UPI / Infinity Fabric)
                                             │
                        +────────────────────▼────────────────────+
                        |   Global Epoch Counter (Read-Mostly)    |
                        |   - Acq/Rel only on R=1024 threshold    |
                        |   - No cross-socket CAS in read-path    |
                        +─────────────────────────────────────────+
```

1. **False Sharing Elimination**:
   * All thread-local control blocks (`ThreadControlBlock`) and internal index node headers are aligned to 64 bytes (`alignas(hardware_destructive_interference_size)`). This isolates per-thread epoch state and hazard pointers to private L1/L2 cache lines, completely avoiding cross-core invalidation traffic during pure reader execution.
2. **Reclamation Scalability**:
   * SMR epoch checks run entirely against local epoch snapshots during fast-path execution. Cross-socket coherency traffic across NUMA interconnects occurs **only** when a thread exceeds its retired allocation threshold ($R = 1024$), amortizing cross-socket atomic CAS operations to $O(1/R)$ frequency per update.

