// Custom NUMA Memory Allocator Abstraction
inline void* numa_aligned_malloc(size_t size, size_t alignment, int numa_node) noexcept {
    void* ptr = nullptr;
#if HAS_LIBNUMA
    if (numa_node >= 0 && numa_available() >= 0) {
        ptr = numa_alloc_onnode(size, numa_node);
        if (ptr && (reinterpret_cast<uintptr_t>(ptr) % alignment != 0)) {
            // numa_alloc_onnode guarantees page-alignment (4KB+), which satisfies 128B alignment.
            // If alignment requirement exceeds page boundary, fallback to aligned allocation.
            numa_free(ptr, size);
            ptr = nullptr;
        }
    }
#endif
    if (!ptr) {
#if defined(_MSC_VER) || defined(__MINGW32__)
        ptr = _aligned_malloc(size, alignment);
#else
        if (posix_memalign(&ptr, alignment, size) != 0) {
            ptr = nullptr;
        }
#endif
    }
    return ptr;
}

inline void numa_aligned_free(void* ptr, size_t size) noexcept {
    if (!ptr) return;
#if HAS_LIBNUMA
    if (numa_available() >= 0) {
        numa_free(ptr, size);
        return;
    }
#endif
#if defined(_MSC_VER) || defined(__MINGW32__)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
