// Lock-Free Thread Domain Hazard Pointer Subsystem for Safe Slot Reclamation
template <typename T, size_t MaxThreads = 128>
class HazardPointerDomain {
public:
    struct HazardRecord {
        std::atomic<void*> hazard_ptr{nullptr};
        std::atomic<std::thread::id> owner{std::thread::id{}};
    };

    static HazardPointerDomain& instance() {
        static HazardPointerDomain domain;
        return domain;
    }

    HazardRecord* acquire_record() noexcept {
        const auto tid = std::this_thread::get_id();
        for (size_t i = 0; i < MaxThreads; ++i) {
            std::thread::id expected{};
            if (records_[i].owner.compare_exchange_strong(expected, tid, 
                    std::memory_order_relaxed, std::memory_order_relaxed)) {
                return &records_[i];
            }
            if (expected == tid) {
                return &records_[i];
            }
        }
        return nullptr; // Exceeded max threads
    }

    void release_record(HazardRecord* rec) noexcept {
        if (rec) {
            rec->hazard_ptr.store(nullptr, std::memory_order_release);
            rec->owner.store(std::thread::id{}, std::memory_order_release);
        }
    }

private:
    alignas(HardwareCacheLineSize) HazardRecord records_[MaxThreads];
};

