// Lock-free MPMC Queue Slot Design
template <typename T>
struct alignas(HardwareCacheLineSize) Slot {
    std::atomic<size_t> turn{0};
    alignas(alignof(T)) std::byte storage[sizeof(T)];

    template <typename... Args>
    void construct(Args&&... args) {
        ::new (static_cast<void*>(storage)) T(std::forward<Args>(args)...);
    }

    void destroy() noexcept {
        reinterpret_cast<T*>(storage)->~T();
    }

    T* value_ptr() noexcept {
        return reinterpret_cast<T*>(storage);
    }

    const T* value_ptr() const noexcept {
        return reinterpret_cast<const T*>(storage);
    }
};

template <typename T, size_t Capacity = 0, typename Allocator = std::allocator<T>>
class NumaAwareBatchedMPMCQueue {
public:
    static_assert(Capacity == 0 || (Capacity >= 2 && (Capacity & (Capacity - 1)) == 0),
                  "Capacity must be 0 (dynamic) or a power of two.");

    explicit NumaAwareBatchedMPMCQueue(size_t dynamic_capacity = Capacity, int numa_node = -1)
        : numa_node_(numa_node),
          capacity_((Capacity > 0) ? Capacity : dynamic_capacity),
          capacity_mask_(capacity_ - 1) 
    {
        if (capacity_ < 2 || (capacity_ & capacity_mask_) != 0) {
            throw std::invalid_argument("Queue capacity must be a power of two and >= 2.");
        }

        const size_t total_bytes = capacity_ * sizeof(Slot<T>);
        void* mem = detail::numa_aligned_malloc(total_bytes, HardwareCacheLineSize, numa_node_);
        if (!mem) {
            throw std::bad_alloc();
        }

        slots_ = static_cast<Slot<T>*>(mem);

        // Initialize slots and set sequence numbers
        for (size_t i = 0; i < capacity_; ++i) {
            ::new (static_cast<void*>(&slots_[i])) Slot<T>();
            slots_[i].turn.store(0, std::memory_order_relaxed);
        }

        tail_ticket_.store(0, std::memory_order_relaxed);
        head_ticket_.store(0, std::memory_order_relaxed);
    }

    ~NumaAwareBatchedMPMCQueue() {
        if (!slots_) return;

        size_t head = head_ticket_.load(std::memory_order_relaxed);
        size_t tail = tail_ticket_.load(std::memory_order_relaxed);

        for (size_t t = head; t < tail; ++t) {
            size_t idx = t & capacity_mask_;
            size_t gen = t / capacity_;
            if (slots_[idx].turn.load(std::memory_order_relaxed) == (2 * gen + 1)) {
                slots_[idx].destroy();
            }
        }

        for (size_t i = 0; i < capacity_; ++i) {
            slots_[i].~Slot<T>();
        }

        detail::numa_aligned_free(slots_, capacity_ * sizeof(Slot<T>));
    }

    // Disable copy & move semantics
    NumaAwareBatchedMPMCQueue(const NumaAwareBatchedMPMCQueue&) = delete;
    NumaAwareBatchedMPMCQueue& operator=(const NumaAwareBatchedMPMCQueue&) = delete;
    NumaAwareBatchedMPMCQueue(NumaAwareBatchedMPMCQueue&&) = delete;
    NumaAwareBatchedMPMCQueue& operator=(NumaAwareBatchedMPMCQueue&&) = delete;

    // Single-element Non-blocking operations
    template <typename... Args>
    bool try_emplace(Args&&... args) noexcept(std::is_nothrow_constructible_v<T, Args...>) {
        size_t ticket = tail_ticket_.load(std::memory_order_relaxed);
        for (;;) {
            size_t idx = ticket & capacity_mask_;
            size_t gen = ticket / capacity_;
            size_t expected_turn = 2 * gen;

            size_t actual_turn = slots_[idx].turn.load(std::memory_order_acquire);

            if (actual_turn == expected_turn) {
                if (tail_ticket_.compare_exchange_weak(ticket, ticket + 1, 
                        std::memory_order_relaxed, std::memory_order_relaxed)) {
                    slots_[idx].construct(std::forward<Args>(args)...);
                    slots_[idx].turn.store(expected_turn + 1, std::memory_order_release);
                    return true;
                }
            } else if (actual_turn < expected_turn) {
                // Queue is full or slot lags behind
                size_t head = head_ticket_.load(std::memory_order_relaxed);
                if (ticket >= head + capacity_) {
                    return false; // Queue Full
                }
                ticket = tail_ticket_.load(std::memory_order_relaxed);
            } else {
                // Ahead ticket race: re-read tail ticket
                ticket = tail_ticket_.load(std::memory_order_relaxed);
            }
        }
    }

    bool try_pop(T& out_value) noexcept(std::is_nothrow_move_assignable_v<T>) {
        size_t ticket = head_ticket_.load(std::memory_order_relaxed);
        for (;;) {
            size_t idx = ticket & capacity_mask_;
            size_t gen = ticket / capacity_;
            size_t expected_turn = 2 * gen + 1;

            size_t actual_turn = slots_[idx].turn.load(std::memory_order_acquire);

            if (actual_turn == expected_turn) {
                if (head_ticket_.compare_exchange_weak(ticket, ticket + 1, 
                        std::memory_order_relaxed, std::memory_order_relaxed)) {
                    out_value = std::move(*slots_[idx].value_ptr());
                    slots_[idx].destroy();
                    slots_[idx].turn.store(expected_turn + 1, std::memory_order_release);
                    return true;
                }
            } else if (actual_turn < expected_turn) {
                size_t tail = tail_ticket_.load(std::memory_order_relaxed);
                if (ticket >= tail) {
                    return false; // Queue Empty
                }
                ticket = head_ticket_.load(std::memory_order_relaxed);
            } else {
                ticket = head_ticket_.load(std::memory_order_relaxed);
            }
        }
    }

    // Zero-copy / Zero-allocation Batched Operations
    template <typename InputIt>
    size_t try_push_batch(InputIt first, size_t count) noexcept {
        if (count == 0) return 0;

        size_t head = head_ticket_.load(std::memory_order_relaxed);
        size_t tail = tail_ticket_.load(std::memory_order_relaxed);

        size_t available_space = 0;
        if (tail < head + capacity_) {
            available_space = capacity_ - (tail - head);
        }

        size_t to_push = (std::min)(count, available_space);
        if (to_push == 0) return 0;

        // Atomically claim a batch of tickets
        size_t base_ticket = tail_ticket_.fetch_add(to_push, std::memory_order_relaxed);

        size_t pushed_count = 0;
        for (size_t i = 0; i < to_push; ++i) {
            size_t ticket = base_ticket + i;
            size_t idx = ticket & capacity_mask_;
            size_t gen = ticket / capacity_;
            size_t expected_turn = 2 * gen;

            // Spin briefly until the specific reserved slot turn is write-ready
            // (Handles preemption of consumers on prior generations)
            while (slots_[idx].turn.load(std::memory_order_acquire) != expected_turn) {
#if defined(__x86_64__) || defined(_M_X64)
                _mm_pause();
#elif defined(__aarch64__)
                asm volatile("yield" ::: "memory");
#endif
            }

            try {
                slots_[idx].construct(*first);
                ++first;
                slots_[idx].turn.store(expected_turn + 1, std::memory_order_release);
                ++pushed_count;
            } catch (...) {
                // Exception mitigation during element construction:
                // Publish uninitialized slot reset turn to prevent slot corruption, then exit.
                slots_[idx].turn.store(expected_turn + 2, std::memory_order_release);
                return pushed_count;
            }
        }
        return pushed_count;
    }

    template <typename OutputIt>
    size_t try_pop_batch(OutputIt d_first, size_t max_count) noexcept {
        if (max_count == 0) return 0;

        size_t head = head_ticket_.load(std::memory_order_relaxed);
        size_t tail = tail_ticket_.load(std::memory_order_relaxed);

        if (head >= tail) return 0;

        size_t available_items = tail - head;
        size_t to_pop = (std::min)(max_count, available_items);
        if (to_pop == 0) return 0;

        // Reserve consumer ticket range
        size_t base_ticket = head_ticket_.fetch_add(to_pop, std::memory_order_relaxed);

        for (size_t i = 0; i < to_pop; ++i) {
            size_t ticket = base_ticket + i;
            size_t idx = ticket & capacity_mask_;
            size_t gen = ticket / capacity_;
            size_t expected_turn = 2 * gen + 1;

            // Wait until slot write has committed
            while (slots_[idx].turn.load(std::memory_order_acquire) != expected_turn) {
#if defined(__x86_64__) || defined(_M_X64)
                _mm_pause();
#elif defined(__aarch64__)
                asm volatile("yield" ::: "memory");
#endif
            }

            *d_first = std::move(*slots_[idx].value_ptr());
            ++d_first;
            slots_[idx].destroy();
            slots_[idx].turn.store(expected_turn + 2, std::memory_order_release);
        }
        return to_pop;
    }

    // Introspection
    [[nodiscard]] size_t size() const noexcept {
        size_t head = head_ticket_.load(std::memory_order_relaxed);
        size_t tail = tail_ticket_.load(std::memory_order_relaxed);
        return (tail > head) ? (tail - head) : 0;
    }

    [[nodiscard]] bool empty() const noexcept {
        return size() == 0;
    }

    [[nodiscard]] size_t capacity() const noexcept {
        return capacity_;
    }

private:
    // Layout designed to prevent False Sharing across NUMA Sockets & Core L1/L2 Cache Lines.
    // 128-byte alignment strictly isolates state variables onto distinct cache lines.

    int numa_node_{-1};
    size_t capacity_;
    size_t capacity_mask_;
    Slot<T>* slots_{nullptr};

    alignas(HardwareCacheLineSize) std::atomic<size_t> tail_ticket_{0};
    alignas(HardwareCacheLineSize) std::atomic<size_t> head_ticket_{0};

    // Padding to ensure boundary separation from adjacent allocations
    uint8_t padding_[HardwareCacheLineSize - (sizeof(std::atomic<size_t>) % HardwareCacheLineSize)];
};

} // namespace ultra_low_latency
```

