#ifndef NUMA_AWARE_BATCHED_MPMC_QUEUE_HPP
#define NUMA_AWARE_BATCHED_MPMC_QUEUE_HPP

#include <atomic>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <new>
#include <memory>
#include <type_traits>
#include <utility>
#include <algorithm>
#include <concepts>
#include <iterator>
#include <tuple>

#if defined(__linux__)
#include <numa.h>
#include <numaif.h>
#include <sys/mman.h>
#include <unistd.h>
