namespace antigravity {

// 128-byte cache line alignment to avoid adjacent-line prefetcher false sharing
inline constexpr size_t kCacheLineAlignment = 128;

#if defined(__cpp_lib_hardware_interference_size)
inline constexpr size_t kDestructiveInterference =
    std::hardware_destructive_interference_size > kCacheLineAlignment
        ? std::hardware_destructive_interference_size
        : kCacheLineAlignment;
#else
inline constexpr size_t kDestructiveInterference = kCacheLineAlignment;
#endif

namespace detail {

[[nodiscard]] constexpr bool is_power_of_two(size_t v) noexcept {
    return v && ((v & (v - 1)) == 0);
}

[[nodiscard]] constexpr size_t round_to_power_of_two(size_t v) noexcept {
    if (v <= 1) return 1;
    --v;
    for (size_t shift = 1; shift < sizeof(size_t) * 8; shift <<= 1) {
        v |= (v >> shift);
    }
    return v + 1;
}

inline void* numa_aligned_alloc(size_t alignment, size_t size, int numa_node) noexcept {
    void* ptr = nullptr;
#if defined(HAS_LIBNUMA)
    if (numa_node >= 0 && numa_available() >= 0) {
        ptr = numa_alloc_onnode(size, numa_node);
        if (ptr) return ptr;
    }
#endif
#if defined(__linux__) && defined(MPOL_BIND)
    if (numa_node >= 0) {
        ptr = ::mmap(nullptr, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (ptr != MAP_FAILED) {
            unsigned long nodemask = (1UL << numa_node);
            ::mbind(ptr, size, MPOL_BIND, &nodemask, sizeof(nodemask) * 8, MPOL_MF_STRICT);
            return ptr;
        }
        ptr = nullptr;
    }
#endif
#if defined(_ISOC11_SOURCE) || (defined(__STDC_VERSION__) && __STDC_VERSION__ >= 201112L)
    ptr = std::aligned_alloc(alignment, (size + alignment - 1) & ~(alignment - 1));
#else
    if (::posix_memalign(&ptr, alignment, size) != 0) {
        ptr = nullptr;
    }
#endif
    return ptr;
}

inline void numa_aligned_free(void* ptr, size_t size [[maybe_unused]], int numa_node [[maybe_unused]]) noexcept {
    if (!ptr) return;
#if defined(HAS_LIBNUMA)
    if (numa_node >= 0 && numa_available() >= 0) {
        numa_free(ptr, size);
        return;
    }
#endif
#if defined(__linux__)
    if (numa_node >= 0) {
        ::munmap(ptr, size);
        return;
    }
#endif
    std::free(ptr);
}

} // namespace detail

template <typename T, size_t Capacity = 0, typename Allocator = std::allocator<T>>
class NumaAwareBatchedMPMCQueue {
    static_assert(std::is_nothrow_destructible_v<T>, "Type T must be nothrow destructible");

private:
    struct alignas(kDestructiveInterference) Slot {
        std::atomic<size_t> turn;
        alignas(alignof(T)) std::byte storage[sizeof(T)];

        [[nodiscard]] T* get_ptr() noexcept {
            return reinterpret_cast<T*>(storage);
        }

        [[nodiscard]] const T* get_ptr() const noexcept {
            return reinterpret_cast<const T*>(storage);
        }
    };

    // Dedicated cache line for enqueue cursor
    alignas(kDestructiveInterference) std::atomic<size_t> enqueue_pos_{0};

    // Dedicated cache line for dequeue cursor
    alignas(kDestructiveInterference) std::atomic<size_t> dequeue_pos_{0};

    // Dedicated cache line for read-only invariants & buffer pointer
    alignas(kDestructiveInterference) Slot* buffer_{nullptr};
    size_t capacity_{0};
    size_t mask_{0};
    int numa_node_{-1};
    size_t allocated_bytes_{0};

public:
    explicit NumaAwareBatchedMPMCQueue(size_t dynamic_capacity = Capacity, int numa_node = -1)
        : numa_node_(numa_node) {
        size_t cap = (Capacity > 0) ? Capacity : dynamic_capacity;
        assert(cap >= 2 && "Capacity must be at least 2");

        capacity_ = detail::is_power_of_two(cap) ? cap : detail::round_to_power_of_two(cap);
        mask_ = capacity_ - 1;
        allocated_bytes_ = capacity_ * sizeof(Slot);

        void* raw_mem = detail::numa_aligned_alloc(kDestructiveInterference, allocated_bytes_, numa_node_);
        if (!raw_mem) {
            throw std::bad_alloc();
        }

        buffer_ = static_cast<Slot*>(raw_mem);

        for (size_t i = 0; i < capacity_; ++i) {
            ::new (static_cast<void*>(&buffer_[i].turn)) std::atomic<size_t>(i);
        }
    }

    ~NumaAwareBatchedMPMCQueue() {
        if (!buffer_) return;

        // Drain any remaining active instances
        T discarded;
        while (try_pop(discarded)) {}

        for (size_t i = 0; i < capacity_; ++i) {
            buffer_[i].turn.~atomic();
        }

        detail::numa_aligned_free(buffer_, allocated_bytes_, numa_node_);
    }

    NumaAwareBatchedMPMCQueue(const NumaAwareBatchedMPMCQueue&) = delete;
    NumaAwareBatchedMPMCQueue& operator=(const NumaAwareBatchedMPMCQueue&) = delete;
    NumaAwareBatchedMPMCQueue(NumaAwareBatchedMPMCQueue&&) = delete;
    NumaAwareBatchedMPMCQueue& operator=(NumaAwareBatchedMPMCQueue&&) = delete;

    template <typename... Args>
    bool try_emplace(Args&&... args) noexcept {
        size_t pos = enqueue_pos_.load(std::memory_order_relaxed);

        while (true) {
            Slot& slot = buffer_[pos & mask_];
            const size_t turn = slot.turn.load(std::memory_order_acquire);
            const intptr_t diff = static_cast<intptr_t>(turn) - static_cast<intptr_t>(pos);

            if (diff == 0) {
                // Slot is ready for our turn; claim ticket pos
                if (enqueue_pos_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed, std::memory_order_relaxed)) {
                    // Safe in-place construction inside reserved slot
                    std::construct_at(slot.get_ptr(), std::forward<Args>(args)...);
                    slot.turn.store(pos + 1, std::memory_order_release);
                    return true;
                }
            } else if (diff < 0) {
                // Buffer is full (turn belongs to a previous epoch)
                const size_t dpos = dequeue_pos_.load(std::memory_order_relaxed);
                if (pos >= dpos + capacity_) {
                    return false;
                }
                pos = enqueue_pos_.load(std::memory_order_relaxed);
            } else {
                // Ticket pos already taken by another producer; update pos
                pos = enqueue_pos_.load(std::memory_order_relaxed);
            }
        }
    }

    bool try_pop(T& out_value) noexcept {
        size_t pos = dequeue_pos_.load(std::memory_order_relaxed);

        while (true) {
            Slot& slot = buffer_[pos & mask_];
            const size_t turn = slot.turn.load(std::memory_order_acquire);
            const intptr_t diff = static_cast<intptr_t>(turn) - static_cast<intptr_t>(pos + 1);

            if (diff == 0) {
                // Slot contains item ready for consumption; claim ticket pos
                if (dequeue_pos_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed, std::memory_order_relaxed)) {
                    out_value = std::move(*slot.get_ptr());
                    std::destroy_at(slot.get_ptr());
                    slot.turn.store(pos + capacity_, std::memory_order_release);
                    return true;
                }
            } else if (diff < 0) {
                // Buffer is empty
                const size_t epos = enqueue_pos_.load(std::memory_order_relaxed);
                if (pos >= epos) {
                    return false;
                }
                pos = dequeue_pos_.load(std::memory_order_relaxed);
            } else {
                // Ticket pos already taken by another consumer; update pos
                pos = dequeue_pos_.load(std::memory_order_relaxed);
            }
        }
    }

    template <typename InputIt>
    size_t try_push_batch(InputIt first, size_t count) noexcept {
        if (count == 0) return 0;

        size_t curr_enqueue = enqueue_pos_.load(std::memory_order_relaxed);
        size_t reserved_count = 0;
        size_t start_ticket = 0;

        // Bounded CAS reservation loop: reserves a continuous sub-batch [start_ticket, start_ticket + reserved_count)
        while (true) {
            const size_t curr_dequeue = dequeue_pos_.load(std::memory_order_relaxed);
            const size_t occupied = curr_enqueue - curr_dequeue;

            if (occupied >= capacity_) {
                return 0; // Buffer full
            }

            const size_t available = capacity_ - occupied;
            reserved_count = (count < available) ? count : available;
            start_ticket = curr_enqueue;

            if (enqueue_pos_.compare_exchange_weak(
                    curr_enqueue, curr_enqueue + reserved_count,
                    std::memory_order_relaxed, std::memory_order_relaxed)) {
                break; // Contiguous ticket block successfully acquired
            }
        }

        // Commit phase: construct objects into reserved slots
        for (size_t i = 0; i < reserved_count; ++i) {
            const size_t ticket = start_ticket + i;
            Slot& slot = buffer_[ticket & mask_];

            // Wait until previous epoch consumer releases the slot
            while (slot.turn.load(std::memory_order_acquire) != ticket) {
#if defined(__x86_64__) || defined(_M_X64)
                __builtin_ia32_pause();
#elif defined(__aarch64__)
                asm volatile("yield" ::: "memory");
#endif
            }

            if constexpr (std::is_nothrow_move_constructible_v<T> || std::is_nothrow_copy_constructible_v<T>) {
                std::construct_at(slot.get_ptr(), *first);
            } else {
                try {
                    std::construct_at(slot.get_ptr(), *first);
                } catch (...) {
                    // Poison slot state to unblock consumers and avoid queue stalls
                    slot.turn.store(ticket + 1, std::memory_order_release);
                    return i;
                }
            }

            ++first;
            slot.turn.store(ticket + 1, std::memory_order_release);
        }

        return reserved_count;
    }

    template <typename OutputIt>
    size_t try_pop_batch(OutputIt d_first, size_t max_count) noexcept {
        if (max_count == 0) return 0;

        size_t curr_dequeue = dequeue_pos_.load(std::memory_order_relaxed);
        size_t reserved_count = 0;
        size_t start_ticket = 0;

        // Bounded CAS reservation loop: reserves a continuous sub-batch [start_ticket, start_ticket + reserved_count)
        while (true) {
            const size_t curr_enqueue = enqueue_pos_.load(std::memory_order_relaxed);
            if (curr_dequeue >= curr_enqueue) {
                return 0; // Buffer empty
            }

            const size_t available = curr_enqueue - curr_dequeue;
            reserved_count = (max_count < available) ? max_count : available;
            start_ticket = curr_dequeue;

            if (dequeue_pos_.compare_exchange_weak(
                    curr_dequeue, curr_dequeue + reserved_count,
                    std::memory_order_relaxed, std::memory_order_relaxed)) {
                break; // Contiguous ticket block successfully acquired
            }
        }

        // Commit phase: extract elements and recycle slots
        for (size_t i = 0; i < reserved_count; ++i) {
            const size_t ticket = start_ticket + i;
            Slot& slot = buffer_[ticket & mask_];

            // Wait until the producer publishes the item
            while (slot.turn.load(std::memory_order_acquire) != (ticket + 1)) {
#if defined(__x86_64__) || defined(_M_X64)
                __builtin_ia32_pause();
#elif defined(__aarch64__)
                asm volatile("yield" ::: "memory");
#endif
            }

            *d_first = std::move(*slot.get_ptr());
            ++d_first;
            std::destroy_at(slot.get_ptr());
            slot.turn.store(ticket + capacity_, std::memory_order_release);
        }

        return reserved_count;
    }

    [[nodiscard]] size_t size() const noexcept {
        const size_t c = dequeue_pos_.load(std::memory_order_relaxed);
        const size_t p = enqueue_pos_.load(std::memory_order_relaxed);
        return (p >= c) ? (p - c) : 0;
    }

    [[nodiscard]] bool empty() const noexcept {
        return size() == 0;
    }

    [[nodiscard]] size_t capacity() const noexcept {
        return capacity_;
    }
};

} // namespace antigravity
```

---

### 3. Performance Trade-Off & Edge Case Analysis

#### 3.1 Handling Thread Preemption Mid-Batch & Stall Mitigation
When Producer $T_1$ reserves a batch of tickets $[K, K+B-1]$ and is preempted by the OS scheduler:
1. **Isolation of Successive Producers:** Producer $T_2$, arriving later, reserves tickets $[K+B, K+2B-1]$. $T_2$ writes to physical slots $(K+B) \pmod N \dots (K+2B-1) \pmod N$. Since $T_2$'s physical slots do not overlap with $T_1$'s slots (as long as total in-flight items $< N$), $T_2$ constructs and publishes its items without stalling.
2. **Consumer Decoupling:** Consumers processing tickets prior to $K$ proceed at line rate. Once a consumer reaches slot $K$, it observes `turn.load(acquire) == K` (instead of $K+1$). The consumer executes hardware spin-pause (`_mm_pause` / `yield`) while waiting for $T_1$ to wake up and publish.
3. **Recovery Strategy:** 
   - Strict ticket reservation prevents race conditions or duplicated writes.
   - For high-priority matching engines, thread pinning (`pthread_setaffinity_np`) to isolated cores (`isolcpus`, `nohz_full`) eliminates preemption stalls entirely.

```
 Producer T1 (Preempted): [Slot K] (Writing stalled...)
 Producer T2 (Active):    [Slot K+1] (Finished & Published) ──► turn = K+2
 Producer T3 (Active):    [Slot K+2] (Finished & Published) ──► turn = K+3

 Consumer stream: Reads up to K-1 -> Waits on Slot K -> Once T1 commits, consumes K, K+1, K+2 seamlessly.
```

---

#### 3.2 Cache-Line Transfer Overhead: Vyukov Single-Ticket vs. Batched Reservation

```
Vyukov Single-Ticket Contention (P Producers):
Each element write requires 1 atomic fetch_add on enqueue_pos_
=> P invalidations across interconnect per P elements.

Batched Ticket Reservation (Batch Size = B):
B elements reserved in 1 atomic CAS/fetch_add on enqueue_pos_
=> 1 invalidation per B elements (Interconnect traffic reduced by factor of B).
```

Let $P$ be the number of concurrent producers, $C$ the number of consumers, and $B$ the batch size.

| Dimension | Classical Vyukov MPMC Queue | Batched Ticket MPMC Queue | Architectural Impact |
| :--- | :--- | :--- | :--- |
| **Global Ticket Invalidation Rate** | $O(M)$ cache-line invalidation broadcasts for $M$ elements | $O(M / B)$ cache-line invalidation broadcasts | **$B\times$ reduction** in MESI/MOESI bus invalidation traffic on `enqueue_pos_`. |
| **L3 Miss Latency per Item** | $\sim 40\text{--}65\text{ ns}$ per single item (socket cross-traffic) | $\sim 40\text{--}65\text{ ns}$ amortized over $B$ items ($\approx \frac{40}{B}\text{ ns/item}$) | Amortizes cross-CCX and cross-socket interconnect latencies. |
| **Slot Contention (`turn` flags)** | Dedicated slot per ticket; no false sharing if aligned to 128B. | Dedicated slot per ticket; contiguous stream improves hardware spatial prefetcher. | Streaming access allows L2/L1 hardware stream prefetchers to fetch upcoming slot lines. |
| **Cross-Socket NUMA Penalty** | Up to $\approx 180\text{ ns}$ when buffer memory traverses UPI / Infinity Fabric. | Near-zero cross-socket penalty when allocated via `numa_alloc_onnode` on consumer socket. | Eliminates remote memory controller round-trips for local consumers. |

