inline constexpr size_t MAX_NUMA_NODES  = 8;
inline constexpr size_t MAX_CORES_PER_NODE = 64;
inline constexpr size_t MAX_TOTAL_WORKERS = MAX_NUMA_NODES * MAX_CORES_PER_NODE;
inline constexpr size_t NUM_PRIORITY_TIERS = 3;

