enum class TaskState : uint32_t {
    READY       = 0,
    EXECUTING   = 1,
    COMPLETED   = 2,
    CANCELLED   = 3
};

struct alignas(CACHE_LINE_SIZE) TaskDescriptor {
    TaskId id;
    Priority priority;
    std::atomic<TaskState> state;
    void (*execute_fn)(void* payload);
    alignas(16) uint8_t payload_storage[64];

    TaskDescriptor() noexcept 
        : id(0), priority(Priority::Normal), state(TaskState::READY), execute_fn(nullptr) {
        std::memset(payload_storage, 0, sizeof(payload_storage));
    }

    void reset(TaskId tid, Priority prio, void (*fn)(void*), const void* data, size_t data_len) noexcept {
        id = tid;
        priority = prio;
        state.store(TaskState::READY, std::memory_order_relaxed);
        execute_fn = fn;
        if (data && data_len > 0) {
            size_t copy_size = (data_len > sizeof(payload_storage)) ? sizeof(payload_storage) : data_len;
            std::memcpy(payload_storage, data, copy_size);
        }
    }
};

struct alignas(16) TaggedTaskPtr {
    TaskDescriptor* ptr{nullptr};
    uint64_t tag{0};

    constexpr bool operator==(const TaggedTaskPtr& other) const noexcept {
        return ptr == other.ptr && tag == other.tag;
    }
    constexpr bool operator!=(const TaggedTaskPtr& other) const noexcept {
        return !(*this == other);
    }
