// ============================================================================
// 3-STATE EPOCH-BASED MEMORY RECLAMATION (EBMR)
// ============================================================================
inline constexpr uint64_t EPOCH_INACTIVE = std::numeric_limits<uint64_t>::max();
inline constexpr size_t QUARANTINE_CAPACITY = 1024;

class EpochManager;

struct alignas(CACHE_LINE_SIZE) ThreadRegistrationToken {
    std::atomic<uint64_t> active_epoch{EPOCH_INACTIVE};
    size_t worker_id{0};
    size_t numa_node{0};
    size_t core_id{0};

    // Thread-local quarantine buffers for Epochs 0, 1, 2
    std::array<std::array<TaskDescriptor*, QUARANTINE_CAPACITY>, 3> retire_rings{};
    std::array<size_t, 3> retire_counts{0, 0, 0};
};

class EpochManager {
public:
    static EpochManager& instance() {
        static EpochManager inst;
        return inst;
    }

    EpochManager() noexcept : global_epoch_(0), registered_count_(0) {
        for (size_t i = 0; i < MAX_TOTAL_WORKERS; ++i) {
            tokens_[i] = nullptr;
        }
    }

    void register_thread(ThreadRegistrationToken& token, size_t worker_id, size_t numa, size_t core) noexcept {
        token.worker_id = worker_id;
        token.numa_node = numa;
        token.core_id = core;
        token.active_epoch.store(EPOCH_INACTIVE, std::memory_order_relaxed);
        tokens_[worker_id] = &token;
        registered_count_.fetch_add(1, std::memory_order_release);
    }

    void unregister_thread(ThreadRegistrationToken& token) noexcept {
        token.active_epoch.store(EPOCH_INACTIVE, std::memory_order_release);
        tokens_[token.worker_id] = nullptr;
        registered_count_.fetch_sub(1, std::memory_order_release);
    }

    inline void enter_critical(ThreadRegistrationToken& token) noexcept {
