        token.active_epoch.store(ge, std::memory_order_release);
    }

    inline void exit_critical(ThreadRegistrationToken& token) noexcept {
        token.active_epoch.store(EPOCH_INACTIVE, std::memory_order_release);
    }

    void retire(ThreadRegistrationToken& token, TaskDescriptor* desc) noexcept {
        if (!desc) return;
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t idx = cur_epoch % 3;
        size_t& count = token.retire_counts[idx];

        if (count < QUARANTINE_CAPACITY) {
            token.retire_rings[idx][count++] = desc;
        } else {
            // Buffer full, force epoch progression & reclaim
            try_advance_and_reclaim(token);
            idx = global_epoch_.load(std::memory_order_relaxed) % 3;
            size_t& new_count = token.retire_counts[idx];
            if (new_count < QUARANTINE_CAPACITY) {
                token.retire_rings[idx][new_count++] = desc;
            } else {
                // Extreme fallback: directly free node if reclamation did not free slot
                free_descriptor(desc);
            }
        }
    }

    void try_advance_and_reclaim(ThreadRegistrationToken& token) noexcept {
        uint64_t current_g = global_epoch_.load(std::memory_order_relaxed);

        // Check if all active workers have observed the current epoch
        bool can_advance = true;
        size_t total = registered_count_.load(std::memory_order_acquire);
        for (size_t i = 0; i < total; ++i) {
            auto* t = tokens_[i];
            if (!t) continue;
            uint64_t th_epoch = t->active_epoch.load(std::memory_order_acquire);
            if (th_epoch != EPOCH_INACTIVE && th_epoch < current_g) {
                can_advance = false;
                break;
            }
        }

        if (can_advance) {
            if (global_epoch_.compare_exchange_strong(current_g, current_g + 1, std::memory_order_acq_rel)) {
                // Epoch successfully incremented. Nodes retired in (current_g - 1) are safe to destroy.
                uint64_t safe_epoch = (current_g + 1) % 3; // Epoch to drain
                size_t& count = token.retire_counts[safe_epoch];
                for (size_t i = 0; i < count; ++i) {
                    free_descriptor(token.retire_rings[safe_epoch][i]);
                    token.retire_rings[safe_epoch][i] = nullptr;
                }
                count = 0;
            }
        }
    }

private:
    void free_descriptor(TaskDescriptor* desc) noexcept {
        delete desc;
    }

    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> global_epoch_{0};
    alignas(CACHE_LINE_SIZE) std::atomic<size_t> registered_count_{0};
    alignas(CACHE_LINE_SIZE) std::array<ThreadRegistrationToken*, MAX_TOTAL_WORKERS> tokens_{};
};

// RAII Guard for Epoch Critical Section
struct EpochGuard {
    ThreadRegistrationToken& token;
    explicit EpochGuard(ThreadRegistrationToken& tok) noexcept : token(tok) {
        EpochManager::instance().enter_critical(token);
    }
    ~EpochGuard() noexcept {
        EpochManager::instance().exit_critical(token);
    }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
};

// ============================================================================
// SINGLE PRIORITY RING BUFFER (Bounded Lock-Free Chase-Lev with Batches)
// ============================================================================
template <size_t Capacity>
class BoundedPriorityLane {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of two.");
    static constexpr size_t Mask = Capacity - 1;

public:
    BoundedPriorityLane() noexcept : head_(0), tail_(0) {
        for (size_t i = 0; i < Capacity; ++i) {
            slots_[i].store(TaggedTaskPtr{nullptr, 0}, std::memory_order_relaxed);
        }
    }

    ~BoundedPriorityLane() = default;

    bool push(TaskDescriptor* desc) noexcept {
        uint64_t t = tail_.load(std::memory_order_relaxed);
        uint64_t h = head_.load(std::memory_order_acquire);

        if (static_cast<int64_t>(t - h) >= static_cast<int64_t>(Capacity)) {
            return false; // Ring buffer full
        }

        TaggedTaskPtr item{desc, t};
        slots_[t & Mask].store(item, std::memory_order_relaxed);
        tail_.store(t + 1, std::memory_order_release);
        return true;
    }

    size_t push_batch(std::span<TaskDescriptor*> batch) noexcept {
        if (batch.empty()) return 0;
        uint64_t t = tail_.load(std::memory_order_relaxed);
        uint64_t h = head_.load(std::memory_order_acquire);

        size_t available = (static_cast<int64_t>(t - h) >= static_cast<int64_t>(Capacity)) 
                         ? 0 
                         : Capacity - static_cast<size_t>(t - h);
        size_t count = std::min(available, batch.size());
        if (count == 0) return 0;

        for (size_t i = 0; i < count; ++i) {
            TaggedTaskPtr item{batch[i], t + i};
            slots_[(t + i) & Mask].store(item, std::memory_order_relaxed);
        }
        tail_.store(t + count, std::memory_order_release);
        return count;
    }

    TaskDescriptor* pop() noexcept {
        uint64_t t = tail_.load(std::memory_order_relaxed);
        if (t == 0) return nullptr;
        t--;
        tail_.store(t, std::memory_order_relaxed);

        std::atomic_thread_fence(std::memory_order_seq_cst);
        uint64_t h = head_.load(std::memory_order_acquire);

        if (static_cast<int64_t>(t) >= static_cast<int64_t>(h)) {
            // Task is available
            TaggedTaskPtr item = slots_[t & Mask].load(std::memory_order_relaxed);
            if (t == h) {
                // Race against concurrent stealer on the last item
                TaggedTaskPtr empty{nullptr, 0};
                if (!head_.compare_exchange_strong(h, h + 1, std::memory_order_acq_rel, std::memory_order_acquire)) {
                    item.ptr = nullptr; // Stealer won
                }
                tail_.store(h + 1, std::memory_order_relaxed);
            }
            return item.ptr;
        } else {
            // Empty queue
            tail_.store(h, std::memory_order_relaxed);
            return nullptr;
        }
    }

    size_t steal_batch(TaskDescriptor** dest, size_t max_count) noexcept {
        while (true) {
            uint64_t h = head_.load(std::memory_order_acquire);
            std::atomic_thread_fence(std::memory_order_seq_cst);
            uint64_t t = tail_.load(std::memory_order_acquire);

            if (static_cast<int64_t>(h) >= static_cast<int64_t>(t)) {
                return 0; // Empty lane
            }

            size_t available = static_cast<size_t>(t - h);
            size_t steal_count = std::min(max_count, available);
            if (steal_count == 0) return 0;

            // Attempt atomic claim on the head range [h, h + steal_count)
            if (head_.compare_exchange_weak(h, h + steal_count, 
                                            std::memory_order_acq_rel, 
                                            std::memory_order_acquire)) {
                for (size_t i = 0; i < steal_count; ++i) {
                    TaggedTaskPtr item = slots_[(h + i) & Mask].load(std::memory_order_relaxed);
                    dest[i] = item.ptr;
                }
                return steal_count;
            }
            HARDWARE_PAUSE();
        }
    }

    bool cancel(TaskId id, ThreadRegistrationToken& token) noexcept {
        // Iterate through active elements in the ring
        uint64_t h = head_.load(std::memory_order_acquire);
        uint64_t t = tail_.load(std::memory_order_acquire);

        for (uint64_t i = h; i < t; ++i) {
            TaggedTaskPtr item = slots_[i & Mask].load(std::memory_order_relaxed);
            if (item.ptr && item.ptr->id == id) {
                TaskState expected = TaskState::READY;
                if (item.ptr->state.compare_exchange_strong(expected, TaskState::CANCELLED, 
                                                             std::memory_order_acq_rel)) {
                    EpochManager::instance().retire(token, item.ptr);
                    return true;
                }
            }
        }
        return false;
    }

private:
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> head_{0};
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> tail_{0};
    alignas(CACHE_LINE_SIZE) std::array<std::atomic<TaggedTaskPtr>, Capacity> slots_{};
};

