template <size_t LaneCapacity>
class NUMAWorkStealingPriorityDeque {
public:
    NUMAWorkStealingPriorityDeque(size_t worker_id, size_t numa_node, size_t core_id)
        : worker_id_(worker_id), numa_node_(numa_node), core_id_(core_id), rng_state_(1337 + worker_id * 71) {
        EpochManager::instance().register_thread(token_, worker_id, numa_node, core_id);
        TopologyDirectory::instance().register_worker(worker_id, numa_node, core_id, this);
    }

    ~NUMAWorkStealingPriorityDeque() {
        EpochManager::instance().unregister_thread(token_);
    }

    // PUSH LOCAL (LIFO)
    bool push_local(TaskId id, Priority prio, void (*fn)(void*), const void* data, size_t len) noexcept {
        EpochGuard guard(token_);
        auto* desc = new (std::nothrow) TaskDescriptor();
        if (!desc) return false;
        desc->reset(id, prio, fn, data, len);

        size_t lane_idx = static_cast<size_t>(prio);
        if (!lanes_[lane_idx].push(desc)) {
            delete desc;
            return false;
        }
        return true;
    }

    // PUSH BATCH LOCAL
    size_t push_batch(std::span<TaskDescriptor*> batch, Priority prio) noexcept {
        EpochGuard guard(token_);
        size_t lane_idx = static_cast<size_t>(prio);
        return lanes_[lane_idx].push_batch(batch);
    }

    // POP LOCAL (LIFO, Strict Priority Order: Critical -> Normal -> Speculative)
    std::optional<TaskDescriptor*> pop_local() noexcept {
        EpochGuard guard(token_);
        for (size_t p = 0; p < NUM_PRIORITY_TIERS; ++p) {
            while (TaskDescriptor* desc = lanes_[p].pop()) {
                TaskState expected = TaskState::READY;
                if (desc->state.compare_exchange_strong(expected, TaskState::EXECUTING, 
                                                         std::memory_order_acq_rel)) {
                    return desc;
                }
                // If task was CANCELLED, retire and advance
                EpochManager::instance().retire(token_, desc);
            }
        }
        return std::nullopt;
    }

    // STEAL REMOTE (FIFO, Hierarchical NUMA Stealing)
    size_t steal_batch(TaskDescriptor** dest, size_t max_count, Priority min_prio = Priority::Speculative) noexcept {
        EpochGuard guard(token_);
        size_t target_max_prio = static_cast<size_t>(min_prio);

        // Step 1: Intra-Core SMT Siblings
        size_t stolen = try_steal_domain(dest, max_count, target_max_prio, LocalityDomain::SMT);
        if (stolen > 0) return stolen;

        // Step 2: Intra-Socket NUMA Siblings
        stolen = try_steal_domain(dest, max_count, target_max_prio, LocalityDomain::NUMA_Local);
        if (stolen > 0) return stolen;

        // Step 3: Remote NUMA Sockets
        stolen = try_steal_domain(dest, max_count, target_max_prio, LocalityDomain::NUMA_Remote);
        return stolen;
    }

    // SPECULATIVE TASK CANCELLATION
    bool cancel_task(TaskId id) noexcept {
        EpochGuard guard(token_);
        // Search across all priority lanes (speculative lanes first)
        for (int p = static_cast<int>(NUM_PRIORITY_TIERS) - 1; p >= 0; --p) {
            if (lanes_[p].cancel(id, token_)) {
                return true;
            }
        }
        return false;
    }

    void advance_epoch_and_reclaim() noexcept {
        EpochManager::instance().try_advance_and_reclaim(token_);
    }

    ThreadRegistrationToken& get_token() noexcept {
        return token_;
    }

private:
    enum class LocalityDomain {
        SMT,
        NUMA_Local,
        NUMA_Remote
    };

    uint32_t fast_rand() noexcept {
        rng_state_ ^= rng_state_ << 13;
        rng_state_ ^= rng_state_ >> 17;
        rng_state_ ^= rng_state_ << 5;
        return rng_state_;
    }

    size_t try_steal_domain(TaskDescriptor** dest, size_t max_count, size_t max_prio, LocalityDomain domain) noexcept {
        // Build candidate list based on locality domain
        std::array<size_t, MAX_TOTAL_WORKERS> candidates{};
        size_t cand_count = 0;

        for (size_t i = 0; i < MAX_TOTAL_WORKERS; ++i) {
            if (i == worker_id_) continue;
            auto* q = static_cast<NUMAWorkStealingPriorityDeque<LaneCapacity>*>(TopologyDirectory::instance().get_queue(i));
            if (!q) continue;

            const auto& aff = TopologyDirectory::instance().get_affinity(i);
            bool match = false;
            switch (domain) {
                case LocalityDomain::SMT:
                    match = (aff.numa_node == numa_node_ && aff.core_id == core_id_);
                    break;
                case LocalityDomain::NUMA_Local:
                    match = (aff.numa_node == numa_node_ && aff.core_id != core_id_);
                    break;
                case LocalityDomain::NUMA_Remote:
                    match = (aff.numa_node != numa_node_);
                    break;
            }
            if (match) {
                candidates[cand_count++] = i;
            }
        }

        if (cand_count == 0) return 0;

        // Randomized victim selection to minimize lockstep contention
        size_t start_idx = fast_rand() % cand_count;
        for (size_t c = 0; c < cand_count; ++c) {
            size_t victim_id = candidates[(start_idx + c) % cand_count];
            auto* victim_queue = static_cast<NUMAWorkStealingPriorityDeque<LaneCapacity>*>(TopologyDirectory::instance().get_queue(victim_id));

            for (size_t p = 0; p <= max_prio; ++p) {
                size_t stolen = victim_queue->lanes_[p].steal_batch(dest, max_count);
                if (stolen > 0) {
                    // Filter out cancelled tasks during steal
                    size_t valid_count = 0;
                    for (size_t s = 0; s < stolen; ++s) {
                        TaskDescriptor* desc = dest[s];
                        TaskState expected = TaskState::READY;
                        if (desc && desc->state.compare_exchange_strong(expected, TaskState::EXECUTING, 
                                                                         std::memory_order_acq_rel)) {
                            dest[valid_count++] = desc;
                        } else if (desc) {
                            EpochManager::instance().retire(token_, desc);
                        }
                    }
                    if (valid_count > 0) {
                        return valid_count;
                    }
                }
            }
        }
        return 0;
    }

    alignas(CACHE_LINE_SIZE) size_t worker_id_;
    alignas(CACHE_LINE_SIZE) size_t numa_node_;
    alignas(CACHE_LINE_SIZE) size_t core_id_;
    alignas(CACHE_LINE_SIZE) uint32_t rng_state_;
    alignas(CACHE_LINE_SIZE) ThreadRegistrationToken token_{};
    alignas(CACHE_LINE_SIZE) std::array<BoundedPriorityLane<LaneCapacity>, NUM_PRIORITY_TIERS> lanes_{};
};

