    EpochManager() : global_epoch_(0) {
        for (size_t i = 0; i < MAX_SYSTEM_THREADS; ++i) {
            tcbs_[i].active_epoch.store(INACTIVE, std::memory_order_relaxed);
            tcbs_[i].is_registered.store(false, std::memory_order_relaxed);
        }
    }

    static EpochManager& instance() {
        static EpochManager mgr;
        return mgr;
    }

    size_t register_thread() {
        for (size_t i = 0; i < MAX_SYSTEM_THREADS; ++i) {
            bool expected = false;
            if (tcbs_[i].is_registered.compare_exchange_strong(expected, true, 
                    std::memory_order_acq_rel, std::memory_order_relaxed)) {
                return i;
            }
        }
        return SIZE_MAX;
    }

    void unregister_thread(size_t thread_id) {
        if (thread_id < MAX_SYSTEM_THREADS) {
            tcbs_[thread_id].active_epoch.store(INACTIVE, std::memory_order_release);
            tcbs_[thread_id].is_registered.store(false, std::memory_order_release);
        }
    }

    void enter_epoch(size_t thread_id) noexcept {
        const uint64_t current = global_epoch_.load(std::memory_order_acquire);
        tcbs_[thread_id].active_epoch.store(current, std::memory_order_release);
    }

    void exit_epoch(size_t thread_id) noexcept {
        tcbs_[thread_id].active_epoch.store(INACTIVE, std::memory_order_release);
    }

    void retire(size_t thread_id, void* ptr, void (*deleter)(void*)) {
        if (!ptr || !deleter) return;
        auto& q = quarantine_[thread_id];
        const uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);

        if (q.count >= MAX_RETIRE_CAPACITY) {
            reclaim_quarantine(thread_id);
        }

        q.ring[q.tail] = RetiredNode{.ptr = ptr, .deleter = deleter, .epoch = cur_epoch};
        q.tail = (q.tail + 1) % MAX_RETIRE_CAPACITY;
        q.count++;
    }

    void try_advance_and_reclaim(size_t thread_id) {
        try_advance_global_epoch();
        reclaim_quarantine(thread_id);
    }

private:
    bool try_advance_global_epoch() {
        const uint64_t cur = global_epoch_.load(std::memory_order_acquire);

        for (size_t i = 0; i < MAX_SYSTEM_THREADS; ++i) {
            if (!tcbs_[i].is_registered.load(std::memory_order_relaxed)) {
                continue;
            }
            const uint64_t thread_epoch = tcbs_[i].active_epoch.load(std::memory_order_acquire);
            if (thread_epoch != INACTIVE && thread_epoch < cur) {
                return false;
            }
        }

        return global_epoch_.compare_exchange_strong(
            const_cast<uint64_t&>(cur), cur + 1, std::memory_order_acq_rel, std::memory_order_relaxed
        );
    }

    void reclaim_quarantine(size_t thread_id) {
        auto& q = quarantine_[thread_id];
        if (q.count == 0) return;

        uint64_t min_active = global_epoch_.load(std::memory_order_acquire);
        for (size_t i = 0; i < MAX_SYSTEM_THREADS; ++i) {
            if (!tcbs_[i].is_registered.load(std::memory_order_relaxed)) continue;
            const uint64_t thread_ep = tcbs_[i].active_epoch.load(std::memory_order_acquire);
            if (thread_ep != INACTIVE && thread_ep < min_active) {
                min_active = thread_ep;
            }
        }

        size_t processed = 0;
        const size_t initial_count = q.count;

        while (processed < initial_count) {
            RetiredNode& node = q.ring[q.head];
            if (node.epoch < min_active) {
                node.deleter(node.ptr);
                node.ptr = nullptr;
                node.deleter = nullptr;
                q.head = (q.head + 1) % MAX_RETIRE_CAPACITY;
                q.count--;
                processed++;
            } else {
                break;
            }
        }
    }

    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> global_epoch_;
    alignas(CACHE_LINE_SIZE) std::array<ThreadControlBlock, MAX_SYSTEM_THREADS> tcbs_;
    alignas(CACHE_LINE_SIZE) std::array<QuarantineBuffer, MAX_SYSTEM_THREADS> quarantine_;
};

class ThreadRegistrationToken {
public:
    ThreadRegistrationToken() {
        thread_id_ = EpochManager::instance().register_thread();
    }

    ~ThreadRegistrationToken() {
        if (thread_id_ != SIZE_MAX) {
            EpochManager::instance().unregister_thread(thread_id_);
        }
    }

    ThreadRegistrationToken(const ThreadRegistrationToken&) = delete;
    ThreadRegistrationToken& operator=(const ThreadRegistrationToken&) = delete;
    ThreadRegistrationToken(ThreadRegistrationToken&& o) noexcept : thread_id_(o.thread_id_) {
        o.thread_id_ = SIZE_MAX;
    }

    size_t id() const noexcept { return thread_id_; }
    bool is_valid() const noexcept { return thread_id_ != SIZE_MAX; }

private:
    size_t thread_id_{SIZE_MAX};
};

struct EpochGuard {
    size_t tid;
    explicit EpochGuard(size_t thread_id) noexcept : tid(thread_id) {
        EpochManager::instance().enter_epoch(tid);
    }
    ~EpochGuard() noexcept {
        EpochManager::instance().exit_epoch(tid);
    }
};

// ============================================================================
// MULTI-LANE LOCK-FREE PRIORITY RING DEQUE
// Stratified Priority Rings with LIFO Local & FIFO Remote Stealing Semantics
// ============================================================================
template <typename T, size_t CapacityPerLane = 4096>
class SinglePriorityLaneRing {
    static_assert((CapacityPerLane & (CapacityPerLane - 1)) == 0, "Capacity must be power of 2");
    static constexpr size_t MASK = CapacityPerLane - 1;

public:
    struct Slot {
        alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> header{0};
        T payload{};
    };

    SinglePriorityLaneRing() : top_(0), bottom_(0) {
        for (size_t i = 0; i < CapacityPerLane; ++i) {
            SlotHeader initial{
                .generation = 0,
                .state = TaskSlotState::EMPTY,
                .priority = Priority::Normal
            };
            buffer_[i].header.store(initial.to_u64(), std::memory_order_relaxed);
        }
    }

    bool push_local(const T& item, Priority prio, TaskId id) noexcept {
        int64_t b = bottom_.load(std::memory_order_relaxed);
        int64_t t = top_.load(std::memory_order_acquire);

        if (b - t >= static_cast<int64_t>(CapacityPerLane)) {
            return false; // Ring buffer saturated
        }

        const size_t slot_idx = static_cast<size_t>(b) & MASK;
        Slot& slot = buffer_[slot_idx];

        uint64_t cur_hdr_raw = slot.header.load(std::memory_order_relaxed);
        SlotHeader cur_hdr = SlotHeader::from_u64(cur_hdr_raw);

        slot.payload = item;
        slot.payload.id = id;
        slot.payload.priority = prio;

        SlotHeader new_hdr{
            .generation = cur_hdr.generation + 1,
            .state = TaskSlotState::COMMITTED,
            .priority = prio
        };

        slot.header.store(new_hdr.to_u64(), std::memory_order_release);
        bottom_.store(b + 1, std::memory_order_release);
        return true;
    }

    bool push_batch_local(std::span<const T> items, Priority prio, uint64_t base_id) noexcept {
        int64_t b = bottom_.load(std::memory_order_relaxed);
        int64_t t = top_.load(std::memory_order_acquire);
        const size_t n = items.size();

        if ((b - t) + static_cast<int64_t>(n) > static_cast<int64_t>(CapacityPerLane)) {
            return false;
        }

        for (size_t i = 0; i < n; ++i) {
            const size_t slot_idx = static_cast<size_t>(b + i) & MASK;
            Slot& slot = buffer_[slot_idx];

            uint64_t cur_hdr_raw = slot.header.load(std::memory_order_relaxed);
            SlotHeader cur_hdr = SlotHeader::from_u64(cur_hdr_raw);

            slot.payload = items[i];
            slot.payload.id = base_id + i;
            slot.payload.priority = prio;

            SlotHeader new_hdr{
                .generation = cur_hdr.generation + 1,
                .state = TaskSlotState::COMMITTED,
                .priority = prio
            };
            slot.header.store(new_hdr.to_u64(), std::memory_order_release);
        }

        bottom_.store(b + static_cast<int64_t>(n), std::memory_order_release);
        return true;
    }

    std::optional<T> pop_local() noexcept {
        int64_t b = bottom_.load(std::memory_order_relaxed) - 1;
        bottom_.store(b, std::memory_order_seq_cst);

        int64_t t = top_.load(std::memory_order_seq_cst);

        if (t <= b) {
            // Non-empty queue
            const size_t slot_idx = static_cast<size_t>(b) & MASK;
            Slot& slot = buffer_[slot_idx];

            if (t == b) {
                // Single element race condition against concurrent stealers
                int64_t expected_top = t;
                if (!top_.compare_exchange_strong(expected_top, t + 1, 
                        std::memory_order_acq_rel, std::memory_order_relaxed)) {
                    bottom_.store(t + 1, std::memory_order_relaxed);
                    return std::nullopt; // Lost race to stealer
                }
                bottom_.store(t + 1, std::memory_order_relaxed);
            }

            uint64_t cur_raw = slot.header.load(std::memory_order_acquire);
            SlotHeader hdr = SlotHeader::from_u64(cur_raw);

            if (hdr.state == TaskSlotState::CANCELLED) {
                return std::nullopt; // Task was cancelled in flight
            }

            SlotHeader next_hdr = hdr;
            next_hdr.state = TaskSlotState::CONSUMED;
            slot.header.store(next_hdr.to_u64(), std::memory_order_release);

            return slot.payload;
        } else {
            // Empty queue
            bottom_.store(t, std::memory_order_relaxed);
            return std::nullopt;
        }
    }

    size_t steal_batch(T* dest, size_t max_count) noexcept {
        if (max_count == 0) return 0;

        while (true) {
            int64_t t = top_.load(std::memory_order_acquire);
            int64_t b = bottom_.load(std::memory_order_acquire);

            if (t >= b) {
                return 0; // Empty lane
            }

            size_t available = static_cast<size_t>(b - t);
            size_t steal_n = std::min(max_count, (available + 1) / 2); // Dynamic chunk split
            if (steal_n == 0) steal_n = 1;

            int64_t expected_top = t;
            if (top_.compare_exchange_weak(expected_top, t + static_cast<int64_t>(steal_n),
                    std::memory_order_acq_rel, std::memory_order_acquire)) {

                size_t actual_stolen = 0;
                for (size_t i = 0; i < steal_n; ++i) {
                    const size_t slot_idx = static_cast<size_t>(t + i) & MASK;
                    Slot& slot = buffer_[slot_idx];

                    uint64_t cur_raw = slot.header.load(std::memory_order_acquire);
                    SlotHeader hdr = SlotHeader::from_u64(cur_raw);

                    if (hdr.state == TaskSlotState::COMMITTED) {
                        SlotHeader next_hdr = hdr;
                        next_hdr.state = TaskSlotState::CONSUMED;
                        if (slot.header.compare_exchange_strong(cur_raw, next_hdr.to_u64(),
                                std::memory_order_acq_rel, std::memory_order_relaxed)) {
                            dest[actual_stolen++] = slot.payload;
                        }
                    }
                }
                return actual_stolen;
            }
            _mm_pause(); // Low-latency architectural yield
        }
    }

    bool cancel_task_in_lane(TaskId id) noexcept {
        int64_t t = top_.load(std::memory_order_acquire);
        int64_t b = bottom_.load(std::memory_order_acquire);

        for (int64_t idx = t; idx < b; ++idx) {
            Slot& slot = buffer_[static_cast<size_t>(idx) & MASK];
            uint64_t cur_raw = slot.header.load(std::memory_order_acquire);
            SlotHeader hdr = SlotHeader::from_u64(cur_raw);

            if (hdr.state == TaskSlotState::COMMITTED && slot.payload.id == id) {
                SlotHeader cancelled_hdr = hdr;
                cancelled_hdr.state = TaskSlotState::CANCELLED;
                cancelled_hdr.generation += 1;

                if (slot.header.compare_exchange_strong(cur_raw, cancelled_hdr.to_u64(),
                        std::memory_order_acq_rel, std::memory_order_relaxed)) {
                    return true;
                }
            }
        }
        return false;
    }

    int64_t size_approx() const noexcept {
        int64_t b = bottom_.load(std::memory_order_relaxed);
        int64_t t = top_.load(std::memory_order_relaxed);
        return std::max<int64_t>(0, b - t);
    }

private:
    alignas(CACHE_LINE_SIZE) std::atomic<int64_t> top_;
    alignas(CACHE_LINE_SIZE) std::atomic<int64_t> bottom_;
    alignas(CACHE_LINE_SIZE) std::array<Slot, CapacityPerLane> buffer_;
};

// ============================================================================
// NUMA TOPOLOGY AWARE WORK-STEALING PRIORITY DEQUE
// Multi-Tier Priority Deque with Local Core -> Socket -> Inter-Socket Hierarchy
// ============================================================================
template <typename T, size_t CapacityPerLane = 4096>
class NUMAWorkStealingPriorityDeque {
public:
    static constexpr size_t NUM_PRIORITIES = static_cast<size_t>(Priority::Count);

    NUMAWorkStealingPriorityDeque(size_t numa_node_id, size_t core_id)
        : numa_node_id_(numa_node_id), core_id_(core_id) {}

    bool push_local(T&& task, Priority prio) noexcept {
        const size_t p_idx = static_cast<size_t>(prio);
        const TaskId id = task.id;
        return lanes_[p_idx].push_local(task, prio, id);
    }

    bool push_batch(std::span<const T> tasks, Priority prio, uint64_t base_id) noexcept {
        const size_t p_idx = static_cast<size_t>(prio);
        return lanes_[p_idx].push_batch_local(tasks, prio, base_id);
    }

    std::optional<T> pop_local() noexcept {
        // Priority stratification: Drain Critical -> Normal -> Speculative
        for (size_t p = 0; p < NUM_PRIORITIES; ++p) {
            auto task = lanes_[p].pop_local();
            if (task.has_value()) {
                return task;
            }
        }
        return std::nullopt;
    }

    size_t steal_batch(T* dest, size_t max_count, Priority min_prio) noexcept {
        size_t total_stolen = 0;
        const size_t max_p_idx = static_cast<size_t>(min_prio);

        for (size_t p = 0; p <= max_p_idx && total_stolen < max_count; ++p) {
            size_t remaining = max_count - total_stolen;
            size_t stolen = lanes_[p].steal_batch(dest + total_stolen, remaining);
            total_stolen += stolen;
        }
        return total_stolen;
    }

    bool cancel_task(TaskId id) noexcept {
        for (size_t p = 0; p < NUM_PRIORITIES; ++p) {
            if (lanes_[p].cancel_task_in_lane(id)) {
                return true;
            }
        }
        return false;
    }

    void advance_epoch_and_reclaim(size_t thread_id) noexcept {
        EpochManager::instance().try_advance_and_reclaim(thread_id);
    }

    size_t numa_node_id() const noexcept { return numa_node_id_; }
    size_t core_id() const noexcept { return core_id_; }

    int64_t total_tasks_approx() const noexcept {
        int64_t total = 0;
        for (size_t p = 0; p < NUM_PRIORITIES; ++p) {
            total += lanes_[p].size_approx();
        }
        return total;
    }

private:
    const size_t numa_node_id_;
    const size_t core_id_;
    alignas(CACHE_LINE_SIZE) std::array<SinglePriorityLaneRing<T, CapacityPerLane>, NUM_PRIORITIES> lanes_;
};

// ============================================================================
// HIERARCHICAL NUMA DISPATCHER & SCHEDULER
// SMT sibling -> Socket NUMA -> Cross-Socket Remote Domain Escalation
// ============================================================================
class HierarchicalNUMAScheduler {
public:
    struct WorkerThreadEntry {
        size_t thread_id{0};
        size_t numa_node{0};
        size_t core_id{0};
        NUMAWorkStealingPriorityDeque<Task>* deque{nullptr};
    };

    HierarchicalNUMAScheduler(size_t num_nodes, size_t cores_per_node)
        : num_nodes_(num_nodes), cores_per_node_(cores_per_node) {}

    void register_worker(size_t tid, size_t node_id, size_t core_id, NUMAWorkStealingPriorityDeque<Task>* deque) {
        workers_[tid] = WorkerThreadEntry{
            .thread_id = tid,
            .numa_node = node_id,
            .core_id = core_id,
            .deque = deque
        };
        active_workers_.store(std::max(active_workers_.load(std::memory_order_relaxed), tid + 1), 
                              std::memory_order_release);
    }

    size_t steal_work_hierarchical(size_t caller_tid, Task* dest_buffer, size_t max_tasks, Priority min_prio) noexcept {
        const WorkerThreadEntry& caller = workers_[caller_tid];
        const size_t total_w = active_workers_.load(std::memory_order_acquire);
        if (total_w <= 1) return 0;

        thread_local std::minstd_rand prng(static_cast<uint32_t>(caller_tid + 104729));

        // Domain 1: Intra-Core / SMT Sibling Domain
        for (size_t i = 0; i < total_w; ++i) {
            if (i == caller_tid) continue;
            const auto& victim = workers_[i];
            if (victim.deque && victim.numa_node == caller.numa_node && victim.core_id == caller.core_id) {
                size_t stolen = victim.deque->steal_batch(dest_buffer, max_tasks, min_prio);
                if (stolen > 0) return stolen;
            }
        }

        // Domain 2: Intra-Socket NUMA Node Cores (Randomized selection)
        std::array<size_t, MAX_THREADS_PER_NODE> intra_socket_candidates;
        size_t intra_count = 0;

        for (size_t i = 0; i < total_w; ++i) {
            if (i == caller_tid) continue;
            const auto& victim = workers_[i];
            if (victim.deque && victim.numa_node == caller.numa_node && victim.core_id != caller.core_id) {
                intra_socket_candidates[intra_count++] = i;
                if (intra_count >= MAX_THREADS_PER_NODE) break;
            }
        }

        if (intra_count > 0) {
            size_t start_idx = prng() % intra_count;
            for (size_t k = 0; k < intra_count; ++k) {
                size_t victim_id = intra_socket_candidates[(start_idx + k) % intra_count];
                size_t stolen = workers_[victim_id].deque->steal_batch(dest_buffer, max_tasks, min_prio);
                if (stolen > 0) return stolen;
            }
        }

        // Domain 3: Inter-Socket Remote NUMA Domains (Randomized Cross-CCX/Socket Steal)
        std::array<size_t, MAX_SYSTEM_THREADS> remote_candidates;
        size_t remote_count = 0;

        for (size_t i = 0; i < total_w; ++i) {
            if (i == caller_tid) continue;
            const auto& victim = workers_[i];
            if (victim.deque && victim.numa_node != caller.numa_node) {
                remote_candidates[remote_count++] = i;
                if (remote_count >= MAX_SYSTEM_THREADS) break;
            }
        }

        if (remote_count > 0) {
            size_t start_idx = prng() % remote_count;
            for (size_t k = 0; k < remote_count; ++k) {
                size_t victim_id = remote_candidates[(start_idx + k) % remote_count];
                size_t stolen = workers_[victim_id].deque->steal_batch(dest_buffer, max_tasks, min_prio);
                if (stolen > 0) return stolen;
            }
        }

        return 0;
    }

private:
    const size_t num_nodes_;
    const size_t cores_per_node_;
    alignas(CACHE_LINE_SIZE) std::atomic<size_t> active_workers_{0};
    alignas(CACHE_LINE_SIZE) std::array<WorkerThreadEntry, MAX_SYSTEM_THREADS> workers_{};
};

// ============================================================================
// VERIFICATION TEST SUITE & LATENCY BENCHMARK HARNESS
// ============================================================================
inline void dummy_matching_engine_task(void* ctx) {
    auto* counter = static_cast<std::atomic<uint64_t>*>(ctx);
    counter->fetch_add(1, std::memory_order_relaxed);
}

int main() {
    constexpr size_t TEST_NUMA_NODES = 2;
    constexpr size_t TEST_CORES_PER_NODE = 4;
    constexpr size_t TOTAL_THREADS = TEST_NUMA_NODES * TEST_CORES_PER_NODE;
    constexpr size_t TASKS_PER_PRODUCER = 50'000;

    HierarchicalNUMAScheduler scheduler(TEST_NUMA_NODES, TEST_CORES_PER_NODE);
    std::vector<std::unique_ptr<NUMAWorkStealingPriorityDeque<Task>>> deques;
    deques.reserve(TOTAL_THREADS);

    for (size_t i = 0; i < TOTAL_THREADS; ++i) {
        size_t node_id = i / TEST_CORES_PER_NODE;
        size_t core_id = i % TEST_CORES_PER_NODE;
        deques.push_back(std::make_unique<NUMAWorkStealingPriorityDeque<Task>>(node_id, core_id));
    }

    std::atomic<uint64_t> completed_tasks{0};
    std::atomic<bool> start_flag{false};
    std::vector<std::jthread> threads;

    for (size_t tid = 0; tid < TOTAL_THREADS; ++tid) {
        threads.emplace_back([&, tid]() {
            ThreadRegistrationToken token;
            scheduler.register_worker(token.id(), tid / TEST_CORES_PER_NODE, tid % TEST_CORES_PER_NODE, deques[tid].get());

            while (!start_flag.load(std::memory_order_acquire)) {
                _mm_pause();
            }

            // Local push phase with stratified priorities
            for (size_t i = 0; i < TASKS_PER_PRODUCER; ++i) {
                Priority prio = (i % 100 == 0) ? Priority::Critical :
                                (i % 10 == 0)  ? Priority::Speculative : Priority::Normal;

                Task t{
                    .id = (static_cast<uint64_t>(tid) << 32) | i,
                    .priority = prio,
                    .execute_fn = dummy_matching_engine_task,
                    .context = &completed_tasks
                };

                while (!deques[tid]->push_local(std::move(t), prio)) {
                    // Lane is saturated: local drain to prevent pipeline stalls
                    auto local_task = deques[tid]->pop_local();
                    if (local_task.has_value()) {
                        EpochGuard guard(token.id());
                        local_task->execute();
                    }
                }
            }

            // Speculative Task Cancellation Verification
            deques[tid]->cancel_task((static_cast<uint64_t>(tid) << 32) | 10);

            // Dynamic Execution and Work-Stealing Loop
            std::array<Task, 16> steal_buffer;
            while (completed_tasks.load(std::memory_order_relaxed) < TOTAL_THREADS * TASKS_PER_PRODUCER - 10) {
                EpochGuard guard(token.id());

                auto local_task = deques[tid]->pop_local();
                if (local_task.has_value()) {
                    local_task->execute();
                } else {
                    size_t stolen = scheduler.steal_work_hierarchical(token.id(), steal_buffer.data(), 
                                                                     steal_buffer.size(), Priority::Speculative);
                    for (size_t s = 0; s < stolen; ++s) {
                        steal_buffer[s].execute();
                    }
                }

                deques[tid]->advance_epoch_and_reclaim(token.id());
            }
        });
    }

    auto start_time = std::chrono::steady_clock::now();
    start_flag.store(true, std::memory_order_release);

    for (auto& th : threads) {
        if (th.joinable()) {
            th.join();
        }
    }
    auto end_time = std::chrono::steady_clock::now();

    auto elapsed_us = std::chrono::duration_cast<std::chrono::microseconds>(end_time - start_time).count();
    std::cout << "Executed " << completed_tasks.load() << " tasks in " 
              << elapsed_us << " us (~" 
              << (completed_tasks.load() * 1'000'000ULL) / (elapsed_us > 0 ? elapsed_us : 1) 
              << " tasks/sec across NUMA domains)\n";

    return 0;
}
