namespace TransactionEngine {

    enum class IsolationLevel {
        SNAPSHOT_ISOLATION,
        READ_COMMITTED
    };

    struct Transaction {
        txn_id_t tx_id;
        txn_id_t snapshot_ts;
        IsolationLevel isolation;
        bool active;
        std::vector<lsn_t> staged_lsns;
    };

    class Engine {
    public:
        Engine(const std::string& wal_path) : wal_(wal_path) {}

        void RegisterThread(size_t tid) {
            MemoryManagement::EpochManager::Instance().RegisterThread(tid);
        }

        Transaction BeginTx(IsolationLevel level = IsolationLevel::SNAPSHOT_ISOLATION) {
            txn_id_t tid = global_tx_id_.fetch_add(1, std::memory_order_relaxed);
            return Transaction{
                .tx_id = tid,
                .snapshot_ts = tid,
                .isolation = level,
                .active = true,
                .staged_lsns = {}
            };
        }

        bool Get(Transaction& tx, const std::string& key, std::string& value, size_t tid) {
            std::vector<uint8_t> out;
            bool ok = index_.Get(reinterpret_cast<const uint8_t*>(key.data()), key.size(), tx.snapshot_ts, out, tid);
            if (ok) {
                value.assign(reinterpret_cast<const char*>(out.data()), out.size());
            }
            return ok;
        }

        bool Put(Transaction& tx, const std::string& key, const std::string& value, size_t tid) {
            if (!tx.active) return false;

            lsn_t lsn = wal_.ReserveSlot(sizeof(WAL::LogRecord));
            wal_.WriteRecord(lsn, tx.tx_id, WAL::RecordType::ROW_PUT, 
                             reinterpret_cast<const uint8_t*>(key.data()), key.size(), 
                             reinterpret_cast<const uint8_t*>(value.data()), value.size());
            tx.staged_lsns.push_back(lsn);

            return index_.Put(reinterpret_cast<const uint8_t*>(key.data()), key.size(), 
                              reinterpret_cast<const uint8_t*>(value.data()), value.size(), 
                              tx.tx_id, tid);
        }

        bool Commit(Transaction& tx) {
            if (!tx.active) return false;

            lsn_t commit_lsn = wal_.ReserveSlot(sizeof(WAL::LogRecord));
            wal_.WriteRecord(commit_lsn, tx.tx_id, WAL::RecordType::TXN_COMMIT, nullptr, 0, nullptr, 0);

            // Synchronously flush all transaction logs up to the commit record
            wal_.FlushUpTo(commit_lsn);
            tx.active = false;
            return true;
        }

        void Abort(Transaction& tx) {
            if (!tx.active) return;
            lsn_t abort_lsn = wal_.ReserveSlot(sizeof(WAL::LogRecord));
            wal_.WriteRecord(abort_lsn, tx.tx_id, WAL::RecordType::TXN_ABORT, nullptr, 0, nullptr, 0);
            tx.active = false;
        }

    private:
        alignas(64) std::atomic<txn_id_t> global_tx_id_{1};
        WAL::WALRingBuffer wal_;
        MVCCEngine::RadixTreeIndex index_;
    };
}
