constexpr size_t CACHE_LINE_SIZE = 64;
constexpr uint64_t INF_TXN = UINT64_MAX;
constexpr size_t WAL_RING_BUFFER_SIZE = 1024 * 1024 * 16; // 16MB Ring Buffer
constexpr size_t MAX_KEY_LEN = 64;
constexpr size_t MAX_THREADS = 128;
constexpr size_t MAX_PREFIX_LEN = 16;

// ============================================================================
// 1. ROBUST EPOCH-BASED RECLAMATION (EBR)
// ============================================================================

struct RetiredNode {
    void* ptr;
    void (*deleter)(void*);
    RetiredNode* next;
