struct alignas(CACHE_LINE_SIZE) ThreadEpochState {
    std::atomic<bool> active{false};
    std::atomic<uint64_t> local_epoch{0};
    RetiredNode* retire_bins[3]{nullptr, nullptr, nullptr};
    size_t pending_allocations{0};
    uint8_t pad[CACHE_LINE_SIZE - sizeof(std::atomic<bool>) - sizeof(std::atomic<uint64_t>) - 
                sizeof(RetiredNode*) * 3 - sizeof(size_t)];
};

class EpochManager {
public:
    static EpochManager& Instance() {
        static EpochManager instance;
        return instance;
    }

    EpochManager() : global_epoch_(0), thread_count_(0) {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            registry_[i].store(nullptr, std::memory_order_relaxed);
        }
    }

    void RegisterThread(size_t tid, ThreadEpochState* state) {
        registry_[tid].store(state, std::memory_order_release);
    }

    void UnregisterThread(size_t tid) {
        ThreadEpochState* state = registry_[tid].load(std::memory_order_acquire);
        if (state) {
            // Reclaim all bins eagerly during de-registration
            for (size_t i = 0; i < 3; ++i) {
                ReclaimBin(state->retire_bins[i]);
                state->retire_bins[i] = nullptr;
            }
            state->active.store(false, std::memory_order_release);
            registry_[tid].store(nullptr, std::memory_order_release);
        }
    }

    void EnterCritical(ThreadEpochState& state) {
        state.active.store(true, std::memory_order_relaxed);
        // Sequential consistency fence guarantees visibility of active flag before reading global epoch
        std::atomic_thread_fence(std::memory_order_seq_cst);
        uint64_t current = global_epoch_.load(std::memory_order_acquire);
        state.local_epoch.store(current, std::memory_order_relaxed);
    }

    void LeaveCritical(ThreadEpochState& state) {
        state.active.store(false, std::memory_order_release);
    }

    template <typename T>
    void Retire(ThreadEpochState& state, T* ptr) {
        auto* node = new RetiredNode{
            .ptr = static_cast<void*>(ptr),
            .deleter = [](void* p) { delete static_cast<T*>(p); },
            .next = nullptr
        };
        uint64_t e = state.local_epoch.load(std::memory_order_relaxed) % 3;
        node->next = state.retire_bins[e];
        state.retire_bins[e] = node;

        if (++state.pending_allocations > 64) {
            TryAdvanceEpoch(state);
            state.pending_allocations = 0;
        }
    }

    void TryAdvanceEpoch(ThreadEpochState& local_state) {
        uint64_t global_e = global_epoch_.load(std::memory_order_relaxed);

        // Verification phase: Check all active thread local states
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            ThreadEpochState* other = registry_[i].load(std::memory_order_acquire);
            if (other && other->active.load(std::memory_order_acquire)) {
                if (other->local_epoch.load(std::memory_order_acquire) != global_e) {
                    return; // Cannot advance; a thread is lagging in the prior epoch
                }
            }
        }

        // Advance global epoch
        if (global_epoch_.compare_exchange_strong(global_e, global_e + 1, std::memory_order_acq_rel)) {
            // Safe to reclaim bin (global_e + 2) % 3, which is 2 epochs behind the new epoch
            uint64_t reclaim_idx = (global_e + 2) % 3;
            ReclaimBin(local_state.retire_bins[reclaim_idx]);
            local_state.retire_bins[reclaim_idx] = nullptr;
        }
    }

private:
    void ReclaimBin(RetiredNode* head) {
        while (head) {
            RetiredNode* next = head->next;
            head->deleter(head->ptr);
            delete head;
            head = next;
        }
    }

    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> global_epoch_;
    alignas(CACHE_LINE_SIZE) std::atomic<ThreadEpochState*> registry_[MAX_THREADS];
    std::atomic<size_t> thread_count_;
};

