enum class NodeType : uint8_t { N4, N16, N48, N256 };

// Optimistic Seqlock header with Path Compression
struct alignas(64) NodeHeader {
    std::atomic<uint64_t> version_lock{0};
    uint32_t prefix_len{0};
    uint8_t prefix[MAX_PREFIX_LEN]{0};
    NodeType type;
    uint8_t count{0};

    // Lock bit: Bit 0. Version counter: Bits 1..63
    bool IsLocked(uint64_t v) const { return (v & 1ULL) != 0; }

    uint64_t ReadLockOrRestart(bool& need_restart) const {
        uint64_t v = version_lock.load(std::memory_order_acquire);
        if (IsLocked(v)) {
            need_restart = true;
            return 0;
        }
        need_restart = false;
        return v;
    }

    void CheckOrRestart(uint64_t start_version, bool& need_restart) const {
        std::atomic_thread_fence(std::memory_order_acquire);
        if (version_lock.load(std::memory_order_relaxed) != start_version) {
            need_restart = true;
        }
    }

    void UpgradeToWriteLockOrRestart(uint64_t& version, bool& need_restart) {
        if (IsLocked(version)) {
            need_restart = true;
            return;
        }
        if (!version_lock.compare_exchange_strong(version, version + 1, std::memory_order_acquire)) {
            need_restart = true;
        } else {
            version += 1;
        }
    }

    void WriteUnlock() {
        version_lock.fetch_add(1, std::memory_order_release);
    }
};

struct Node4 : public NodeHeader {
    uint8_t keys[4];
    std::atomic<void*> children[4];

    Node4() {
        type = NodeType::N4;
        std::memset(keys, 0, sizeof(keys));
        for (auto& c : children) c.store(nullptr, std::memory_order_relaxed);
    }
};

struct Node16 : public NodeHeader {
    uint8_t keys[16];
    std::atomic<void*> children[16];

    Node16() {
        type = NodeType::N16;
        std::memset(keys, 0, sizeof(keys));
        for (auto& c : children) c.store(nullptr, std::memory_order_relaxed);
    }
};

struct Node48 : public NodeHeader {
    uint8_t child_indices[256];
    std::atomic<void*> children[48];

    Node48() {
        type = NodeType::N48;
        std::memset(child_indices, 0xFF, sizeof(child_indices));
        for (auto& c : children) c.store(nullptr, std::memory_order_relaxed);
    }
};

struct Node256 : public NodeHeader {
    std::atomic<void*> children[256];

    Node256() {
        type = NodeType::N256;
        for (auto& c : children) c.store(nullptr, std::memory_order_relaxed);
    }
};

// Tagging: Pointer bit 0 indicates Leaf (VersionNode pointer) vs Internal Node
inline bool IsLeaf(void* ptr) {
    return (reinterpret_cast<uintptr_t>(ptr) & 1ULL) != 0;
}

inline void* TagLeaf(VersionNode* vnode) {
    return reinterpret_cast<void*>(reinterpret_cast<uintptr_t>(vnode) | 1ULL);
}

inline VersionNode* UntagLeaf(void* ptr) {
    return reinterpret_cast<VersionNode*>(reinterpret_cast<uintptr_t>(ptr) & ~1ULL);
}

class RadixTreeIndex {
public:
    RadixTreeIndex() {
        root_.store(new Node4(), std::memory_order_relaxed);
    }

    ~RadixTreeIndex() {
        // Unsafe teardown (requires quiescence)
        FreeRecursive(root_.load(std::memory_order_relaxed));
    }

    bool Get(std::string_view key, uint64_t snapshot_ts, std::string& result) {
        EpochGuard guard;
    restart:
        void* curr = root_.load(std::memory_order_acquire);
        size_t depth = 0;

        while (curr) {
            if (IsLeaf(curr)) {
                VersionNode* vhead = UntagLeaf(curr);
                return ReadVersion(vhead, snapshot_ts, result);
            }

            auto* header = static_cast<NodeHeader*>(curr);
            bool restart = false;
            uint64_t v = header->ReadLockOrRestart(restart);
            if (restart) goto restart;

            // Prefix check
            if (header->prefix_len > 0) {
                for (uint32_t i = 0; i < header->prefix_len; ++i) {
                    if (depth + i >= key.size() || header->prefix[i] != static_cast<uint8_t>(key[depth + i])) {
                        header->CheckOrRestart(v, restart);
                        if (restart) goto restart;
                        return false;
                    }
                }
                depth += header->prefix_len;
            }

            if (depth >= key.size()) {
                header->CheckOrRestart(v, restart);
                if (restart) goto restart;
                return false;
            }

            uint8_t byte = static_cast<uint8_t>(key[depth]);
            void* next = FindChild(header, byte);

            header->CheckOrRestart(v, restart);
            if (restart) goto restart;

            if (!next) return false;
            curr = next;
            depth++;
        }
        return false;
    }

    bool Put(std::string_view key, std::string_view value, uint64_t txn_id) {
        EpochGuard guard;
    restart:
        void* parent = nullptr;
        void* curr = root_.load(std::memory_order_acquire);
        size_t depth = 0;
        uint8_t parent_byte = 0;

        while (curr) {
            if (IsLeaf(curr)) {
                VersionNode* vhead = UntagLeaf(curr);
                // First-Committer-Wins CAS modification
                if (vhead->created_tx_id == txn_id) {
                    return false; // Abort on write conflict
                }

                VersionNode* new_vnode = VersionNode::Create(txn_id, value, vhead);
                vhead->expired_tx_id.store(txn_id, std::memory_order_release);

                void* tagged_new = TagLeaf(new_vnode);
                if (!ReplaceChild(parent, parent_byte, curr, tagged_new)) {
                    VersionNode::Destroy(new_vnode);
                    goto restart;
                }
                return true;
            }

            auto* node = static_cast<NodeHeader*>(curr);
            bool restart = false;
            uint64_t v = node->ReadLockOrRestart(restart);
            if (restart) goto restart;

            // Handle path compression/prefix mismatch
            if (node->prefix_len > 0) {
                uint32_t matched = 0;
                while (matched < node->prefix_len && (depth + matched) < key.size() &&
                       node->prefix[matched] == static_cast<uint8_t>(key[depth + matched])) {
                    matched++;
                }

                if (matched < node->prefix_len) {
                    node->UpgradeToWriteLockOrRestart(v, restart);
                    if (restart) goto restart;

                    // Split prefix: Create intermediate Node4
                    auto* split_node = new Node4();
                    split_node->prefix_len = matched;
                    std::memcpy(split_node->prefix, node->prefix, matched);

                    // Morph existing node prefix
                    node->prefix_len -= (matched + 1);
                    uint8_t old_char = node->prefix[matched];
                    std::memmove(node->prefix, node->prefix + matched + 1, node->prefix_len);

                    // Insert leaf
                    VersionNode* leaf = VersionNode::Create(txn_id, value);
                    uint8_t new_char = static_cast<uint8_t>(key[depth + matched]);

                    split_node->keys[0] = old_char;
                    split_node->children[0].store(node, std::memory_order_relaxed);
                    split_node->keys[1] = new_char;
                    split_node->children[1].store(TagLeaf(leaf), std::memory_order_relaxed);
                    split_node->count = 2;

                    if (!parent) {
                        root_.store(split_node, std::memory_order_release);
                    } else {
                        SetChild(parent, parent_byte, split_node);
                    }
                    node->WriteUnlock();
                    return true;
                }
                depth += node->prefix_len;
            }

            if (depth == key.size()) {
                // Key terminates exactly at this internal node
                return false;
            }

            uint8_t byte = static_cast<uint8_t>(key[depth]);
            void* next = FindChild(node, byte);

            if (!next) {
                node->UpgradeToWriteLockOrRestart(v, restart);
                if (restart) goto restart;

                VersionNode* leaf = VersionNode::Create(txn_id, value);
                if (!InsertChild(node, byte, TagLeaf(leaf), parent, parent_byte)) {
                    VersionNode::Destroy(leaf);
                    node->WriteUnlock();
                    goto restart;
                }
                node->WriteUnlock();
                return true;
            }

            parent = curr;
            parent_byte = byte;
            curr = next;
            depth++;
        }
        return false;
    }

private:
    std::atomic<void*> root_;

    bool ReadVersion(VersionNode* head, uint64_t snapshot_ts, std::string& out_val) {
        VersionNode* curr = head;
        while (curr) {
            uint64_t created = curr->created_tx_id;
            uint64_t expired = curr->expired_tx_id.load(std::memory_order_acquire);
            if (created <= snapshot_ts && snapshot_ts < expired) {
                out_val.assign(curr->value, curr->val_len);
                return true;
            }
            curr = curr->next.load(std::memory_order_acquire);
        }
        return false;
    }

    void* FindChild(NodeHeader* header, uint8_t byte) {
        switch (header->type) {
            case NodeType::N4: {
                auto* n = static_cast<Node4*>(header);
                for (uint8_t i = 0; i < n->count; ++i) {
                    if (n->keys[i] == byte) return n->children[i].load(std::memory_order_acquire);
                }
                return nullptr;
            }
            case NodeType::N16: {
                auto* n = static_cast<Node16*>(header);
                __m128i cmp = _mm_cmpeq_epi8(_mm_set1_epi8(byte), _mm_loadu_si128(reinterpret_cast<const __m128i*>(n->keys)));
                int mask = _mm_movemask_epi8(cmp) & ((1 << n->count) - 1);
                if (mask) {
                    int idx = __builtin_ctz(mask);
                    return n->children[idx].load(std::memory_order_acquire);
                }
                return nullptr;
            }
            case NodeType::N48: {
                auto* n = static_cast<Node48*>(header);
                uint8_t idx = n->child_indices[byte];
                if (idx != 0xFF) {
                    return n->children[idx].load(std::memory_order_acquire);
                }
                return nullptr;
            }
            case NodeType::N256: {
                auto* n = static_cast<Node256*>(header);
                return n->children[byte].load(std::memory_order_acquire);
            }
        }
        return nullptr;
    }

    bool InsertChild(NodeHeader* node, uint8_t byte, void* child, void* parent, uint8_t parent_byte) {
        switch (node->type) {
            case NodeType::N4: {
                auto* n = static_cast<Node4*>(node);
                if (n->count < 4) {
                    n->keys[n->count] = byte;
                    n->children[n->count].store(child, std::memory_order_release);
                    n->count++;
                    return true;
                }
                // Grow to Node16
                auto* n16 = new Node16();
                n16->count = n->count;
                n16->prefix_len = n->prefix_len;
                std::memcpy(n16->prefix, n->prefix, n->prefix_len);
                std::memcpy(n16->keys, n->keys, 4);
                for (int i = 0; i < 4; ++i) {
                    n16->children[i].store(n->children[i].load(std::memory_order_relaxed), std::memory_order_relaxed);
                }
                n16->keys[4] = byte;
                n16->children[4].store(child, std::memory_order_relaxed);
                n16->count++;

                if (!parent) root_.store(n16, std::memory_order_release);
                else SetChild(parent, parent_byte, n16);

                EpochManager::Instance().Retire(t_epoch_state, n);
                return true;
            }
            case NodeType::N16: {
                auto* n = static_cast<Node16*>(node);
                if (n->count < 16) {
                    n->keys[n->count] = byte;
                    n->children[n->count].store(child, std::memory_order_release);
                    n->count++;
                    return true;
                }
                // Grow to Node48
                auto* n48 = new Node48();
                n48->count = n->count;
                n48->prefix_len = n->prefix_len;
                std::memcpy(n48->prefix, n->prefix, n->prefix_len);
                for (uint8_t i = 0; i < 16; ++i) {
                    n48->child_indices[n->keys[i]] = i;
                    n48->children[i].store(n->children[i].load(std::memory_order_relaxed), std::memory_order_relaxed);
                }
                n48->child_indices[byte] = 16;
                n48->children[16].store(child, std::memory_order_relaxed);
                n48->count++;

                if (!parent) root_.store(n48, std::memory_order_release);
                else SetChild(parent, parent_byte, n48);

                EpochManager::Instance().Retire(t_epoch_state, n);
                return true;
            }
            case NodeType::N48: {
                auto* n = static_cast<Node48*>(node);
                if (n->count < 48) {
                    n->child_indices[byte] = n->count;
                    n->children[n->count].store(child, std::memory_order_release);
                    n->count++;
                    return true;
                }
                // Grow to Node256
                auto* n256 = new Node256();
                n256->count = n->count;
                n256->prefix_len = n->prefix_len;
                std::memcpy(n256->prefix, n->prefix, n->prefix_len);
                for (int i = 0; i < 256; ++i) {
                    uint8_t idx = n->child_indices[i];
                    if (idx != 0xFF) {
                        n256->children[i].store(n->children[idx].load(std::memory_order_relaxed), std::memory_order_relaxed);
                    }
                }
                n256->children[byte].store(child, std::memory_order_relaxed);
                n256->count++;

                if (!parent) root_.store(n256, std::memory_order_release);
                else SetChild(parent, parent_byte, n256);

                EpochManager::Instance().Retire(t_epoch_state, n);
                return true;
            }
            case NodeType::N256: {
                auto* n = static_cast<Node256*>(node);
                n->children[byte].store(child, std::memory_order_release);
                n->count++;
                return true;
            }
        }
        return false;
    }

    void SetChild(void* parent, uint8_t byte, void* new_child) {
        auto* header = static_cast<NodeHeader*>(parent);
        switch (header->type) {
            case NodeType::N4: {
                auto* n = static_cast<Node4*>(parent);
                for (uint8_t i = 0; i < n->count; ++i) {
                    if (n->keys[i] == byte) {
                        n->children[i].store(new_child, std::memory_order_release);
                        return;
                    }
                }
                break;
            }
            case NodeType::N16: {
                auto* n = static_cast<Node16*>(parent);
                for (uint8_t i = 0; i < n->count; ++i) {
                    if (n->keys[i] == byte) {
                        n->children[i].store(new_child, std::memory_order_release);
                        return;
                    }
                }
                break;
            }
            case NodeType::N48: {
                auto* n = static_cast<Node48*>(parent);
                uint8_t idx = n->child_indices[byte];
                n->children[idx].store(new_child, std::memory_order_release);
                break;
            }
            case NodeType::N256: {
                auto* n = static_cast<Node256*>(parent);
                n->children[byte].store(new_child, std::memory_order_release);
                break;
            }
        }
    }

    bool ReplaceChild(void* parent, uint8_t byte, void* old_child, void* new_child) {
        if (!parent) {
            return root_.compare_exchange_strong(old_child, new_child, std::memory_order_acq_rel);
        }
        auto* header = static_cast<NodeHeader*>(parent);
        switch (header->type) {
            case NodeType::N4: {
                auto* n = static_cast<Node4*>(parent);
                for (uint8_t i = 0; i < n->count; ++i) {
                    if (n->keys[i] == byte) {
                        return n->children[i].compare_exchange_strong(old_child, new_child, std::memory_order_acq_rel);
                    }
                }
                return false;
            }
            case NodeType::N16: {
                auto* n = static_cast<Node16*>(parent);
                for (uint8_t i = 0; i < n->count; ++i) {
                    if (n->keys[i] == byte) {
                        return n->children[i].compare_exchange_strong(old_child, new_child, std::memory_order_acq_rel);
                    }
                }
                return false;
            }
            case NodeType::N48: {
                auto* n = static_cast<Node48*>(parent);
                uint8_t idx = n->child_indices[byte];
                return n->children[idx].compare_exchange_strong(old_child, new_child, std::memory_order_acq_rel);
            }
            case NodeType::N256: {
                auto* n = static_cast<Node256*>(parent);
                return n->children[byte].compare_exchange_strong(old_child, new_child, std::memory_order_acq_rel);
            }
        }
        return false;
    }

    void FreeRecursive(void* node) {
        if (!node) return;
        if (IsLeaf(node)) {
            VersionNode* curr = UntagLeaf(node);
            while (curr) {
                VersionNode* nxt = curr->next.load(std::memory_order_relaxed);
                VersionNode::Destroy(curr);
                curr = nxt;
            }
            return;
        }
        auto* header = static_cast<NodeHeader*>(node);
        switch (header->type) {
            case NodeType::N4: {
                auto* n = static_cast<Node4*>(node);
                for (int i = 0; i < n->count; ++i) FreeRecursive(n->children[i].load(std::memory_order_relaxed));
                delete n;
                break;
            }
            case NodeType::N16: {
                auto* n = static_cast<Node16*>(node);
                for (int i = 0; i < n->count; ++i) FreeRecursive(n->children[i].load(std::memory_order_relaxed));
                delete n;
                break;
            }
            case NodeType::N48: {
                auto* n = static_cast<Node48*>(node);
                for (int i = 0; i < 256; ++i) {
                    if (n->child_indices[i] != 0xFF) FreeRecursive(n->children[n->child_indices[i]].load(std::memory_order_relaxed));
                }
                delete n;
                break;
            }
            case NodeType::N256: {
                auto* n = static_cast<Node256*>(node);
                for (int i = 0; i < 256; ++i) FreeRecursive(n->children[i].load(std::memory_order_relaxed));
                delete n;
                break;
            }
        }
    }
};

