#pragma pack(push, 1)
struct LogHeader {
    uint64_t lsn;
    uint64_t tx_id;
    uint32_t key_len;
    uint32_t val_len;
    uint32_t crc32c;
};
#pragma pack(pop)

// Fast Hardware CRC32C using SSE4.2
inline uint32_t ComputeCRC32C(const void* data, size_t len) {
    uint32_t crc = 0xFFFFFFFF;
    const auto* p = static_cast<const uint8_t*>(data);
    while (len >= 8) {
        crc = static_cast<uint32_t>(_mm_crc32_u64(crc, *reinterpret_cast<const uint64_t*>(p)));
        p += 8;
        len -= 8;
    }
    if (len >= 4) {
        crc = _mm_crc32_u32(crc, *reinterpret_cast<const uint32_t*>(p));
        p += 4;
        len -= 4;
    }
    while (len > 0) {
        crc = _mm_crc32_u8(crc, *p);
        p++;
        len--;
    }
    return crc ^ 0xFFFFFFFF;
}

class WALRingBuffer {
public:
    WALRingBuffer(const char* file_path) {
        fd_ = open(file_path, O_CREAT | O_RDWR | O_DIRECT, 0644);
        if (fd_ < 0) {
            // Fallback for filesystems lacking direct I/O support in memory mocks
            fd_ = open(file_path, O_CREAT | O_RDWR, 0644);
        }
        assert(fd_ >= 0);
        posix_memalign(reinterpret_cast<void**>(&buffer_), 4096, WAL_RING_BUFFER_SIZE);
        head_.store(0, std::memory_order_relaxed);
        tail_.store(0, std::memory_order_relaxed);
        flushed_lsn_.store(0, std::memory_order_relaxed);
        leader_active_.store(false, std::memory_order_relaxed);
    }

    ~WALRingBuffer() {
        if (fd_ >= 0) close(fd_);
        free(buffer_);
    }

    uint64_t AppendRecord(uint64_t tx_id, std::string_view key, std::string_view val) {
        uint32_t total_size = sizeof(LogHeader) + key.size() + val.size();
        uint64_t offset = head_.fetch_add(total_size, std::memory_order_acq_rel);

        LogHeader hdr{
            .lsn = offset + total_size,
            .tx_id = tx_id,
            .key_len = static_cast<uint32_t>(key.size()),
            .val_len = static_cast<uint32_t>(val.size()),
            .crc32c = 0
        };

        // Ring buffer wrapping arithmetic
        size_t ring_idx = offset % WAL_RING_BUFFER_SIZE;
        std::memcpy(buffer_ + ring_idx, &hdr, sizeof(LogHeader));
        std::memcpy(buffer_ + ring_idx + sizeof(LogHeader), key.data(), key.size());
        std::memcpy(buffer_ + ring_idx + sizeof(LogHeader) + key.size(), val.data(), val.size());

        // Calculate CRC32C over the header + payload
        hdr.crc32c = ComputeCRC32C(buffer_ + ring_idx + sizeof(LogHeader), key.size() + val.size());
        std::memcpy(buffer_ + ring_idx, &hdr, sizeof(LogHeader));

        return hdr.lsn;
    }

    void CommitLSN(uint64_t target_lsn) {
        while (flushed_lsn_.load(std::memory_order_acquire) < target_lsn) {
            bool expected = false;
            if (leader_active_.compare_exchange_strong(expected, true, std::memory_order_acquire)) {
                // Leader: Batch flush up to current head
                FlushPipelined();
                leader_active_.store(false, std::memory_order_release);
                FutexWakeAll(&flushed_lsn_);
                return;
            } else {
                // Follower: Block on futex until target_lsn is persisted
                uint64_t current_flushed = flushed_lsn_.load(std::memory_order_acquire);
                if (current_flushed >= target_lsn) return;
                FutexWait(&flushed_lsn_, current_flushed);
            }
        }
    }

private:
    void FlushPipelined() {
        uint64_t current_tail = tail_.load(std::memory_order_relaxed);
        uint64_t target_head = head_.load(std::memory_order_acquire);

        if (target_head <= current_tail) return;

        size_t bytes_to_write = target_head - current_tail;
        size_t ring_offset = current_tail % WAL_RING_BUFFER_SIZE;

        // Perform synchronous batched disk sync
        ssize_t written = pwrite(fd_, buffer_ + ring_offset, bytes_to_write, current_tail);
        if (written > 0) {
            fdatasync(fd_);
        }

        tail_.store(target_head, std::memory_order_release);
        flushed_lsn_.store(target_head, std::memory_order_release);
    }

    void FutexWait(std::atomic<uint64_t>* addr, uint64_t val) {
        syscall(SYS_futex, reinterpret_cast<int*>(addr), FUTEX_WAIT_PRIVATE, static_cast<int>(val), nullptr, nullptr, 0);
    }

    void FutexWakeAll(std::atomic<uint64_t>* addr) {
        syscall(SYS_futex, reinterpret_cast<int*>(addr), FUTEX_WAKE_PRIVATE, INT32_MAX, nullptr, nullptr, 0);
    }

    int fd_;
    char* buffer_;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> head_;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> tail_;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> flushed_lsn_;
    alignas(CACHE_LINE_SIZE) std::atomic<bool> leader_active_;
};

