// Direct memory mapped io_uring abstraction
pub struct LinuxIoUring {
    ring_fd: RawFd,
    sq_ptr: *mut u8,
    sq_size: usize,
    cq_ptr: *mut u8,
    cq_size: usize,
    sqes_ptr: *mut io_uring_sqe,
    sqes_size: usize,

    sq_khead: *const AtomicU32,
    sq_ktail: *mut AtomicU32,
    sq_kmask: u32,
    sq_array: *mut u32,

    cq_khead: *mut AtomicU32,
    cq_ktail: *const AtomicU32,
    cq_kmask: u32,
    cq_cqes: *const io_uring_cqe,
}

unsafe impl Send for LinuxIoUring {}
unsafe impl Sync for LinuxIoUring {}

impl LinuxIoUring {
    pub fn new(entries: u32) -> io::Result<Self> {
        let mut p: io_uring_params = unsafe { mem::zeroed() };
        let ring_fd = unsafe { sys::io_uring_setup(entries, &mut p) };
        if ring_fd < 0 {
            return Err(io::Error::last_os_error());
        }

        let sq_size = (p.sq_off.array as usize) + (p.sq_entries as usize) * mem::size_of::<u32>();
        let cq_size = (p.cq_off.cqes as usize) + (p.cq_entries as usize) * mem::size_of::<io_uring_cqe>();
        let sqes_size = (p.sq_entries as usize) * mem::size_of::<io_uring_sqe>();

        unsafe {
            let sq_ptr = libc::mmap(
                ptr::null_mut(),
                sq_size,
                libc::PROT_READ | libc::PROT_WRITE,
                libc::MAP_SHARED | libc::MAP_POPULATE,
                ring_fd,
                0x0, // IORING_OFF_SQ_RING
            ) as *mut u8;

            let cq_ptr = libc::mmap(
                ptr::null_mut(),
                cq_size,
                libc::PROT_READ | libc::PROT_WRITE,
                libc::MAP_SHARED | libc::MAP_POPULATE,
                ring_fd,
                0x8000000, // IORING_OFF_CQ_RING
            ) as *mut u8;

            let sqes_ptr = libc::mmap(
                ptr::null_mut(),
                sqes_size,
                libc::PROT_READ | libc::PROT_WRITE,
                libc::MAP_SHARED | libc::MAP_POPULATE,
                ring_fd,
                0x10000000, // IORING_OFF_SQES
            ) as *mut io_uring_sqe;

            if sq_ptr == libc::MAP_FAILED || cq_ptr == libc::MAP_FAILED || sqes_ptr == libc::MAP_FAILED {
                libc::close(ring_fd);
                return Err(io::Error::last_os_error());
            }

            Ok(Self {
                ring_fd,
                sq_ptr,
                sq_size,
                cq_ptr,
                cq_size,
                sqes_ptr,
                sqes_size,
                sq_khead: sq_ptr.add(p.sq_off.head as usize) as *const AtomicU32,
                sq_ktail: sq_ptr.add(p.sq_off.tail as usize) as *mut AtomicU32,
                sq_kmask: *(sq_ptr.add(p.sq_off.ring_mask as usize) as *const u32),
                sq_array: sq_ptr.add(p.sq_off.array as usize) as *mut u32,
                cq_khead: cq_ptr.add(p.cq_off.head as usize) as *mut AtomicU32,
                cq_ktail: cq_ptr.add(p.cq_off.tail as usize) as *const AtomicU32,
                cq_kmask: *(cq_ptr.add(p.cq_off.ring_mask as usize) as *const u32),
                cq_cqes: cq_ptr.add(p.cq_off.cqes as usize) as *const io_uring_cqe,
            })
        }
    }

    #[inline(always)]
    pub fn get_sqe(&mut self) -> Option<&mut io_uring_sqe> {
        unsafe {
            let head = (*self.sq_khead).load(Ordering::Acquire);
            let tail = (*self.sq_ktail).load(Ordering::Relaxed);
            if tail - head > self.sq_kmask {
                return None; // SQ is full
            }
            let index = tail & self.sq_kmask;
            let sqe = &mut *self.sqes_ptr.add(index as usize);
            *sqe = mem::zeroed();
            *self.sq_array.add(index as usize) = index;
            (*self.sq_ktail).store(tail + 1, Ordering::Release);
            Some(sqe)
        }
    }

    pub fn submit_and_wait(&mut self, wait_nr: u32) -> io::Result<u32> {
        let ret = unsafe {
            sys::io_uring_enter(
                self.ring_fd,
                0, // Kernel reads tail directly
                wait_nr,
                IORING_ENTER_GETEVENTS,
                ptr::null(),
            )
        };
        if ret < 0 {
            Err(io::Error::from_raw_os_error(-ret))
        } else {
            Ok(ret as u32)
        }
    }

    #[inline(always)]
    pub fn reap_cqes<F: FnMut(io_uring_cqe)>(&mut self, mut f: F) {
        unsafe {
            let mut head = (*self.cq_khead).load(Ordering::Relaxed);
            let tail = (*self.cq_ktail).load(Ordering::Acquire);
            while head != tail {
                let index = head & self.cq_kmask;
                let cqe = *self.cq_cqes.add(index as usize);
                f(cqe);
                head += 1;
            }
            (*self.cq_khead).store(head, Ordering::Release);
        }
    }
}

impl Drop for LinuxIoUring {
    fn drop(&mut self) {
        unsafe {
            libc::munmap(self.sq_ptr as *mut libc::c_void, self.sq_size);
            libc::munmap(self.cq_ptr as *mut libc::c_void, self.cq_size);
            libc::munmap(self.sqes_ptr as *mut libc::c_void, self.sqes_size);
            libc::close(self.ring_fd);
        }
    }
}

