    capacity: usize,
}

unsafe impl Send for DmaAlignedBuffer {}
unsafe impl Sync for DmaAlignedBuffer {}

impl DmaAlignedBuffer {
    pub fn new(capacity: usize) -> Self {
        assert_eq!(capacity % SECTOR_SIZE, 0);
        let mut raw_ptr: *mut libc::c_void = ptr::null_mut();
        let ret = unsafe { libc::posix_memalign(&mut raw_ptr, SECTOR_SIZE, capacity) };
        assert_eq!(ret, 0, "posix_memalign failed");
        unsafe { ptr::write_bytes(raw_ptr as *mut u8, 0, capacity) };
        Self {
            ptr: raw_ptr as *mut u8,
            capacity,
        }
    }

    #[inline(always)]
    pub fn as_ptr(&self) -> *mut u8 {
        self.ptr
    }

    #[inline(always)]
    pub fn as_slice(&self) -> &[u8] {
        unsafe { std::slice::from_raw_parts(self.ptr, self.capacity) }
    }

    #[inline(always)]
    pub fn as_mut_slice(&mut self) -> &mut [u8] {
        unsafe { std::slice::from_raw_parts_mut(self.ptr, self.capacity) }
    }
