// ============================================================================
// 3. PIPELINED LOCK-FREE GROUP COMMIT WAL
// ============================================================================

const STATE_UNUSED: u32 = 0;
const STATE_QUEUED: u32 = 1;
const STATE_PERSISTED: u32 = 2;

#[repr(align(64))]
pub struct CommitSlot {
    pub state: AtomicU32,
    pub lsn: AtomicU64,
    pub key: u64,
    pub value_len: u32,
    pub value_buf: [u8; 128], // Inline small-payload buffer to avoid dynamic allocation
}

impl Default for CommitSlot {
    fn default() -> Self {
        Self {
            state: AtomicU32::new(STATE_UNUSED),
            lsn: AtomicU64::new(0),
            key: 0,
            value_len: 0,
            value_buf: [0u8; 128],
        }
    }
}

#[repr(align(64))]
pub struct GroupCommitPipeline {
    tail_index: CacheAligned<AtomicUsize>,
    head_index: CacheAligned<AtomicUsize>,
    leader_lock: CacheAligned<AtomicBool>,
    global_lsn: CacheAligned<AtomicU64>,
    persisted_lsn: CacheAligned<AtomicU64>,
    slots: Box<[CommitSlot; MAX_BATCH_ENTRIES]>,
    dma_buffer: UnsafeCell<DmaAlignedBuffer>,
    file_fd: RawFd,
    ring: UnsafeCell<LinuxIoUring>,
    file_offset: CacheAligned<AtomicU64>,
}

unsafe impl Send for GroupCommitPipeline {}
unsafe impl Sync for GroupCommitPipeline {}

impl GroupCommitPipeline {
    pub fn new(wal_file: &File, ring_entries: u32) -> io::Result<Self> {
        let ring = LinuxIoUring::new(ring_entries)?;
        let initial_offset = wal_file.metadata()?.len();

        let mut slots_vec = Vec::with_capacity(MAX_BATCH_ENTRIES);
        for _ in 0..MAX_BATCH_ENTRIES {
            slots_vec.push(CommitSlot::default());
        }
        let boxed_slice = slots_vec.into_boxed_slice();
        let raw_boxed = Box::into_raw(boxed_slice) as *mut [CommitSlot; MAX_BATCH_ENTRIES];
        let slots = unsafe { Box::from_raw(raw_boxed) };

        Ok(Self {
            tail_index: CacheAligned(AtomicUsize::new(0)),
            head_index: CacheAligned(AtomicUsize::new(0)),
            leader_lock: CacheAligned(AtomicBool::new(false)),
            global_lsn: CacheAligned(AtomicU64::new(1)),
            persisted_lsn: CacheAligned(AtomicU64::new(0)),
            slots,
            dma_buffer: UnsafeCell::new(DmaAlignedBuffer::new(MAX_BATCH_BYTES)),
            file_fd: wal_file.as_raw_fd(),
            ring: UnsafeCell::new(ring),
            file_offset: CacheAligned(AtomicU64::new(initial_offset)),
        })
    }

    pub fn append(&self, epoch: u64, key: u64, value: &[u8]) -> io::Result<u64> {
        assert!(value.len() <= 128, "Value exceeds inline buffer threshold");

        // 1. Reserve contiguous slot
        let slot_idx = self.tail_index.fetch_add(1, Ordering::AcqRel) % MAX_BATCH_ENTRIES;
        let slot = &self.slots[slot_idx];

        // Wait if slot is currently being flushed from a previous wrap-around
        while slot.state.load(Ordering::Acquire) != STATE_UNUSED {
            std::hint::spin_loop();
        }

        let lsn = self.global_lsn.fetch_add(1, Ordering::SeqCst);
        unsafe {
            let slot_mut = slot as *const CommitSlot as *mut CommitSlot;
            (*slot_mut).key = key;
            (*slot_mut).value_len = value.len() as u32;
            ptr::copy_nonoverlapping(value.as_ptr(), (*slot_mut).value_buf.as_mut_ptr(), value.len());
        }
        slot.lsn.store(lsn, Ordering::Release);
        slot.state.store(STATE_QUEUED, Ordering::Release);

        // 2. Leader election
        if self.leader_lock.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_ok() {
            self.drive_group_commit(epoch)?;
        } else {
            // 3. Follower path: Futex wait on slot state
            while slot.state.load(Ordering::Acquire) != STATE_PERSISTED {
                unsafe {
                    sys::futex_wait(&slot.state, STATE_QUEUED);
                }
            }
            slot.state.store(STATE_UNUSED, Ordering::Release);
        }

        Ok(lsn)
    }

    fn drive_group_commit(&self, current_epoch: u64) -> io::Result<()> {
        let dma_buf = unsafe { &mut *self.dma_buffer.get() };
        let ring = unsafe { &mut *self.ring.get() };

        let mut batch_bytes = 0usize;
        let mut processed_slots = Vec::with_capacity(MAX_BATCH_ENTRIES);
        let mut max_lsn = 0u64;

        let start_head = self.head_index.load(Ordering::Relaxed);
        let current_tail = self.tail_index.load(Ordering::Acquire);
        let count = current_tail.saturating_sub(start_head).min(MAX_BATCH_ENTRIES);

        for i in 0..count {
            let slot_idx = (start_head + i) % MAX_BATCH_ENTRIES;
            let slot = &self.slots[slot_idx];

            if slot.state.load(Ordering::Acquire) != STATE_QUEUED {
                break;
            }

            let lsn = slot.lsn.load(Ordering::Acquire);
            max_lsn = max_lsn.max(lsn);

            // Serialize record into DMA buffer
            let frame_payload_len = 8 + 4 + slot.value_len as usize; // key + len + val
            let total_frame_len = mem::size_of::<FrameHeader>() + frame_payload_len;

            if batch_bytes + total_frame_len + 8 > MAX_BATCH_BYTES {
                break; // Buffer full
            }

            let mut header = FrameHeader {
                crc32: 0,
                segment_epoch: current_epoch,
                lsn,
                payload_len: frame_payload_len as u32,
                torn_canary: TORN_WRITE_CANARY,
            };

            // Payload assembly
            let payload_offset = batch_bytes + mem::size_of::<FrameHeader>();
            unsafe {
                let dst = dma_buf.as_ptr().add(payload_offset);
                ptr::copy_nonoverlapping(&slot.key as *const u64 as *const u8, dst, 8);
                ptr::copy_nonoverlapping(&slot.value_len as *const u32 as *const u8, dst.add(8), 4);
                ptr::copy_nonoverlapping(slot.value_buf.as_ptr(), dst.add(12), slot.value_len as usize);

                let payload_slice = std::slice::from_raw_parts(dst, frame_payload_len);
                header.crc32 = compute_crc32c(payload_slice);

                ptr::copy_nonoverlapping(
                    &header as *const FrameHeader as *const u8,
                    dma_buf.as_ptr().add(batch_bytes),
                    mem::size_of::<FrameHeader>(),
                );
            }

            batch_bytes += total_frame_len;
            processed_slots.push(slot);
        }

        if batch_bytes > 0 {
            // Align up batch_bytes to SECTOR_SIZE (4096) for O_DIRECT NVMe write
            let aligned_len = (batch_bytes + SECTOR_SIZE - 1) & !(SECTOR_SIZE - 1);
            // Write torn-write canaries at sector boundaries
            let mut sector_cursor = 0;
            while sector_cursor < aligned_len {
                let sector_tail = sector_cursor + SECTOR_SIZE - 8;
                unsafe {
                    ptr::copy_nonoverlapping(
                        &TORN_WRITE_CANARY as *const u64 as *const u8,
                        dma_buf.as_ptr().add(sector_tail),
                        8,
                    );
                }
                sector_cursor += SECTOR_SIZE;
            }

            let write_offset = self.file_offset.fetch_add(aligned_len as u64, Ordering::SeqCst);

            // 1. Prep Write SQE
            let sqe_write = loop {
                if let Some(sqe) = ring.get_sqe() {
                    break sqe;
                }
                ring.submit_and_wait(1)?;
            };
            sqe_write.opcode = IORING_OP_WRITEV;
            sqe_write.fd = self.file_fd;
            sqe_write.off_or_addr2 = write_offset;

            let mut iovec = libc::iovec {
                iov_base: dma_buf.as_ptr() as *mut libc::c_void,
                iov_len: aligned_len,
            };
            sqe_write.addr_or_splice_off_in = &mut iovec as *mut _ as u64;
            sqe_write.len = 1;
            sqe_write.user_data = 0x101;
            sqe_write.flags = 1 << 2; // IOSQE_IO_LINK

            // 2. Prep Fsync SQE
            let sqe_fsync = loop {
                if let Some(sqe) = ring.get_sqe() {
                    break sqe;
                }
                ring.submit_and_wait(1)?;
            };
            sqe_fsync.opcode = IORING_OP_FSYNC;
            sqe_fsync.fd = self.file_fd;
            sqe_fsync.union_flags = IORING_FSYNC_DATASYNC;
            sqe_fsync.user_data = 0x102;

            // Submit both and block until completion
            ring.submit_and_wait(2)?;

            let mut cqes_seen = 0;
            ring.reap_cqes(|cqe| {
                assert!(cqe.res >= 0, "io_uring operation failed with code: {}", cqe.res);
                cqes_seen += 1;
            });
            assert!(cqes_seen >= 2);

            self.persisted_lsn.store(max_lsn, Ordering::Release);
            self.head_index.fetch_add(processed_slots.len(), Ordering::SeqCst);

            // Wake up followers
            for slot in processed_slots {
                slot.state.store(STATE_PERSISTED, Ordering::Release);
                unsafe {
                    sys::futex_wake_all(&slot.state);
                }
            }
        }

        // Leader handoff
        self.leader_lock.store(false, Ordering::Release);

        // If new entries were queued concurrently while finishing batch, elect self again or notify
        if self.tail_index.load(Ordering::Acquire) > self.head_index.load(Ordering::Acquire) {
            if self.leader_lock.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_ok() {
                self.drive_group_commit(current_epoch)?;
            }
        }

        Ok(())
    }
}

// ============================================================================
// 4. CRASH RECOVERY & TORN-WRITE SCANNER
// ============================================================================

pub struct WALScanner;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RecoveredRecord {
    pub epoch: u64,
    pub lsn: u64,
    pub key: u64,
    pub value: Vec<u8>,
}

impl WALScanner {
    pub fn scan_and_recover(wal_path: &str) -> io::Result<(Vec<RecoveredRecord>, u64)> {
        let mut file = OpenOptions::new().read(true).open(wal_path)?;
        let file_len = file.metadata()?.len() as usize;
        let mut buffer = vec![0u8; file_len];
        file.read_exact(&mut buffer)?;

        let mut records = Vec::new();
        let mut offset = 0;
        let mut max_valid_offset = 0u64;

        while offset + mem::size_of::<FrameHeader>() <= file_len {
            let header_slice = &buffer[offset..offset + mem::size_of::<FrameHeader>()];
            let header = unsafe { ptr::read_unaligned(header_slice.as_ptr() as *const FrameHeader) };

            // Check torn canary
            if header.torn_canary != TORN_WRITE_CANARY {
                break; // Detected uninitialized or torn block
            }

            let payload_start = offset + mem::size_of::<FrameHeader>();
            let payload_end = payload_start + header.payload_len as usize;

            if payload_end > file_len {
                break; // Incomplete record at EOF
            }

            let payload = &buffer[payload_start..payload_end];
            let expected_crc = compute_crc32c(payload);

            if expected_crc != header.crc32 {
                break; // CRC mismatch: Corrupt / Torn write
            }

            // Extract Key & Value
            let key = u64::from_ne_bytes(payload[0..8].try_into().unwrap());
            let val_len = u32::from_ne_bytes(payload[8..12].try_into().unwrap()) as usize;
            let val = payload[12..12 + val_len].to_vec();

            records.push(RecoveredRecord {
                epoch: header.segment_epoch,
                lsn: header.lsn,
                key,
                value: val,
            });

            let record_len = mem::size_of::<FrameHeader>() + header.payload_len as usize;
            offset += record_len;
            max_valid_offset = offset as u64;

            // Advance to next 4KB boundary if crossing sector
            let sector_aligned_rem = offset % SECTOR_SIZE;
            if sector_aligned_rem != 0 && (offset + mem::size_of::<FrameHeader>() > (offset + (SECTOR_SIZE - sector_aligned_rem))) {
                offset = (offset + SECTOR_SIZE - 1) & !(SECTOR_SIZE - 1);
            }
        }

        Ok((records, max_valid_offset))
    }
}

// ============================================================================
// 5. LOCK-FREE MVCC & DYNAMIC EPOCH-BASED RECLAMATION (EBR)
// ============================================================================

pub struct VersionNode {
    pub epoch: u64,
    pub lsn: u64,
    pub value: Vec<u8>,
    pub next: AtomicPtr<VersionNode>,
}

const MAX_THREADS: usize = 128;
const EPOCH_INACTIVE: u64 = u64::MAX;

#[repr(align(64))]
struct ThreadEpochState {
    active_epoch: AtomicU64,
    in_use: AtomicBool,
}

pub struct EpochTracker {
    global_epoch: CacheAligned<AtomicU64>,
    thread_states: [ThreadEpochState; MAX_THREADS],
    retired_lists: [CacheAligned<UnsafeCell<Vec<*mut VersionNode>>>; 3],
    gc_lock: AtomicBool,
}

unsafe impl Send for EpochTracker {}
unsafe impl Sync for EpochTracker {}

impl EpochTracker {
    pub fn new() -> Self {
        Self {
            global_epoch: CacheAligned(AtomicU64::new(0)),
            thread_states: std::array::from_fn(|_| ThreadEpochState {
                active_epoch: AtomicU64::new(EPOCH_INACTIVE),
                in_use: AtomicBool::new(false),
            }),
            retired_lists: [
                CacheAligned(UnsafeCell::new(Vec::new())),
                CacheAligned(UnsafeCell::new(Vec::new())),
                CacheAligned(UnsafeCell::new(Vec::new())),
            ],
            gc_lock: AtomicBool::new(false),
        }
    }

    pub fn register_thread(&self) -> usize {
        for (idx, state) in self.thread_states.iter().enumerate() {
            if !state.in_use.swap(true, Ordering::AcqRel) {
                return idx;
            }
        }
        panic!("Maximum EBR thread registry exceeded (128 threads)");
    }

    pub fn unregister_thread(&self, thread_id: usize) {
        self.thread_states[thread_id].active_epoch.store(EPOCH_INACTIVE, Ordering::Release);
        self.thread_states[thread_id].in_use.store(false, Ordering::Release);
    }

    #[inline(always)]
    pub fn enter_read(&self, thread_id: usize) -> u64 {
        let global = self.global_epoch.load(Ordering::Acquire);
        self.thread_states[thread_id].active_epoch.store(global, Ordering::Release);
        fence(Ordering::SeqCst);
        global
    }

    #[inline(always)]
    pub fn exit_read(&self, thread_id: usize) {
        self.thread_states[thread_id].active_epoch.store(EPOCH_INACTIVE, Ordering::Release);
    }

    pub fn retire_node(&self, node: *mut VersionNode) {
        let current = self.global_epoch.load(Ordering::Acquire);
        let list_idx = (current % 3) as usize;
        unsafe {
            // Protected via single GC-coordinator or atomic retire vector
            (*self.retired_lists[list_idx].get()).push(node);
        }
    }

    pub fn try_advance_and_reclaim(&self) {
        if self.gc_lock.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return;
        }

        let curr_epoch = self.global_epoch.load(Ordering::Acquire);

        // Check if any active thread is lingering in (curr_epoch - 1)
        let safe_to_advance = self.thread_states.iter().all(|state| {
            if !state.in_use.load(Ordering::Acquire) {
                return true;
            }
            let active = state.active_epoch.load(Ordering::Acquire);
            active == EPOCH_INACTIVE || active >= curr_epoch
        });

        if safe_to_advance {
            let next_epoch = curr_epoch + 1;
            let reclaim_idx = ((next_epoch + 1) % 3) as usize;

            // Reclaim retired memory from epoch (curr - 2)
            unsafe {
                let list = &mut *self.retired_lists[reclaim_idx].get();
                for node_ptr in list.drain(..) {
                    let _ = Box::from_raw(node_ptr);
                }
            }

            self.global_epoch.store(next_epoch, Ordering::Release);
        }

        self.gc_lock.store(false, Ordering::Release);
    }
}

pub struct MVCCStore {
    buckets: Vec<CacheAligned<AtomicPtr<VersionNode>>>,
    num_buckets: usize,
    pub ebr: Arc<EpochTracker>,
}

impl MVCCStore {
    pub fn new(num_buckets: usize) -> Self {
        let mut buckets = Vec::with_capacity(num_buckets);
        for _ in 0..num_buckets {
            buckets.push(CacheAligned(AtomicPtr::new(ptr::null_mut())));
        }
        Self {
            buckets,
            num_buckets,
            ebr: Arc::new(EpochTracker::new()),
        }
    }

    #[inline(always)]
    fn bucket_for(&self, key: u64) -> &AtomicPtr<VersionNode> {
        let mut x = key;
        x ^= x >> 30;
        x = x.wrapping_mul(0xbf58476d1ce4e5b9);
        x ^= x >> 27;
        x = x.wrapping_mul(0x94d049bb133111eb);
        x ^= x >> 31;
        &self.buckets[(x as usize) % self.num_buckets]
    }

    pub fn insert(&self, key: u64, value: Vec<u8>, lsn: u64, epoch: u64) {
        let bucket = self.bucket_for(key);
        let new_node = Box::into_raw(Box::new(VersionNode {
            epoch,
            lsn,
            value,
            next: AtomicPtr::new(ptr::null_mut()),
        }));

        let mut curr_head = bucket.load(Ordering::Acquire);
        loop {
            unsafe {
                (*new_node).next.store(curr_head, Ordering::Relaxed);
            }
            match bucket.compare_exchange_weak(
                curr_head,
                new_node,
                Ordering::AcqRel,
                Ordering::Acquire,
            ) {
                Ok(_) => break,
                Err(actual) => curr_head = actual,
            }
        }
    }

    pub fn get_at_lsn(&self, key: u64, read_lsn: u64, thread_id: usize) -> Option<Vec<u8>> {
        self.ebr.enter_read(thread_id);

        let bucket = self.bucket_for(key);
        let mut curr = bucket.load(Ordering::Acquire);

        let mut result = None;
        while !curr.is_null() {
            let node = unsafe { &*curr };
            if node.lsn <= read_lsn {
                result = Some(node.value.clone());
                break;
            }
            curr = node.next.load(Ordering::Acquire);
        }

        self.ebr.exit_read(thread_id);
        result
    }

    pub fn prune_older_versions(&self, key: u64, min_active_epoch: u64) {
        let bucket = self.bucket_for(key);
        let mut curr = bucket.load(Ordering::Acquire);

        while !curr.is_null() {
            let node = unsafe { &*curr };
            let next = node.next.load(Ordering::Acquire);

            if !next.is_null() {
                let next_node = unsafe { &*next };
                if next_node.epoch < min_active_epoch {
                    // Unlink chain beyond next
                    let old_tail = next_node.next.swap(ptr::null_mut(), Ordering::AcqRel);
                    if !old_tail.is_null() {
                        self.retire_chain(old_tail);
                    }
                    break;
                }
            }
            curr = next;
        }
    }

    fn retire_chain(&self, mut head: *mut VersionNode) {
        while !head.is_null() {
            let next = unsafe { (*head).next.load(Ordering::Relaxed) };
            self.ebr.retire_node(head);
            head = next;
        }
    }
}

impl Drop for MVCCStore {
    fn drop(&mut self) {
        for bucket in &self.buckets {
            let mut curr = bucket.load(Ordering::Relaxed);
            while !curr.is_null() {
                let next = unsafe { (*curr).next.load(Ordering::Relaxed) };
                let _ = unsafe { Box::from_raw(curr) };
                curr = next;
            }
        }
    }
}

// ============================================================================
// 6. ENGINE ORCHESTRATOR
// ============================================================================

pub struct Engine {
    wal: Arc<GroupCommitPipeline>,
    store: Arc<MVCCStore>,
}

impl Engine {
    pub fn open(wal_path: &str) -> io::Result<Self> {
        let wal_file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .custom_flags(libc::O_DIRECT | libc::O_DSYNC)
            .open(wal_path)?;

        let wal = Arc::new(GroupCommitPipeline::new(&wal_file, 256)?);
        let store = Arc::new(MVCCStore::new(65536));

        Ok(Self { wal, store })
    }

    pub fn put(&self, key: u64, value: &[u8], thread_id: usize) -> io::Result<u64> {
        let epoch = self.store.ebr.global_epoch.load(Ordering::Acquire);
        let lsn = self.wal.append(epoch, key, value)?;
        self.store.insert(key, value.to_vec(), lsn, epoch);
        self.store.ebr.try_advance_and_reclaim();
        Ok(lsn)
    }

    pub fn get(&self, key: u64, read_lsn: u64, thread_id: usize) -> Option<Vec<u8>> {
        self.store.get_at_lsn(key, read_lsn, thread_id)
    }
}

