// ============================================================================

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Barrier;
    use std::thread;

    #[test]
    fn test_lock_free_group_commit_concurrency() {
        let wal_path = "/tmp/wal_group_commit_test.log";
        let _ = std::fs::remove_file(wal_path);

        let engine = Arc::new(Engine::open(wal_path).expect("Failed to initialize engine"));
        let num_threads = 8;
        let ops_per_thread = 500;
        let barrier = Arc::new(Barrier::new(num_threads));

        let mut handles = Vec::new();
        for t_idx in 0..num_threads {
            let engine_cloned = Arc::clone(&engine);
            let barrier_cloned = Arc::clone(&barrier);

            handles.push(thread::spawn(move || {
                let tid = engine_cloned.store.ebr.register_thread();
                barrier_cloned.wait();

                for i in 0..ops_per_thread {
                    let key = (t_idx * ops_per_thread + i) as u64;
                    let val = format!("val-{}-{}", t_idx, i);
                    let lsn = engine_cloned.put(key, val.as_bytes(), tid).unwrap();
                    assert!(lsn > 0);
                }

                engine_cloned.store.ebr.unregister_thread(tid);
            }));
        }

        for h in handles {
            h.join().unwrap();
        }

        let persisted = engine.wal.persisted_lsn.load(Ordering::Acquire);
        assert_eq!(persisted, (num_threads * ops_per_thread) as u64);
        let _ = std::fs::remove_file(wal_path);
    }

    #[test]
    fn test_torn_write_and_recovery_truncation() {
        let wal_path = "/tmp/wal_torn_write_test.log";
        let _ = std::fs::remove_file(wal_path);

        {
            let engine = Engine::open(wal_path).expect("Engine open fail");
            let tid = engine.store.ebr.register_thread();
            for i in 1..=50 {
                let val = format!("payload-{}", i);
                engine.put(i as u64, val.as_bytes(), tid).unwrap();
            }
            engine.store.ebr.unregister_thread(tid);
        }

        // Corrupt file tail to simulate power outage mid-block
        {
            let mut file = OpenOptions::new().write(true).open(wal_path).unwrap();
            let len = file.metadata().unwrap().len();
            // Corrupt last 128 bytes
            file.seek(SeekFrom::Start(len - 128)).unwrap();
            let junk = [0xAAu8; 128];
            use std::io::Write;
            file.write_all(&junk).unwrap();
            file.sync_all().unwrap();
        }

        // Recover
        let (records, valid_offset) = WALScanner::scan_and_recover(wal_path).unwrap();
        assert!(!records.is_empty(), "Must recover valid entries prior to tear point");
        assert!(valid_offset > 0);

        // Verify deterministic state reconstruction
        let reconstructed_store = MVCCStore::new(1024);
        for rec in records {
            reconstructed_store.insert(rec.key, rec.value, rec.lsn, rec.epoch);
        }

        let tid = reconstructed_store.ebr.register_thread();
        let val = reconstructed_store.get_at_lsn(1, 100, tid).unwrap();
        assert_eq!(val, b"payload-1");
        reconstructed_store.ebr.unregister_thread(tid);

        let _ = std::fs::remove_file(wal_path);
    }
