// POSIX & Linux System Headers
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <sys/syscall.h>
#include <linux/io_uring.h>

// Hardware-destructive interference size (Cache line: 64B)
constexpr size_t CACHE_LINE_SIZE = 64;
constexpr size_t SECTOR_SIZE = 4096;
constexpr uint32_t TORN_WRITE_MAGIC = 0x544F524EU; // "TORN"

// ============================================================================
// 1. HARDWARE-ACCELERATED / FALLBACK CRC32C (Castagnoli)
// ============================================================================
namespace CRC32C {
    static constexpr uint32_t CRC32C_POLYNOMIAL = 0x82F63B78;

    static constinit const auto TABLE = []() consteval {
        std::array<uint32_t, 256> table{};
        for (uint32_t i = 0; i < 256; ++i) {
            uint32_t crc = i;
            for (int j = 0; j < 8; ++j) {
                if (crc & 1) crc = (crc >> 1) ^ CRC32C_POLYNOMIAL;
                else crc >>= 1;
            }
            table[i] = crc;
        }
        return table;
    }();

    inline uint32_t Compute(const uint8_t* data, size_t length, uint32_t initial = 0xFFFFFFFF) {
        uint32_t crc = initial;
#if defined(__x86_64__) && defined(__SSE4_2__)
        size_t idx = 0;
        while (idx + 8 <= length) {
            uint64_t val;
            std::memcpy(&val, data + idx, 8);
            crc = static_cast<uint32_t>(__builtin_ia32_crc32di(crc, val));
            idx += 8;
        }
        while (idx < length) {
            crc = static_cast<uint32_t>(__builtin_ia32_crc32qi(crc, data[idx]));
            idx++;
        }
#else
        for (size_t i = 0; i < length; ++i) {
            uint8_t table_idx = static_cast<uint8_t>((crc ^ data[i]) & 0xFF);
            crc = (crc >> 8) ^ TABLE[table_idx];
        }
#endif
        return crc ^ 0xFFFFFFFF;
    }
}

// ============================================================================
// 2. WAL BINARY FRAME DEFINITIONS & MEMORY LAYOUT
// ============================================================================
#pragma pack(push, 1)
struct WALFrameHeader {
    uint32_t crc32c;           // Castagnoli CRC32C across header + payload
    uint32_t segment_epoch;    // Monotonic Epoch ID
    uint64_t lsn;              // Logical Sequence Number
    uint32_t payload_len;      // Length of following Key/Value bytes
};

struct WALFrameTrailer {
    uint32_t torn_write_tag;   // Sector torn write validation tag
};
#pragma pack(pop)

static_assert(sizeof(WALFrameHeader) == 20, "WALFrameHeader must be exactly 20 bytes");
static_assert(sizeof(WALFrameTrailer) == 4, "WALFrameTrailer must be exactly 4 bytes");

// Helper to compute torn write tag based on epoch and LSN
inline uint32_t ComputeTornWriteTag(uint32_t epoch, uint64_t lsn) {
    return TORN_WRITE_MAGIC ^ epoch ^ static_cast<uint32_t>(lsn & 0xFFFFFFFF) ^ static_cast<uint32_t>(lsn >> 32);
}

// ============================================================================
// 3. ZERO-ALLOCATION LOCK-FREE DMA RING BUFFER & IO_URING DRIVER
// ============================================================================
struct IOURingParamsWrapper {
    static int Setup(unsigned entries, struct io_uring_params* p) {
        return static_cast<int>(syscall(SYS_io_uring_setup, entries, p));
    }
    static int Enter(int fd, unsigned to_submit, unsigned min_complete, unsigned flags, sigset_t* sig) {
        return static_cast<int>(syscall(SYS_io_uring_enter, fd, to_submit, min_complete, flags, sig, _NSIG / 8));
    }
};

class DirectIOURingWAL {
public:
    static constexpr size_t RING_CAPACITY = 16 * 1024 * 1024; // 16 MB Pre-allocated Buffer
    static constexpr unsigned URING_QUEUE_DEPTH = 512;

private:
    int fd_{-1};
    int ring_fd_{-1};

    // io_uring memory mapping pointers
    void* sq_ptr_{nullptr};
    void* cq_ptr_{nullptr};
    void* sqes_ptr_{nullptr};

    uint32_t* sq_khead_{nullptr};
    uint32_t* sq_ktail_{nullptr};
    uint32_t* sq_kflags_{nullptr};
    uint32_t* sq_karray_{nullptr};
    struct io_uring_sqe* sqes_{nullptr};

    uint32_t* cq_khead_{nullptr};
    uint32_t* cq_ktail_{nullptr};
    struct io_uring_cqe* cqes_{nullptr};
    unsigned sq_mask_{0};
    unsigned cq_mask_{0};

    // Pre-allocated DMA Page-aligned Memory
    uint8_t* dma_buffer_{nullptr};

    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> reserved_offset_{0};
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> flushed_offset_{0};
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> committed_lsn_{0};
    alignas(CACHE_LINE_SIZE) std::atomic<bool> leader_active_{false};

    uint32_t segment_epoch_{1};

public:
    DirectIOURingWAL(const std::string& path, uint32_t epoch) : segment_epoch_(epoch) {
        // Open file with O_DIRECT | O_SYNC | O_RDWR | O_CREAT
        fd_ = open(path.c_str(), O_DIRECT | O_DSYNC | O_RDWR | O_CREAT | O_TRUNC, 0644);
        if (fd_ < 0) {
            // Fallback without O_DIRECT if direct I/O is not supported on host filesystem
            fd_ = open(path.c_str(), O_RDWR | O_CREAT | O_TRUNC, 0644);
            if (fd_ < 0) {
                throw std::runtime_error("Failed to open WAL file: " + std::string(strerror(errno)));
            }
        }

        // Allocate Page-Aligned DMA Ring Buffer
        if (posix_memalign(reinterpret_cast<void**>(&dma_buffer_), SECTOR_SIZE, RING_CAPACITY) != 0) {
            throw std::bad_alloc();
        }
        std::memset(dma_buffer_, 0, RING_CAPACITY);

        // Initialize io_uring
        struct io_uring_params p{};
        ring_fd_ = IOURingParamsWrapper::Setup(URING_QUEUE_DEPTH, &p);
        if (ring_fd_ < 0) {
            // Fallback for non-Linux or systems without io_uring syscall configured
            std::cerr << "[WARN] io_uring_setup failed (" << strerror(errno) 
                      << "). Using synchronous Direct-I/O fallback." << std::endl;
            ring_fd_ = -1;
        } else {
            // Map Submission Queue
            size_t sq_size = p.sq_off.array + p.sq_entries * sizeof(uint32_t);
            sq_ptr_ = mmap(0, sq_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_POPULATE, ring_fd_, IORING_OFF_SQ_RING);
            size_t sqes_size = p.sq_entries * sizeof(struct io_uring_sqe);
            sqes_ptr_ = mmap(0, sqes_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_POPULATE, ring_fd_, IORING_OFF_SQES);

            // Map Completion Queue
            size_t cq_size = p.cq_off.cqes + p.cq_entries * sizeof(struct io_uring_cqe);
            cq_ptr_ = mmap(0, cq_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_POPULATE, ring_fd_, IORING_OFF_CQ_RING);

            sq_khead_ = reinterpret_cast<uint32_t*>(static_cast<uint8_t*>(sq_ptr_) + p.sq_off.head);
            sq_ktail_ = reinterpret_cast<uint32_t*>(static_cast<uint8_t*>(sq_ptr_) + p.sq_off.tail);
            sq_kflags_ = reinterpret_cast<uint32_t*>(static_cast<uint8_t*>(sq_ptr_) + p.sq_off.flags);
            sq_karray_ = reinterpret_cast<uint32_t*>(static_cast<uint8_t*>(sq_ptr_) + p.sq_off.array);
            sqes_ = static_cast<struct io_uring_sqe*>(sqes_ptr_);

            cq_khead_ = reinterpret_cast<uint32_t*>(static_cast<uint8_t*>(cq_ptr_) + p.cq_off.head);
            cq_ktail_ = reinterpret_cast<uint32_t*>(static_cast<uint8_t*>(cq_ptr_) + p.cq_off.tail);
            cqes_ = static_cast<struct io_uring_cqe*>(static_cast<uint8_t*>(cq_ptr_) + p.cq_off.cqes);

            sq_mask_ = p.sq_entries - 1;
            cq_mask_ = p.cq_entries - 1;
        }
    }

    ~DirectIOURingWAL() {
        if (ring_fd_ >= 0) {
            if (sq_ptr_) munmap(sq_ptr_, 0);
            if (sqes_ptr_) munmap(sqes_ptr_, 0);
            if (cq_ptr_) munmap(cq_ptr_, 0);
            close(ring_fd_);
        }
        if (fd_ >= 0) {
            close(fd_);
        }
        if (dma_buffer_) {
            free(dma_buffer_);
        }
    }

    // Direct synchronous fallback submit or io_uring async submit
    void SubmitIOUringDirect(uint64_t from_offset, size_t write_size) {
        if (ring_fd_ < 0) {
            // Direct Synchronous Fallback
            pwrite(fd_, dma_buffer_ + from_offset, write_size, from_offset);
            return;
        }

        uint32_t tail = *sq_ktail_;
        uint32_t index = tail & sq_mask_;
        struct io_uring_sqe* sqe = &sqes_[index];
        std::memset(sqe, 0, sizeof(*sqe));

        sqe->opcode = IORING_OP_WRITE;
        sqe->fd = fd_;
        sqe->addr = reinterpret_cast<uint64_t>(dma_buffer_ + from_offset);
        sqe->len = static_cast<uint32_t>(write_size);
        sqe->off = from_offset;
        sqe->user_data = from_offset + write_size;

        sq_karray_[index] = index;
        tail++;
        std::atomic_thread_fence(std::memory_order_release);
        *sq_ktail_ = tail;

        int submitted = IOURingParamsWrapper::Enter(ring_fd_, 1, 1, IORING_ENTER_GETEVENTS, nullptr);
        if (submitted < 0) {
            // Gracefully fallback to synchronous pwrite
            pwrite(fd_, dma_buffer_ + from_offset, write_size, from_offset);
            return;
        }

        // Reap CQE
        uint32_t cq_head = *cq_khead_;
        if (cq_head != *cq_ktail_) {
            // uint32_t cq_idx = cq_head & cq_mask_;
            // Reaped completion successfully
            cq_head++;
            std::atomic_thread_fence(std::memory_order_release);
            *cq_khead_ = cq_head;
        }
    }

    // Pipelined Group Commit Entry Point
    uint64_t AppendAndCommit(uint64_t lsn, std::span<const uint8_t> payload) {
        const size_t raw_frame_size = sizeof(WALFrameHeader) + payload.size() + sizeof(WALFrameTrailer);
        // Pad each record internally to 8-byte alignment
        const size_t aligned_frame_size = (raw_frame_size + 7) & ~7ULL;

        // Reserve space in the DMA buffer atomically
        uint64_t my_offset = reserved_offset_.fetch_add(aligned_frame_size, std::memory_order_acq_rel);
        if (my_offset + aligned_frame_size > RING_CAPACITY) {
            throw std::runtime_error("WAL Ring Buffer capacity exceeded in flight!");
        }

        // Format Binary Frame into Page-Aligned DMA memory
        WALFrameHeader header;
        header.segment_epoch = segment_epoch_;
        header.lsn = lsn;
        header.payload_len = static_cast<uint32_t>(payload.size());

        // Compute checksum over header (without crc field) + payload
        uint32_t partial_crc = CRC32C::Compute(
            reinterpret_cast<const uint8_t*>(&header) + sizeof(uint32_t),
            sizeof(WALFrameHeader) - sizeof(uint32_t)
        );
        header.crc32c = CRC32C::Compute(payload.data(), payload.size(), partial_crc ^ 0xFFFFFFFF);

        WALFrameTrailer trailer;
        trailer.torn_write_tag = ComputeTornWriteTag(segment_epoch_, lsn);

        // Copy into pre-allocated DMA ring buffer
        std::memcpy(dma_buffer_ + my_offset, &header, sizeof(WALFrameHeader));
        std::memcpy(dma_buffer_ + my_offset + sizeof(WALFrameHeader), payload.data(), payload.size());
        std::memcpy(dma_buffer_ + my_offset + sizeof(WALFrameHeader) + payload.size(), &trailer, sizeof(WALFrameTrailer));

        // Pipelined Leader Election Loop
        while (committed_lsn_.load(std::memory_order_acquire) < lsn) {
            bool expected = false;
            if (leader_active_.compare_exchange_weak(expected, true, std::memory_order_acq_rel, std::memory_order_relaxed)) {
                // ELECTED LEADER: Group commit all bytes reserved up to this instant
                uint64_t target_offset = reserved_offset_.load(std::memory_order_acquire);
                uint64_t start_offset = flushed_offset_.load(std::memory_order_relaxed);

                if (target_offset > start_offset) {
                    size_t bytes_to_flush = target_offset - start_offset;
                    // Sector-align flush size for O_DIRECT compliance
                    size_t aligned_flush_size = (bytes_to_flush + SECTOR_SIZE - 1) & ~(SECTOR_SIZE - 1);

                    SubmitIOUringDirect(start_offset, aligned_flush_size);
                    flushed_offset_.store(target_offset, std::memory_order_release);
                }

                // Publish newly committed LSN and release leader role
                committed_lsn_.store(lsn, std::memory_order_release);
                leader_active_.store(false, std::memory_order_release);

                // Wake followers
                committed_lsn_.notify_all();
                break;
            } else {
                // FOLLOWER: Atomic wait on committed_lsn_
                uint64_t cur_committed = committed_lsn_.load(std::memory_order_acquire);
                if (cur_committed >= lsn) {
                    break;
                }
                committed_lsn_.wait(cur_committed, std::memory_order_relaxed);
            }
        }

        return lsn;
    }

    uint64_t GetCommittedLSN() const noexcept {
        return committed_lsn_.load(std::memory_order_acquire);
    }
};

// ============================================================================
// 4. CONCURRENT MVCC VERSION STORE WITH EPOCH-BASED RECLAMATION (EBR)
// ============================================================================
struct VersionNode {
    uint64_t commit_lsn;
    uint64_t epoch;
    std::string key;
    std::string value;
    std::atomic<VersionNode*> prev{nullptr};

    VersionNode(uint64_t lsn, uint64_t ep, std::string k, std::string v)
        : commit_lsn(lsn), epoch(ep), key(std::move(k)), value(std::move(v)), prev(nullptr) {}
};

// Thread-Local EBR Registration Node
struct alignas(CACHE_LINE_SIZE) ThreadEpochNode {
    std::atomic<uint64_t> local_epoch{0};
    std::atomic<bool> active{false};
    std::atomic<ThreadEpochNode*> next{nullptr};
    std::thread::id tid;

    ThreadEpochNode() : tid(std::this_thread::get_id()) {}
};

class EpochReclamationManager {
private:
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> global_epoch_{1};
    alignas(CACHE_LINE_SIZE) std::atomic<ThreadEpochNode*> thread_list_head_{nullptr};

    // Multi-Epoch Limbo Bags (Bucketed by epoch % 3)
    struct LimboBag {
        std::mutex mtx;
        std::vector<VersionNode*> nodes;
    };
    std::array<LimboBag, 3> limbo_bags_;

public:
    static EpochReclamationManager& Instance() {
        static EpochReclamationManager mgr;
        return mgr;
    }

    void RegisterThread(ThreadEpochNode* node) {
        ThreadEpochNode* current_head = thread_list_head_.load(std::memory_order_relaxed);
        do {
            node->next.store(current_head, std::memory_order_relaxed);
        } while (!thread_list_head_.compare_exchange_weak(
            current_head, node, std::memory_order_release, std::memory_order_relaxed));
    }

    void DeregisterThread(ThreadEpochNode* target) {
        target->active.store(false, std::memory_order_release);
        // Retain node in linked list; it will be skipped during epoch scans
    }

    uint64_t EnterReader(ThreadEpochNode* node) {
        uint64_t ep = global_epoch_.load(std::memory_order_relaxed);
        node->local_epoch.store(ep, std::memory_order_seq_cst);
        node->active.store(true, std::memory_order_seq_cst);
        return ep;
    }

    void ExitReader(ThreadEpochNode* node) {
        node->active.store(false, std::memory_order_release);
    }

    void RetireNode(VersionNode* node, uint64_t epoch) {
        size_t bag_idx = epoch % 3;
        std::lock_guard<std::mutex> lock(limbo_bags_[bag_idx].mtx);
        limbo_bags_[bag_idx].nodes.push_back(node);
    }

    void TryAdvanceAndReclaim() {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        uint64_t min_active_epoch = cur_epoch;

        ThreadEpochNode* curr = thread_list_head_.load(std::memory_order_acquire);
        while (curr != nullptr) {
            if (curr->active.load(std::memory_order_acquire)) {
                uint64_t th_epoch = curr->local_epoch.load(std::memory_order_acquire);
                if (th_epoch < min_active_epoch) {
                    min_active_epoch = th_epoch;
                }
            }
            curr = curr->next.load(std::memory_order_relaxed);
        }

        // If all active threads have caught up, advance epoch and drain safe limbo bag
        if (min_active_epoch == cur_epoch) {
            global_epoch_.fetch_add(1, std::memory_order_acq_rel);
            uint64_t safe_reclaim_epoch = cur_epoch > 1 ? cur_epoch - 1 : 0;
            size_t safe_bag_idx = safe_reclaim_epoch % 3;

            std::vector<VersionNode*> to_free;
            {
                std::lock_guard<std::mutex> lock(limbo_bags_[safe_bag_idx].mtx);
                to_free.swap(limbo_bags_[safe_bag_idx].nodes);
            }
            for (auto* n : to_free) {
                delete n;
            }
        }
    }

    uint64_t GetGlobalEpoch() const noexcept {
        return global_epoch_.load(std::memory_order_relaxed);
    }
};

// Thread-Local RAII Registration and Reader Guard
class ThreadEpochContext {
private:
    ThreadEpochNode node_;

public:
    ThreadEpochContext() {
        EpochReclamationManager::Instance().RegisterThread(&node_);
    }
    ~ThreadEpochContext() {
        EpochReclamationManager::Instance().DeregisterThread(&node_);
    }

    ThreadEpochNode* GetNode() { return &node_; }

    static ThreadEpochContext& Get() {
        static thread_local ThreadEpochContext instance;
        return instance;
    }
};

class EpochGuard {
private:
    ThreadEpochNode* node_;
public:
    EpochGuard() : node_(ThreadEpochContext::Get().GetNode()) {
        EpochReclamationManager::Instance().EnterReader(node_);
    }
    ~EpochGuard() {
        EpochReclamationManager::Instance().ExitReader(node_);
    }
};

// ============================================================================
// 5. LOCK-FREE MVCC IN-MEMORY VERSION STORE
// ============================================================================
class MVCCStore {
private:
    struct alignas(CACHE_LINE_SIZE) IndexBucket {
        std::mutex bucket_mtx;
        std::vector<std::pair<std::string, std::atomic<VersionNode*>>> items;
    };

    static constexpr size_t NUM_BUCKETS = 1024;
    std::array<IndexBucket, NUM_BUCKETS> table_;

    size_t HashKey(const std::string& key) const {
        return std::hash<std::string>{}(key) % NUM_BUCKETS;
    }

public:
    MVCCStore() = default;
    ~MVCCStore() {
        for (auto& bucket : table_) {
            for (auto& [k, head_atomic] : bucket.items) {
                VersionNode* curr = head_atomic.load(std::memory_order_relaxed);
                while (curr) {
                    VersionNode* next = curr->prev.load(std::memory_order_relaxed);
                    delete curr;
                    curr = next;
                }
            }
        }
    }

    // Wait-Free Multi-Version Snapshot Read
    std::optional<std::string> Get(const std::string& key, uint64_t read_lsn) {
        EpochGuard guard; // Wait-free EBR guard
        size_t b_idx = HashKey(key);
        auto& bucket = table_[b_idx];

        // Traverse bucket array
        std::atomic<VersionNode*>* version_head = nullptr;
        {
            // Read-side index search
            std::lock_guard<std::mutex> lock(bucket.bucket_mtx);
            for (auto& item : bucket.items) {
                if (item.first == key) {
                    version_head = &item.second;
                    break;
                }
            }
        }

        if (!version_head) return std::nullopt;

        // Traverse Version Chain Lock-Free (Acquire semantics)
        VersionNode* curr = version_head->load(std::memory_order_acquire);
        while (curr != nullptr) {
            if (curr->commit_lsn <= read_lsn) {
                return curr->value;
            }
            curr = curr->prev.load(std::memory_order_acquire);
        }

        return std::nullopt;
    }

    // Atomic Version Prepend (Release Semantics)
    void Put(const std::string& key, const std::string& value, uint64_t lsn, uint64_t epoch) {
        size_t b_idx = HashKey(key);
        auto& bucket = table_[b_idx];

        std::atomic<VersionNode*>* target_chain = nullptr;
        {
            std::lock_guard<std::mutex> lock(bucket.bucket_mtx);
            for (auto& item : bucket.items) {
                if (item.first == key) {
                    target_chain = &item.second;
                    break;
                }
            }
            if (!target_chain) {
                bucket.items.emplace_back(key, nullptr);
                target_chain = &bucket.items.back().second;
            }
        }

        // Allocate and atomically prepend VersionNode
        auto* new_node = new VersionNode(lsn, epoch, key, value);
        VersionNode* old_head = target_chain->load(std::memory_order_relaxed);
        do {
            new_node->prev.store(old_head, std::memory_order_relaxed);
        } while (!target_chain->compare_exchange_weak(
            old_head, new_node, std::memory_order_release, std::memory_order_relaxed));
    }

    // Garbage Collection Pruning: Retires nodes hidden behind the oldest active snapshot
    void PruneOlderVersions(const std::string& key, uint64_t horizon_lsn) {
        size_t b_idx = HashKey(key);
        auto& bucket = table_[b_idx];

        std::lock_guard<std::mutex> lock(bucket.bucket_mtx);
        for (auto& item : bucket.items) {
            if (item.first == key) {
                VersionNode* curr = item.second.load(std::memory_order_acquire);
                VersionNode* prev_valid = nullptr;
                bool passed_horizon = false;

                while (curr != nullptr) {
                    VersionNode* next = curr->prev.load(std::memory_order_acquire);
                    if (passed_horizon) {
                        // Unlink and retire to EBR
                        if (prev_valid) {
                            prev_valid->prev.store(nullptr, std::memory_order_release);
                        }
                        EpochReclamationManager::Instance().RetireNode(curr, curr->epoch);
                    } else if (curr->commit_lsn <= horizon_lsn) {
                        passed_horizon = true;
                        prev_valid = curr;
                    } else {
                        prev_valid = curr;
                    }
                    curr = next;
                }
                break;
            }
        }
    }
};

// ============================================================================
// 6. CRASH-CONSISTENCY & DETERMINISTIC WAL RECOVERY SCANNER
// ============================================================================
class WALScanner {
public:
    struct RecoveredRecord {
        uint64_t lsn;
        uint32_t epoch;
        std::string key;
        std::string value;
    };

    static std::vector<RecoveredRecord> Recover(const std::string& path, uint64_t* max_valid_lsn_out = nullptr) {
        std::vector<RecoveredRecord> recovered;
        int fd = open(path.c_str(), O_RDONLY);
        if (fd < 0) return recovered;

        struct stat st{};
        if (fstat(fd, &st) != 0 || st.st_size == 0) {
            close(fd);
            return recovered;
        }

        size_t file_size = static_cast<size_t>(st.st_size);
        uint8_t* mapped = static_cast<uint8_t*>(mmap(nullptr, file_size, PROT_READ, MAP_PRIVATE, fd, 0));
        if (mapped == MAP_FAILED) {
            close(fd);
            return recovered;
        }

        size_t offset = 0;
        uint64_t last_valid_lsn = 0;
        size_t valid_bytes_boundary = 0;

        while (offset + sizeof(WALFrameHeader) + sizeof(WALFrameTrailer) <= file_size) {
            WALFrameHeader header;
            std::memcpy(&header, mapped + offset, sizeof(WALFrameHeader));

            // Stop at unwritten / zeroed sectors
            if (header.lsn == 0 || header.payload_len == 0 || header.payload_len > 1024 * 1024) {
                break;
            }

            size_t raw_frame_size = sizeof(WALFrameHeader) + header.payload_len + sizeof(WALFrameTrailer);
            size_t aligned_frame_size = (raw_frame_size + 7) & ~7ULL;

            if (offset + raw_frame_size > file_size) {
                // Partial frame cut off by crash
                break;
            }

            const uint8_t* payload_ptr = mapped + offset + sizeof(WALFrameHeader);

            // 1. Verify CRC32C
            uint32_t partial_crc = CRC32C::Compute(
                reinterpret_cast<const uint8_t*>(&header) + sizeof(uint32_t),
                sizeof(WALFrameHeader) - sizeof(uint32_t)
            );
            uint32_t computed_crc = CRC32C::Compute(payload_ptr, header.payload_len, partial_crc ^ 0xFFFFFFFF);

            if (computed_crc != header.crc32c) {
                std::cerr << "[RECOVERY] CRC32C Mismatch at offset " << offset 
                          << "! Halting at last consistent transaction." << std::endl;
                break;
            }

            // 2. Verify Sector Torn-Write Tag
            WALFrameTrailer trailer;
            std::memcpy(&trailer, mapped + offset + sizeof(WALFrameHeader) + header.payload_len, sizeof(WALFrameTrailer));
            uint32_t expected_tag = ComputeTornWriteTag(header.segment_epoch, header.lsn);

            if (trailer.torn_write_tag != expected_tag) {
                std::cerr << "[RECOVERY] Torn-Write detected at LSN " << header.lsn << "! Truncating corrupt tail." << std::endl;
                break;
            }

            // Deserialize Key/Value Payload (Encoded as [2B KeyLen | Key | Val])
            if (header.payload_len >= 2) {
                uint16_t key_len = 0;
                std::memcpy(&key_len, payload_ptr, sizeof(uint16_t));
                if (sizeof(uint16_t) + key_len <= header.payload_len) {
                    std::string k(reinterpret_cast<const char*>(payload_ptr + 2), key_len);
                    std::string v(reinterpret_cast<const char*>(payload_ptr + 2 + key_len), header.payload_len - 2 - key_len);
                    recovered.push_back({header.lsn, header.segment_epoch, std::move(k), std::move(v)});
                }
            }

            last_valid_lsn = header.lsn;
            offset += aligned_frame_size;
            valid_bytes_boundary = offset;
        }

        munmap(mapped, file_size);
        close(fd);

        // Deterministically truncate corrupt or zeroed tails
        if (valid_bytes_boundary < file_size && valid_bytes_boundary > 0) {
            int trunc_fd = open(path.c_str(), O_RDWR);
            if (trunc_fd >= 0) {
                ftruncate(trunc_fd, valid_bytes_boundary);
                close(trunc_fd);
            }
        }

        if (max_valid_lsn_out) *max_valid_lsn_out = last_valid_lsn;
        return recovered;
    }
};

