// 7. HIGH-LEVEL STORAGE ENGINE
// ============================================================================
class StorageEngine {
private:
    std::string wal_path_;
    uint32_t epoch_;
    std::unique_ptr<DirectIOURingWAL> wal_;
    MVCCStore mvcc_;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> next_lsn_{1};

public:
    StorageEngine(const std::string& wal_path, uint32_t epoch = 1)
        : wal_path_(wal_path), epoch_(epoch) {

        // Deterministic Recovery on Startup
        uint64_t recovered_lsn = 0;
        auto records = WALScanner::Recover(wal_path_, &recovered_lsn);
        for (const auto& rec : records) {
            mvcc_.Put(rec.key, rec.value, rec.lsn, rec.epoch);
        }
        next_lsn_.store(recovered_lsn + 1, std::memory_order_relaxed);

        wal_ = std::make_unique<DirectIOURingWAL>(wal_path_, epoch_);
    }

    // Atomic Transaction Commit
    uint64_t Put(const std::string& key, const std::string& value) {
        uint64_t lsn = next_lsn_.fetch_add(1, std::memory_order_acq_rel);
        uint64_t cur_epoch = EpochReclamationManager::Instance().GetGlobalEpoch();

        // Encode binary payload: [uint16_t key_len | key_bytes | val_bytes]
        std::vector<uint8_t> payload(sizeof(uint16_t) + key.size() + value.size());
        uint16_t klen = static_cast<uint16_t>(key.size());
        std::memcpy(payload.data(), &klen, sizeof(uint16_t));
        std::memcpy(payload.data() + sizeof(uint16_t), key.data(), key.size());
        std::memcpy(payload.data() + sizeof(uint16_t) + key.size(), value.data(), value.size());

        // 1. Persist to WAL via Pipelined io_uring Group Commit
        wal_->AppendAndCommit(lsn, payload);

        // 2. Publish to In-Memory MVCC Store
        mvcc_.Put(key, value, lsn, cur_epoch);

        // 3. Periodic EBR advance
        if (lsn % 100 == 0) {
            EpochReclamationManager::Instance().TryAdvanceAndReclaim();
            mvcc_.PruneOlderVersions(key, lsn - 50);
        }

        return lsn;
    }

    std::optional<std::string> Get(const std::string& key, uint64_t read_lsn) {
        return mvcc_.Get(key, read_lsn);
    }

    uint64_t GetCommittedLSN() const noexcept {
        return wal_->GetCommittedLSN();
    }
};

