struct io_uring_params {
    sq_entries: u32,
    cq_entries: u32,
    flags: u32,
    sq_thread_cpu: u32,
    sq_thread_idle: u32,
    features: u32,
    wq_fd: u32,
    resv: [u32; 3],
    sq_off: io_sqring_offsets,
    cq_off: io_cqring_offsets,
}

const IORING_OP_WRITE: u8 = 23;
const IORING_OP_FSYNC: u8 = 3;
const IORING_FSYNC_DATASYNC: u32 = 1;
const SYS_IO_URING_SETUP: libc::c_long = 425;
const SYS_IO_URING_ENTER: libc::c_long = 426;

pub struct DirectIoUring {
    ring_fd: RawFd,
    sq_khead: *mut u32,
    sq_ktail: *mut u32,
    sq_kmask: *mut u32,
    sq_entries: *mut u32,
    sq_kflags: *mut u32,
    sq_array: *mut u32,
    sqes: *mut io_uring_sqe,
    cq_khead: *mut u32,
    cq_ktail: *mut u32,
    cq_kmask: *mut u32,
    cqes: *mut io_uring_cqe,
    ring_sz: usize,
    sqes_sz: usize,
    cq_sz: usize,
    ring_ptr: *mut libc::c_void,
    cq_ptr: *mut libc::c_void,
    sqes_ptr: *mut libc::c_void,
}

unsafe impl Send for DirectIoUring {}
unsafe impl Sync for DirectIoUring {}

impl DirectIoUring {
    pub fn new(entries: u32) -> io::Result<Self> {
        let mut params: io_uring_params = unsafe { std::mem::zeroed() };
        let ring_fd = unsafe {
            libc::syscall(
                SYS_IO_URING_SETUP,
                entries as libc::c_uint,
                &mut params as *mut io_uring_params,
            ) as RawFd
        };
        if ring_fd < 0 {
            return Err(io::Error::last_os_error());
        }

        let sq_ring_sz = params.sq_off.array as usize + (params.sq_entries as usize * 4);
        let cq_ring_sz = params.cq_off.cqes as usize
            + (params.cq_entries as usize * std::mem::size_of::<io_uring_cqe>());

        let ring_sz = std::cmp::max(sq_ring_sz, cq_ring_sz);
        let ring_ptr = unsafe {
            libc::mmap(
                ptr::null_mut(),
                ring_sz,
                libc::PROT_READ | libc::PROT_WRITE,
                libc::MAP_SHARED | libc::MAP_POPULATE,
                ring_fd,
                0, // IORING_OFF_SQ_RING
            )
        };

        if ring_ptr == libc::MAP_FAILED {
            unsafe { libc::close(ring_fd) };
            return Err(io::Error::last_os_error());
        }

        let sqes_sz = params.sq_entries as usize * std::mem::size_of::<io_uring_sqe>();
        let sqes_ptr = unsafe {
            libc::mmap(
                ptr::null_mut(),
                sqes_sz,
                libc::PROT_READ | libc::PROT_WRITE,
                libc::MAP_SHARED | libc::MAP_POPULATE,
                ring_fd,
                0x10000000, // IORING_OFF_SQES
            )
        };

        if sqes_ptr == libc::MAP_FAILED {
            unsafe {
                libc::munmap(ring_ptr, ring_sz);
                libc::close(ring_fd);
            }
            return Err(io::Error::last_os_error());
        }

        unsafe {
            let p = ring_ptr as *mut u8;
            Ok(Self {
                ring_fd,
                sq_khead: p.add(params.sq_off.head as usize) as *mut u32,
                sq_ktail: p.add(params.sq_off.tail as usize) as *mut u32,
                sq_kmask: p.add(params.sq_off.ring_mask as usize) as *mut u32,
                sq_entries: p.add(params.sq_off.ring_entries as usize) as *mut u32,
                sq_kflags: p.add(params.sq_off.flags as usize) as *mut u32,
                sq_array: p.add(params.sq_off.array as usize) as *mut u32,
                sqes: sqes_ptr as *mut io_uring_sqe,
                cq_khead: p.add(params.cq_off.head as usize) as *mut u32,
                cq_ktail: p.add(params.cq_off.tail as usize) as *mut u32,
                cq_kmask: p.add(params.cq_off.ring_mask as usize) as *mut u32,
                cqes: p.add(params.cq_off.cqes as usize) as *mut io_uring_cqe,
                ring_sz,
                sqes_sz,
                cq_sz: cq_ring_sz,
                ring_ptr,
                cq_ptr: ring_ptr,
                sqes_ptr,
            })
        }
    }

    /// Submit a direct write + datasync barrier and block until completion
    pub fn write_and_sync(
        &mut self,
        fd: RawFd,
        buf: *const u8,
        len: usize,
        offset: u64,
    ) -> io::Result<()> {
        unsafe {
            let mut tail = *self.sq_ktail;
            let mask = *self.sq_kmask;

            // 1. SQE for Write
            let idx_write = tail & mask;
            let sqe_write = self.sqes.add(idx_write as usize);
            std::ptr::write_bytes(sqe_write, 0, 1);
            (*sqe_write).opcode = IORING_OP_WRITE;
            (*sqe_write).fd = fd;
            (*sqe_write).addr = buf as u64;
            (*sqe_write).len = len as u32;
            (*sqe_write).off = offset;
            (*sqe_write).user_data = 1;
            *self.sq_array.add(idx_write as usize) = idx_write;
            tail = tail.wrapping_add(1);

            // 2. SQE for Fsync/Datasync Barrier
            let idx_sync = tail & mask;
            let sqe_sync = self.sqes.add(idx_sync as usize);
            std::ptr::write_bytes(sqe_sync, 0, 1);
            (*sqe_sync).opcode = IORING_OP_FSYNC;
            (*sqe_sync).fd = fd;
            (*sqe_sync).rw_flags = IORING_FSYNC_DATASYNC as i32;
            (*sqe_sync).user_data = 2;
            *self.sq_array.add(idx_sync as usize) = idx_sync;
            tail = tail.wrapping_add(1);

            // Publish SQ tail
            std::sync::atomic::fence(Ordering::Release);
            *self.sq_ktail = tail;

            // Enter kernel
            let submitted = 2;
            let ret = libc::syscall(
                SYS_IO_URING_ENTER,
                self.ring_fd,
                submitted,
                2, // wait for 2 completions
                1, // IORING_ENTER_GETEVENTS
                ptr::null::<libc::sigset_t>(),
            );

            if ret < 0 {
                return Err(io::Error::last_os_error());
            }

            // Drain CQEs
            let mut completed = 0;
            let cq_mask = *self.cq_kmask;
            while completed < 2 {
                let cq_head = *self.cq_khead;
                let cq_tail = std::ptr::read_volatile(self.cq_ktail);
                if cq_head != cq_tail {
                    let cqe = self.cqes.add((cq_head & cq_mask) as usize);
                    if (*cqe).res < 0 {
                        return Err(io::Error::from_raw_os_error(-(*cqe).res));
                    }
                    std::sync::atomic::fence(Ordering::Acquire);
                    *self.cq_khead = cq_head.wrapping_add(1);
                    completed += 1;
                } else {
                    std::hint::spin_loop();
                }
            }
        }
        Ok(())
    }
}

impl Drop for DirectIoUring {
    fn drop(&mut self) {
        unsafe {
            libc::munmap(self.sqes_ptr, self.sqes_sz);
            libc::munmap(self.ring_ptr, self.ring_sz);
            libc::close(self.ring_fd);
        }
    }
}

