    wal_offset: CachePadded<AtomicU64>,
    ring: CachePadded<UnsafeCell<Option<DirectIoUring>>>,
    dma_buffer: CachePadded<*mut u8>,
}

unsafe impl Send for GroupCommitPipeline {}
unsafe impl Sync for GroupCommitPipeline {}

impl GroupCommitPipeline {
    pub fn new(wal_file: File, initial_offset: u64) -> Arc<Self> {
        let ring = DirectIoUring::new(256).ok();
        // Allocate page-aligned DMA buffer (64 KB)
        let mut dma_buf: *mut libc::c_void = ptr::null_mut();
        unsafe {
            libc::posix_memalign(&mut dma_buf, SECTOR_SIZE, MAX_BATCH_SIZE);
        }

        let stub = Box::into_raw(Box::new(CommitRequest::new(0, 0, Vec::new())));

        Arc::new(Self {
            head: CachePadded::new(AtomicPtr::new(stub)),
            tail: CachePadded::new(AtomicPtr::new(stub)),
            leader_lock: CachePadded::new(AtomicBool::new(false)),
            flushed_lsn: CachePadded::new(AtomicU64::new(0)),
            wal_file: CachePadded::new(wal_file),
            wal_offset: CachePadded::new(AtomicU64::new(initial_offset)),
            ring: CachePadded::new(UnsafeCell::new(ring)),
            dma_buffer: CachePadded::new(dma_buf as *mut u8),
        })
    }

    /// Enqueue transaction and participate in leader-follower group commit
    pub fn commit(&self, req: &mut CommitRequest) -> io::Result<()> {
        let req_ptr = req as *mut CommitRequest;

        // 1. Enqueue atomically using lock-free Michael-Scott style tail append
        loop {
            let tail_ptr = self.tail.load(Ordering::Acquire);
            let next_ptr = unsafe { (*tail_ptr).next.load(Ordering::Acquire) };
            if tail_ptr == self.tail.load(Ordering::Relaxed) {
                if next_ptr.is_null() {
                    if unsafe {
                        (*tail_ptr).next.compare_exchange_weak(
                            ptr::null_mut(),
                            req_ptr,
                            Ordering::Release,
                            Ordering::Relaxed,
                        )
                    }
                    .is_ok()
                    {
                        let _ = self.tail.compare_exchange(
                            tail_ptr,
                            req_ptr,
                            Ordering::Release,
                            Ordering::Relaxed,
                        );
                        break;
                    }
                } else {
                    let _ = self.tail.compare_exchange(
                        tail_ptr,
                        next_ptr,
                        Ordering::Release,
                        Ordering::Relaxed,
                    );
                }
            }
        }

        // 2. Leader Election: Try to become the Group Leader
        loop {
            if self.leader_lock.compare_exchange_weak(
                false,
                true,
                Ordering::Acquire,
                Ordering::Relaxed,
            ).is_ok() {
                // Elected as Leader: Process pending batch
                let res = self.process_batch();
                self.leader_lock.store(false, Ordering::Release);

                // Wake all parked threads waiting on their request completion
                futex_wake_all(&req.completed);

                if let Err(e) = res {
                    return Err(e);
                }
                break;
            }

            // Follower Path: Check if our request is committed
            let status = req.completed.load(Ordering::Acquire);
            if status == 1 {
                return Ok(());
            } else if status == 2 {
                return Err(io::Error::new(
                    io::ErrorKind::Other,
                    "Group commit pipeline failed",
                ));
            }

            // Park follower on sequence latch via Futex
            futex_wait(&req.completed, 0);
        }

        Ok(())
    }

    fn process_batch(&self) -> io::Result<()> {
        let mut head_ptr = self.head.load(Ordering::Acquire);
        let mut current = unsafe { (*head_ptr).next.load(Ordering::Acquire) };

        if current.is_null() {
            return Ok(());
        }

        let mut batch: Vec<*mut CommitRequest> = Vec::with_capacity(256);
        let mut total_bytes = 0usize;
        let start_time = Instant::now();

        // Coalesce requests up to MAX_BATCH_SIZE or bounded latency
        while !current.is_null() {
            let req = unsafe { &*current };
            let record_len = WALFrameHeader::SIZE + 8 + 4 + req.value.len() + WALFrameTrailer::SIZE;
            if total_bytes + record_len > MAX_BATCH_SIZE {
                break;
            }

            batch.push(current);
            total_bytes += record_len;
            head_ptr = current;
            current = req.next.load(Ordering::Acquire);

            if start_time.elapsed() >= Duration::from_micros(MAX_TXN_LATENCY_US) {
                break;
            }
        }

        if batch.is_empty() {
            return Ok(());
        }

        // Write batch into DMA Buffer with Sector Alignment & Torn Write Tags
        let dma_ptr = *self.dma_buffer;
        let mut buffer_offset = 0usize;
        let mut max_lsn = 0u64;

        for &req_ptr in &batch {
            let req = unsafe { &*req_ptr };
            max_lsn = std::cmp::max(max_lsn, req.lsn);

            let frame_payload_len = (8 + 4 + req.value.len()) as u32;
            let mut header = WALFrameHeader {
                magic: WAL_MAGIC,
                crc32c: 0,
                segment_epoch: 1,
                lsn: req.lsn,
                payload_len: frame_payload_len,
            };

            // Serialize header -> payload (key + len + value)
            let header_slice = unsafe {
                std::slice::from_raw_parts(
                    &header as *const _ as *const u8,
                    WALFrameHeader::SIZE,
                )
            };
            unsafe {
                ptr::copy_nonoverlapping(
                    header_slice.as_ptr(),
                    dma_ptr.add(buffer_offset),
                    WALFrameHeader::SIZE,
                );
            }
            buffer_offset += WALFrameHeader::SIZE;

            let payload_start = buffer_offset;
            unsafe {
                // Key (u64)
                ptr::copy_nonoverlapping(
                    &req.key as *const u64 as *const u8,
                    dma_ptr.add(buffer_offset),
                    8,
                );
                buffer_offset += 8;

                // Value len (u32)
                let val_len = req.value.len() as u32;
                ptr::copy_nonoverlapping(
                    &val_len as *const u32 as *const u8,
                    dma_ptr.add(buffer_offset),
                    4,
                );
                buffer_offset += 4;

                // Value bytes
                ptr::copy_nonoverlapping(
                    req.value.as_ptr(),
                    dma_ptr.add(buffer_offset),
                    req.value.len(),
                );
                buffer_offset += req.value.len();
            }

            // Calculate CRC32C over payload
            let payload_bytes = unsafe {
                std::slice::from_raw_parts(dma_ptr.add(payload_start), frame_payload_len as usize)
            };
            let calculated_crc = crc32c(payload_bytes);

            // Write CRC back to header in buffer
            unsafe {
                let crc_ptr = dma_ptr.add(payload_start - WALFrameHeader::SIZE + 4) as *mut u32;
                *crc_ptr = calculated_crc;
            }

            // Write Torn-Write Trailer
            let trailer = WALFrameTrailer {
                torn_tag: TORN_WRITE_MAGIC,
            };
            let trailer_slice = unsafe {
                std::slice::from_raw_parts(
                    &trailer as *const _ as *const u8,
                    WALFrameTrailer::SIZE,
                )
            };
            unsafe {
                ptr::copy_nonoverlapping(
                    trailer_slice.as_ptr(),
                    dma_ptr.add(buffer_offset),
                    WALFrameTrailer::SIZE,
                );
            }
            buffer_offset += WALFrameTrailer::SIZE;
        }

        // Align DMA buffer size to 4KB sector
        let aligned_write_size = (buffer_offset + SECTOR_SIZE - 1) & !(SECTOR_SIZE - 1);
        unsafe {
            // Zero out sector padding
            ptr::write_bytes(
                dma_ptr.add(buffer_offset),
                0,
                aligned_write_size - buffer_offset,
            );
        }

        let write_offset = self.wal_offset.load(Ordering::Relaxed);
        let fd = self.wal_file.as_raw_fd();

        // 3. Issue io_uring direct write and datasync flush
        let ring_cell = self.ring.value.get();
        let ring_opt = unsafe { &mut *ring_cell };

        if let Some(ring) = ring_opt {
            ring.write_and_sync(fd, dma_ptr, aligned_write_size, write_offset)?;
        } else {
            // Fallback: Synchronous POSIX pwrite + fdatasync
            let slice = unsafe { std::slice::from_raw_parts(dma_ptr, aligned_write_size) };
            let mut file = &*self.wal_file;
            file.seek(SeekFrom::Start(write_offset))?;
            file.write_all(slice)?;
            file.sync_data()?;
        }

        self.wal_offset
            .fetch_add(aligned_write_size as u64, Ordering::Release);
        self.flushed_lsn.store(max_lsn, Ordering::Release);
        self.head.store(head_ptr, Ordering::Release);

        // Notify followers
        for &req_ptr in &batch {
            unsafe {
                (*req_ptr).completed.store(1, Ordering::Release);
                futex_wake_all(&(*req_ptr).completed);
            }
        }

        Ok(())
    }
}

impl Drop for GroupCommitPipeline {
    fn drop(&mut self) {
        unsafe {
            libc::free(*self.dma_buffer as *mut libc::c_void);
            let mut curr = self.head.load(Ordering::Relaxed);
            while !curr.is_null() {
                let next = (*curr).next.load(Ordering::Relaxed);
                drop(Box::from_raw(curr));
                curr = next;
            }
        }
    }
}

// ============================================================================
// 5. CRASH RECOVERY SCANNER (WALScanner)
// ============================================================================

pub struct WALScanner;

impl WALScanner {
    /// Deterministically scans WAL segments, validates CRCs and torn tags,
    /// and returns reconstructed KV state up to the last valid LSN.
    pub fn recover(file_path: &str) -> io::Result<(HashMap<u64, Vec<u8>>, u64, u64)> {
        let mut file = OpenOptions::new().read(true).write(true).open(file_path)?;
        let file_len = file.metadata()?.len();
        let mut offset = 0u64;
        let mut state = HashMap::new();
        let mut max_lsn = 0u64;
        let mut valid_end_offset = 0u64;

        let mut buffer = vec![0u8; SECTOR_SIZE * 16]; // 64 KB read buffer

        'scan: while offset < file_len {
            let read_len = std::cmp::min(buffer.len() as u64, file_len - offset) as usize;
            file.seek(SeekFrom::Start(offset))?;
            file.read_exact(&mut buffer[..read_len])?;

            let mut buf_pos = 0;
            while buf_pos + WALFrameHeader::SIZE + WALFrameTrailer::SIZE <= read_len {
                let header = unsafe {
                    ptr::read_unaligned(
                        buffer[buf_pos..].as_ptr() as *const WALFrameHeader
                    )
                };

                if header.magic != WAL_MAGIC {
                    // Check if remaining sector is zero padding
                    break 'scan;
                }

                let total_frame_len =
                    WALFrameHeader::SIZE + header.payload_len as usize + WALFrameTrailer::SIZE;

                if buf_pos + total_frame_len > read_len {
                    // Frame crosses read buffer; break to re-align
                    break;
                }

                let payload_slice = &buffer[buf_pos + WALFrameHeader::SIZE
                    ..buf_pos + WALFrameHeader::SIZE + header.payload_len as usize];

                // Check CRC32C
                if crc32c(payload_slice) != header.crc32c {
                    eprintln!("[WAL Recovery] Torn write / CRC mismatch detected at offset: {}", offset + buf_pos as u64);
                    break 'scan;
                }

                // Check Torn-Write Trailer
                let trailer_pos = buf_pos + WALFrameHeader::SIZE + header.payload_len as usize;
                let trailer = unsafe {
                    ptr::read_unaligned(
                        buffer[trailer_pos..].as_ptr() as *const WALFrameTrailer
                    )
                };

                if trailer.torn_tag != TORN_WRITE_MAGIC {
                    eprintln!("[WAL Recovery] Torn write tag corrupt at offset: {}", offset + buf_pos as u64);
                    break 'scan;
                }

                // Payload: Key(u64) + ValLen(u32) + ValData
                let key = unsafe { ptr::read_unaligned(payload_slice.as_ptr() as *const u64) };
                let val_len = unsafe {
                    ptr::read_unaligned(payload_slice[8..].as_ptr() as *const u32)
                } as usize;
                let val_bytes = payload_slice[12..12 + val_len].to_vec();

                state.insert(key, val_bytes);
                max_lsn = std::cmp::max(max_lsn, header.lsn);

                buf_pos += total_frame_len;
                valid_end_offset = offset + buf_pos as u64;
            }

            offset += buf_pos as u64;
            if buf_pos == 0 {
                break;
            }
        }

        // Truncate any uncommitted/torn tail writes
        file.set_len(valid_end_offset)?;
        file.sync_all()?;

        Ok((state, max_lsn, valid_end_offset))
    }
}

// ============================================================================
// 6. DYNAMIC EPOCH-BASED RECLAMATION (EBR) & MVCC VERSION STORE
// ============================================================================

pub struct EpochTracker {
    global_epoch: CachePadded<AtomicU64>,
    participants_head: CachePadded<AtomicPtr<ParticipantNode>>,
}

#[repr(C, align(64))]
pub struct ParticipantNode {
    active_epoch: AtomicU64, // u64::MAX indicates unpinned / inactive
    is_active: AtomicBool,
    retired_list: UnsafeCell<[Vec<*mut VersionNode>; 3]>,
    next: AtomicPtr<ParticipantNode>,
}

unsafe impl Send for ParticipantNode {}
unsafe impl Sync for ParticipantNode {}

pub const INACTIVE_EPOCH: u64 = u64::MAX;

impl EpochTracker {
    pub fn new() -> Arc<Self> {
        Arc::new(Self {
            global_epoch: CachePadded::new(AtomicU64::new(0)),
            participants_head: CachePadded::new(AtomicPtr::new(ptr::null_mut())),
        })
    }

    pub fn register_thread(&self) -> *mut ParticipantNode {
        let node = Box::into_raw(Box::new(ParticipantNode {
            active_epoch: AtomicU64::new(INACTIVE_EPOCH),
            is_active: AtomicBool::new(true),
            retired_list: UnsafeCell::new([Vec::new(), Vec::new(), Vec::new()]),
            next: AtomicPtr::new(ptr::null_mut()),
        }));

        loop {
            let head = self.participants_head.load(Ordering::Acquire);
            unsafe { (*node).next.store(head, Ordering::Relaxed) };
            if self
                .participants_head
                .compare_exchange_weak(head, node, Ordering::Release, Ordering::Relaxed)
                .is_ok()
            {
                break;
            }
        }
        node
    }

    pub fn advance_epoch(&self) {
        let current = self.global_epoch.load(Ordering::Acquire);
        // Find minimum epoch of all active threads
        let mut curr_part = self.participants_head.load(Ordering::Acquire);
        let mut can_advance = true;

        while !curr_part.is_null() {
            let part = unsafe { &*curr_part };
            if part.is_active.load(Ordering::Acquire) {
                let p_epoch = part.active_epoch.load(Ordering::Acquire);
                if p_epoch != INACTIVE_EPOCH && p_epoch < current {
                    can_advance = false;
                    break;
                }
            }
            curr_part = part.next.load(Ordering::Acquire);
        }

        if can_advance {
            self.global_epoch.fetch_add(1, Ordering::Release);
        }
    }
}

pub struct EpochGuard<'a> {
    participant: &'a ParticipantNode,
    tracker: &'a EpochTracker,
    pinned_epoch: u64,
}

impl<'a> EpochGuard<'a> {
    pub fn pin(tracker: &'a EpochTracker, participant: &'a ParticipantNode) -> Self {
        let epoch = tracker.global_epoch.load(Ordering::Acquire);
        participant.active_epoch.store(epoch, Ordering::Release);
        fence(Ordering::SeqCst);
        Self {
            participant,
            tracker,
            pinned_epoch: epoch,
        }
    }

    pub fn defer_reclaim(&self, node: *mut VersionNode) {
        let epoch_slot = (self.pinned_epoch % 3) as usize;
        unsafe {
            let lists = &mut *self.participant.retired_list.get();
            lists[epoch_slot].push(node);
        }
    }
}

impl<'a> Drop for EpochGuard<'a> {
    fn drop(&mut self) {
        self.participant
            .active_epoch
            .store(INACTIVE_EPOCH, Ordering::Release);

        // Attempt garbage collection on safe epochs: (global_epoch + 2) % 3
        let global = self.tracker.global_epoch.load(Ordering::Acquire);
        let safe_slot = ((global + 1) % 3) as usize;

        unsafe {
            let lists = &mut *self.participant.retired_list.get();
            for node_ptr in lists[safe_slot].drain(..) {
                let _ = Box::from_raw(node_ptr);
            }
        }
    }
}

// Thread-Local EBR Token for automatic lifecycle registration & teardown
thread_local! {
    static TLS_PARTICIPANT: UnsafeCell<Option<(*mut ParticipantNode, Arc<EpochTracker>)>> = const { UnsafeCell::new(None) };
}

pub struct EBRHandle;

impl EBRHandle {
    pub fn pin(tracker: &Arc<EpochTracker>) -> EpochGuard<'static> {
        TLS_PARTICIPANT.with(|cell| {
            let state = unsafe { &mut *cell.get() };
            if state.is_none() {
                let node = tracker.register_thread();
                *state = Some((node, tracker.clone()));
            }
            let (node, _) = state.as_ref().unwrap();
            EpochGuard::pin(tracker, unsafe { &**node })
        })
    }
}

// MVCC Version Chain Node
#[repr(C, align(64))]
pub struct VersionNode {
    pub lsn: u64,
    pub key: u64,
    pub val: Vec<u8>,
    pub prev: AtomicPtr<VersionNode>,
}

#[repr(C, align(64))]
pub struct MVCCStore {
    index: CachePadded<AtomicPtr<IndexEntry>>,
    epoch_tracker: Arc<EpochTracker>,
    next_lsn: CachePadded<AtomicU64>,
}

struct IndexEntry {
    key: u64,
    head: AtomicPtr<VersionNode>,
    next: AtomicPtr<IndexEntry>,
}

impl MVCCStore {
    pub fn new(epoch_tracker: Arc<EpochTracker>, initial_lsn: u64) -> Self {
        Self {
            index: CachePadded::new(AtomicPtr::new(ptr::null_mut())),
            epoch_tracker,
            next_lsn: CachePadded::new(AtomicU64::new(initial_lsn + 1)),
        }
    }

    fn get_or_insert_entry(&self, key: u64) -> *mut IndexEntry {
        let mut curr = self.index.load(Ordering::Acquire);
        while !curr.is_null() {
            if unsafe { (*curr).key } == key {
                return curr;
            }
            curr = unsafe { (*curr).next.load(Ordering::Acquire) };
        }

        let new_entry = Box::into_raw(Box::new(IndexEntry {
            key,
            head: AtomicPtr::new(ptr::null_mut()),
            next: AtomicPtr::new(ptr::null_mut()),
        }));

        loop {
            let head = self.index.load(Ordering::Acquire);
            unsafe { (*new_entry).next.store(head, Ordering::Relaxed) };
            if self
                .index
                .compare_exchange_weak(head, new_entry, Ordering::Release, Ordering::Relaxed)
                .is_ok()
            {
                return new_entry;
            }
        }
    }

    /// Wait-free RCU-style read at specific transaction snapshot epoch/LSN
    pub fn read(&self, key: u64, snapshot_lsn: u64) -> Option<Vec<u8>> {
        let _guard = EBRHandle::pin(&self.epoch_tracker);
        let entry = self.get_or_insert_entry(key);
        let mut v_curr = unsafe { (*entry).head.load(Ordering::Acquire) };

        while !v_curr.is_null() {
            let node = unsafe { &*v_curr };
            if node.lsn <= snapshot_lsn {
                return Some(node.val.clone());
            }
            v_curr = node.prev.load(Ordering::Acquire);
        }
        None
    }

    /// Insert new version delta and schedule unreferenced node for EBR deallocation
    pub fn install_version(&self, lsn: u64, key: u64, val: Vec<u8>) {
        let guard = EBRHandle::pin(&self.epoch_tracker);
        let entry = self.get_or_insert_entry(key);

        let new_node = Box::into_raw(Box::new(VersionNode {
            lsn,
            key,
            val,
            prev: AtomicPtr::new(ptr::null_mut()),
        }));

        loop {
            let current_head = unsafe { (*entry).head.load(Ordering::Acquire) };
            unsafe { (*new_node).prev.store(current_head, Ordering::Relaxed) };

            if unsafe {
                (*entry).head.compare_exchange_weak(
                    current_head,
                    new_node,
                    Ordering::Release,
                    Ordering::Relaxed,
                )
            }
            .is_ok()
            {
                // Prune older versions if chained deeply
                if !current_head.is_null() {
                    let prev_node = unsafe { (*current_head).prev.load(Ordering::Acquire) };
                    if !prev_node.is_null() {
                        let grand_prev = unsafe { (*prev_node).prev.load(Ordering::Acquire) };
                        if !grand_prev.is_null() {
                            // Unlink grand_prev and defer reclamation
                            unsafe {
                                (*prev_node)
                                    .prev
                                    .store(ptr::null_mut(), Ordering::Release);
                            }
                            guard.defer_reclaim(grand_prev);
                        }
                    }
                }
                break;
            }
        }
        self.epoch_tracker.advance_epoch();
    }

    pub fn allocate_lsn(&self) -> u64 {
        self.next_lsn.fetch_add(1, Ordering::Relaxed)
    }
}

// ============================================================================
// 7. HIGH-LEVEL STORAGE ENGINE
// ============================================================================

pub struct Engine {
    pipeline: Arc<GroupCommitPipeline>,
    store: Arc<MVCCStore>,
    epoch_tracker: Arc<EpochTracker>,
}

impl Engine {
    pub fn open(wal_path: &str) -> io::Result<Self> {
        let (recovered_state, last_lsn, end_offset) = if std::path::Path::new(wal_path).exists() {
            WALScanner::recover(wal_path)?
        } else {
            (HashMap::new(), 0, 0)
        };

        let wal_file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .custom_flags(libc::O_DIRECT)
            .open(wal_path)
            .or_else(|_| {
                // Fallback without O_DIRECT for local non-block devices / CI tests
                OpenOptions::new()
                    .read(true)
                    .write(true)
                    .create(true)
                    .open(wal_path)
            })?;

        let epoch_tracker = EpochTracker::new();
        let store = Arc::new(MVCCStore::new(epoch_tracker.clone(), last_lsn));
        let pipeline = GroupCommitPipeline::new(wal_file, end_offset);

        // Replay recovered entries into MVCC Store
        for (k, v) in recovered_state {
            store.install_version(last_lsn, k, v);
        }

        Ok(Self {
            pipeline,
            store,
            epoch_tracker,
        })
    }

    pub fn put(&self, key: u64, value: Vec<u8>) -> io::Result<u64> {
        let lsn = self.store.allocate_lsn();
        let mut req = CommitRequest::new(lsn, key, value.clone());

        // Group Commit pipeline ensures durable persistence
        self.pipeline.commit(&mut req)?;

        // Install into in-memory wait-free MVCC store
        self.store.install_version(lsn, key, value);

        Ok(lsn)
    }

    pub fn get(&self, key: u64, snapshot_lsn: u64) -> Option<Vec<u8>> {
        self.store.read(key, snapshot_lsn)
    }
}

// ============================================================================
// 8. STRESS TEST & SYNTHETIC CRASH INJECTION HARNESS
// ============================================================================

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Barrier;
    use std::thread;

    #[test]
    fn test_concurrent_group_commit_and_ebr() {
        let wal_path = "/tmp/wal_test_concurrent.wal";
        let _ = std::fs::remove_file(wal_path);

        let engine = Arc::new(Engine::open(wal_path).expect("Engine open failed"));
        let num_threads = 8;
        let ops_per_thread = 500;
        let barrier = Arc::new(Barrier::new(num_threads));

        let mut handles = Vec::new();
        for t_idx in 0..num_threads {
            let engine = engine.clone();
            let barrier = barrier.clone();
            handles.push(thread::spawn(move || {
                barrier.wait();
                for i in 0..ops_per_thread {
                    let key = (t_idx * 1000 + i) as u64;
                    let val = format!("val_{}_{}", t_idx, i).into_bytes();
                    let lsn = engine.put(key, val.clone()).expect("Put failed");
                    let read_val = engine.get(key, lsn).expect("Get failed");
                    assert_eq!(read_val, val);
                }
            }));
        }

        for h in handles {
            h.join().unwrap();
        }

        drop(engine);

        // Verify recovery after normal shutdown
        let (recovered, max_lsn, _) = WALScanner::recover(wal_path).expect("Recovery failed");
        assert_eq!(recovered.len(), num_threads * ops_per_thread);
        assert_eq!(max_lsn, (num_threads * ops_per_thread) as u64);
        let _ = std::fs::remove_file(wal_path);
    }

    #[test]
    fn test_crash_injection_torn_write_recovery() {
        let wal_path = "/tmp/wal_test_torn_write.wal";
        let _ = std::fs::remove_file(wal_path);

        {
            let engine = Engine::open(wal_path).expect("Open failed");
            for i in 1..=50 {
                engine.put(i, format!("consistent_val_{}", i).into_bytes()).unwrap();
            }
        }

        // Inject simulated torn write at the end of the WAL file
        let mut file = OpenOptions::new().append(true).open(wal_path).unwrap();
        let partial_header = WALFrameHeader {
            magic: WAL_MAGIC,
            crc32c: 0xDEADBEEF, // Bad CRC
            segment_epoch: 1,
            lsn: 51,
            payload_len: 128,
        };
        let slice = unsafe {
            std::slice::from_raw_parts(
                &partial_header as *const _ as *const u8,
                WALFrameHeader::SIZE,
            )
        };
        file.write_all(slice).unwrap();
        // Write corrupted partial sector
        file.write_all(&[0xCC; 64]).unwrap();
        file.sync_all().unwrap();
        drop(file);

        // Reopen engine -> must detect torn write, truncate cleanly, and recover 50 items
        let (recovered, max_lsn, _) = WALScanner::recover(wal_path).expect("Recovery should truncate torn frame");
        assert_eq!(recovered.len(), 50);
        assert_eq!(max_lsn, 50);

        let engine = Engine::open(wal_path).expect("Reopen failed");
        assert_eq!(
            engine.get(50, 50).unwrap(),
            b"consistent_val_50"
        );
        assert_eq!(engine.get(51, 51), None);

        let _ = std::fs::remove_file(wal_path);
    }
}
